create or replace function public.ai_spend_reserve(
  p_user_id uuid,
  p_function text,
  p_kind text default 'question',
  p_estimate_micros bigint default 0,
  p_provider text default null,
  p_model text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_cfg ai_spend_limits;
  v_day date;
  v_month date;
  v_kind text := case when p_kind = 'content' then 'content' else 'question' end;
  v_estimate bigint := greatest(0, coalesce(p_estimate_micros, 0));
  v_rank integer;
  v_min_rank integer;
  v_calls integer;
  v_cap_micros bigint;
  v_effective_cap bigint;
  v_reserved bigint;
  v_event_id uuid;
  v_alert text := null;
  v_counted boolean := false;

  -- Who to tell when a threshold is crossed. Resolved here rather than in the
  -- edge function because this is already SECURITY DEFINER and can read
  -- profiles without depending on their RLS policies (which are being reworked
  -- separately) — and it saves the guard a round trip on the one call that has
  -- just been told there is a problem.
  v_owner_ids jsonb := '[]'::jsonb;
begin
  select * into v_cfg from ai_spend_limits where id = 1;
  if not found then
    insert into ai_spend_limits (id) values (1)
      on conflict (id) do nothing;
    select * into v_cfg from ai_spend_limits where id = 1;
  end if;

  v_day := (now() at time zone v_cfg.timezone)::date;
  v_month := date_trunc('month', (now() at time zone v_cfg.timezone))::date;

  v_min_rank := case v_cfg.min_role
    when 'owner' then 3
    when 'supervisor' then 2
    when 'foreman' then 1
    else 0
  end;

  v_cap_micros := v_cfg.monthly_cap_cents::bigint * 10000;
  v_effective_cap := case
    when v_kind = 'content'
      then (v_cap_micros * v_cfg.content_multiplier)::bigint
    else v_cap_micros
  end;

  -- (1) Role floor. Only applies to `question` traffic and only to a real end
  -- user: `content` jobs and service-role/webhook callers (null user) carry no
  -- role and are gated by the ceiling alone.
  if v_cfg.enforced and v_kind = 'question' and p_user_id is not null then
    v_rank := ai_role_rank(p_user_id);
    if v_rank < v_min_rank then
      insert into ai_usage_events (
        user_id, function_name, kind, provider, model, outcome,
        estimate_micros, usage_day, usage_month
      ) values (
        p_user_id, p_function, v_kind, p_provider, p_model, 'denied_role',
        0, v_day, v_month
      ) returning id into v_event_id;
      return jsonb_build_object(
        'allowed', false,
        'reason', 'role',
        'reservation_id', v_event_id,
        'min_role', v_cfg.min_role
      );
    end if;
  end if;

  -- (2) Per-user daily count. ONE statement: the upsert locks the day row, so a
  -- burst of concurrent callers queues on it and each one tests the limit
  -- against the value the previous caller actually committed. When the guard
  -- fails no row comes back, which IS the refusal — there is no window between
  -- reading the count and writing it.
  if v_cfg.enforced and v_kind = 'question' and p_user_id is not null then
    insert into ai_usage_days (user_id, usage_day, calls)
    values (p_user_id, v_day, 1)
    on conflict (user_id, usage_day) do update
      set calls = ai_usage_days.calls + 1,
          updated_at = now()
      where ai_usage_days.calls < v_cfg.per_user_daily_calls
    returning calls into v_calls;

    if v_calls is null then
      insert into ai_usage_events (
        user_id, function_name, kind, provider, model, outcome,
        estimate_micros, usage_day, usage_month
      ) values (
        p_user_id, p_function, v_kind, p_provider, p_model, 'denied_user_daily',
        0, v_day, v_month
      ) returning id into v_event_id;
      return jsonb_build_object(
        'allowed', false,
        'reason', 'user_daily',
        'reservation_id', v_event_id,
        'daily_limit', v_cfg.per_user_daily_calls
      );
    end if;
    v_counted := true;
  elsif p_user_id is not null then
    -- Not gated, but still metered, so the owner screen shows every caller.
    insert into ai_usage_days (user_id, usage_day, calls)
    values (p_user_id, v_day, 1)
    on conflict (user_id, usage_day) do update
      set calls = ai_usage_days.calls + 1, updated_at = now()
    returning calls into v_calls;
    v_counted := true;
  end if;

  -- (3) Company monthly ceiling, tested against money already booked. Same
  -- single-statement pattern, so the ceiling holds under a burst too.
  if v_cfg.enforced then
    insert into ai_spend_months (usage_month, calls, reserved_micros)
    values (v_month, 1, v_estimate)
    on conflict (usage_month) do update
      set calls = ai_spend_months.calls + 1,
          reserved_micros = ai_spend_months.reserved_micros + v_estimate,
          updated_at = now()
      where ai_spend_months.reserved_micros < v_effective_cap
    returning reserved_micros into v_reserved;
  else
    insert into ai_spend_months (usage_month, calls, reserved_micros)
    values (v_month, 1, v_estimate)
    on conflict (usage_month) do update
      set calls = ai_spend_months.calls + 1,
          reserved_micros = ai_spend_months.reserved_micros + v_estimate,
          updated_at = now()
    returning reserved_micros into v_reserved;
  end if;

  if v_reserved is null then
    -- Ceiling refused. Give the user back the day-count we just took: their
    -- own quota should not be burned by the company running out of budget.
    if v_counted then
      update ai_usage_days
         set calls = greatest(0, calls - 1), updated_at = now()
       where user_id = p_user_id and usage_day = v_day;
    end if;

    insert into ai_usage_events (
      user_id, function_name, kind, provider, model, outcome,
      estimate_micros, usage_day, usage_month
    ) values (
      p_user_id, p_function, v_kind, p_provider, p_model, 'denied_monthly_cap',
      0, v_day, v_month
    ) returning id into v_event_id;

    insert into ai_spend_alerts (usage_month, level, reserved_micros, cap_micros)
    select v_month, 'cap',
           coalesce((select reserved_micros from ai_spend_months where usage_month = v_month), 0),
           v_cap_micros
    on conflict (usage_month, level) do nothing
    returning level into v_alert;

    if v_alert is not null then
      select coalesce(jsonb_agg(id), '[]'::jsonb) into v_owner_ids
        from profiles where role in ('owner', 'big_boss', 'supervisor', 'admin');
    end if;

    return jsonb_build_object(
      'allowed', false,
      'reason', 'monthly_cap',
      'reservation_id', v_event_id,
      'cap_micros', v_cap_micros,
      'alert', v_alert,
      'alert_profile_ids', v_owner_ids
    );
  end if;

  -- (4) Approaching the ceiling: raise the warn alert exactly once.
  if v_cap_micros > 0
     and v_reserved >= (v_cap_micros * v_cfg.alert_at_pct) / 100 then
    insert into ai_spend_alerts (usage_month, level, reserved_micros, cap_micros)
    values (v_month, 'warn', v_reserved, v_cap_micros)
    on conflict (usage_month, level) do nothing
    returning level into v_alert;

    if v_alert is not null then
      select coalesce(jsonb_agg(id), '[]'::jsonb) into v_owner_ids
        from profiles where role in ('owner', 'big_boss', 'supervisor', 'admin');
    end if;
  end if;

  insert into ai_usage_events (
    user_id, function_name, kind, provider, model, outcome,
    estimate_micros, usage_day, usage_month
  ) values (
    p_user_id, p_function, v_kind, p_provider, p_model, 'allowed',
    v_estimate, v_day, v_month
  ) returning id into v_event_id;

  return jsonb_build_object(
    'allowed', true,
    'reason', null,
    'reservation_id', v_event_id,
    'calls_today', v_calls,
    'daily_limit', v_cfg.per_user_daily_calls,
    'reserved_micros', v_reserved,
    'cap_micros', v_cap_micros,
    'alert', v_alert,
    'alert_profile_ids', v_owner_ids
  );
end;
$$;;
;
create or replace function public.ai_spend_settle(
  p_event_id uuid,
  p_input_tokens integer,
  p_output_tokens integer,
  p_cost_micros bigint,
  p_model text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event ai_usage_events;
  v_actual bigint := greatest(0, coalesce(p_cost_micros, 0));
begin
  select * into v_event from ai_usage_events
   where id = p_event_id and outcome = 'allowed' and settled_at is null
   for update;
  if not found then return; end if;

  update ai_usage_events
     set input_tokens = p_input_tokens,
         output_tokens = p_output_tokens,
         cost_micros = v_actual,
         model = coalesce(p_model, model),
         settled_at = now()
   where id = p_event_id;

  -- Swap the reservation for the real figure, and add the real figure to the
  -- running truth.
  update ai_spend_months
     set reserved_micros =
           greatest(0, reserved_micros - v_event.estimate_micros + v_actual),
         spent_micros = spent_micros + v_actual,
         updated_at = now()
   where usage_month = v_event.usage_month;

  if v_event.user_id is not null then
    update ai_usage_days
       set cost_micros = cost_micros + v_actual, updated_at = now()
     where user_id = v_event.user_id and usage_day = v_event.usage_day;
  end if;
end;
$$;;
;
create or replace function public.ai_spend_release(
  p_event_id uuid,
  p_reason text default null,
  p_refund_call boolean default false
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event ai_usage_events;
begin
  select * into v_event from ai_usage_events
   where id = p_event_id and outcome = 'allowed' and settled_at is null
   for update;
  if not found then return; end if;

  update ai_usage_events
     set outcome = 'released',
         release_reason = p_reason,
         cost_micros = 0,
         settled_at = now()
   where id = p_event_id;

  update ai_spend_months
     set reserved_micros = greatest(0, reserved_micros - v_event.estimate_micros),
         calls = case when p_refund_call then greatest(0, calls - 1) else calls end,
         updated_at = now()
   where usage_month = v_event.usage_month;

  if p_refund_call and v_event.user_id is not null then
    update ai_usage_days
       set calls = greatest(0, calls - 1), updated_at = now()
     where user_id = v_event.user_id and usage_day = v_event.usage_day;
  end if;
end;
$$;;
;
create or replace function public.ai_spend_overview()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_cfg ai_spend_limits;
  v_month date;
  v_day date;
  v_rank integer := ai_role_rank(auth.uid());
begin
  if not public.can_see_costs(auth.uid()) then
    raise exception 'Only an owner, or somebody given "Sees costs", can see what the assistant costs.'
      using errcode = '42501';
  end if;

  select * into v_cfg from ai_spend_limits where id = 1;
  v_month := date_trunc('month', (now() at time zone coalesce(v_cfg.timezone, 'UTC')))::date;
  v_day := (now() at time zone coalesce(v_cfg.timezone, 'UTC'))::date;

  return jsonb_build_object(
    'can_edit', v_rank >= 3,
    'limits', jsonb_build_object(
      'per_user_daily_calls', v_cfg.per_user_daily_calls,
      'monthly_cap_cents', v_cfg.monthly_cap_cents,
      'content_multiplier', v_cfg.content_multiplier,
      'min_role', v_cfg.min_role,
      'alert_at_pct', v_cfg.alert_at_pct,
      'enforced', v_cfg.enforced,
      'timezone', v_cfg.timezone,
      'updated_at', v_cfg.updated_at
    ),
    'month', jsonb_build_object(
      'usage_month', v_month,
      'calls', coalesce((select calls from ai_spend_months where usage_month = v_month), 0),
      'spent_micros', coalesce((select spent_micros from ai_spend_months where usage_month = v_month), 0),
      'reserved_micros', coalesce((select reserved_micros from ai_spend_months where usage_month = v_month), 0),
      'cap_micros', v_cfg.monthly_cap_cents::bigint * 10000
    ),
    'people', coalesce((
      select jsonb_agg(row_to_json(t))
      from (
        select
          e.user_id,
          coalesce(p.display_name, 'Removed user') as display_name,
          coalesce(p.role, 'unknown') as role,
          count(*) filter (where e.outcome = 'allowed') as calls,
          coalesce(sum(e.cost_micros), 0) as cost_micros,
          count(*) filter (where e.outcome like 'denied%') as blocked,
          coalesce((
            select d.calls from ai_usage_days d
             where d.user_id = e.user_id and d.usage_day = v_day
          ), 0) as calls_today
        from ai_usage_events e
        left join profiles p on p.id = e.user_id
        where e.usage_month = v_month
        group by e.user_id, p.display_name, p.role
        order by coalesce(sum(e.cost_micros), 0) desc,
                 count(*) filter (where e.outcome = 'allowed') desc
        limit 25
      ) t
    ), '[]'::jsonb),
    'functions', coalesce((
      select jsonb_agg(row_to_json(f))
      from (
        select function_name,
               count(*) filter (where outcome = 'allowed') as calls,
               coalesce(sum(cost_micros), 0) as cost_micros
          from ai_usage_events
         where usage_month = v_month
         group by function_name
         order by coalesce(sum(cost_micros), 0) desc
      ) f
    ), '[]'::jsonb),
    'alerts', coalesce((
      select jsonb_agg(row_to_json(a))
      from (
        select level, reserved_micros, cap_micros, created_at
          from ai_spend_alerts
         where usage_month = v_month
         order by created_at desc
      ) a
    ), '[]'::jsonb)
  );
end;
$$;;
;
create or replace function public.ai_spend_set_limits(
  p_per_user_daily_calls integer default null,
  p_monthly_cap_cents integer default null,
  p_min_role text default null,
  p_enforced boolean default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tz text;
begin
  if ai_role_rank(auth.uid()) < 3 then
    raise exception 'ai_spend_set_limits: owner only';
  end if;
  if p_min_role is not null
     and p_min_role not in ('installer', 'foreman', 'supervisor', 'owner') then
    raise exception 'ai_spend_set_limits: unknown role %', p_min_role;
  end if;

  update ai_spend_limits
     set per_user_daily_calls =
           coalesce(greatest(0, p_per_user_daily_calls), per_user_daily_calls),
         monthly_cap_cents =
           coalesce(greatest(0, p_monthly_cap_cents), monthly_cap_cents),
         min_role = coalesce(p_min_role, min_role),
         enforced = coalesce(p_enforced, enforced),
         updated_at = now(),
         updated_by = auth.uid()
   where id = 1;

  -- Raising the ceiling must clear the block immediately, so the 'cap' alert
  -- for this month is retired and can fire again if the new ceiling is reached.
  select timezone into v_tz from ai_spend_limits where id = 1;
  delete from ai_spend_alerts
   where level = 'cap'
     and usage_month = date_trunc('month', (now() at time zone coalesce(v_tz, 'UTC')))::date
     and cap_micros < (select monthly_cap_cents::bigint * 10000 from ai_spend_limits where id = 1);

  return public.ai_spend_overview();
end;
$$;;
;
create or replace function public.role_rank(p_role text)
returns int
language sql
immutable
set search_path = public
as $$
  select case p_role
    when 'owner'      then 3
    when 'big_boss'   then 3   -- legacy alias for owner
    when 'supervisor' then 2
    when 'admin'      then 2   -- legacy alias for supervisor
    when 'foreman'    then 1
    when 'lead'       then 1   -- legacy alias for foreman
    when 'installer'  then 0
    else 0                     -- unknown / null: installer floor
  end;
$$;;
;
create or replace function public.my_role_rank()
returns int
language sql
stable
security definer
set search_path = public
as $$
  select public.role_rank((select role from public.profiles where id = auth.uid()));
$$;;
;
create or replace function public.trg_guard_profile_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_email text;
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.id <> auth.uid() then
    if public.my_role_rank() < 2 then
      raise exception 'you may only create your own profile'
        using errcode = '42501';
    end if;
    return new;
  end if;

  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));

  if exists (select 1 from partner_invites where email = v_email) then
    new.is_partner := true;
    new.role := 'installer';
    delete from partner_invites where email = v_email;
    return new;
  end if;

  if new.role is distinct from 'installer'
     and v_email not in ('ammon@horizonsolarusa.com', 'isaacammonbarlow@gmail.com')
  then
    raise exception
      'a new profile starts as installer; a supervisor or owner assigns the role'
      using errcode = '42501';
  end if;

  return new;
end;
$$;;
;
create or replace function public.claim_owner_bootstrap()
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_email text;
begin
  if auth.uid() is null then
    return false;
  end if;

  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if v_email not in ('ammon@horizonsolarusa.com', 'isaacammonbarlow@gmail.com') then
    return false;
  end if;

  update public.profiles
     set role = 'owner',
         display_name = 'Ammon',
         active = true,
         updated_at = now()
   where id = auth.uid()
     and (role <> 'owner' or display_name <> 'Ammon' or not active);

  return true;
end;
$$;;
;
create or replace function public.set_profile_role(p_target uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rank int := public.my_role_rank();
  v_row  public.profiles;
begin
  if p_role not in ('installer', 'foreman', 'supervisor', 'owner') then
    raise exception 'invalid role %', p_role using errcode = '22023';
  end if;

  if v_rank < 2 then
    raise exception 'only a supervisor or owner can change roles'
      using errcode = '42501';
  end if;

  -- Owners belong to owners (2026-08-26): below owner rank, the owner role
  -- can be neither granted nor touched. Sentences the app shows as-is.
  if v_rank < 3 and p_role = 'owner' then
    raise exception 'only an owner can make an owner'
      using errcode = '42501';
  end if;
  if v_rank < 3
     and exists (select 1 from public.profiles where id = p_target and role = 'owner')
  then
    raise exception 'only an owner can change an owner''s role'
      using errcode = '42501';
  end if;

  -- No self-promotion above your own rank: a supervisor cannot make themselves
  -- the owner. Lateral and downward self-changes stay allowed.
  if p_target = auth.uid() and public.role_rank(p_role) > v_rank then
    raise exception 'you cannot promote yourself above your own role'
      using errcode = '42501';
  end if;

  update public.profiles
     set role = p_role, updated_at = now()
   where id = p_target
  returning * into v_row;

  if v_row.id is null then
    raise exception 'no such profile %', p_target using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'display_name', v_row.display_name,
    'role', v_row.role,
    'skill_level', v_row.skill_level,
    'active', v_row.active,
    'updated_at', v_row.updated_at
  );
end;
$$;;
;
create or replace function public.can_read_ask_log(p_uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select role from profiles where id = p_uid)
      in ('foreman', 'supervisor', 'owner', 'admin', 'big_boss'),
    false
  );
$$;;
;
create or replace function public.create_staging_bays(p_job_code text)
returns setof public.locations
language plpgsql
security definer
set search_path = public
as $$
declare
  v_code text := btrim(coalesce(p_job_code, ''));
begin
  -- A job code of '' would generate the address 'J--A', which is not a shelf
  -- anyone can label or find. Better to create nothing and let the detection
  -- check and suggest_location()'s refusal make the gap loud.
  if v_code = '' then
    return;
  end if;

  -- Bring back a bay that was retired rather than leaving the job one short.
  -- Retiring is how the app deletes a slot (deleteLocation sets active=false),
  -- so without this the repair path would have no way to undo one.
  update public.locations
     set active = true
   where zone = 'J' and rack = v_code and slot in ('A', 'B') and not active;

  -- `where not exists` rather than relying on ON CONFLICT alone: locations.serial
  -- defaults to nextval('location_serial_seq'), sequences are not transactional,
  -- and ON CONFLICT evaluates the default before it discovers the conflict. So a
  -- bare ON CONFLICT DO NOTHING would burn two permanent serials every time this
  -- ran against a job that already had its bays — and this runs on every project
  -- insert and every repair click. ON CONFLICT stays as the race backstop only.
  --
  -- serial is never named here, exactly as createProject never named it and the
  -- seed migration never named it: the column default is the only allocator, and
  -- the six live bays hold SLOT-000039..000052 with gaps in them. Nothing
  -- requires serials to be contiguous. `address` is never named either — it is a
  -- generated column and Postgres rejects an INSERT that mentions it.
  insert into public.locations (zone, rack, slot, capacity)
  select 'J', v_code, s.slot, 10
    from (values ('A'), ('B')) as s(slot)
   where not exists (
     select 1 from public.locations l
      where l.zone = 'J' and l.rack = v_code and l.slot = s.slot
   )
  on conflict (zone, rack, slot) do nothing;

  return query
    select l.* from public.locations l
     where l.zone = 'J' and l.rack = v_code
     order by l.slot;
end;
$$;;
;
create or replace function public.projects_create_staging_bays()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.job_bay_box(new.id);
  return null;
end;
$$;;
;
create or replace function public.locations_staging_bay_exists()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.zone = 'J' and exists (
    select 1 from public.locations l
     where l.zone = 'J' and l.rack = new.rack and l.slot = new.slot
  ) then
    return null;  -- skip the insert; the bay is already there
  end if;
  return new;
end;
$$;;
;
create or replace function public.ensure_project_staging_bays(p_project_id uuid)
returns setof public.locations
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller_role text;
  v_job_code text;
begin
  select role into v_caller_role from public.profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can create staging bays';
  end if;

  select job_code into v_job_code from public.projects where id = p_project_id;
  if v_job_code is null then
    raise exception 'unknown job %', p_project_id;
  end if;

  return query select * from public.create_staging_bays(v_job_code);
end;
$$;;
;
create or replace function public.trg_guard_crew_invite_rank()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_inviter_rank int;
begin
  -- A seed or migration with no author recorded. Nothing to compare against.
  if new.invited_by is null then
    return new;
  end if;

  select public.role_rank(role) into v_inviter_rank
    from public.profiles
   where id = new.invited_by;

  -- No profile for the author: treat as the installer floor rather than as
  -- permission. A missing row must never be a way past the check.
  v_inviter_rank := coalesce(v_inviter_rank, 0);

  if v_inviter_rank < 2 then
    raise exception
      'only a supervisor or owner can create an invite (author rank %)',
      v_inviter_rank
      using errcode = '42501';
  end if;

  if public.role_rank(new.role) > v_inviter_rank then
    raise exception
      'an invite cannot grant a role above its author (% > rank %)',
      new.role, v_inviter_rank
      using errcode = '42501';
  end if;

  return new;
end;
$$;;
;
create or replace function public.is_test_profile(p_uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select is_test from public.profiles where id = p_uid), false);
$$;;
;
create or replace function public.seed_opening_origin_pin()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    -- A re-extract re-inserts rows and deliberately carries a manually placed
    -- pin across (see planDraftPersistence). When the caller supplies an
    -- origin, that is the freshly extracted position and it wins; otherwise
    -- the pin it was created at is the origin.
    if new.origin_pin_x is null and new.pin_x is not null then
      new.origin_pin_x := new.pin_x;
      new.origin_pin_y := new.pin_y;
    end if;
    if new.origin_page_number is null then
      new.origin_page_number := new.page_number;
    end if;
    return new;
  end if;

  -- Write-once. An ordinary update can fill a blank origin but can never
  -- rewrite one, so no amount of dragging can launder a nudge into "original".
  if old.origin_pin_x is not null then
    new.origin_pin_x := old.origin_pin_x;
    new.origin_pin_y := old.origin_pin_y;
  end if;
  if old.origin_page_number is not null then
    new.origin_page_number := old.origin_page_number;
  end if;
  return new;
end;
$$;;
;
create or replace function public.record_opening_pin_move()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- An undo is not a move. The undo functions set this for their transaction
  -- so walking the stack back does not push new entries onto it.
  if coalesce(current_setting('app.pin_undo', true), '') = 'on' then
    return null;
  end if;
  -- Only an actual relocation counts. Placing a mark for the first time
  -- (null -> value) and clearing one (value -> null) are different actions
  -- with their own undo already, and neither has a "from" to go back to.
  if old.pin_x is null or old.pin_y is null
     or new.pin_x is null or new.pin_y is null then
    return null;
  end if;
  if old.pin_x = new.pin_x
     and old.pin_y = new.pin_y
     and old.page_number is not distinct from new.page_number then
    return null;
  end if;

  insert into project_opening_pin_moves (
    project_id, opening_id, moved_by,
    from_pin_x, from_pin_y, from_page_number,
    to_pin_x, to_pin_y, to_page_number
  ) values (
    new.project_id, new.id, auth.uid(),
    old.pin_x, old.pin_y, old.page_number,
    new.pin_x, new.pin_y, new.page_number
  );
  return null;
end;
$$;;
;
create or replace function public.undo_opening_pin_move(p_move_id uuid)
returns project_opening_pin_moves
language plpgsql
security definer
set search_path = public
as $$
declare
  v_move project_opening_pin_moves;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can undo a mark move';
  end if;

  select * into v_move from project_opening_pin_moves where id = p_move_id;
  if v_move.id is null then
    raise exception 'That move is no longer on record';
  end if;
  if v_move.undone_at is not null then
    return v_move;
  end if;

  perform set_config('app.pin_undo', 'on', true);
  update project_openings
  set pin_x = v_move.from_pin_x,
      pin_y = v_move.from_pin_y,
      page_number = coalesce(v_move.from_page_number, page_number)
  where id = v_move.opening_id;
  perform set_config('app.pin_undo', 'off', true);

  update project_opening_pin_moves
  set undone_at = now(),
      undone_by = auth.uid()
  where id = p_move_id
  returning * into v_move;

  return v_move;
end;
$$;;
;
create or replace function public.reset_project_pins_to_extracted(p_project_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can reset a job''s marks';
  end if;

  perform set_config('app.pin_undo', 'on', true);
  with restored as (
    update project_openings
    set pin_x = origin_pin_x,
        pin_y = origin_pin_y,
        page_number = coalesce(origin_page_number, page_number)
    where project_id = p_project_id
      and origin_pin_x is not null
      and pin_x is not null
      and (pin_x <> origin_pin_x or pin_y <> origin_pin_y)
    returning 1
  )
  select count(*) into v_count from restored;
  perform set_config('app.pin_undo', 'off', true);

  update project_opening_pin_moves
  set undone_at = now(),
      undone_by = auth.uid()
  where project_id = p_project_id
    and undone_at is null;

  return v_count;
end;
$$;;
;
create or replace function public.reset_opening_pin_to_extracted(p_opening_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can reset a mark';
  end if;

  perform set_config('app.pin_undo', 'on', true);
  with restored as (
    update project_openings
    set pin_x = origin_pin_x,
        pin_y = origin_pin_y,
        page_number = coalesce(origin_page_number, page_number)
    where id = p_opening_id
      and origin_pin_x is not null
      and pin_x is not null
      and (pin_x <> origin_pin_x or pin_y <> origin_pin_y)
    returning 1
  )
  select count(*) into v_count from restored;
  perform set_config('app.pin_undo', 'off', true);

  update project_opening_pin_moves
  set undone_at = now(),
      undone_by = auth.uid()
  where opening_id = p_opening_id
    and undone_at is null;

  return v_count;
end;
$$;;
;
create or replace function public.guard_opening_pin_move()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Only the mark's POSITION is policed. An update that leaves the pin alone —
  -- which is every claim, start, finish, measurement, condition check, flag and
  -- assignment — passes straight through.
  if new.pin_x is not distinct from old.pin_x
     and new.pin_y is not distinct from old.pin_y
     and new.page_number is not distinct from old.page_number then
    return new;
  end if;

  -- Undo and the two resets already checked the caller before setting this for
  -- their transaction; asking the same question twice would only cost a lookup.
  if coalesce(current_setting('app.pin_undo', true), '') = 'on' then
    return new;
  end if;

  -- No JWT means this is not a person holding a phone: a migration, or an edge
  -- function on the service key. Both are already trusted above RLS, and the
  -- anon role cannot reach this table at all — the only policy on it is granted
  -- `to authenticated`.
  if auth.uid() is null then
    return new;
  end if;

  if not public.is_foreman_plus(auth.uid()) then
    -- Plain English, because this sentence can reach a phone: an installer on a
    -- page cached before this shipped still has a draggable dot, and the app
    -- shows what comes back from here.
    raise exception 'Only a foreman or above can move a mark on the plan.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;;
;
create or replace function public.guard_opening_create_delete()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row project_openings;
begin
  v_row := case when tg_op = 'DELETE' then old else new end;

  -- No JWT means this is not a person holding a phone: a migration, or an edge
  -- function on the service key. Both are already trusted above RLS.
  if auth.uid() is null then
    return v_row;
  end if;

  -- add_field_unit, which has already proved the caller is clocked in on this
  -- job. Wave E: presence is the permission for one missed window, and only
  -- for the insert that function makes inside its own transaction.
  if tg_op = 'INSERT'
     and coalesce(current_setting('app.field_unit_add', true), '') = 'on' then
    return v_row;
  end if;

  if not public.is_foreman_plus(auth.uid()) then
    if tg_op = 'DELETE' then
      raise exception 'Only a foreman or above can remove a window or door from a job.'
        using errcode = '42501';
    else
      raise exception 'Only a foreman or above can add windows or doors to a job.'
        using errcode = '42501';
    end if;
  end if;

  return v_row;
end;
$$;;
;
create or replace function public.guard_opening_removal()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Only interested in a change to the hidden flag itself.
  if new.removed_at is not distinct from old.removed_at then
    return new;
  end if;

  -- remove_opening / restore_opening, which have already checked the role and
  -- are recording who did it.
  if coalesce(current_setting('app.opening_removal', true), '') = 'on' then
    return new;
  end if;

  -- No JWT: a migration or the service key, both already trusted above RLS.
  if auth.uid() is null then
    return new;
  end if;

  raise exception 'Use Remove or Put back to hide a window or door, so the job keeps a record of who did it.'
    using errcode = '42501';
end;
$$;;
;
create or replace function public.remove_opening(
  p_opening_id uuid,
  p_reason text default null
)
returns project_openings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row project_openings;
begin
  -- Byte-identical to the sentence the create/delete guard raises, so the app
  -- shows one wording for "you may not remove a window" however it is reached.
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can remove a window or door from a job.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;

  -- Already hidden. Replaying this is a no-op rather than an error, so a second
  -- tap or a retried request cannot turn into a scary red message.
  if v_row.removed_at is not null then
    return v_row;
  end if;

  if v_row.status = 'installed' then
    raise exception 'That window or door is already installed, so it can''t be removed. Undo the install first.'
      using errcode = '42501';
  end if;

  -- A removed opening must not go on holding a physical unit: the warehouse
  -- would have it reserved for something nobody can see, and the damage-issue
  -- dedup in unload_units/activate_preissued_unit finds an opening BY its
  -- assigned unit. Refusing here keeps both correct without touching either.
  if v_row.assigned_window_id is not null then
    raise exception 'That window or door has a unit from the warehouse against it. Take the unit off it first.'
      using errcode = '42501';
  end if;

  perform set_config('app.opening_removal', 'on', true);
  update project_openings
     set removed_at = now(),
         removed_by = auth.uid(),
         removed_reason = nullif(trim(coalesce(p_reason, '')), '')
   where id = p_opening_id
   returning * into v_row;
  perform set_config('app.opening_removal', 'off', true);

  return v_row;
end;
$$;;
;
create or replace function public.restore_opening(p_opening_id uuid)
returns project_openings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row project_openings;
  v_clash text;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can put a window or door back on a job.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;

  if v_row.removed_at is null then
    return v_row;
  end if;

  -- Somebody added the code back, or a re-extract found it on the plan again.
  -- The live one wins; this one stays hidden and the foreman is told why in the
  -- words they would use themselves.
  select opening_code into v_clash
    from project_openings
   where project_id = v_row.project_id
     and opening_code = v_row.opening_code
     and removed_at is null
   limit 1;
  if v_clash is not null then
    raise exception 'There is already a #% on this job, so this one cannot come back under that name. Remove or rename the one that is there first.', v_clash
      using errcode = '23505';
  end if;

  perform set_config('app.opening_removal', 'on', true);
  update project_openings
     set removed_at = null,
         removed_by = null,
         removed_reason = null
   where id = p_opening_id
   returning * into v_row;
  perform set_config('app.opening_removal', 'off', true);

  return v_row;
end;
$$;;
;
create or replace function public.list_removed_openings(p_project_id uuid)
returns table (
  id uuid,
  opening_code text,
  label text,
  window_type_id uuid,
  status text,
  removed_at timestamptz,
  removed_by uuid,
  removed_by_name text,
  removed_reason text,
  code_taken boolean
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can see what was removed from a job.'
      using errcode = '42501';
  end if;

  return query
    select o.id, o.opening_code, o.label, o.window_type_id, o.status,
           o.removed_at, o.removed_by, p.display_name, o.removed_reason,
           exists (
             select 1 from project_openings live
              where live.project_id = o.project_id
                and live.opening_code = o.opening_code
                and live.removed_at is null
           )
      from project_openings o
      left join profiles p on p.id = o.removed_by
     where o.project_id = p_project_id
       and o.removed_at is not null
     order by o.removed_at desc;
end;
$$;;
;
create or replace function public.is_sandbox_project(p_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_project_id is not null and exists (
    select 1 from public.sandbox_projects s where s.project_id = p_project_id
  );
$$;;
;
create or replace function public.row_project_id(p_kind text, p_value text)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if p_value is null then
    return null;
  end if;
  begin
    v_id := p_value::uuid;
  exception when others then
    return null;
  end;

  if p_kind = 'project' then
    return v_id;
  end if;
  -- 'opening'
  return (select o.project_id from public.project_openings o where o.id = v_id);
end;
$$;;
;
create or replace function public.guard_test_account_sandbox_only()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_kind    text := tg_argv[1];
  v_column  text := tg_argv[0];
  v_uid     uuid := auth.uid();
  v_project uuid;
begin
  -- No JWT: a migration, a seed, or an edge function on the service-role key.
  -- All of those are already trusted above RLS, and this guard is about one
  -- specific kind of signed-in account.
  if v_uid is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  -- The fast path, and the reason this is safe to put on forty tables: for
  -- every real crew member it is one primary-key lookup on profiles and a
  -- return. `is_test_profile` is STABLE, so a statement touching many rows
  -- resolves it once.
  if not public.is_test_profile(v_uid) then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if tg_op <> 'INSERT' then
    v_project := public.row_project_id(v_kind, to_jsonb(old) ->> v_column);
    if not public.is_sandbox_project(v_project) then
      raise exception
        'This is a test login. It can only change the automation sandbox job, not a real one.'
        using errcode = '42501',
              detail = format('refused %s on %s (project %s)',
                              tg_op, tg_table_name,
                              coalesce(v_project::text, 'unknown'));
    end if;
  end if;

  if tg_op <> 'DELETE' then
    v_project := public.row_project_id(v_kind, to_jsonb(new) ->> v_column);
    if not public.is_sandbox_project(v_project) then
      raise exception
        'This is a test login. It can only change the automation sandbox job, not a real one.'
        using errcode = '42501',
              detail = format('refused %s on %s (project %s)',
                              tg_op, tg_table_name,
                              coalesce(v_project::text, 'unknown'));
    end if;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;;
;
create or replace function public.guard_test_account_profile_writes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null or not public.is_test_profile(v_uid) then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'This is a test login. It cannot remove a crew member.'
      using errcode = '42501';
  end if;

  if new.id <> v_uid then
    raise exception 'This is a test login. It can only change its own profile.'
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and new.role is distinct from old.role then
    raise exception 'This is a test login. It cannot change anyone''s role, including its own.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;;
;
create or replace function public.guard_test_account_cannot_invite()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_test_profile(new.invited_by)
     or (auth.uid() is not null and public.is_test_profile(auth.uid())) then
    raise exception 'This is a test login. It cannot give anybody access to the app.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;;
;
create or replace function public.is_sandbox_storage_path(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if p_name is null then
    return false;
  end if;
  begin
    v_id := split_part(p_name, '/', 1)::uuid;
  exception when others then
    -- A path that does not start with a project id cannot be shown to belong to
    -- the sandbox, so for a test account it is refused.
    return false;
  end;
  return public.is_sandbox_project(v_id);
end;
$$;;
;
create or replace function public.test_account_write_scope()
returns table (
  table_name      text,
  link_column     text,
  guarded         boolean,
  client_writable boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with tables as (
    select c.oid, c.relname::text as name
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relkind = 'r'
      and c.relname <> 'sandbox_projects'
  ),
  linked as (
    select
      t.oid,
      t.name,
      case
        when t.name = 'projects' then 'id'
        when exists (select 1 from information_schema.columns col
                     where col.table_schema = 'public' and col.table_name = t.name
                       and col.column_name = 'project_id') then 'project_id'
        when exists (select 1 from information_schema.columns col
                     where col.table_schema = 'public' and col.table_name = t.name
                       and col.column_name = 'project_opening_id') then 'project_opening_id'
        when exists (select 1 from information_schema.columns col
                     where col.table_schema = 'public' and col.table_name = t.name
                       and col.column_name = 'opening_id') then 'opening_id'
      end as link_column
    from tables t
  )
  select
    l.name,
    l.link_column,
    exists (
      select 1 from pg_trigger tg
      where tg.tgrelid = l.oid
        and tg.tgname = 'guard_test_account_sandbox_only'
        and not tg.tgisinternal
    ),
    has_table_privilege('authenticated', l.oid, 'INSERT')
      or has_table_privilege('authenticated', l.oid, 'UPDATE')
      or has_table_privilege('authenticated', l.oid, 'DELETE')
  from linked l
  order by l.link_column nulls first, l.name;
$$;;
;
create or replace function shift_cap_hours()
returns int language sql immutable set search_path = public, pg_temp as $$
  select 16
$$;;
;
create or replace function _close_dangling_shift(p_profile uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_cap interval := make_interval(hours => shift_cap_hours());
begin
  -- Believable: a forgotten punch inside the day, or a job/phase switch. The
  -- elapsed time is still evidence, so close it exactly as before — now
  -- also naming WHY, so this row never reads as a punch the person closed
  -- themselves.
  update time_shifts
     set clock_out_at = now(),
         status = 'submitted',
         closed_reason = 'auto-closed by next clock-in'
   where profile_id = p_profile
     and status = 'open'
     and clock_out_at is null
     and now() - clock_in_at <= v_cap;

  -- Not believable. Refuse to name a finish time; say so on the row instead.
  update time_shifts
     set status = 'needs_finish',
         break_started_at = null,
         break_type = null,
         edited_note = left(
           coalesce(edited_note || ' | ', '') ||
           'Ran past ' || shift_cap_hours() || 'h without a clock-out, so the app '
           || 'stopped counting instead of guessing an end time. Needs the real '
           || 'finish time from the crew member or the office.',
           2000)
   where profile_id = p_profile
     and status = 'open'
     and clock_out_at is null
     and now() - clock_in_at > v_cap;
end;
$$;;
;
create or replace function finish_shift_at(
  p_shift_id uuid,
  p_clock_out_at timestamptz,
  p_injured boolean default false,
  p_break_seconds int default null
)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_shift time_shifts;
  v_lead boolean := _is_lead(auth.uid());
begin
  select * into v_shift from time_shifts where id = p_shift_id;
  if v_shift.id is null then
    raise exception 'no shift %', p_shift_id;
  end if;
  if v_shift.profile_id <> auth.uid() and not v_lead then
    raise exception 'that is not your shift';
  end if;
  if v_shift.clock_out_at is not null then
    raise exception 'that shift already has a finish time';
  end if;
  if p_clock_out_at is null then
    raise exception 'a finish time is required';
  end if;
  if p_clock_out_at <= v_shift.clock_in_at then
    raise exception 'the finish time must be after the clock-in time';
  end if;
  -- Two minutes of tolerance for a phone whose clock runs fast. Anything
  -- further ahead would be recording work that has not happened yet.
  if p_clock_out_at > now() + interval '2 minutes' then
    raise exception 'the finish time cannot be in the future';
  end if;

  update time_shifts
     set clock_out_at = p_clock_out_at,
         injured = coalesce(p_injured, injured),
         break_seconds = coalesce(p_break_seconds, break_seconds),
         break_started_at = null,
         break_type = null,
         time_confirmed = true,
         signed_at = now(),
         status = 'submitted',
         edited_by = auth.uid(),
         edited_at = now(),
         edited_note = left(
           coalesce(edited_note || ' | ', '') ||
           'Finish time entered by hand because the shift ran past '
           || shift_cap_hours() || 'h and the app would not guess one.',
           2000)
   where id = p_shift_id
  returning * into v_shift;

  return v_shift;
end;
$$;;
;
create or replace function install_timer_cap_minutes()
returns int language sql immutable set search_path = public, pg_temp as $$
  select 480
$$;;
;
create or replace function close_shift_as_no_work(
  p_shift_id uuid,
  p_reason text default null
)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_shift time_shifts;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can write a shift off to zero';
  end if;

  select * into v_shift from time_shifts where id = p_shift_id;
  if v_shift.id is null then
    raise exception 'no shift %', p_shift_id;
  end if;
  if v_shift.clock_out_at is not null then
    raise exception 'that shift is already closed';
  end if;

  update time_shifts
     set clock_out_at  = clock_in_at,
         break_seconds = 0,
         break_started_at = null,
         break_type    = null,
         -- The worker never signed off on this, a supervisor decided it.
         time_confirmed = false,
         injured       = coalesce(injured, false),
         signed_at     = now(),
         status        = 'approved',
         edited_by     = auth.uid(),
         edited_at     = now(),
         approved_by   = auth.uid(),
         approved_at   = now(),
         edited_note   = left(
           coalesce(edited_note || ' | ', '') ||
           'Recorded as zero hours — no work was done on this punch.' ||
           coalesce(' Reason: ' || nullif(btrim(p_reason), ''), ''),
           2000)
   where id = p_shift_id
  returning * into v_shift;

  return v_shift;
end;
$$;;
;
create or replace function _is_supervisor(p_uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select role in ('supervisor','owner','admin','big_boss')
       from profiles where id = p_uid),
    false
  );
$$;;
;
create or replace function start_opening_phase(p_opening_id uuid, p_kind text)
returns opening_phases
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_phase opening_phases;
begin
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before starting a task';
  end if;
  perform public._unit_work_gate(v_uid);

  insert into opening_phases (opening_id, kind, started_by)
  values (p_opening_id, p_kind, v_uid)
  on conflict (opening_id, kind) do update
    -- Re-starting an unfinished phase is fine (a second person joining, or a
    -- resume); a submitted phase stays submitted.
    set started_by = coalesce(opening_phases.started_by, excluded.started_by)
  returning * into v_phase;

  if v_phase.status = 'submitted' then
    raise exception 'this % is already submitted', p_kind;
  end if;
  return v_phase;
end;
$$;;
;
create or replace function submit_opening_phase(
  p_opening_id uuid,
  p_kind text,
  p_photo_path text
)
returns opening_phases
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_phase opening_phases;
begin
  if p_photo_path is null or btrim(p_photo_path) = '' then
    raise exception 'a finished-work photo is required to submit %', p_kind;
  end if;

  update opening_phases
     set status = 'submitted',
         submitted_at = now(),
         submitted_by = v_uid,
         photo_path = p_photo_path,
         minutes = least(
           greatest(0,
             floor((
               extract(epoch from now() - started_at)
               - paused_seconds
               - coalesce(extract(epoch from now() - paused_at), 0)
             ) / 60)::int
           ),
           install_timer_cap_minutes()
         ),
         paused_at = null
   where opening_id = p_opening_id and kind = p_kind and status = 'active'
   returning * into v_phase;

  if v_phase is null then
    raise exception 'no active % to submit on this opening', p_kind;
  end if;
  return v_phase;
end;
$$;;
;
create or replace function set_opening_needs_flashing(p_opening_id uuid, p_needs boolean)
returns project_openings
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_opening project_openings;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can change flashing requirements';
  end if;
  update project_openings set needs_flashing = p_needs
  where id = p_opening_id returning * into v_opening;
  if v_opening is null then raise exception 'unknown opening %', p_opening_id; end if;
  return v_opening;
end;
$$;;
;
create or replace function set_project_needs_flashing(p_project_id uuid, p_needs boolean)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_count int;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can change flashing requirements';
  end if;
  update project_openings set needs_flashing = p_needs
  where project_id = p_project_id and needs_flashing is distinct from p_needs;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;;
;
create or replace function _flashing_outstanding(p_opening_id uuid)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select o.needs_flashing
     and not exists (
       select 1 from opening_phases ph
       where ph.opening_id = o.id and ph.kind = 'flashing'
         and ph.status = 'submitted'
     )
  from project_openings o where o.id = p_opening_id
$$;;
;
create or replace function pause_opening_phase(p_opening_id uuid, p_kind text)
returns opening_phases
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v opening_phases;
begin
  update opening_phases
     set paused_at = coalesce(paused_at, now())
   where opening_id = p_opening_id and kind = p_kind and status = 'active'
   returning * into v;
  if v is null then raise exception 'no active % on this opening', p_kind; end if;
  return v;
end;
$$;;
;
create or replace function resume_opening_phase(p_opening_id uuid, p_kind text)
returns opening_phases
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v opening_phases;
begin
  -- A phase paused yesterday must not run today on an unsigned talk: for the
  -- signature's purposes, resuming is starting. (This RPC never checked the
  -- shift; that is unchanged.)
  perform public._unit_work_gate(auth.uid());
  update opening_phases
     set paused_seconds = paused_seconds
           + greatest(0, extract(epoch from (now() - paused_at))::int),
         paused_at = null
   where opening_id = p_opening_id and kind = p_kind
     and status = 'active' and paused_at is not null
   returning * into v;
  if v is null then
    -- Already running (or never paused) — return the row as it stands.
    select * into v from opening_phases
    where opening_id = p_opening_id and kind = p_kind and status = 'active';
    if v is null then raise exception 'no active % on this opening', p_kind; end if;
  end if;
  return v;
end;
$$;;
;
create or replace function cancel_opening_phase(p_opening_id uuid, p_kind text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  delete from opening_phases
  where opening_id = p_opening_id and kind = p_kind and status = 'active';
end;
$$;;
;
create or replace function set_opening_rough_opening(
  p_opening_id uuid,
  p_width_in numeric,
  p_height_in numeric,
  p_actor text default null,
  p_check jsonb default null
)
returns project_openings
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_opening project_openings;
begin
  update project_openings
  set ro_width_in = p_width_in,
      ro_height_in = p_height_in,
      ro_measured_by = p_actor,
      ro_measured_at = now(),
      ro_check = coalesce(p_check, ro_check),
      ro_quick_ok = false
  where id = p_opening_id
  returning * into v_opening;

  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;
  return v_opening;
end;
$$;;
;
create or replace function lead_void_shift(p_shift_id uuid, p_note text)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old time_shifts;
  v_shift time_shifts;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can delete crew time';
  end if;
  if p_note is null or btrim(p_note) = '' then
    raise exception 'deleting a punch needs a reason note';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status = 'voided' then
    raise exception 'this punch is already deleted';
  end if;

  update time_shifts
     set status      = 'voided',
         edited_note = btrim(p_note),
         edited_by   = auth.uid(),
         edited_at   = now(),
         approved_by = null,
         approved_at = null
   where id = p_shift_id
   returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', v_old.status, 'voided', btrim(p_note));

  return v_shift;
end;
$$;;
;
create or replace function _toolbox_library_for_date(p_date date)
returns toolbox_talk_library
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_row toolbox_talk_library;
  v_category text;
  v_count int;
  v_idx int;
begin
  -- An explicit assignment for the date always wins.
  select l.* into v_row
  from toolbox_talk_assignments a
  join toolbox_talk_library l on l.id = a.library_id
  where a.assigned_date = p_date and l.is_active
  limit 1;
  if v_row.id is not null then return v_row; end if;

  v_category := case extract(isodow from p_date)::int
    when 1 then 'lifting'
    when 2 then 'glass'
    when 3 then 'cutting'
    when 4 then 'heights'
    when 5 then 'site'
    else null  -- weekends rotate the whole library
  end;

  if v_category is not null then
    select count(*) into v_count from toolbox_talk_library
      where category = v_category and is_active;
    if v_count = 0 then return null; end if;
    -- Same talk all week within the category; advances each Monday.
    v_idx := ((p_date - date '1970-01-05') / 7) % v_count;
    select * into v_row from toolbox_talk_library
      where category = v_category and is_active
      order by position, slug offset v_idx limit 1;
  else
    select count(*) into v_count from toolbox_talk_library where is_active;
    if v_count = 0 then return null; end if;
    -- Weekend: walk the whole library day by day so Sat != Sun.
    v_idx := (p_date - date '1970-01-05') % v_count;
    select * into v_row from toolbox_talk_library
      where is_active
      order by category, position, slug offset v_idx limit 1;
  end if;
  return v_row;
end;
$$;;
;
create or replace function get_or_create_toolbox_talk_for_date(p_date date)
returns safety_talks
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_talk safety_talks;
  v_lib toolbox_talk_library;
  v_body text;
begin
  -- One writer per date; readers queue briefly instead of double-inserting.
  perform pg_advisory_xact_lock(hashtext('toolbox_talk_' || p_date::text));

  select * into v_talk from safety_talks
    where talk_date = p_date
    order by created_at desc limit 1;
  if v_talk.id is not null then return v_talk; end if;

  v_lib := _toolbox_library_for_date(p_date);
  if v_lib.id is null then
    -- Empty library: leave the app on its legacy newest-talk fallback.
    return null;
  end if;

  -- Plain-text body so every legacy reader (snapshot, PDF, old cards)
  -- keeps working without knowing about the structured fields.
  v_body := v_lib.briefing || E'\n\nKey points:\n' ||
    (select string_agg('• ' || x, E'\n') from jsonb_array_elements_text(v_lib.key_points) x) ||
    case when v_lib.stop_work_line is not null
      then E'\n\nStop work: ' || v_lib.stop_work_line else '' end;

  insert into safety_talks
    (title, body, talk_date, library_slug, category, citation,
     key_points, watch_for, stop_work_line, pledge)
  values
    (v_lib.title, v_body, p_date, v_lib.slug, v_lib.category, v_lib.citation,
     v_lib.key_points, v_lib.watch_for, v_lib.stop_work_line, v_lib.pledge)
  returning * into v_talk;
  return v_talk;
end;
$$;;
;
create or replace function lead_unapprove_shift(p_shift_id uuid, p_note text)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old time_shifts;
  v_shift time_shifts;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can revert an approval';
  end if;
  if p_note is null or btrim(p_note) = '' then
    raise exception 'reverting an approval needs a reason note';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status <> 'approved' then
    raise exception 'this punch is not approved';
  end if;

  update time_shifts
     set status      = 'submitted',
         approved_by = null,
         approved_at = null,
         edited_note = 'Approval reverted: ' || btrim(p_note),
         edited_by   = auth.uid(),
         edited_at   = now()
   where id = p_shift_id
   returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', 'approved', 'submitted', btrim(p_note));

  return v_shift;
end;
$$;;
