create or replace function mint_packages(p_count int)
returns setof packages
language plpgsql
security definer
as $$
declare
  i int;
  v_row packages;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_count is null or p_count < 1 or p_count > 500 then
    raise exception 'sticker batches are 1-500 at a time';
  end if;

  for i in 1..p_count loop
    insert into packages (short_code)
    values (issue_package_short_code())
    returning * into v_row;
    return next v_row;
  end loop;
  return;
end;
$$;;
;
create or replace function issue_package_short_code()
returns text
language plpgsql
as $$
declare
  v_code text;
begin
  loop
    v_code := gen_short_code(6);
    exit when not exists (select 1 from packages where short_code = v_code);
  end loop;
  return v_code;
end;
$$;;
;
create or replace function ensure_package_delivery(p_label text)
returns package_deliveries
language plpgsql
security definer
as $$
declare
  v_row package_deliveries;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  select * into v_row
  from package_deliveries
  where label = trim(p_label) and arrived_on = current_date
  limit 1;
  if found then
    return v_row;
  end if;
  insert into package_deliveries (label, created_by)
  values (trim(p_label), auth.uid()::text)
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function store_packages(p_packages uuid[], p_container uuid)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_prev uuid;
  v_prev_loc uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id, location_id into v_prev, v_prev_loc
    from packages
    where id = v_id and status in ('received', 'stored', 'checked_out');
    if not found then
      continue; -- blank stickers can't be stored
    end if;

    update packages
    set status = 'stored', container_id = p_container, location_id = null
    where id = v_id;

    -- from_location_id carries the shelf it came off, so a package moving from
    -- a job's bay into a conex leaves a trail that says where it was. Without
    -- it the bay simply vanishes from the history.
    insert into movements (
      package_id, event, from_container_id, from_location_id, to_container_id, actor
    )
    values (
      v_id,
      case when v_prev is null and v_prev_loc is null then 'stored' else 'moved' end,
      v_prev,
      v_prev_loc,
      p_container,
      auth.uid()::text
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;;
;
create or replace function checkout_packages(
  p_packages uuid[],
  p_reason text,
  p_project uuid
)
returns int
language plpgsql
security definer
as $$
declare
  v_id uuid;
  v_from uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'pick a reason for taking the material';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is going to';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id into v_from
    from packages
    where id = v_id and status in ('received', 'stored');
    if not found then
      continue;
    end if;

    update packages
    set status = 'checked_out', container_id = null
    where id = v_id;

    insert into movements (package_id, event, from_container_id, project_id, reason, actor)
    values (v_id, 'checked_out', v_from, p_project, trim(p_reason), auth.uid()::text);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;;
;
create or replace function save_checkout_reason(
  p_id uuid,
  p_label text,
  p_sort int default 100,
  p_active boolean default true
)
returns checkout_reasons
language plpgsql
security definer
as $$
declare
  v_role text;
  v_row checkout_reasons;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role in ('installer', 'foreman') then
    raise exception 'only a supervisor or above can edit checkout reasons';
  end if;
  if p_label is null or length(trim(p_label)) = 0 then
    raise exception 'a reason needs a label';
  end if;

  if p_id is null then
    insert into checkout_reasons (label, sort, active)
    values (trim(p_label), coalesce(p_sort, 100), coalesce(p_active, true))
    returning * into v_row;
  else
    update checkout_reasons
    set label = trim(p_label), sort = coalesce(p_sort, 100), active = coalesce(p_active, true)
    where id = p_id
    returning * into v_row;
    if not found then
      raise exception 'reason not found';
    end if;
  end if;
  return v_row;
end;
$$;;
