create or replace function answer_summon(p_summon_id uuid)
returns summon_helpers
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_summon summons;
  v_row summon_helpers;
  v_count int;
begin
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before answering a summon';
  end if;
  -- Answering opens a helper unit session (unit_sessions_follow_summon_helpers,
  -- 20260963000000) — unit work, so it waits for today's signature too.
  perform public._unit_work_gate(v_uid);
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.status = 'closed' then
    raise exception 'this summon has ended';
  end if;
  -- Expired but not yet swept: a day-old call is over whatever the row says.
  if v_summon.created_at < now() - interval '1 day' then
    raise exception 'this summon has ended';
  end if;
  if v_summon.requested_by = v_uid then
    raise exception 'you called this summon — no answering yourself';
  end if;
  select count(*) into v_count
  from summon_helpers
  where summon_id = p_summon_id and canceled_at is null;
  if v_count >= v_summon.needed then
    raise exception 'this summon is covered — thanks anyway';
  end if;

  -- Re-answer after a cancel revives the old row; first answer inserts.
  update summon_helpers
  set canceled_at = null, joined_at = now(), completed_at = null, minutes = null
  where summon_id = p_summon_id and profile_id = v_uid and canceled_at is not null
  returning * into v_row;
  if v_row.id is null then
    insert into summon_helpers (summon_id, profile_id)
    values (p_summon_id, v_uid)
    returning * into v_row;
  end if;

  if v_count + 1 >= v_summon.needed then
    update summons set status = 'covered' where id = p_summon_id;
  end if;

  insert into points_ledger (profile_id, kind, points, ref, status)
  values (v_uid, 'summon_answer', 10, p_summon_id::text, 'confirmed');

  -- You answered — any earlier "can't help" no longer applies.
  delete from summon_declines where summon_id = p_summon_id and profile_id = v_uid;

  return v_row;
end;
$$;;
;
create or replace function complete_summon_help(p_summon_id uuid)
returns summon_helpers
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_row summon_helpers;
begin
  update summon_helpers
  set completed_at = now(),
      minutes = least(480, greatest(0, floor(extract(epoch from now() - joined_at) / 60))::int)
  where summon_id = p_summon_id and profile_id = v_uid and completed_at is null
  returning * into v_row;
  if v_row.id is null then
    raise exception 'no open help of yours on this summon';
  end if;
  return v_row;
end;
$$;;
;
create or replace function close_summon(p_summon_id uuid)
returns summons
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_summon summons;
begin
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.requested_by <> v_uid and not _is_lead(v_uid) then
    raise exception 'only the caller or a foreman can end a summon';
  end if;
  update summon_helpers
  set completed_at = now(),
      minutes = least(480, greatest(0, floor(extract(epoch from now() - joined_at) / 60))::int)
  where summon_id = p_summon_id and completed_at is null and canceled_at is null;
  update summons
  set status = 'closed', closed_at = now()
  where id = p_summon_id
  returning * into v_summon;
  return v_summon;
end;
$$;;
;
create or replace function canonical_jsonb(j jsonb)
returns text
language plpgsql
immutable
as $$
declare
  k text;
  parts text[] := '{}';
  elem jsonb;
begin
  case jsonb_typeof(j)
    when 'object' then
      for k in select key from jsonb_object_keys(j) as key order by key collate "C" loop
        parts := parts || (to_jsonb(k)::text || ':' || canonical_jsonb(j -> k));
      end loop;
      return '{' || array_to_string(parts, ',') || '}';
    when 'array' then
      for elem in select value from jsonb_array_elements(j) as value loop
        parts := parts || canonical_jsonb(elem);
      end loop;
      return '[' || array_to_string(parts, ',') || ']';
    else
      -- scalars (string, number, boolean, null): jsonb's own compact text
      return j::text;
  end case;
end;
$$;;
;
create or replace function set_unit_signature(p_opening_id uuid, p_signature jsonb)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_key text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  -- v1 shape gates: versioned, computed, categorical — never free text.
  if (p_signature ->> 'v') is distinct from '1' then
    raise exception 'unknown signature version';
  end if;
  if (p_signature ->> 'kind') not in ('window', 'door') then
    raise exception 'kind must be window or door';
  end if;
  if (p_signature ->> 'corner') not in ('none', 'corner') then
    raise exception 'corner must be none or corner';
  end if;
  if jsonb_typeof(p_signature -> 'tiers') is distinct from 'array'
     or jsonb_array_length(p_signature -> 'tiers') < 1 then
    raise exception 'signature needs at least one tier';
  end if;
  if (p_signature ->> 'insetOutset') is not null
     and (p_signature ->> 'insetOutset') not in ('inset', 'outset') then
    raise exception 'insetOutset must be inset, outset or null';
  end if;
  if jsonb_typeof(p_signature -> 'panelCount') is distinct from 'number'
     or jsonb_typeof(p_signature -> 'movingCount') is distinct from 'number' then
    raise exception 'panelCount and movingCount must be numbers';
  end if;

  v_key := canonical_jsonb(p_signature);

  update project_openings
  set signature = p_signature,
      sig_key = v_key,
      sig_computed_at = now()
  where id = p_opening_id;
  if not found then
    raise exception 'opening not found';
  end if;
end;
$$;;
;
create or replace function _end_open_session(
  p_profile uuid,
  p_reason text,
  p_block_reason text default null,
  p_block_issue uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update unit_sessions
  set ended_at = now(),
      end_reason = p_reason,
      block_reason = p_block_reason,
      block_issue_id = p_block_issue
  where profile_id = p_profile and ended_at is null;
end;
$$;;
;
create or replace function _close_stale_sessions(p_profile uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update unit_sessions
  set ended_at = now(), end_reason = 'auto_closed'
  where profile_id = p_profile and ended_at is null
    and started_at < now() - interval '16 hours';
end;
$$;;
;
create or replace function _has_open_redo(p_opening uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from unit_redos where opening_id = p_opening and resolved_at is null
  );
$$;;
;
create or replace function start_unit_session(
  p_opening_id uuid,
  p_role text default 'install'
)
returns unit_sessions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_row unit_sessions;
begin
  if p_role not in ('install', 'helper') then
    raise exception 'role must be install or helper';
  end if;
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before starting a task';
  end if;
  perform public._unit_work_gate(v_uid);
  if p_role = 'install' and _flashing_outstanding(p_opening_id) then
    raise exception 'this opening needs flashing before the install starts';
  end if;

  perform _close_stale_sessions(v_uid);
  perform _end_open_session(v_uid, 'handoff');

  insert into unit_sessions (opening_id, profile_id, role, is_rework)
  values (p_opening_id, v_uid, p_role, _has_open_redo(p_opening_id))
  returning * into v_row;

  -- Keep the map/Heartbeat read-model true: first touch stamps the unit.
  update project_openings
  set work_started_at = coalesce(work_started_at, now())
  where id = p_opening_id;

  return v_row;
end;
$$;;
;
create or replace function reattribute_session(p_opening_id uuid)
returns unit_sessions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_row unit_sessions;
begin
  update unit_sessions
  set opening_id = p_opening_id,
      is_rework = _has_open_redo(p_opening_id)
  where profile_id = v_uid and ended_at is null
    and started_at > now() - interval '5 minutes'
  returning * into v_row;
  if v_row.id is null then
    raise exception 'nothing to move — no open session younger than 5 minutes';
  end if;
  update project_openings
  set work_started_at = coalesce(work_started_at, now())
  where id = p_opening_id;
  return v_row;
end;
$$;;
;
create or replace function finish_unit(
  p_opening_id uuid,
  p_next_opening_id uuid default null,
  p_installer text default null,
  p_quality_grade int default null,
  p_difficulty text default null,
  p_went_well text default null,
  p_went_poorly text default null,
  p_obstacles text default null,
  p_tools_helped text default null,
  p_time_vs_estimate text default null,
  p_safety_notes text default null,
  p_do_again text default null,
  p_transcript_raw text default null,
  p_installer_id uuid default null,
  p_estimate_minutes int default null
)
returns install_events
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  return finish_unit(
    p_opening_id, p_next_opening_id, p_installer, p_quality_grade,
    p_difficulty, p_went_well, p_went_poorly, p_obstacles, p_tools_helped,
    p_time_vs_estimate, p_safety_notes, p_do_again, p_transcript_raw,
    p_installer_id, p_estimate_minutes, null);
end;
$$;;
;
create or replace function block_unit(
  p_opening_id uuid,
  p_reason text,
  p_issue_id uuid default null,
  p_next_opening_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_issue uuid := p_issue_id;
  v_project uuid;
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required to block a unit';
  end if;
  select project_id into v_project from project_openings where id = p_opening_id;
  if v_project is null then
    raise exception 'opening not found';
  end if;
  if v_issue is null then
    insert into issues (project_id, opening_id, kind, note, created_by)
    values (v_project, p_opening_id, 'blocker', p_reason, v_uid)
    returning id into v_issue;
  end if;

  update unit_sessions
  set ended_at = now(), end_reason = 'block',
      block_reason = p_reason, block_issue_id = v_issue
  where profile_id = v_uid and ended_at is null and opening_id = p_opening_id;

  if p_next_opening_id is not null then
    begin
      perform start_unit_session(p_next_opening_id, 'install');
    exception when others then
      null;
    end;
  end if;
end;
$$;;
;
create or replace function press_redo(p_opening_id uuid, p_reason text)
returns unit_redos
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_row unit_redos;
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required to redo a unit';
  end if;
  if exists (
    select 1 from unit_redos where opening_id = p_opening_id and resolved_at is null
  ) then
    raise exception 'a redo is already open on this unit';
  end if;

  insert into unit_redos (opening_id, pressed_by, reason)
  values (p_opening_id, v_uid, p_reason)
  returning * into v_row;

  -- Back in play, visibly. The install_events row is NOT touched.
  update project_openings
  set status = case when assigned_to is not null then 'assigned' else 'planned' end,
      confirmed = false,
      work_ended_at = null
  where id = p_opening_id;

  return v_row;
end;
$$;;
;
create or replace function unit_sessions_follow_shift()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_held uuid;
begin
  -- Clock-out (including every dangling-shift guard that stamps it).
  if new.clock_out_at is not null and old.clock_out_at is null then
    perform _end_open_session(new.profile_id, 'clock_out');
    return new;
  end if;
  -- Break starts: the session ends; the unit waits.
  if new.break_started_at is not null and old.break_started_at is null then
    perform _end_open_session(new.profile_id, 'break');
    return new;
  end if;
  -- Break ends: straight back on the held unit (owner call — a minute or
  -- two of walk-back inflation accepted for zero friction).
  if new.break_started_at is null and old.break_started_at is not null
     and new.clock_out_at is null then
    if exists(select 1 from custom_work_sessions where shift_id=new.id and end_reason='break' and ended_at=old.break_started_at) or exists(select 1 from service_time_sessions where shift_id=new.id and end_reason='break' and ended_at>=old.break_started_at) then
      return new; -- Custom work resumes explicitly on Current Work.
    end if;
    select s.opening_id into v_held
    from unit_sessions s
    join project_openings o on o.id = s.opening_id
    where s.profile_id = new.profile_id and s.end_reason = 'break'
      and o.status <> 'installed'
    order by s.ended_at desc
    limit 1;
    if v_held is not null then
      insert into unit_sessions (opening_id, profile_id, role, is_rework)
      values (v_held, new.profile_id, 'install', _has_open_redo(v_held));
    end if;
  end if;
  return new;
end;
$$;;
;
create or replace function public.unit_sessions_on_clock_in()
returns trigger language plpgsql security definer
set search_path=public,pg_temp as $$
begin
  if new.source_import_key is null then
    perform _close_stale_sessions(new.profile_id);
  end if;
  return new;
end; $$;;
;
create or replace function unit_sessions_follow_summon_helpers()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_opening uuid;
begin
  if tg_op = 'INSERT' then
    select opening_id into v_opening from summons where id = new.summon_id;
    if v_opening is not null then
      perform _close_stale_sessions(new.profile_id);
      perform _end_open_session(new.profile_id, 'handoff');
      insert into unit_sessions (opening_id, profile_id, role, is_rework)
      values (v_opening, new.profile_id, 'helper', _has_open_redo(v_opening));
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' and new.completed_at is not null and old.completed_at is null then
    select opening_id into v_opening from summons where id = new.summon_id;
    update unit_sessions
    set ended_at = now(), end_reason = 'complete'
    where profile_id = new.profile_id and ended_at is null and role = 'helper'
      and opening_id = v_opening;
  end if;
  if tg_op = 'UPDATE' and new.canceled_at is not null and old.canceled_at is null then
    select opening_id into v_opening from summons where id = new.summon_id;
    update unit_sessions
    set ended_at = now(), end_reason = 'handoff'
    where profile_id = new.profile_id and ended_at is null and role = 'helper'
      and opening_id = v_opening;
  end if;
  -- A revived answer (canceled_at cleared) opens a fresh helper session.
  if tg_op = 'UPDATE' and new.canceled_at is null and old.canceled_at is not null then
    select opening_id into v_opening from summons where id = new.summon_id;
    if v_opening is not null then
      perform _close_stale_sessions(new.profile_id);
      perform _end_open_session(new.profile_id, 'handoff');
      insert into unit_sessions (opening_id, profile_id, role, is_rework)
      values (v_opening, new.profile_id, 'helper', _has_open_redo(v_opening));
    end if;
    return new;
  end if;
  return new;
end;
$$;;
;
create or replace function sync_project_mark()
returns trigger
language plpgsql
security definer
as $$
begin
  insert into project_marks (project_id, mark_code)
  values (new.project_id, upper(trim(new.mark_code)))
  on conflict (project_id, mark_code) do nothing;
  return new;
end;
$$;;
;
create or replace function enforce_container_depth()
returns trigger
language plpgsql
as $$
begin
  if new.parent_container_id is not null then
    if new.parent_container_id = new.id then
      raise exception 'a container cannot sit inside itself';
    end if;
    if exists (
      select 1 from storage_containers
      where id = new.parent_container_id and parent_container_id is not null
    ) then
      raise exception 'one level only — a crate inside a conex is as deep as it goes';
    end if;
    if exists (
      select 1 from storage_containers where parent_container_id = new.id
    ) then
      raise exception 'this container holds others — empty it before nesting it';
    end if;
  end if;
  return new;
end;
$$;;
;
create or replace function move_container(
  p_container uuid,
  p_parent uuid default null,
  p_location uuid default null
)
returns storage_containers
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row storage_containers;
  v_old_parent uuid;
  v_old_location uuid;
  v_kind text;
  v_parent_kind text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_parent is not null and p_location is not null then
    raise exception 'pick one destination — inside a container or at a spot, not both';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  select kind into v_kind from storage_containers where id = p_container;
  if v_kind = 'building' then
    raise exception 'the building does not move';
  end if;

  if p_parent is not null then
    select kind into v_parent_kind
    from storage_containers where id = p_parent and active;
    if v_parent_kind is null then
      raise exception 'destination container not found or inactive';
    end if;
    if v_parent_kind = 'crate' then
      raise exception 'nothing goes inside a crate — a crate is the smallest box there is';
    end if;
    if v_kind = 'conex' and v_parent_kind <> 'truck' then
      raise exception 'a conex only rides on a truck';
    end if;
    if v_kind = 'truck' then
      raise exception 'a truck does not go inside anything';
    end if;
  end if;

  select parent_container_id, location_id into v_old_parent, v_old_location
  from storage_containers where id = p_container;

  update storage_containers
  set parent_container_id = p_parent,
      location_id = p_location
  where id = p_container
  returning * into v_row;

  insert into movements
    (container_id, event, from_container_id, to_container_id,
     from_location_id, to_location_id, actor)
  values
    (p_container, 'moved', v_old_parent, p_parent, v_old_location, p_location,
     auth.uid()::text);

  insert into movements (package_id, event, to_container_id, actor, reason)
  select p.id, 'moved', p.container_id, auth.uid()::text,
         'rode along — ' || v_row.name || ' moved'
  from packages p
  where p.status = 'stored'
    and (
      p.container_id = p_container
      or p.container_id in (
        select id from storage_containers where parent_container_id = p_container
      )
    );

  return v_row;
end;
$$;;
;
create or replace function count_supply(
  p_supply uuid,
  p_counted numeric
)
returns supplies
language plpgsql
security definer
as $$
declare
  v_row supplies;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_counted is null or p_counted < 0 then
    raise exception 'a shelf count can''t be negative';
  end if;

  update supplies
  set on_hand = p_counted,
      last_counted_at = now()
  where id = p_supply
  returning * into v_row;
  if not found then
    raise exception 'that supply is not in the catalog';
  end if;

  insert into movements (supply_id, event, qty, actor)
  values (p_supply, 'count_verified', p_counted, auth.uid()::text);

  return v_row;
end;
$$;;
;
create or replace function public.job_staging_bay(p_project uuid)
returns uuid
language sql
stable
security definer
as $$
  select l.id
  from locations l
  join projects p on p.job_code = l.rack
  where p.id = p_project and l.zone = 'J' and l.active
  order by l.slot
  limit 1;
$$;;
;
create or replace function stage_packages(p_packages uuid[], p_project uuid)
returns int
language plpgsql
security definer
as $$
declare
  v_bay uuid;
  v_id uuid;
  v_prev uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is staged for';
  end if;

  v_bay := public.job_staging_bay(p_project);
  if v_bay is null then
    raise exception 'this job has no staging bay yet'
      using hint = 'no_staging_bay';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id into v_prev
    from packages
    where id = v_id and status in ('received', 'stored');
    if not found then
      continue; -- blank stickers and checked-out packages cannot be staged
    end if;

    update packages
    set status = 'stored', container_id = null, location_id = v_bay
    where id = v_id;

    insert into movements
      (package_id, event, from_container_id, to_location_id, project_id, actor, reason)
    values (v_id, 'staged', v_prev, v_bay, p_project, auth.uid()::text,
            'staged for the job');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;;
;
create or replace function merge_mark_spec_extra(
  p_id uuid,
  p_patch jsonb default '{}'::jsonb,
  p_drop text[] default '{}'::text[]
)
returns project_mark_specs
language plpgsql
security definer
as $$
declare
  v_row project_mark_specs;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'only a foreman-level user or above can edit mark specs';
  end if;

  update project_mark_specs
  set extra = (coalesce(extra, '{}'::jsonb) || coalesce(p_patch, '{}'::jsonb))
              - coalesce(p_drop, '{}'::text[]),
      source = 'manual'
  where id = p_id
  returning * into v_row;

  if not found then
    raise exception 'that mark spec no longer exists';
  end if;
  return v_row;
end;
$$;;
;
create or replace function add_supply(p_name text, p_unit text default 'ea')
returns supplies
language plpgsql
security definer
as $$
declare
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_row supplies;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if v_name is null then
    raise exception 'give the supply a name';
  end if;

  -- Case-insensitive duplicate guard: "Caulk", "caulk" and "CAULK" are one
  -- supply, and a split catalog makes every count on it meaningless.
  select * into v_row from supplies where lower(name) = lower(v_name) limit 1;
  if found then
    return v_row;
  end if;

  insert into supplies (name, unit)
  values (v_name, coalesce(nullif(trim(coalesce(p_unit, '')), ''), 'ea'))
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function take_supply(
  p_supply uuid,
  p_project uuid,
  p_qty numeric,
  p_client_id uuid
)
returns supplies
language plpgsql
security definer
as $$
declare
  v_row supplies;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  -- Belt and braces. Leaving the key off can't even reach this function (the
  -- 3-arg version no longer exists), but a caller can still pass an explicit
  -- null, and that must fail loudly rather than quietly skip the guard.
  if p_client_id is null then
    raise exception 'this take is missing the id that keeps it from counting twice';
  end if;

  -- The replay check runs FIRST and short-circuits everything, same as
  -- clock_in's. This take already landed on an earlier try whose answer never
  -- made it back to the phone. Hand back where the count stands now: the
  -- phone needs a success so it stops retrying, and nobody did anything wrong.
  if exists (select 1 from movements where client_id = p_client_id) then
    select * into v_row from supplies where id = p_supply;
    return v_row;
  end if;

  if p_qty is null or p_qty <= 0 then
    raise exception 'how many did you take?';
  end if;
  if p_project is null then
    raise exception 'pick the job this is for';
  end if;
  if not exists (select 1 from supplies where id = p_supply) then
    raise exception 'that supply is not in the catalog';
  end if;

  -- Claim the key before the count moves. Two phones draining the same take at
  -- the same instant both pass the check above; the index is what decides it.
  -- The loser lands here, subtracts nothing, and answers with the count the
  -- winner left behind.
  begin
    insert into movements (supply_id, event, project_id, qty, actor, client_id)
    values (p_supply, 'took', p_project, p_qty, auth.uid()::text, p_client_id);
  exception when unique_violation then
    select * into v_row from supplies where id = p_supply;
    return v_row;
  end;

  -- The running count floors at zero: a negative "about" number reads as
  -- broken, the movement keeps the true quantity, and the next shelf count
  -- corrects the estimate anyway.
  update supplies
  set on_hand = case when on_hand is null then null
                     else greatest(on_hand - p_qty, 0) end
  where id = p_supply
  returning * into v_row;
  if not found then
    raise exception 'that supply is not in the catalog';
  end if;

  -- The pull list ticks itself off when a take matches it: flip the OLDEST
  -- open request for this supply on this job to 'picked'. A take with no
  -- matching request is fine and stays recorded — the list is a plan, the
  -- movement is what happened.
  update supply_orders
  set status = 'picked'
  where id = (
    select id from supply_orders
    where supply_id = p_supply and project_id = p_project
      and status in ('needed', 'ordered')
    order by created_at
    limit 1
  );

  return v_row;
end;
$$;;
;
create or replace function store_packages(
  p_packages uuid[],
  p_container uuid,
  p_expected jsonb
)
returns jsonb
language plpgsql
security definer
-- Pinned because this runs as the owner and RLS is off inside it. There is a
-- whole migration in this repo (20260729210100) that exists because this was
-- forgotten twice; the neighbours it copies are still unpinned, and that is
-- the reason to pin here rather than the reason not to.
set search_path = public
as $$
declare
  v_id uuid;
  v_status text;
  v_container uuid;
  v_location uuid;
  v_serial text;
  v_note jsonb;
  v_exp_status text;
  v_exp_container uuid;
  v_hit int;
  v_stored int := 0;
  v_refused jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    -- `select into` sets every target to null when nothing comes back, and
    -- packages.status is NOT NULL, so a null status here means one thing:
    -- there is no such package. Read that instead of `FOUND`, which several
    -- later statements in this loop would clobber.
    select p.status, p.container_id, p.location_id, p.serial
      into v_status, v_container, v_location, v_serial
    from packages p
    where p.id = v_id;

    -- Already sitting exactly where this check-in was sending it. That is
    -- this same write arriving a second time — the answer to the first one
    -- got lost, or a foreman pressed Try again after another package in the
    -- batch was refused. It is done. Counting it and writing NO movement row
    -- keeps the history honest about how many times the package moved, and
    -- makes the whole call safe to send again.
    if v_status = 'stored' and v_container is not distinct from p_container then
      v_stored := v_stored + 1;
      continue;
    end if;

    v_note := coalesce(p_expected, '{}'::jsonb) -> v_id::text;
    v_exp_status := v_note ->> 'status';
    v_exp_container := nullif(v_note ->> 'container', '')::uuid;

    -- Apply only what the phone can vouch for. Three ways to fall out of this
    -- and every one of them ends up reported rather than skipped:
    --   * there is no such package;
    --   * the note has nothing for it, so we cannot tell whether it is still
    --     true (this is what a check-in queued by an older bundle looks like);
    --   * the note says it was a blank sticker, which was never storable —
    --     the old version skipped that one in silence, which is exactly the
    --     habit this migration exists to break.
    if v_status is not null
       and v_exp_status is not null
       and v_exp_status in ('received', 'stored', 'checked_out')
    then
      -- The compare and the write are ONE statement on purpose. Reading the
      -- row first and updating after leaves a gap another actor fits inside;
      -- putting the note in the WHERE clause makes the database do the
      -- comparing, against the row as it stands at the instant of the write.
      --
      -- location_id is cleared because a package in a container is not also
      -- on a shelf — `packages_one_place_ck` says so, and a package that was
      -- set aside on a job's bay is a real, everyday check-in candidate.
      update packages
      set status = 'stored',
          container_id = p_container,
          location_id = null
      where id = v_id
        and status = v_exp_status
        and container_id is not distinct from v_exp_container;
      get diagnostics v_hit = row_count;

      if v_hit = 1 then
        -- The previous container is v_exp_container and not a fresh read:
        -- the update only touched the row BECAUSE the two matched, so the
        -- note is the proven old value. Same movement row the old version
        -- wrote, so history reads identically for every check-in that lands.
        insert into movements (package_id, event, from_container_id, to_container_id, actor)
        values (
          v_id,
          case when v_exp_container is null then 'stored' else 'moved' end,
          v_exp_container,
          p_container,
          auth.uid()::text
        );
        v_stored := v_stored + 1;
        continue;
      end if;

      -- The note matched a moment ago and does not now: somebody wrote to
      -- this row between the read at the top of the loop and the update.
      -- Re-read so the refusal names what is actually true.
      select p.status, p.container_id, p.location_id, p.serial
        into v_status, v_container, v_location, v_serial
      from packages p
      where p.id = v_id;
    end if;

    -- Refused. Say which package and what beat it, in facts the app can turn
    -- into a sentence: the serial a person reads off the sticker, the state
    -- the package is really in, the container it is really in, and — when it
    -- was checked out — the job it went to.
    v_refused := v_refused || jsonb_build_array(jsonb_build_object(
      'id', v_id,
      'serial', v_serial,
      'status', v_status,
      'container', (
        select c.name from storage_containers c where c.id = v_container
      ),
      -- The shelf, when the package went onto a job's bay instead. Its sibling
      -- (stage_packages) has always sent this, and the app has a sentence
      -- ready for it — "it is on shelf J-BLACK22-A now" — which was
      -- unreachable for check-ins because this key was never here. That is
      -- the very case F3 made likely: set-aside became queueable, so a
      -- check-in now loses to a set-aside far more often than it used to.
      'location', (
        select l.address from locations l where l.id = v_location
      ),
      'job', case when v_status = 'checked_out' then (
        select pr.job_code
        from movements m
        join projects pr on pr.id = m.project_id
        where m.package_id = v_id and m.event = 'checked_out'
        order by m.created_at desc
        limit 1
      ) end
    ));
  end loop;

  return jsonb_build_object(
    'stored', v_stored,
    'container', (select c.name from storage_containers c where c.id = p_container),
    'refused', v_refused
  );
end;
$$;;
;
create or replace function stage_packages(
  p_packages uuid[],
  p_project uuid,
  p_expected jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_bay uuid;
  v_id uuid;
  v_status text;
  v_container uuid;
  v_location uuid;
  v_serial text;
  v_note jsonb;
  v_exp_status text;
  v_exp_container uuid;
  v_exp_location uuid;
  v_hit int;
  v_staged int := 0;
  v_refused jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is staged for';
  end if;

  v_bay := public.job_bay_box(p_project);

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select p.status, p.container_id, p.location_id, p.serial
      into v_status, v_container, v_location, v_serial
    from packages p
    where p.id = v_id;

    -- Already in the bay: the same write arriving twice. Done, no new line.
    if v_status = 'stored' and v_container is not distinct from v_bay then
      v_staged := v_staged + 1;
      continue;
    end if;

    v_note := coalesce(p_expected, '{}'::jsonb) -> v_id::text;
    v_exp_status := v_note ->> 'status';
    v_exp_container := nullif(v_note ->> 'container', '')::uuid;
    v_exp_location := nullif(v_note ->> 'location', '')::uuid;

    if v_status is not null
       and v_exp_status is not null
       and v_exp_status in ('received', 'stored')
    then
      update packages
      set status = 'stored',
          container_id = v_bay,
          location_id = null
      where id = v_id
        and status = v_exp_status
        and container_id is not distinct from v_exp_container
        and location_id is not distinct from v_exp_location;
      get diagnostics v_hit = row_count;

      if v_hit = 1 then
        insert into movements
          (package_id, event, from_container_id, from_location_id,
           to_container_id, project_id, actor, reason)
        values (v_id, 'staged', v_exp_container, v_exp_location,
                v_bay, p_project, auth.uid()::text, 'set aside in the job''s bay');
        v_staged := v_staged + 1;
        continue;
      end if;

      select p.status, p.container_id, p.location_id, p.serial
        into v_status, v_container, v_location, v_serial
      from packages p
      where p.id = v_id;
    end if;

    v_refused := v_refused || jsonb_build_array(jsonb_build_object(
      'id', v_id,
      'serial', v_serial,
      'status', v_status,
      'container', (
        select c.name from storage_containers c where c.id = v_container
      ),
      'location', (
        select l.address from locations l where l.id = v_location
      ),
      'job', case when v_status = 'checked_out' then (
        select pr.job_code
        from movements m
        join projects pr on pr.id = m.project_id
        where m.package_id = v_id and m.event = 'checked_out'
        order by m.created_at desc
        limit 1
      ) end
    ));
  end loop;

  return jsonb_build_object(
    'staged', v_staged,
    'job', (select pr.job_code from projects pr where pr.id = p_project),
    -- Was the slot's address; the bay is a box now, so its name.
    'bay', (select c.name from storage_containers c where c.id = v_bay),
    'refused', v_refused
  );
end;
$$;;
;
create or replace function save_storage_container(
  p_id uuid,
  p_name text,
  p_address text default null,
  p_access_code text default null,
  p_notes text default null,
  p_active boolean default true,
  p_kind text default null,
  p_length_cm numeric default null,
  p_width_cm numeric default null,
  p_height_cm numeric default null,
  p_weight_kg numeric default null
)
returns storage_containers
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row storage_containers;
  v_old_address text;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'a container needs a name';
  end if;

  if p_id is null then
    if coalesce(p_kind, 'conex') = 'building'
       and exists (select 1 from storage_containers where kind = 'building') then
      raise exception 'there is already a building — the main warehouse is one of a kind';
    end if;
    insert into storage_containers
      (name, address, access_code, notes, active, kind,
       length_cm, width_cm, height_cm, weight_kg)
    values
      (trim(p_name), p_address, p_access_code, p_notes, coalesce(p_active, true),
       coalesce(p_kind, 'conex'),
       p_length_cm, p_width_cm, p_height_cm, p_weight_kg)
    returning * into v_row;
  else
    select address into v_old_address from storage_containers where id = p_id;
    if not found then
      raise exception 'container not found';
    end if;

    update storage_containers
    set name = trim(p_name), address = p_address, access_code = p_access_code,
        notes = p_notes, active = coalesce(p_active, true),
        length_cm = p_length_cm, width_cm = p_width_cm,
        height_cm = p_height_cm, weight_kg = p_weight_kg
    where id = p_id
    returning * into v_row;

    -- The trail. Whitespace-insensitive so a stray space is not a "move", and
    -- written AFTER the update so a failed update writes no phantom line.
    if nullif(trim(coalesce(v_old_address, '')), '')
       is distinct from nullif(trim(coalesce(p_address, '')), '') then
      insert into movements (container_id, event, actor, reason)
      values (
        p_id,
        'moved',
        auth.uid()::text,
        case
          when nullif(trim(coalesce(v_old_address, '')), '') is null
            then 'address set: ' || trim(p_address)
          when nullif(trim(coalesce(p_address, '')), '') is null
            then 'address cleared — was ' || trim(v_old_address)
          else 'address changed: ' || trim(v_old_address) || ' → ' || trim(p_address)
        end
      );
    end if;
  end if;
  return v_row;
end;
$$;;
;
create or replace function packages_clear_area_on_move()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.container_id is distinct from old.container_id
     or new.location_id is distinct from old.location_id then
    new.area := null;
  end if;
  return new;
end;
$$;;
