create or replace function cancel_summon_help(p_summon_id uuid)
returns summon_helpers
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_summon summons;
  v_row summon_helpers;
begin
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.status = 'closed' then
    raise exception 'this summon already ended';
  end if;

  update summon_helpers
  set canceled_at = now(), minutes = 0
  where summon_id = p_summon_id and profile_id = v_uid
    and completed_at is null and canceled_at is null
  returning * into v_row;
  if v_row.id is null then
    raise exception 'no open help of yours on this summon';
  end if;

  -- The 10 answer points come back off — a matching negative entry, so the
  -- ledger reads as the story actually went.
  insert into points_ledger (profile_id, kind, points, ref, status)
  values (v_uid, 'summon_answer_canceled', -10, p_summon_id::text, 'confirmed');

  -- A covered summon with a freed seat is open again.
  if v_summon.status = 'covered' then
    update summons set status = 'open' where id = p_summon_id;
  end if;

  return v_row;
end;
$$;;
;
create or replace function create_summon(
  p_opening_id uuid,
  p_needed int,
  p_lead_minutes int default null,
  p_note text default null
)
returns summons
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_project uuid;
  v_row summons;
begin
  if p_needed is null or p_needed < 1 or p_needed > 8 then
    raise exception 'ask for between 1 and 8 helpers';
  end if;
  if p_lead_minutes is not null and (p_lead_minutes < 5 or p_lead_minutes > 480) then
    raise exception 'lead time must be between 5 minutes and 8 hours';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'keep the note under 500 characters';
  end if;
  select project_id into v_project from project_openings where id = p_opening_id;
  if v_project is null then
    raise exception 'opening not found';
  end if;
  if exists (
    select 1 from summons
    where opening_id = p_opening_id
      and status in ('open', 'covered')
      and created_at >= now() - interval '1 day'
  ) then
    raise exception 'a summon is already live on this window';
  end if;
  insert into summons (project_id, opening_id, requested_by, needed, needed_at, note)
  values (
    v_project, p_opening_id, v_uid, p_needed,
    case when p_lead_minutes is null then null
         else now() + make_interval(mins => p_lead_minutes) end,
    nullif(trim(p_note), '')
  )
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function public.clock_out(
  p_shift_id uuid,
  p_photo text default null,
  p_injured boolean default false,
  p_time_confirmed boolean default true,
  p_break_seconds int default null,
  p_lat double precision default null,
  p_lng double precision default null,
  p_injury_note text default null
)
returns public.time_shifts language plpgsql set search_path = public, pg_temp as $$
declare v_shift public.time_shifts;
begin
  update public.time_shifts
  set clock_out_at = now(),
      last_punch_at = now(),
      clock_out_photo = coalesce(p_photo, clock_out_photo),
      injured = p_injured,
      injury_note = case when p_injured then nullif(trim(coalesce(p_injury_note, '')), '') else null end,
      time_confirmed = p_time_confirmed,
      break_seconds = coalesce(p_break_seconds, break_seconds),
      break_started_at = null,
      break_type = null,
      clock_out_lat = coalesce(p_lat, clock_out_lat),
      clock_out_lng = coalesce(p_lng, clock_out_lng),
      signed_at = now(),
      status = 'submitted'
  where id = p_shift_id and profile_id = auth.uid()
    and status = 'open' and clock_out_at is null
  returning * into v_shift;
  if v_shift is null then
    if exists (select 1 from public.time_shifts where id = p_shift_id and profile_id = auth.uid()) then
      raise exception 'This shift was already clocked out. Nothing was changed.';
    end if;
    raise exception 'no open shift %', p_shift_id;
  end if;
  return v_shift;
end;
$$;;
;
create or replace function arrive_packages(
  p_ok uuid[],
  p_damaged uuid[],
  p_project uuid,
  p_note text default null,
  p_photos jsonb default '{}'::jsonb
)
returns int
language plpgsql
security definer
as $$
declare
  v_id uuid;
  v_note text;
  v_serial text;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material arrived at';
  end if;
  v_note := nullif(trim(coalesce(p_note, '')), '');

  foreach v_id in array coalesce(p_ok, array[]::uuid[])
  loop
    if not exists (
      select 1 from packages where id = v_id and status = 'checked_out'
    ) then
      continue;
    end if;
    insert into movements (package_id, event, project_id, actor, reason)
    values (v_id, 'unloaded', p_project, auth.uid()::text,
            coalesce('arrived on site — ' || v_note, 'arrived on site'));
    v_count := v_count + 1;
  end loop;

  foreach v_id in array coalesce(p_damaged, array[]::uuid[])
  loop
    select serial into v_serial from packages where id = v_id and status = 'checked_out';
    if v_serial is null then
      continue;
    end if;

    insert into movements (package_id, event, project_id, actor, reason)
    values (v_id, 'damaged', p_project, auth.uid()::text,
            coalesce('damaged on arrival — ' || v_note, 'damaged on arrival'));

    -- Deduped per package, mirroring the unit-side rule: a second report on
    -- the same package while the first is still open is the same problem.
    -- The photo follows the same rule the note already did — a repeat report
    -- on a package that already has an open issue does not retro-fit either
    -- one onto history it didn't carry when that issue was opened.
    if not exists (
      select 1 from issues
      where package_id = v_id and kind = 'damage' and status = 'open'
    ) then
      insert into issues (project_id, package_id, kind, urgency, note, created_by, photo_path)
      values (
        p_project, v_id, 'damage', 'urgent',
        coalesce('Package ' || v_serial || ' damaged on arrival — ' || v_note,
                 'Package ' || v_serial || ' damaged on arrival'),
        auth.uid(),
        p_photos ->> v_id::text
      );
    end if;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;;
;
create or replace function set_capability_badge(
  p_installer_id uuid,
  p_capability text,
  p_granted boolean
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_caller_role text;
begin
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'Only a foreman or above can grant or take away a badge.'
      using errcode = '42501';
  end if;
  if p_capability not in ('nail_fin', 'retrofit', 'doors', 'wet_glazing', 'curtain_wall') then
    raise exception 'That is not one of the five badges.';
  end if;
  if p_granted then
    insert into capability_badges (installer_id, capability, granted_by)
    values (p_installer_id, p_capability, auth.uid())
    on conflict (installer_id, capability) do nothing;
  else
    delete from capability_badges
    where installer_id = p_installer_id and capability = p_capability;
  end if;
end;
$$;;
