create or replace function add_job_crate(
  p_project uuid,
  p_name text default null
)
returns packages
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_n int;
  v_name text;
  v_row packages;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;
  select count(*) + 1 into v_n from packages
  where project_id = p_project and part_type = 'crate';
  v_name := upper(trim(coalesce(nullif(p_name, ''), 'Crate ' || v_n)));
  insert into packages
    (status, project_id, category, part_type, mfr_mark,
     short_code, bound_at, bound_by)
  values
    ('received', p_project, 'other', 'crate', v_name,
     issue_package_short_code(), now(), auth.uid()::text)
  returning * into v_row;
  insert into movements (package_id, event, project_id, actor, reason)
  values (v_row.id, 'received', p_project, auth.uid()::text,
          'one more crate than the list said — added to match reality');
  return v_row;
end;
$$;;
;
create or replace function update_delivery(
  p_delivery uuid,
  p_label text default null,
  p_expected_at timestamptz default null
)
returns package_deliveries
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_row package_deliveries;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  update package_deliveries
  set label = coalesce(nullif(trim(coalesce(p_label, '')), ''), label),
      expected_at = coalesce(p_expected_at, expected_at)
  where id = p_delivery
  returning * into v_row;
  if not found then
    raise exception 'That delivery is gone.';
  end if;
  -- The schedule entry follows the truck's new time.
  if p_expected_at is not null then
    update schedule_assignments
    set start_date = p_expected_at::date,
        end_date = p_expected_at::date,
        start_time = p_expected_at::time
    where delivery_id = p_delivery;
  end if;
  return v_row;
end;
$$;;
;
create or replace function delete_delivery(p_delivery uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_killed int;
  v_kept int;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can delete a delivery.'
      using errcode = '42501';
  end if;
  select count(*) filter (where status = 'minted'),
         count(*) filter (where status <> 'minted')
    into v_killed, v_kept
  from packages where delivery_id = p_delivery;

  delete from packages where delivery_id = p_delivery and status = 'minted';
  delete from package_deliveries where id = p_delivery;

  return jsonb_build_object('killed', coalesce(v_killed, 0), 'kept', coalesce(v_kept, 0));
end;
$$;;
;
CREATE OR REPLACE FUNCTION public.schedule_delivery(p_delivery uuid, p_when timestamp with time zone, p_member_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text;
  v_label text;
  v_assignment uuid;
  v_member uuid;
begin
  select role into v_role from profiles where id = auth.uid();
  if public.is_partner_user() or v_role is null or v_role not in ('supervisor', 'owner', 'admin', 'big_boss') then
    raise exception 'Only a supervisor or above can put a delivery on the schedule.'
      using errcode = '42501';
  end if;
  if p_when is null then
    raise exception 'Pick the date and time the truck comes.';
  end if;
  select label into v_label from package_deliveries where id = p_delivery;
  if v_label is null then
    raise exception 'That delivery is gone.';
  end if;

  update package_deliveries set expected_at = p_when where id = p_delivery;

  select id into v_assignment from schedule_assignments
  where delivery_id = p_delivery;

  if v_assignment is null then
    insert into schedule_assignments
      (kind, delivery_id, project_id, start_date, end_date, start_time,
       status, note, created_by, published_at)
    values
      ('delivery', p_delivery, null, p_when::date, p_when::date, p_when::time,
       'published', 'Meet the truck — ' || v_label, auth.uid(), now())
    returning id into v_assignment;
  else
    update schedule_assignments
    set start_date = p_when::date,
        end_date = p_when::date,
        start_time = p_when::time,
        status = 'published',
        note = 'Meet the truck — ' || v_label,
        published_at = coalesce(published_at, now())
    where id = v_assignment;
  end if;

  delete from schedule_assignment_members where assignment_id = v_assignment;
  foreach v_member in array coalesce(p_member_ids, array[]::uuid[])
  loop
    insert into schedule_assignment_members (assignment_id, profile_id, role)
    values (v_assignment, v_member, 'installer')
    on conflict do nothing;
  end loop;

  return v_assignment;
end;
$function$;;
;
create or replace function public.set_project_test(p_project uuid, p_is_test boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_zztest_id uuid;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can flag a job as a testing project';
  end if;

  update projects set is_test = p_is_test where id = p_project;
  if not found then
    raise exception 'that job does not exist';
  end if;

  if p_is_test then
    insert into sandbox_projects (project_id, note)
    values (p_project, 'Testing project — flagged in-app')
    on conflict (project_id) do nothing;
  else
    -- Never remove the dedicated automation-sandbox job (ZZTEST, seeded by
    -- 20260730220000) from this list even if somebody toggles the testing
    -- flag off on it by mistake — that would silently cut off the QA test
    -- login's only writable project. Every OTHER project this RPC ever
    -- added to sandbox_projects, it may also remove.
    select id into v_zztest_id from projects where job_code = 'ZZTEST';
    if v_zztest_id is null or p_project <> v_zztest_id then
      delete from sandbox_projects where project_id = p_project;
    end if;
  end if;
end;
$$;;
;
create or replace function public.delete_test_project(p_project uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text;
  v_project projects;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role not in ('owner', 'big_boss') then
    raise exception 'only an owner can permanently delete a testing project';
  end if;

  select * into v_project from projects where id = p_project;
  if v_project is null then
    raise exception 'that job does not exist';
  end if;
  if not v_project.is_test then
    raise exception 'only a job flagged as a testing project can be permanently deleted this way';
  end if;

  delete from packages where project_id = p_project;
  delete from projects where id = p_project;
end;
$$;;
;
create or replace function add_delivery_set(
  p_delivery uuid,
  p_project uuid,
  p_job_name text,
  p_mark text,
  p_kind text,
  p_package_count int,
  p_crate_name text default null,
  p_crate_pieces int default null,
  p_crate_part_type text default null
)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not exists (select 1 from package_deliveries where id = p_delivery) then
    raise exception 'That delivery does not exist.';
  end if;
  if p_kind not in ('window', 'door') then
    raise exception 'A set is a window or a door.';
  end if;

  return public.create_delivery_set(
    p_delivery, p_project, p_mark, p_kind, p_package_count,
    p_crate_name, p_crate_pieces, p_crate_part_type,
    1, p_job_name, null
  );
end;
$$;;
;
create or replace function add_crate_supplies(
  p_project uuid,
  p_job_name text,
  p_part_type text,
  p_pieces int
)
returns packages
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row packages;
  v_type text := lower(nullif(trim(coalesce(p_part_type, '')), ''));
  v_name text := nullif(trim(coalesce(p_job_name, '')), '');
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if v_type is null or length(v_type) not between 1 and 40 then
    raise exception 'Say what the supply is — 1 to 40 characters.';
  end if;
  if p_pieces is null or p_pieces < 1 or p_pieces > 99 then
    raise exception 'How many pieces ride in the crates? 1 to 99.';
  end if;
  if p_project is null and v_name is null then
    raise exception 'Crate supplies belong to a job — picked, or at least named.';
  end if;
  if p_project is not null and not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  insert into packages
    (status, project_id, pending_job_name, category, part_type, piece_count,
     short_code, bound_at, bound_by)
  values
    ('received', p_project,
     case when p_project is null then v_name end,
     'other', v_type, p_pieces,
     issue_package_short_code(), now(), auth.uid()::text)
  returning * into v_row;

  insert into movements (package_id, event, project_id, actor, reason)
  values (v_row.id, 'received', p_project, auth.uid()::text,
          'supply logged into the crates — ' || p_pieces || ' × ' || v_type);

  return v_row;
end;
$$;;
;
create or replace function set_project_status(p_project uuid, p_status text)
returns projects
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row projects;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or owner can finish, cancel, or reopen a job.'
      using errcode = '42501';
  end if;
  if p_status not in ('active', 'completed', 'cancelled') then
    raise exception 'A job is active, completed, or cancelled — nothing else.';
  end if;

  update projects
     set status = p_status,
         status_changed_at = now()
   where id = p_project
  returning * into v_row;
  if v_row.id is null then
    raise exception 'That job does not exist.';
  end if;
  return v_row;
end;
$$;;
;
create or replace function public.delete_project(p_project uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_n int;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can delete a job.' using errcode = '42501';
  end if;
  if not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  select count(*) into v_n from packages where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % tracked package%. Complete or cancel it instead — deleting would erase where material went.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;
  select count(*) into v_n from project_openings where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % opening% on its plans. Complete or cancel it instead.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;
  select count(*) into v_n from time_shifts where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % clocked shift%. Complete or cancel it instead — hours are payroll.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;

  delete from project_marks where project_id = p_project;
  delete from sandbox_projects where project_id = p_project;
  delete from projects where id = p_project;
end;
$$;;
;
create or replace function edit_shift(
  p_shift_id uuid,
  p_project_id uuid default null,
  p_cost_code_id uuid default null,
  p_clock_in_at timestamptz default null,
  p_clock_out_at timestamptz default null,
  p_break_seconds int default null,
  p_note text default null
)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old time_shifts;
  v_shift time_shifts;
  v_signed boolean;
  v_changed boolean;
begin
  if auth.uid() is null or public.is_partner_user() then
    raise exception 'A crew login is required.';
  end if;
  if p_note is null or btrim(p_note) = '' then
    raise exception 'an edit needs a reason note';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;

  if not public.can_edit_timecard(v_old.profile_id) then
    raise exception 'Foremen may edit their own time and installers; supervisor time requires a supervisor.';
  end if;
  if v_old.status = 'voided' then
    raise exception 'Restore this removed punch before editing it.';
  end if;
  v_changed := (coalesce(p_project_id,v_old.project_id) is distinct from v_old.project_id)
    or (coalesce(p_cost_code_id,v_old.cost_code_id) is distinct from v_old.cost_code_id)
    or (coalesce(p_clock_in_at,v_old.clock_in_at) is distinct from v_old.clock_in_at)
    or (coalesce(p_clock_out_at,v_old.clock_out_at) is distinct from v_old.clock_out_at)
    or (coalesce(p_break_seconds,v_old.break_seconds) is distinct from v_old.break_seconds);
  v_signed := exists (
    select 1 from timecard_periods
    where profile_id = v_old.profile_id
      and employee_signed_at is not null
      and period_start <= v_old.clock_in_at
      and v_old.clock_in_at < period_start + interval '14 days'
  );

  update time_shifts
     set project_id    = coalesce(p_project_id, project_id),
         cost_code_id  = coalesce(p_cost_code_id, cost_code_id),
         clock_in_at   = coalesce(p_clock_in_at, clock_in_at),
         clock_out_at  = coalesce(p_clock_out_at, clock_out_at),
         break_seconds = coalesce(p_break_seconds, break_seconds),
         edited_note   = p_note,
         edited_by     = auth.uid(),
         edited_at     = now(),
         edited_after_signing = edited_after_signing or v_signed,
         status        = case
                           when v_old.status = 'approved' and v_changed
                             then 'submitted'
                           when v_old.status = 'rejected'
                             then 'submitted'
                           when p_clock_out_at is not null
                                and v_old.status in ('open', 'needs_finish')
                             then 'submitted'
                           else v_old.status
                         end,
         approved_by   = case
                           when v_old.status = 'approved' and v_changed
                             then null
                           else approved_by
                         end,
         approved_at   = case
                           when v_old.status = 'approved' and v_changed
                             then null
                           else approved_at
                         end
   where id = p_shift_id
   returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  select p_shift_id, auth.uid(), d.field, d.old_value, d.new_value, btrim(p_note)
  from (values
    ('project_id',    v_old.project_id::text,    v_shift.project_id::text),
    ('cost_code_id',  v_old.cost_code_id::text,  v_shift.cost_code_id::text),
    ('clock_in_at',   v_old.clock_in_at::text,   v_shift.clock_in_at::text),
    ('clock_out_at',  v_old.clock_out_at::text,  v_shift.clock_out_at::text),
    ('break_seconds', v_old.break_seconds::text, v_shift.break_seconds::text),
    ('status',        v_old.status,              v_shift.status)
  ) as d(field, old_value, new_value)
  where d.old_value is distinct from d.new_value;

  return v_shift;
end;
$$;;
;
create or replace function void_shift(p_shift_id uuid, p_reason text)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old time_shifts;
  v_shift time_shifts;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can delete crew time';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'deleting a punch needs a reason';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status = 'voided' then
    raise exception 'this punch is already deleted';
  end if;

  update time_shifts
     set status        = 'voided',
         voided_at     = now(),
         voided_by     = auth.uid(),
         voided_reason = btrim(p_reason),
         approved_by   = null,
         approved_at   = null
   where id = p_shift_id
   returning * into v_shift;

  -- The Horizon fake-success lesson, cited per the spec: an UPDATE that
  -- matches nothing (RLS silently excluded the row, or it moved under us)
  -- must never be reported back as though the void happened. Belt-and-
  -- suspenders alongside the `for update` row lock above, which already
  -- makes this unreachable today — kept explicit so a future refactor that
  -- drops the lock still fails loudly instead of lying. (This exact phrase
  -- isn't written down anywhere else in this repo that a search could find;
  -- recording the reasoning here rather than a citation I can't verify.)
  if v_shift.id is null then
    raise exception 'void did not apply to shift % — no row was updated', p_shift_id;
  end if;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', v_old.status, 'voided', btrim(p_reason));

  return v_shift;
end;
$$;;
;
create or replace function restore_shift(p_shift_id uuid)
returns time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old time_shifts;
  v_shift time_shifts;
  v_restored_status text;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can restore crew time';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status <> 'voided' then
    raise exception 'this punch is not deleted';
  end if;

  v_restored_status := case when v_old.clock_out_at is not null then 'submitted' else 'open' end;

  update time_shifts
     set status        = v_restored_status,
         voided_at     = null,
         voided_by     = null,
         voided_reason = null,
         approved_by   = null,
         approved_at   = null
   where id = p_shift_id
   returning * into v_shift;

  if v_shift.id is null then
    raise exception 'restore did not apply to shift % — no row was updated', p_shift_id;
  end if;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', 'voided', v_restored_status, 'restored');

  return v_shift;
end;
$$;;
;
create or replace function sign_my_timecard(p_period_start timestamptz)
returns timecard_periods
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_row timecard_periods;
begin
  if p_period_start is null then
    raise exception 'a period start is required';
  end if;
  -- The card that offers this only shows once the period has ended, but a
  -- server-side guard means the RPC itself can never be talked into
  -- attesting to a period still in progress, from any client.
  if p_period_start + interval '14 days' > now() then
    raise exception 'this pay period has not ended yet';
  end if;

  insert into timecard_periods (profile_id, period_start, employee_signed_at)
  values (v_uid, p_period_start, now())
  on conflict (profile_id, period_start)
    do update set employee_signed_at = now()
  returning * into v_row;

  return v_row;
end;
$$;;
;
create or replace function countersign_timecard(p_profile_id uuid, p_period_start timestamptz)
returns timecard_periods
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row timecard_periods;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can countersign a timecard';
  end if;

  select * into v_row from timecard_periods
    where profile_id = p_profile_id and period_start = p_period_start
    for update;
  if v_row is null or v_row.employee_signed_at is null then
    raise exception 'the crew member has not signed this period yet';
  end if;

  update timecard_periods
     set supervisor_signed_at = now(),
         supervisor_signed_by = auth.uid()
   where id = v_row.id
   returning * into v_row;

  if v_row.id is null then
    raise exception 'countersign did not apply — no row was updated';
  end if;

  return v_row;
end;
$$;;
;
create or replace function server_now()
returns timestamptz
language sql
stable
as $$
  select now();
$$;;
