create or replace function copy_unit(
  p_project uuid,
  p_mark text,
  p_times int,
  p_pooled boolean default false
)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_code text;
  v_mark uuid;
  v_src record;
  v_row packages;
  v_n int := 0;
  i int;
begin
  -- Warehouse work is crew work (ADR-0007): signed in, and not a builder
  -- login, is the whole door.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_times is null or p_times < 1 or p_times > 20 then
    raise exception 'copy a unit 1 to 20 times at once';
  end if;

  v_code := upper(trim(coalesce(p_mark, '')));
  select id into v_mark from project_marks
  where project_id = p_project and mark_code = v_code;
  if v_mark is null then
    raise exception 'window % is not on this job''s schedule', v_code;
  end if;

  -- One representative per part slot: the unit's shape, not its twins.
  for v_src in
    select distinct on (p.part_index, coalesce(p.part_type, ''), coalesce(p.piece_count, -1))
           p.category, p.part_index, p.part_total, p.part_type, p.piece_count, p.mfr_mark
    from packages p
    join package_marks pm on pm.package_id = p.id
    where pm.mark_id = v_mark and p.status <> 'blank'
    order by p.part_index, coalesce(p.part_type, ''), coalesce(p.piece_count, -1), p.created_at
  loop
    for i in 1..p_times loop
      insert into packages
        (status, project_id, category, part_index, part_total, part_type,
         piece_count, mfr_mark, tracking, short_code, bound_at, bound_by)
      values
        ('minted', p_project, v_src.category, v_src.part_index, v_src.part_total,
         v_src.part_type, v_src.piece_count, v_src.mfr_mark,
         case when p_pooled then 'pooled' else 'serial' end,
         issue_package_short_code(), now(), auth.uid()::text)
      returning * into v_row;
      insert into package_marks (package_id, mark_id) values (v_row.id, v_mark)
      on conflict do nothing;
      insert into movements (package_id, event, project_id, actor, reason)
      values (v_row.id, 'preissued', p_project, auth.uid()::text,
              'copy ' || i || ' of ' || p_times || ' of window ' || v_code
              || case when p_pooled then ' — rides on the original''s sticker' else '' end);
      v_n := v_n + 1;
    end loop;
  end loop;

  if v_n = 0 then
    raise exception 'window % has no packages to copy yet', v_code;
  end if;
  return v_n;
end;
$$;;
;
create or replace function set_mark_kind(p_project uuid, p_mark text, p_kind text)
returns project_marks
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_code text := upper(trim(coalesce(p_mark, '')));
  v_row project_marks;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_kind is null or p_kind not in ('window', 'door') then
    raise exception 'a unit is a window or a door';
  end if;
  update project_marks
  set kind = p_kind
  where project_id = p_project and mark_code = v_code
  returning * into v_row;
  if not found then
    raise exception 'window % is not on this job''s schedule', v_code;
  end if;
  return v_row;
end;
$$;;
;
create or replace function public.job_bay_box(p_project uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_code text;
begin
  select id into v_id from storage_containers
  where project_id = p_project and kind = 'bay' and active
  limit 1;
  if v_id is not null then
    return v_id;
  end if;
  select job_code into v_code from projects where id = p_project;
  if v_code is null then
    raise exception 'that job does not exist';
  end if;
  insert into storage_containers (name, kind, project_id, notes)
  values (v_code || ' bay', 'bay', p_project, 'This job''s own bay: what is set aside for it waits here.')
  returning id into v_id;
  return v_id;
end;
$$;;
;
create or replace function create_placeholder_job(p_name text)
returns projects
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_name text := trim(coalesce(p_name, ''));
  v_base text;
  v_code text;
  v_n int := 1;
  v_row projects;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if v_name = '' or length(v_name) > 80 then
    raise exception 'a job name is 1 to 80 characters';
  end if;

  -- A job by this name already exists (typed the same way twice at two
  -- trucks): hand that one back rather than make a twin.
  select * into v_row from projects
  where deleted_at is null and lower(name) = lower(v_name)
  order by created_at limit 1;
  if found then
    return v_row;
  end if;

  -- NEW-<first letters of the name>, numbered when that is taken. The
  -- office renames it from the job page; the code is a handle, not a name.
  v_base := 'NEW-' || left(upper(regexp_replace(v_name, '[^A-Za-z0-9]+', '', 'g')), 8);
  if v_base = 'NEW-' then
    v_base := 'NEW-JOB';
  end if;
  v_code := v_base;
  while exists (select 1 from projects where job_code = v_code) loop
    v_n := v_n + 1;
    v_code := v_base || '-' || v_n;
  end loop;

  insert into projects (job_code, name, notes)
  values (v_code, v_name, 'Made at the truck on ' || to_char(now(), 'YYYY-MM-DD') || ' for material that arrived before the office built the job. Rename the code and fill in the details.')
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function public.job_leftovers_line(p_project uuid)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select string_agg(place || ' ×' || n, ', ' order by n desc, place)
  from (
    select coalesce(c.name, 'not in a box yet') as place, count(*) as n
    from packages p
    left join storage_containers c on c.id = p.container_id
    where p.project_id = p_project
      and p.status in ('received', 'stored')
    group by 1
  ) t;
$$;;
;
create or replace function finalize_job_materials(p_project uuid)
returns projects
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row projects;
  v_left int;
  v_line text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can finalize a job''s material.'
      using errcode = '42501';
  end if;

  select * into v_row from projects where id = p_project and deleted_at is null;
  if not found then
    raise exception 'that job does not exist';
  end if;
  if v_row.materials_finalized_at is not null then
    return v_row;
  end if;

  select count(*) into v_left
  from packages
  where project_id = p_project and status in ('received', 'stored');
  if v_left > 0 then
    v_line := public.job_leftovers_line(p_project);
    raise exception '% package% still in the warehouse (%). Send them to the job site or move them to the Boneyard first.',
      v_left, case when v_left = 1 then ' is' else 's are' end, v_line;
  end if;

  update projects
  set materials_finalized_at = now(), materials_finalized_by = auth.uid()
  where id = p_project
  returning * into v_row;

  -- The job's bay has nothing in it (checked above); it goes quiet with the
  -- job. A fresh one is made if anything is ever set aside for it again.
  update storage_containers
  set active = false
  where project_id = p_project and kind = 'bay' and active;

  insert into movements (project_id, event, actor, reason)
  values (p_project, 'finalized', auth.uid()::text, 'unit movement finalized');

  return v_row;
end;
$$;;
;
create or replace function reopen_job_materials(p_project uuid)
returns projects
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row projects;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can reopen a job''s material.'
      using errcode = '42501';
  end if;

  update projects
  set materials_finalized_at = null, materials_finalized_by = null
  where id = p_project and deleted_at is null
  returning * into v_row;
  if not found then
    raise exception 'that job does not exist';
  end if;

  insert into movements (project_id, event, actor, reason)
  values (p_project, 'reopened', auth.uid()::text, 'material reopened in the warehouse');

  return v_row;
end;
$$;;
;
create or replace function boneyard_job_leftovers(p_project uuid)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_n int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  for v_id in
    select id from packages
    where project_id = p_project and status in ('received', 'stored')
  loop
    perform public.reassign_package(v_id, null, null, 'left over when the job''s material was finalized');
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;;
;
create or replace function public.upsert_build_facts(
  p_project_id uuid,
  p_patch jsonb
)
returns project_build_facts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_allowed constant text[] := array[
    'exterior_lines',
    'flashing_system', 'flashing_system_other', 'flashing_note',
    'fastener_type', 'fastener_type_other', 'fastener_length_in',
    'fastener_spacing_in', 'fastener_note',
    'site_rules', 'gc_contact_name', 'gc_contact_phone', 'elevation_notes'
  ];
  v_key text;
  v_line jsonb;
  v_line_key text;
  v_lines jsonb := '[]'::jsonb;
  v_exists boolean;
  v_checkin project_gc_checkins;
  v_seed jsonb := '{}'::jsonb;
  v_patch jsonb;
  v_row project_build_facts;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'Only a foreman or above can save job facts.';
  end if;
  if not exists (select 1 from projects where id = p_project_id) then
    raise exception 'That job does not exist.';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'Nothing to save.';
  end if;

  for v_key in select jsonb_object_keys(p_patch) loop
    if not (v_key = any(v_allowed)) then
      raise exception 'Job facts has no field called "%".', v_key;
    end if;
  end loop;

  if p_patch ? 'flashing_system' and p_patch->>'flashing_system' is not null
     and p_patch->>'flashing_system' not in ('butyl_tape', 'paper_flashing', 'fluid_applied', 'other') then
    raise exception 'Flashing system is butyl tape, paper flashing, fluid-applied, or other.';
  end if;
  if p_patch ? 'fastener_type' and p_patch->>'fastener_type' is not null
     and p_patch->>'fastener_type' not in ('flange_screw', 'jamb_screw', 'concrete_screw', 'other') then
    raise exception 'Fastener type is flange screw, jamb screw, concrete screw, or other.';
  end if;

  v_patch := p_patch;

  if p_patch ? 'exterior_lines' then
    if p_patch->'exterior_lines' is null or jsonb_typeof(p_patch->'exterior_lines') <> 'array' then
      raise exception 'Exterior situations must be a list.';
    end if;
    if jsonb_array_length(p_patch->'exterior_lines') > 20 then
      raise exception 'A job can carry at most 20 exterior situations.';
    end if;
    for v_line in select * from jsonb_array_elements(p_patch->'exterior_lines') loop
      if jsonb_typeof(v_line) <> 'object' then
        raise exception 'Each exterior situation must be a finish, a set depth, an inch, and a note.';
      end if;
      for v_line_key in select jsonb_object_keys(v_line) loop
        if v_line_key not in ('exterior_finish', 'exterior_note', 'set_depth', 'set_depth_inches') then
          raise exception 'An exterior situation has no field called "%".', v_line_key;
        end if;
      end loop;
      if v_line->>'exterior_finish' is not null
         and v_line->>'exterior_finish' not in ('stucco', 'rock', 'siding', 'brick', 'other') then
        raise exception 'Exterior finish is stucco, rock, siding, brick, or other.';
      end if;
      if v_line->>'set_depth' is not null
         and v_line->>'set_depth' not in ('inset', 'outset', 'unknown') then
        raise exception 'Set depth is inset, outset, or unknown.';
      end if;
      if v_line->'set_depth_inches' is not null
         and jsonb_typeof(v_line->'set_depth_inches') not in ('number', 'null') then
        raise exception 'Set depth inches must be a number.';
      end if;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'exterior_finish', v_line->>'exterior_finish',
        'exterior_note', nullif(btrim(coalesce(v_line->>'exterior_note', '')), ''),
        'set_depth', v_line->>'set_depth',
        'set_depth_inches', (v_line->>'set_depth_inches')::numeric(4,2)));
    end loop;
    v_patch := v_patch || jsonb_build_object('exterior_lines', v_lines);
  end if;

  select exists (select 1 from project_build_facts where project_id = p_project_id) into v_exists;

  if not v_exists then
    -- Seed from the GC handshake on the very first write for this job, before
    -- the caller's own patch is applied — the GC already told us the set
    -- preference and what is going on the outside. That becomes line one of
    -- the exterior situations (finish left open: "stucco" from a GC's mouth
    -- is a note, not a pick-list value), unless the caller sent lines of
    -- their own. `unknown` stays out: an "I don't know" from the GC is not a
    -- fact worth carrying forward as one.
    select * into v_checkin
      from project_gc_checkins
     where project_id = p_project_id
     order by contacted_at desc
     limit 1;

    if found then
      if (v_checkin.set_preference is not null and v_checkin.set_preference <> 'unknown')
         or coalesce(btrim(v_checkin.exterior_material), '') <> '' then
        v_seed := v_seed || jsonb_build_object('exterior_lines', jsonb_build_array(jsonb_build_object(
          'exterior_finish', null::text,
          'exterior_note', nullif(btrim(coalesce(v_checkin.exterior_material, '')), ''),
          'set_depth', case when v_checkin.set_preference <> 'unknown' then v_checkin.set_preference end,
          'set_depth_inches', null::numeric)));
      end if;
      if coalesce(btrim(v_checkin.contact_name), '') <> '' then
        v_seed := v_seed || jsonb_build_object('gc_contact_name', v_checkin.contact_name);
      end if;
      -- The caller's own patch always wins over the seed for the same field.
      v_patch := v_seed || v_patch;
    end if;
  end if;

  insert into project_build_facts as f (
    project_id,
    exterior_lines,
    flashing_system, flashing_system_other, flashing_note,
    fastener_type, fastener_type_other, fastener_length_in, fastener_spacing_in, fastener_note,
    site_rules, gc_contact_name, gc_contact_phone, elevation_notes,
    updated_by, updated_at
  )
  values (
    p_project_id,
    coalesce(v_patch->'exterior_lines', '[]'::jsonb),
    v_patch->>'flashing_system', v_patch->>'flashing_system_other', v_patch->>'flashing_note',
    v_patch->>'fastener_type', v_patch->>'fastener_type_other',
    (v_patch->>'fastener_length_in')::numeric,
    (v_patch->>'fastener_spacing_in')::numeric,
    v_patch->>'fastener_note',
    v_patch->>'site_rules', v_patch->>'gc_contact_name', v_patch->>'gc_contact_phone',
    v_patch->>'elevation_notes',
    auth.uid(), now()
  )
  on conflict (project_id) do update set
    exterior_lines = case when v_patch ? 'exterior_lines' then v_patch->'exterior_lines' else f.exterior_lines end,
    flashing_system = case when v_patch ? 'flashing_system' then v_patch->>'flashing_system' else f.flashing_system end,
    flashing_system_other = case when v_patch ? 'flashing_system_other' then v_patch->>'flashing_system_other' else f.flashing_system_other end,
    flashing_note = case when v_patch ? 'flashing_note' then v_patch->>'flashing_note' else f.flashing_note end,
    fastener_type = case when v_patch ? 'fastener_type' then v_patch->>'fastener_type' else f.fastener_type end,
    fastener_type_other = case when v_patch ? 'fastener_type_other' then v_patch->>'fastener_type_other' else f.fastener_type_other end,
    fastener_length_in = case when v_patch ? 'fastener_length_in' then (v_patch->>'fastener_length_in')::numeric else f.fastener_length_in end,
    fastener_spacing_in = case when v_patch ? 'fastener_spacing_in' then (v_patch->>'fastener_spacing_in')::numeric else f.fastener_spacing_in end,
    fastener_note = case when v_patch ? 'fastener_note' then v_patch->>'fastener_note' else f.fastener_note end,
    site_rules = case when v_patch ? 'site_rules' then v_patch->>'site_rules' else f.site_rules end,
    gc_contact_name = case when v_patch ? 'gc_contact_name' then v_patch->>'gc_contact_name' else f.gc_contact_name end,
    gc_contact_phone = case when v_patch ? 'gc_contact_phone' then v_patch->>'gc_contact_phone' else f.gc_contact_phone end,
    elevation_notes = case when v_patch ? 'elevation_notes' then v_patch->>'elevation_notes' else f.elevation_notes end,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;;
;
create or replace function public.green_light_items(p_project_id uuid)
returns table (item_key text, label_en text, answered boolean, who text)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_first_published_day date;
begin
  if not exists (select 1 from projects where id = p_project_id) then
    raise exception 'That job does not exist.';
  end if;

  select min(sa.start_date) into v_first_published_day
    from schedule_assignments sa
   where sa.project_id = p_project_id
     and sa.status = 'published';

  return query
  select
    'plan_set'::text,
    'A planset is uploaded and its extraction has finished'::text,
    exists (
      select 1 from project_plansets pl
       where pl.project_id = p_project_id and pl.status = 'ready'
    ),
    'supervisor'::text
  union all
  select
    'build_facts'::text,
    'An exterior finish and its set depth are recorded'::text,
    exists (
      select 1
        from project_build_facts f
        cross join lateral jsonb_array_elements(f.exterior_lines) l
       where f.project_id = p_project_id
         and l->>'exterior_finish' is not null
         and l->>'set_depth' is not null
    ),
    'foreman'::text
  union all
  select
    'materials_eta'::text,
    'The materials ETA is set and lands on or before the first day on site'::text,
    (
      v_first_published_day is not null
      and exists (
        select 1 from project_pipeline pp
         where pp.project_id = p_project_id
           and pp.materials_eta is not null
           and pp.materials_eta <= v_first_published_day
      )
    ),
    'supervisor'::text
  union all
  select
    'gc_site'::text,
    'The GC contact and site rules are recorded'::text,
    exists (
      select 1 from project_build_facts f
       where f.project_id = p_project_id
         and coalesce(btrim(f.gc_contact_name), '') <> ''
         and coalesce(btrim(f.site_rules), '') <> ''
    ),
    'foreman'::text
  union all
  select
    'day_one_crew'::text,
    'A crew and a truck are assigned for the first day on site'::text,
    (
      v_first_published_day is not null
      and exists (
        select 1
          from schedule_assignments sa
          join schedule_assignment_members sm on sm.assignment_id = sa.id
         where sa.project_id = p_project_id
           and sa.status = 'published'
           and sa.start_date = v_first_published_day
           and exists (
             select 1 from vehicle_project_assignments vpa
              where vpa.assignment_id = sa.id
           )
      )
    ),
    'supervisor'::text
  union all
  select
    'toolbox'::text,
    'A toolbox talk is pinned to the first day'::text,
    (
      v_first_published_day is not null
      and exists (
        select 1 from toolbox_talk_assignments ta
         where ta.assigned_date = v_first_published_day
      )
    ),
    'supervisor'::text;
end;
$$;;
;
create or replace function public.travel_can_read_trip(p_trip uuid)
returns boolean language sql stable security definer
set search_path = public, pg_temp
as $$
  select auth.uid() is not null and not public.is_partner_user() and (
    public.travel_is_supervisor() or exists (
      select 1 from public.trips t join public.trip_crew c on c.trip_id = t.id
      where t.id = p_trip and t.status = 'published' and c.profile_id = auth.uid()
    )
  );
$$;;
;
create or replace function public.travel_can_read_attachment(p_attachment uuid)
returns boolean language sql stable security definer
set search_path = public, pg_temp
as $$
  select auth.uid() is not null and not public.is_partner_user() and exists (
    select 1 from public.trip_attachments a where a.id = p_attachment and (
      public.travel_is_supervisor() or (
        public.travel_can_read_trip(a.trip_id)
        and split_part(a.storage_path, '/', 1) = a.trip_id::text
        and (a.flight_id is null or exists (
          select 1 from public.flights f where f.id = a.flight_id and f.trip_id = a.trip_id
            and (f.profile_id is null or f.profile_id = auth.uid())
        ))
        and (a.lodging_id is null or exists (
          select 1 from public.lodging l where l.id = a.lodging_id and l.trip_id = a.trip_id
        ))
      )
    )
  );
$$;;
;
create function public.workflow_require_manager() returns void language plpgsql security definer
set search_path=public,pg_temp as $$ begin
 if auth.uid() is null or public.is_partner_user() or not public.travel_is_supervisor() then
  raise exception 'Only an internal supervisor or owner can change a connected plan.' using errcode='42501';
 end if;
end $$;;
;
create function public.workflow_lock_writes() returns trigger language plpgsql
set search_path=public,pg_temp as $$ begin
 perform pg_advisory_xact_lock(639024,1); return null;
end $$;;
;
create function public.workflow_guard_linked_record() returns trigger language plpgsql
set search_path=public,pg_temp as $$
declare old_id uuid; new_id uuid; linked boolean;
begin
 -- Only our definer RPCs (or a database administrator) materialize a plan.
 if current_user = 'postgres' then return coalesce(new,old); end if;
 if tg_table_name in ('schedule_assignments','trips') then
  if tg_op <> 'INSERT' then old_id:=old.id; end if;
  if tg_op <> 'DELETE' then new_id:=new.id; end if;
 elsif tg_table_name in ('schedule_assignment_members','vehicle_project_assignments') then
  if tg_op <> 'INSERT' then old_id:=old.assignment_id; end if;
  if tg_op <> 'DELETE' then new_id:=new.assignment_id; end if;
 else
  if tg_op <> 'INSERT' then old_id:=old.trip_id; end if;
  if tg_op <> 'DELETE' then new_id:=new.trip_id; end if;
 end if;
 if tg_table_name in ('schedule_assignments','schedule_assignment_members','vehicle_project_assignments') then
  select exists(select 1 from public.workflow_plan_assignments where assignment_id in (old_id,new_id)) into linked;
 else
  select exists(select 1 from public.workflow_plan_trips where trip_id in (old_id,new_id)) into linked;
 end if;
 if linked then raise exception 'Open the connected plan to review and publish this change.' using errcode='P0001'; end if;
 return coalesce(new,old);
end $$;;
;
create function public.workflow_guard_linked_storage() returns trigger language plpgsql security definer
set search_path=public,pg_temp as $$
begin
 if tg_op <> 'INSERT' and old.bucket_id='trip-attachments' and exists(
  select 1 from public.workflow_plan_trips where trip_id::text=split_part(old.name,'/',1)
 ) then raise exception 'Files in a connected plan are read-only.'; end if;
 if tg_op <> 'DELETE' and new.bucket_id='trip-attachments' and exists(
  select 1 from public.workflow_plan_trips where trip_id::text=split_part(new.name,'/',1)
 ) then raise exception 'Files in a connected plan are read-only.'; end if;
 return coalesce(new,old);
end $$;;
;
create or replace function public.workflow_snapshot(p_plan uuid) returns jsonb language sql stable security definer
set search_path=public,pg_temp as $$
 select jsonb_build_object(
  'assignments',coalesce((select jsonb_agg((case when a.end_time is null then to_jsonb(a)-'end_time' else to_jsonb(a) end)||jsonb_build_object('members',
   coalesce((select jsonb_agg(to_jsonb(m) order by m.profile_id) from public.schedule_assignment_members m where m.assignment_id=a.id),'[]'::jsonb)) order by a.id)
   from public.schedule_assignments a join public.workflow_plan_assignments l on l.assignment_id=a.id where l.plan_id=p_plan),'[]'::jsonb),
  'trips',coalesce((select jsonb_agg(jsonb_build_object('trip',to_jsonb(t),
   'crew',coalesce((select jsonb_agg(to_jsonb(c) order by c.profile_id) from public.trip_crew c where c.trip_id=t.id),'[]'::jsonb),
   'flights',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.flights c where c.trip_id=t.id),'[]'::jsonb),
   'lodging',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.lodging c where c.trip_id=t.id),'[]'::jsonb),
   'ground',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.ground_transport c where c.trip_id=t.id),'[]'::jsonb),
   'procedures',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.procedures c where c.trip_id=t.id),'[]'::jsonb),
   'contacts',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.trip_contacts c where c.trip_id=t.id),'[]'::jsonb),
   'attachments',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.trip_attachments c where c.trip_id=t.id),'[]'::jsonb)
   ) order by t.id) from public.trips t join public.workflow_plan_trips l on l.trip_id=t.id where l.plan_id=p_plan),'[]'::jsonb),
  'vehicles',coalesce((select jsonb_agg(to_jsonb(v) order by v.id) from public.vehicle_project_assignments v
   join public.workflow_plan_assignments l on l.assignment_id=v.assignment_id where l.plan_id=p_plan),'[]'::jsonb)
 );
$$;;
;
create function public.workflow_create_plan(p_id uuid,p_name text,p_assignments uuid[],p_trips uuid[])
returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare project uuid; graph jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 if p_id is null or nullif(trim(p_name),'') is null or coalesce(cardinality(p_assignments),0) not between 1 and 40
 or coalesce(cardinality(p_trips),0) not between 1 and 20 then
  raise exception 'Choose work and travel drafts for one job.';
 end if;
 -- Caller supplies a UUID so retries after a lost response do not make copies.
 if exists(select 1 from public.workflow_plans where id=p_id) then
  if (select name from public.workflow_plans where id=p_id)=trim(p_name)
   and (select array_agg(assignment_id order by assignment_id) from public.workflow_plan_assignments where plan_id=p_id)=(select array_agg(x order by x) from unnest(p_assignments) x)
   and (select array_agg(trip_id order by trip_id) from public.workflow_plan_trips where plan_id=p_id)=(select array_agg(x order by x) from unnest(p_trips) x)
  then return p_id; end if;
  raise exception 'This request was already used for another plan.';
 end if;
 select a.project_id into project from public.schedule_assignments a where a.id=p_assignments[1];
 if project is null or (select count(*) from public.schedule_assignments where id=any(p_assignments) and project_id=project and kind='install' and status='draft')<>cardinality(p_assignments)
 or (select count(*) from public.trips where id=any(p_trips) and project_id=project and status='draft')<>cardinality(p_trips) then
  raise exception 'Choose existing unpublished work and trips for the same job.';
 end if;
 insert into public.workflow_plans(id,project_id,name,created_by) values(p_id,project,trim(p_name),auth.uid());
 insert into public.workflow_plan_assignments select p_id,x from unnest(p_assignments) x;
 insert into public.workflow_plan_trips select p_id,x from unnest(p_trips) x;
 graph:=public.workflow_snapshot(p_id);
 update public.workflow_plans set draft=graph,source_snapshot=graph where id=p_id;
 return p_id;
end $$;;
;
create or replace function public.workflow_save_draft(p_plan uuid,p_expected bigint,p_draft jsonb)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare plan public.workflow_plans; a jsonb; original jsonb; section jsonb; old_section jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 select * into strict plan from public.workflow_plans where id=p_plan for update;
 if plan.state<>'active' or plan.revision<>p_expected then raise exception 'The plan changed. Reload it before saving.' using errcode='40001'; end if;
 if jsonb_typeof(p_draft) is distinct from 'object' or pg_column_size(p_draft)>1048576 then raise exception 'That draft is not valid.'; end if;
 if (p_draft - array['assignments','trips']) is distinct from (plan.draft - array['assignments','trips'])
 or jsonb_array_length(p_draft->'assignments') is distinct from jsonb_array_length(plan.draft->'assignments')
 or jsonb_array_length(p_draft->'trips') is distinct from jsonb_array_length(plan.draft->'trips') then
  raise exception 'Keep the linked work, trips, and vehicle records in this plan.';
 end if;
 for a in select value from jsonb_array_elements(p_draft->'assignments') loop
  if jsonb_typeof(a->'members') is distinct from 'array' or (a->>'start_date')::date is null or (a->>'end_date')::date is null or (a->>'start_date')::date>(a->>'end_date')::date then raise exception 'Work needs valid dates and a crew list.'; end if;
  if a->>'end_time' is not null and ((a->>'start_time') is null or (a->>'end_time')::time <= (a->>'start_time')::time) then raise exception 'End time must be later than start time on the same day.'; end if;
  select value into original from jsonb_array_elements(plan.draft->'assignments') where value->>'id'=a->>'id';
  if original is null or (a-array['start_date','end_date','start_time','end_time','note','members']) is distinct from (original-array['start_date','end_date','start_time','end_time','note','members']) then raise exception 'The work identity cannot be changed.'; end if;
 end loop;
 for section in select value from jsonb_array_elements(p_draft->'trips') loop
  if jsonb_typeof(section->'crew') is distinct from 'array' or (section->'trip'->>'start_date')::date is null or (section->'trip'->>'end_date')::date is null or (section->'trip'->>'start_date')::date>(section->'trip'->>'end_date')::date then raise exception 'Travel needs valid dates and a crew list.'; end if;
  select value into old_section from jsonb_array_elements(plan.draft->'trips') where value->'trip'->>'id'=section->'trip'->>'id';
  if old_section is null or (section-array['trip','crew']) is distinct from (old_section-array['trip','crew'])
   or ((section->'trip')-array['name','destination','start_date','end_date','timezone','notes']) is distinct from ((old_section->'trip')-array['name','destination','start_date','end_date','timezone','notes']) then
   raise exception 'Keep the existing travel details and files. Only plan fields and crew can change here.';
  end if;
 end loop;
 -- Duplicate parent IDs must not replace another parent in a same-length list.
 if (select count(distinct value->>'id') from jsonb_array_elements(p_draft->'assignments'))<>jsonb_array_length(p_draft->'assignments')
 or (select count(distinct value->'trip'->>'id') from jsonb_array_elements(p_draft->'trips'))<>jsonb_array_length(p_draft->'trips') then raise exception 'A linked record appears twice.'; end if;
 if p_draft=plan.draft then return plan.revision; end if;
 update public.workflow_plans set draft=p_draft,revision=revision+1,updated_at=now() where id=p_plan returning revision into plan.revision;
 return plan.revision;
end $$;;
;
create function public.workflow_conflicts(p_plan uuid) returns jsonb language sql stable security definer
set search_path=public,pg_temp set jit=off as $$
 with draft as (select draft from public.workflow_plans where id=p_plan),
 planned as (select a->>'id' as id,(a->>'start_date')::date as starts,(a->>'end_date')::date as ends,a->'members' as members from draft,jsonb_array_elements(draft->'assignments') a),
 others as (select a.id::text as id,a.start_date as starts,a.end_date as ends,
  coalesce((select jsonb_agg(jsonb_build_object('profile_id',m.profile_id)) from public.schedule_assignment_members m where m.assignment_id=a.id),'[]'::jsonb) as members
  from public.schedule_assignments a where a.status<>'canceled' and not exists(select 1 from planned p where p.id=a.id::text)),
 crew as (select distinct 'crew'::text as kind,p.id as assignment_id,o.id as other_id,m->>'profile_id' as resource_id
  from planned p cross join lateral jsonb_array_elements(p.members) m
  join (select * from others union all select * from planned) o on p.id<>o.id and p.starts<=o.ends and o.starts<=p.ends
  where exists(select 1 from jsonb_array_elements(o.members) om where om->>'profile_id'=m->>'profile_id')),
 vehicles as (select 'vehicle'::text as kind,p.id as assignment_id,v.assignment_id::text as other_id,v.vehicle_id::text as resource_id
  from draft cross join lateral jsonb_array_elements(draft->'vehicles') b join planned p on p.id=b->>'assignment_id'
  join public.vehicle_project_assignments v on v.vehicle_id=(b->>'vehicle_id')::uuid and v.assignment_id is not null
   and not exists(select 1 from planned own where own.id=v.assignment_id::text)
   and v.start_date<=p.ends and p.starts<=v.end_date
  join public.schedule_assignments a on a.id=v.assignment_id and a.status<>'canceled'),
 within_vehicles as (select 'vehicle'::text as kind,p.id as assignment_id,q.id as other_id,b->>'vehicle_id' as resource_id
  from draft cross join lateral jsonb_array_elements(draft->'vehicles') b
  cross join lateral jsonb_array_elements(draft->'vehicles') c
  join planned p on p.id=b->>'assignment_id' join planned q on q.id=c->>'assignment_id'
  where b->>'vehicle_id'=c->>'vehicle_id' and p.id<>q.id and p.starts<=q.ends and q.starts<=p.ends)
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('other_start_date',o.starts,'other_end_date',o.ends,'other_project_id',a.project_id) order by c.kind,c.assignment_id,c.other_id,c.resource_id),'[]'::jsonb)
 from (select * from crew union select * from vehicles union select * from within_vehicles) c
 left join (select * from others union all select * from planned) o on o.id=c.other_id
 left join public.schedule_assignments a on a.id::text=c.other_id;
$$;;
;
create function public.workflow_review_plan(p_plan uuid) returns jsonb language plpgsql security definer
set search_path=public,pg_temp as $$
declare p public.workflow_plans; conflicts jsonb;
begin
 perform public.workflow_require_manager();
 select * into strict p from public.workflow_plans where id=p_plan;
 conflicts:=public.workflow_conflicts(p_plan);
 return to_jsonb(p)||jsonb_build_object('conflicts',conflicts,'review_token',md5(p.draft::text||conflicts::text),
  'conflict_assignments',coalesce((select jsonb_agg(to_jsonb(a)) from public.schedule_assignments a where a.id::text in (select c->>'other_id' from jsonb_array_elements(conflicts) c)),'[]'::jsonb),
  'notices',coalesce((select jsonb_agg(jsonb_build_object('state',state,'count',n)) from
   (select state,count(*) n from public.workflow_notice_outbox where plan_id=p_plan group by state) x),'[]'::jsonb));
end $$;;
;
create or replace function public.workflow_publish_plan(p_plan uuid,p_expected bigint,p_request uuid,p_review_token text,p_allow_crew_conflicts boolean default false,p_cancel boolean default false)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare p public.workflow_plans; prior public.workflow_publish_requests; fingerprint text; conflicts jsonb; a jsonb; pack jsonb; member jsonb; old_members uuid[]; new_members uuid[]; result jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 if p_request is null or p_expected is null or p_review_token is null or p_cancel is null or p_allow_crew_conflicts is null then raise exception 'Review this plan before publishing.'; end if;
 fingerprint:=md5(jsonb_build_array(p_plan,p_expected,p_review_token,p_allow_crew_conflicts,p_cancel)::text);
 select * into prior from public.workflow_publish_requests where request_id=p_request;
 if found then
  if prior.fingerprint<>fingerprint then raise exception 'This publish request was already used for different changes.'; end if;
  return prior.result;
 end if;
 select * into strict p from public.workflow_plans where id=p_plan for update;
 if p.state<>'active' or p.revision<>p_expected then raise exception 'The plan changed. Reload and review it again.' using errcode='40001'; end if;
 if not p_cancel and p.published_revision=p.revision then raise exception 'There are no unpublished changes.'; end if;
 conflicts:=public.workflow_conflicts(p_plan);
 if md5(p.draft::text||conflicts::text)<>p_review_token then raise exception 'Bookings changed since your review. Review the conflicts again.' using errcode='40001'; end if;
 if public.workflow_snapshot(p_plan)<>p.source_snapshot then raise exception 'A linked source changed outside this plan. Reconcile it before publishing.' using errcode='40001'; end if;
 if not p_cancel and exists(select 1 from jsonb_array_elements(conflicts) c where c->>'kind'='vehicle') then raise exception 'Resolve the vehicle double-booking before publishing.'; end if;
 if not p_cancel and jsonb_array_length(conflicts)>0 and not p_allow_crew_conflicts then raise exception 'Review and acknowledge the crew conflicts before publishing.'; end if;
 select array_agg(distinct id) into old_members from (
  select m.profile_id as id from public.schedule_assignment_members m join public.workflow_plan_assignments l on l.assignment_id=m.assignment_id where l.plan_id=p_plan
  union select m.profile_id from public.trip_crew m join public.workflow_plan_trips l on l.trip_id=m.trip_id where l.plan_id=p_plan
 ) x;
 if p_cancel then
  update public.schedule_assignments set status='canceled',updated_at=now() where id in(select assignment_id from public.workflow_plan_assignments where plan_id=p_plan);
  update public.trips set status='draft',updated_at=now() where id in(select trip_id from public.workflow_plan_trips where plan_id=p_plan);
  update public.workflow_plans set state='canceled',revision=revision+1 where id=p_plan returning * into p;
 else
  for a in select value from jsonb_array_elements(p.draft->'assignments') loop
   if (a->>'start_date')::date>(a->>'end_date')::date or jsonb_array_length(a->'members')=0 then raise exception 'Each work block needs valid dates and crew.'; end if;
   update public.schedule_assignments set start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date,
    start_time=(a->>'start_time')::time,end_time=(a->>'end_time')::time,note=a->>'note',status='published',published_at=now(),updated_at=now() where id=(a->>'id')::uuid;
   delete from public.schedule_assignment_members where assignment_id=(a->>'id')::uuid;
   for member in select value from jsonb_array_elements(a->'members') loop
    if not exists(select 1 from public.profiles where id=(member->>'profile_id')::uuid and not is_partner and active) then raise exception 'Choose active internal crew members.'; end if;
    insert into public.schedule_assignment_members(assignment_id,profile_id,role) values((a->>'id')::uuid,(member->>'profile_id')::uuid,member->>'role');
   end loop;
   update public.vehicle_project_assignments set start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date where assignment_id=(a->>'id')::uuid;
  end loop;
  for pack in select value from jsonb_array_elements(p.draft->'trips') loop
   a:=pack->'trip';
   if nullif(trim(a->>'name'),'') is null or (a->>'start_date')::date>(a->>'end_date')::date or jsonb_array_length(pack->'crew')=0 then raise exception 'Each trip needs a name, valid dates and crew.'; end if;
   if nullif(a->>'timezone','') is not null and not exists(select 1 from pg_timezone_names where name=a->>'timezone') then raise exception 'Choose a valid trip time zone.'; end if;
   update public.trips set name=a->>'name',destination=a->>'destination',start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date,
    timezone=nullif(a->>'timezone',''),notes=a->>'notes',status='published',published_at=now(),updated_at=now() where id=(a->>'id')::uuid;
   delete from public.trip_crew where trip_id=(a->>'id')::uuid;
   for member in select value from jsonb_array_elements(pack->'crew') loop
    if not exists(select 1 from public.profiles where id=(member->>'profile_id')::uuid and not is_partner and active) then raise exception 'Choose active internal crew members.'; end if;
    insert into public.trip_crew(trip_id,profile_id,role) values((a->>'id')::uuid,(member->>'profile_id')::uuid,coalesce(member->>'role','crew'));
   end loop;
  end loop;
 end if;
 -- Immutable audit, materialized instructions and the durable notification
 -- queue commit together. A network retry returns this result without replay.
 update public.workflow_plans set published_revision=revision,source_snapshot=public.workflow_snapshot(p_plan),
  draft=public.workflow_snapshot(p_plan),updated_at=now() where id=p_plan returning * into p;
 insert into public.workflow_plan_revisions(plan_id,revision,action,snapshot,actor) values(p_plan,p.revision,case when p_cancel then 'cancel' else 'publish' end,p.draft,auth.uid());
 insert into public.schedule_events(assignment_id,actor,kind,payload)
  select assignment_id,auth.uid(),case when p_cancel then 'removed' else 'published' end,
   jsonb_build_object('plan_id',p_plan,'revision',p.revision) from public.workflow_plan_assignments where plan_id=p_plan;
 select array_agg(distinct id) into new_members from (
  select m.profile_id as id from public.schedule_assignment_members m join public.workflow_plan_assignments l on l.assignment_id=m.assignment_id where l.plan_id=p_plan
  union select m.profile_id from public.trip_crew m join public.workflow_plan_trips l on l.trip_id=m.trip_id where l.plan_id=p_plan
 ) x;
 insert into public.workflow_notice_outbox(plan_id,revision,profile_id)
  select p_plan,p.revision,id from (select distinct unnest(coalesce(old_members,'{}'::uuid[])||coalesce(new_members,'{}'::uuid[])) id) x;
 result:=jsonb_build_object('plan_id',p_plan,'revision',p.revision,'state',p.state,'notifications','pending');
 insert into public.workflow_publish_requests values(p_request,p_plan,fingerprint,result,now());
 return result;
end $$;;
;
create function public.workflow_my_trip_links() returns table(assignment_id uuid,trip_id uuid,name text,start_date date,end_date date)
language sql stable security definer set search_path=public,pg_temp as $$
 select a.assignment_id,t.id,t.name,t.start_date,t.end_date from public.workflow_plan_assignments a
 join public.workflow_plans p on p.id=a.plan_id and p.state='active' and p.published_revision is not null
 join public.workflow_plan_trips l on l.plan_id=p.id join public.trips t on t.id=l.trip_id
 where auth.uid() is not null and not public.is_partner_user() and public.travel_can_read_trip(t.id)
 and (public.travel_is_supervisor() or exists(select 1 from public.schedule_assignment_members m where m.assignment_id=a.assignment_id and m.profile_id=auth.uid()));
$$;;
;
create function public.workflow_claim_notices(p_plan uuid,p_lease uuid) returns setof public.workflow_notice_outbox
language sql security definer set search_path=public,pg_temp as $$
 update public.workflow_notice_outbox set state='sending',lease_id=p_lease,lease_until=now()+interval '2 minutes',attempts=attempts+1
 where id in(select id from public.workflow_notice_outbox where plan_id=p_plan
 and exists(select 1 from public.workflow_plans p where p.id=p_plan and p.project_id is not null)
 and (state in ('pending','failed') or (state='sending' and lease_until<now())) order by created_at,id limit 20 for update skip locked)
 returning *;
$$;;
;
create function public.workflow_finish_notice(p_id uuid,p_lease uuid,p_sent boolean) returns void
language sql security definer set search_path=public,pg_temp as $$
 update public.workflow_notice_outbox set state=case when p_sent then 'sent' else 'failed' end,
 sent_at=case when p_sent then now() else null end,last_error=case when p_sent then null else 'Push delivery failed or no subscribed device.' end,
 lease_id=null,lease_until=null where id=p_id and lease_id=p_lease and state='sending';
$$;;
;
create function public.workflow_discard_plan(p_plan uuid,p_expected bigint) returns void
language plpgsql security definer set search_path=public,pg_temp as $$
declare p public.workflow_plans;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 select * into strict p from public.workflow_plans where id=p_plan for update;
 if p.revision<>p_expected or p.published_revision is not null then raise exception 'Only an unpublished plan can be disconnected.'; end if;
 delete from public.workflow_plans where id=p_plan;
end $$;;
;
create or replace function public.schedule_remove_day(
  p_assignment_id uuid, p_day date, p_expected_updated_at timestamptz
) returns void language plpgsql security invoker
set search_path = public, pg_temp as $$
declare
  a public.schedule_assignments%rowtype;
  right_id uuid;
begin
  if auth.uid() is null or public.is_partner_user() or not public.travel_is_supervisor()
     or not exists (select 1 from public.profiles where id=auth.uid() and active) then
    raise exception 'Only an active owner or supervisor can remove scheduled days.';
  end if;
  if p_day is null or p_expected_updated_at is null then
    raise exception 'Choose a day and reload the assignment before removing it.';
  end if;
  -- Match connected publication's lock order, including membership/vehicle edits.
  perform pg_advisory_xact_lock(639024,1);
  select * into a from public.schedule_assignments where id=p_assignment_id for update;
  -- A retry after a lost response must not remove any additional days.
  if not found then return; end if;
  if exists (select 1 from public.workflow_plan_assignments where assignment_id=a.id) then
    raise exception 'Open the connected plan to change its work dates.';
  end if;
  if p_day < a.start_date or p_day > a.end_date then return; end if;
  if a.updated_at is distinct from p_expected_updated_at then
    raise exception 'This assignment changed. Close and reopen it before removing a day.';
  end if;
  if a.kind is distinct from 'install' then
    raise exception 'Change delivery dates from the delivery schedule.';
  end if;
  if a.start_date = a.end_date then
    delete from public.schedule_assignments where id=a.id;
  elsif p_day = a.start_date then
    update public.schedule_assignments set start_date=p_day+1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=p_day+1,end_date=a.end_date where assignment_id=a.id;
  elsif p_day = a.end_date then
    update public.schedule_assignments set end_date=p_day-1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=a.start_date,end_date=p_day-1 where assignment_id=a.id;
  else
    right_id := gen_random_uuid();
    insert into public.schedule_assignments
      (id,project_id,start_date,end_date,start_time,end_time,status,color,note,created_by,published_at,created_at,kind,created_via)
    values (right_id,a.project_id,p_day+1,a.end_date,a.start_time,a.end_time,a.status,a.color,a.note,a.created_by,a.published_at,a.created_at,a.kind,a.created_via);
    insert into public.schedule_assignment_members (assignment_id,profile_id,role,created_at)
      select right_id,profile_id,role,created_at from public.schedule_assignment_members where assignment_id=a.id;
    insert into public.vehicle_project_assignments (vehicle_id,project_id,assigned_at,note,assignment_id,start_date,end_date)
      select vehicle_id,project_id,assigned_at,note,right_id,p_day+1,a.end_date
      from public.vehicle_project_assignments where assignment_id=a.id;
    update public.schedule_assignments set end_date=p_day-1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=a.start_date,end_date=p_day-1 where assignment_id=a.id;
  end if;
  insert into public.schedule_events (assignment_id,actor,kind,payload)
    values (a.id,auth.uid(),'removed',jsonb_build_object('scope','day','day',p_day,
      'previous_start_date',a.start_date,'previous_end_date',a.end_date,'remaining_assignment_id',right_id));
end $$;;
;
create or replace function public.set_project_labor_targets(
  p_project_id uuid, p_projected_hours numeric, p_goal_hours numeric,
  p_square_feet numeric, p_revision integer, p_reason text
) returns public.project_labor_targets
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_old public.project_labor_targets; v_new public.project_labor_targets;
begin
  if auth.uid() is null or public.is_partner_user() or not exists (
    select 1 from public.profiles where id = auth.uid() and role in ('supervisor','owner','admin','big_boss')
  ) then raise exception 'Only supervisors and owners can edit labor targets.'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 or length(p_reason) > 2000 then
    raise exception 'Please give a short reason for this change.';
  end if;
  -- Lock the parent even on the first save, so two new-target forms cannot both win.
  perform 1 from public.projects where id = p_project_id and deleted_at is null for update;
  if not found then raise exception 'That job is unavailable.'; end if;
  select * into v_old from public.project_labor_targets where project_id = p_project_id;
  if p_revision is null or p_revision <> coalesce(v_old.revision, 0) then
    raise exception 'Labor targets changed. Refresh before saving.';
  end if;
  insert into public.project_labor_targets(project_id, projected_hours, goal_hours, square_feet, revision, updated_by)
  values (p_project_id, p_projected_hours, p_goal_hours, p_square_feet, p_revision + 1, auth.uid())
  on conflict (project_id) do update set projected_hours = excluded.projected_hours,
    goal_hours = excluded.goal_hours, square_feet = excluded.square_feet,
    revision = excluded.revision, updated_at = now(), updated_by = auth.uid()
  returning * into v_new;
  insert into public.project_execution_history(project_id,event_kind,before_value,after_value,reason,actor_id)
  values (p_project_id,'labor_targets',to_jsonb(v_old),to_jsonb(v_new),btrim(p_reason),auth.uid());
  return v_new;
end; $$;;
;
create or replace function public.set_project_stage(
  p_project_id uuid, p_stage_key text, p_completed boolean, p_note text, p_revision integer
) returns public.project_stage_progress
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_old public.project_stage_progress; v_new public.project_stage_progress;
begin
  if auth.uid() is null or public.is_partner_user() or not public._is_lead(auth.uid()) then
    raise exception 'Only foremen and above can update job stages.';
  end if;
  if p_completed is null or p_note is null or length(btrim(p_note)) < 3 or length(p_note) > 2000 then
    raise exception 'Add a short completion note or reopening reason.';
  end if;
  perform 1 from public.projects where id = p_project_id and deleted_at is null for update;
  if not found then raise exception 'That job is unavailable.'; end if;
  select * into v_old from public.project_stage_progress where project_id = p_project_id and stage_key = p_stage_key;
  if p_revision is null or p_revision <> coalesce(v_old.revision, 0) then
    raise exception 'This stage changed. Refresh before saving.';
  end if;
  insert into public.project_stage_progress(project_id,stage_key,completed,note,revision,updated_by)
  values (p_project_id,p_stage_key,p_completed,btrim(p_note),p_revision+1,auth.uid())
  on conflict (project_id,stage_key) do update set completed = excluded.completed,
    note = excluded.note, revision = excluded.revision, updated_at = now(), updated_by = auth.uid()
  returning * into v_new;
  insert into public.project_execution_history(project_id,event_kind,before_value,after_value,reason,actor_id)
  values (p_project_id,'stage:' || p_stage_key,to_jsonb(v_old),to_jsonb(v_new),btrim(p_note),auth.uid());
  return v_new;
end; $$;;
;
create or replace function public.custom_work_internal() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select auth.uid() is not null and not public.is_partner_user() and exists (
    select 1 from profiles where id = auth.uid() and retired_at is null and access_revoked_at is null
      and role in ('installer','foreman','supervisor','owner'))
$$;;
;
create or replace function public.validate_custom_work_facts(f jsonb) returns void
language plpgsql set search_path = public, pg_temp as $$
declare k text; v jsonb; c jsonb;
begin
  if f is null or jsonb_typeof(f) <> 'object' or octet_length(f::text) > 20000 then raise exception 'Unit details are too large or invalid.'; end if;
  for k, v in select * from jsonb_each(f) loop
    if k not in ('width_in','height_in','weight_lb','story','location','material','electrical','complexity','access','equipment_needed','equipment','equipment_minutes','note','named_helpers','area_source','installation_complete',
                 'components','opening_direction','direction_viewpoint','measurement_source','unknown_fields') then
      raise exception 'Unknown unit detail.';
    end if;
    if k in ('width_in','height_in','weight_lb','equipment_minutes') then
      if jsonb_typeof(v) <> 'number' or (v::text)::numeric < 0 or (v::text)::numeric > 100000 or (k in ('width_in','height_in') and (v::text)::numeric = 0) then raise exception 'Enter a valid positive measurement or leave it unknown.'; end if;
    elsif k = 'components' then
      if jsonb_typeof(v) <> 'array' or jsonb_array_length(v) > 30 then raise exception 'List up to 30 kinds of component.'; end if;
      for c in select value from jsonb_array_elements(v) loop
        if jsonb_typeof(c) <> 'object' or jsonb_typeof(c->'label') is distinct from 'string' or length(btrim(c->>'label')) not between 1 and 100
          or jsonb_typeof(c->'quantity') is distinct from 'number' or (c->>'quantity')::numeric not between 1 and 1000
          or trunc((c->>'quantity')::numeric) <> (c->>'quantity')::numeric or (select count(*) from jsonb_object_keys(c)) <> 2 then
          raise exception 'Each component needs a name and a whole-number quantity.';
        end if;
      end loop;
    elsif k = 'unknown_fields' then
      if jsonb_typeof(v) <> 'array' or jsonb_array_length(v) > 20 or exists (
        select 1 from jsonb_array_elements(v) x where jsonb_typeof(x) <> 'string' or x #>> '{}' not in
          ('type_label','components','material','story','width_in','height_in','opening_direction','electrical','access','complexity','equipment_needed','location','area_source','weight_lb','equipment','equipment_minutes')) then
        raise exception 'Unknown answers must name unit details.';
      end if;
    elsif k = 'direction_viewpoint' then
      if jsonb_typeof(v) <> 'string' or v #>> '{}' not in ('outside looking in','inside looking out','outside looking in (default)') then raise exception 'Choose the viewing position for the direction.'; end if;
    elsif k = 'opening_direction' then
      if jsonb_typeof(v) <> 'string' or length(v #>> '{}') not between 1 and 200 then raise exception 'Describe the opening direction briefly.'; end if;
    elsif jsonb_typeof(v) <> 'string' or length(v #>> '{}') > 4000 then raise exception 'Enter a short text detail.';
    end if;
  end loop;
end $$;;
;
create or replace function public.custom_work_command(p_id uuid,p_action text,p_data jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare
  uid uuid:=auth.uid(); c public.custom_work_commands; u public.custom_work_units;
  s public.custom_work_sessions; sh public.time_shifts; oldj jsonb; outid uuid;
  jid uuid; oid uuid; at_time timestamptz; typ public.custom_work_types;
  expected uuid; target uuid; f jsonb; finish_time timestamptz;
  v_obs jsonb; v_obs_present boolean; v_obs_is_null boolean; v_expected_fact_rev numeric;
  v_old_w numeric; v_old_h numeric; v_old_src text; v_old_area text;
  v_new_w numeric; v_new_h numeric; v_new_src text; v_new_area text;
  v_event_kind text; v_width_in numeric; v_height_in numeric; v_m_unit text; v_m_source text; v_m_ref text; v_area text;
  v_estimated boolean; v_obs_actor uuid; v_reason text; v_raw_obs jsonb; v_protected boolean;
  v_origin_project uuid; v_origin_opening uuid; v_origin_kind text; v_origin_author uuid; v_origin_is_test boolean;
  v_legacy_source text; v_legacy_area text; v_norm_source text; v_norm_area text; v_origin_live_job uuid;
  v_cur_rev_num bigint; v_cur_fact_prior public.work_unit_fact_revisions;
  v_applied_intent jsonb; v_before_snapshot jsonb;
begin
  if not public.custom_work_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid work request.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  -- Shares the lock with legacy-session inserts, preventing two surfaces/devices accruing together.
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  select * into c from public.custom_work_commands where id=p_id;
  if found then
    if c.profile_id<>uid or c.payload<>jsonb_build_object('action',p_action,'data',p_data) then raise exception 'This retry belongs to a different request.'; end if;
    return c.result_id;
  end if;
  if p_action='type' then
    if not public._is_lead(uid) or public.is_test_profile(uid) then raise exception 'Only foremen and above can manage shared types.'; end if;
    target:=(p_data->>'id')::uuid;
    select * into typ from public.custom_work_types where id=target for update;
    if coalesce(typ.revision,0)<>coalesce((p_data->>'revision')::int,-1) then raise exception 'This type changed. Refresh before saving.'; end if;
    oldj:=to_jsonb(typ);
    insert into public.custom_work_types(id,label,archived,revision) values(target,btrim(p_data->>'label'),coalesce((p_data->>'archived')::boolean,false),coalesce(typ.revision,0)+1)
    on conflict(id) do update set label=excluded.label,archived=excluded.archived,revision=excluded.revision;
    outid:=target;
  elsif p_action in ('unit','link') then
    target:=(p_data->>'id')::uuid;
    select * into u from public.custom_work_units where id=target for update;
    -- Refresh active-actor status after the row wait (B4): another session
    -- could have retired/revoked this account while we waited for the lock.
    if not public.custom_work_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
    jid:=nullif(p_data->>'project_id','')::uuid;
    oid:=nullif(p_data->>'opening_id','')::uuid;
    -- Current/destination context precedes operational CAS too: a hidden-job
    -- caller must not distinguish a correct unit revision from a guessed one.
    -- This applies to all unit/link edits; nondimensional author/lead role
    -- compatibility is preserved below, subject to actual source visibility.
    if (u.project_id is not null and not public._ai_job_visible(u.project_id,uid))
      or (jid is not null and not public._ai_job_visible(jid,uid)) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if oid is not null and not exists(select 1 from project_openings where id=oid and project_id=jid and removed_at is null) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if u.opening_id is not null and not exists(select 1 from project_openings where id=u.opening_id and project_id=u.project_id and removed_at is null) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if u.id is not null and u.created_by<>uid and not public._is_lead(uid) then raise exception 'Only the author or a foreman can edit this unit.'; end if;
    if u.id is not null and coalesce(u.revision,0)<>coalesce((p_data->>'revision')::int,-1) then raise exception 'Unit details changed. Refresh before saving.'; end if;
    -- Retained evidence belongs to a previous physical unit. Ordinary creates
    -- cannot silently adopt it; restoration needs explicit reconciliation.
    if u.id is null and (exists(select 1 from public.work_unit_fact_current where unit_id=target)
      or exists(select 1 from public.work_unit_fact_revisions where unit_id=target)) then
      raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
    end if;
    if u.id is null and coalesce((p_data->>'revision')::int,-1)<>0 then raise exception 'Unit details changed. Refresh before saving.'; end if;
    if u.project_id is not null and jid is distinct from u.project_id and not public._is_lead(uid) then raise exception 'Ask a foreman to move a record already assigned to a job.'; end if;
    if u.id is not null and (jid is distinct from u.project_id or oid is distinct from u.opening_id) and length(btrim(coalesce(p_data->>'reason','')))<3 then raise exception 'Add a short reason for assigning or linking this record.'; end if;

    -- Unit dimension observation (20261108300000). f is validated against
    -- the ORIGINAL caller shape first (B8), before any server-derived value
    -- can merge over -- and thereby hide -- an invalid supplied type.
    f:=coalesce(p_data->'facts','{}');
    perform public.validate_custom_work_facts(f);
    v_old_w:=nullif(u.facts->>'width_in','')::numeric;
    v_old_h:=nullif(u.facts->>'height_in','')::numeric;
    v_old_src:=u.facts->>'measurement_source';
    v_old_area:=u.facts->>'area_source';
    v_cur_fact_prior:=null; v_cur_rev_num:=0;
    if u.id is not null then
      select r.* into v_cur_fact_prior from public.work_unit_fact_revisions r
        join public.work_unit_fact_current cu on cu.current_revision_id=r.id
        where cu.unit_id=u.id;
      if v_cur_fact_prior.id is not null then
        if v_cur_fact_prior.unit_incarnation_epoch is distinct from public._work_unit_fact_peek_epoch('unit_incarnation',target) then
          raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
        end if;
        v_cur_rev_num:=v_cur_fact_prior.revision;
      end if;
    end if;
    v_obs_present:=p_data ? 'dimension_observation';
    v_obs:=p_data->'dimension_observation';
    v_obs_is_null:=v_obs_present and jsonb_typeof(v_obs)='null';
    v_event_kind:=null; v_width_in:=null; v_height_in:=null; v_m_unit:=null; v_m_source:=null; v_m_ref:=null; v_area:=null;
    v_estimated:=null; v_obs_actor:=null; v_reason:=null; v_raw_obs:=null; v_origin_project:=null; v_origin_opening:=null;
    v_applied_intent:=null; v_before_snapshot:=null;
    v_origin_kind:='none'; v_origin_author:=null; v_origin_is_test:=null;
    v_legacy_source:=null; v_legacy_area:=null;
    if v_obs_present and jsonb_typeof(v_obs) not in ('object','null') then
      raise exception 'Invalid dimension observation.';
    end if;
    if v_obs_present then
      -- Strict type check before extraction (B8): a numeric STRING like "1"
      -- must refuse, not silently coerce.
      if jsonb_typeof(p_data->'expected_fact_revision') is distinct from 'number' then
        raise exception 'A valid expected fact revision is required with a new observation or reset.';
      end if;
      v_expected_fact_rev:=(p_data->>'expected_fact_revision')::numeric;
      if v_expected_fact_rev<>trunc(v_expected_fact_rev) or v_expected_fact_rev<0 or v_expected_fact_rev>9007199254740991 then
        raise exception 'A valid expected fact revision is required with a new observation or reset.';
      end if;
    end if;
    if v_obs_is_null then
      if jsonb_typeof(p_data->'dimension_observation_reason') is distinct from 'string' then
        raise exception 'Add a short reason for clearing this observation.';
      end if;
      v_reason:=btrim(p_data->>'dimension_observation_reason');
      if length(v_reason) not between 3 and 500 then raise exception 'Add a short reason for clearing this observation.'; end if;
      v_event_kind:='cleared';
      f:=f-'width_in'-'height_in'-'measurement_source'-'area_source';
    elsif v_obs_present then
      select n.width_in,n.height_in,n.m_unit,n.m_source,n.m_ref into v_width_in,v_height_in,v_m_unit,v_m_source,v_m_ref
        from public._work_unit_normalize_observation(v_obs) n;
      -- Server mapping, exact per contract (B3): measured->Measured,
      -- plans->From plans, estimated->Estimated.
      v_area:=case v_m_source when 'measured' then 'Measured' when 'plans' then 'From plans' when 'estimated' then 'Estimated' end;
      v_estimated:=(v_m_source='estimated');
      v_obs_actor:=uid;
      v_event_kind:='observation';
      v_raw_obs:=jsonb_build_object('width',v_obs->'width','height',v_obs->'height','unit',v_m_unit,'source',v_m_source,'sourceReference',v_m_ref);
      -- f's own width_in/height_in/measurement_source/area_source, if
      -- present, are already known valid-typed by the pre-merge validation
      -- above (B8), so this comparison is safe rather than coercive.
      if f ? 'width_in' and (f->>'width_in')::numeric is distinct from v_width_in then raise exception 'Supplied width does not match the observation.'; end if;
      if f ? 'height_in' and (f->>'height_in')::numeric is distinct from v_height_in then raise exception 'Supplied height does not match the observation.'; end if;
      if f ? 'measurement_source' and f->>'measurement_source' is distinct from v_m_source then raise exception 'Supplied measurement source does not match the observation.'; end if;
      if f ? 'area_source' and f->>'area_source' is distinct from v_area then raise exception 'Supplied area source does not match the observation.'; end if;
      f:=f || jsonb_build_object('width_in',v_width_in,'height_in',v_height_in,'measurement_source',v_m_source,'area_source',v_area);
      if f ? 'unknown_fields' then
        -- Only deliberately clear a VALID string marker naming width_in/
        -- height_in (B8); anything else -- including an invalid entry --
        -- passes through unchanged for the final validator to judge.
        f:=jsonb_set(f,'{unknown_fields}',(select coalesce(jsonb_agg(x),'[]'::jsonb) from jsonb_array_elements(f->'unknown_fields') x
          where not (jsonb_typeof(x)='string' and x#>>'{}' in ('width_in','height_in'))));
      end if;
    end if;
    v_new_w:=nullif(f->>'width_in','')::numeric; v_new_h:=nullif(f->>'height_in','')::numeric;
    v_new_src:=f->>'measurement_source'; v_new_area:=f->>'area_source';
    -- Protects area_source alongside measurement_source/width/height (B3),
    -- and -- unlike the earlier draft -- applies to a brand-new unit's
    -- first legacy save too, not only an existing row (B2): an empty
    -- legacy create stays silent, but a legacy create with real dimensions
    -- is a genuine new assertion, not historical backfill.
    if v_event_kind is null and (v_new_w,v_new_h,v_new_src,v_new_area) is distinct from (v_old_w,v_old_h,v_old_src,v_old_area) then
      if v_new_w is not null and v_new_h is not null then v_event_kind:='legacy_observation'; else v_event_kind:='incomplete'; end if;
      -- Complete server intent from the FINAL validated flat facts (B2) --
      -- never left null while the unit itself carries real dimensions.
      v_width_in:=v_new_w; v_height_in:=v_new_h;
      v_norm_source:=public._work_unit_fact_legacy_source(v_new_src);
      v_norm_area:=public._work_unit_fact_legacy_source(v_new_area);
      -- Unknown or contradictory labels never become trusted provenance.
      if (v_new_src is null or v_norm_source is not null)
        and (v_new_area is null or v_norm_area is not null)
        and (v_norm_source is null or v_norm_area is null or v_norm_source=v_norm_area) then
        v_m_source:=coalesce(v_norm_source,v_norm_area);
      end if;
      v_estimated:=case when v_norm_source='estimated' or v_norm_area='estimated' then true
        when v_m_source is not null then false else null end;
    end if;
    if v_event_kind is null and u.id is not null and (jid is distinct from u.project_id or oid is distinct from u.opening_id)
        and v_cur_fact_prior.id is not null then
      v_event_kind:='relink';
      v_width_in:=v_cur_fact_prior.width_in; v_height_in:=v_cur_fact_prior.height_in;
      v_m_unit:=v_cur_fact_prior.measurement_unit; v_m_source:=v_cur_fact_prior.measurement_source; v_m_ref:=v_cur_fact_prior.source_reference;
      v_estimated:=v_cur_fact_prior.estimated; v_obs_actor:=v_cur_fact_prior.observation_actor_id; v_raw_obs:=v_cur_fact_prior.raw_observation;
      -- Origin is carried forward UNCHANGED through a pure relink (B1) --
      -- never reset to the new destination job.
      v_origin_project:=v_cur_fact_prior.origin_project_id; v_origin_opening:=v_cur_fact_prior.origin_opening_id;
      v_origin_kind:=v_cur_fact_prior.origin_kind; v_origin_author:=v_cur_fact_prior.origin_author_id;
      v_origin_is_test:=v_cur_fact_prior.origin_is_test;
    end if;
    if v_event_kind is not null and v_event_kind not in ('relink','cleared')
      and (v_new_w is not null or v_new_h is not null or v_new_src is not null or v_new_area is not null) then
      -- A genuinely fresh assertion (new/legacy/incomplete) establishes its
      -- own origin at the current binding; 'relink' already set it above
      -- from the predecessor, and 'cleared' has no observation to attribute.
      v_origin_project:=jid; v_origin_opening:=oid;
      v_origin_kind:=case when jid is null then 'unassigned' else 'job' end;
      v_origin_author:=coalesce(u.created_by,uid);
      v_origin_is_test:=public.is_test_profile(v_origin_author);
    end if;
    -- Every recorded event is protected, including a relink of a legacy/
    -- incomplete (not-yet-raw) prior observation (B4): a relink only ever
    -- reaches this point when v_cur_fact_prior.id is not null, so there is
    -- always something real being administered.
    v_protected:=v_event_kind is not null;
    if v_protected then
      -- All actors, including authors and new creators, pass source checks.
      -- Prior origin is required even for replacement/reset: before_snapshot
      -- preserves that evidence. No source IDs are exposed on a refusal.
      if (u.id is not null and not public._work_unit_fact_context_visible(uid,
          case when u.project_id is null then 'unassigned' else 'job' end,
          u.project_id,u.opening_id,u.created_by,public.is_test_profile(u.created_by),false))
        or not public._work_unit_fact_context_visible(uid,
          case when jid is null then 'unassigned' else 'job' end,
          jid,oid,coalesce(u.created_by,uid),public.is_test_profile(coalesce(u.created_by,uid)),false)
        or (v_cur_fact_prior.id is not null and not public._work_unit_fact_context_visible(uid,
          v_cur_fact_prior.origin_kind,v_cur_fact_prior.origin_project_id,v_cur_fact_prior.origin_opening_id,
          v_cur_fact_prior.origin_author_id,v_cur_fact_prior.origin_is_test,true)) then
        raise exception 'Unit source is unavailable.' using errcode='42501';
      end if;
      select project_id into v_origin_live_job from public.project_openings
        where id=v_cur_fact_prior.origin_opening_id and removed_at is null;
      if not public._work_unit_fact_can_edit_dimensions(uid,coalesce(u.created_by,uid),
          array[u.project_id,jid,v_cur_fact_prior.origin_project_id,v_origin_live_job]) then
        raise exception 'Only the author or an authorized foreman, supervisor or owner can change this unit''s dimensions.' using errcode='42501';
      end if;
    end if;
    -- Do not disclose even a private fact-revision mismatch before source
    -- authorization. Input types above are caller-owned, revision is evidence.
    if v_obs_present and v_expected_fact_rev::bigint<>v_cur_rev_num then
      raise exception 'Unit observation changed. Refresh before saving.';
    end if;
    v_legacy_source:=v_new_src; v_legacy_area:=v_new_area;

    perform public.validate_custom_work_facts(f);

    -- Absent row: FOR UPDATE locked nothing, so two concurrent creators can
    -- both reach here (B5). Decide via a real INSERT conflict rather than
    -- a blind UPSERT -- the loser refuses cleanly instead of silently
    -- overwriting the winner's row, author, and private fact.
    if u.id is null then
      insert into public.custom_work_units(id,project_id,opening_id,created_by,label,type_label,facts,revision)
      values(target,jid,oid,uid,btrim(p_data->>'label'),coalesce(nullif(btrim(p_data->>'type_label'),''),'Unknown'),f,1)
      on conflict(id) do nothing;
      if not found then raise exception 'Unit details changed. Refresh before saving.'; end if;
      -- Recheck after the INSERT wait too: a competing create/delete could
      -- have left retained evidence after our initial absent-row check.
      if exists(select 1 from public.work_unit_fact_current where unit_id=target)
        or exists(select 1 from public.work_unit_fact_revisions where unit_id=target) then
        raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
      end if;
      oldj:=null;
    else
      oldj:=to_jsonb(u);
      update public.custom_work_units set project_id=jid,opening_id=oid,label=btrim(p_data->>'label'),
        type_label=coalesce(nullif(btrim(p_data->>'type_label'),''),'Unknown'),facts=f,revision=u.revision+1,updated_at=now()
        where id=target;
    end if;
    update public.custom_work_units set legacy_time_present=exists(select 1 from unit_sessions where opening_id=oid) or exists(select 1 from task_sessions where opening_id=oid) where id=target;
    -- Attribution moves the observation, never the underlying payroll shift.
    update public.custom_work_sessions set project_id=jid,review_required=review_required or exists(select 1 from time_shifts t where t.id=shift_id and (t.project_id is distinct from jid or t.status in ('needs_finish','rejected','voided'))),revision=revision+1 where unit_id=target and project_id is distinct from jid;
    outid:=target;
    if v_event_kind is not null then
      -- jsonb_strip_nulls: a key assigned the PL/pgSQL `null` scalar must
      -- not become a stored JSON null (B2) -- jsonb_build_object always
      -- encodes a SQL NULL argument as JSON null, and the helper's
      -- raw_observation column CHECK only accepts SQL NULL or an object.
      -- Stripping the key entirely keeps `->` extraction returning true
      -- SQL NULL on the other side.
      v_applied_intent:=jsonb_strip_nulls(jsonb_build_object('event_kind',v_event_kind,'width_in',v_width_in,'height_in',v_height_in,
        'measurement_unit',v_m_unit,'measurement_source',v_m_source,'source_reference',v_m_ref,
        'raw_observation',v_raw_obs,'estimated',v_estimated,'observation_actor_id',v_obs_actor,'reason',v_reason,
        'origin_project_id',v_origin_project,'origin_opening_id',v_origin_opening,
        'origin_kind',v_origin_kind,'origin_author_id',v_origin_author,'origin_is_test',v_origin_is_test,
        'legacy_measurement_source',v_legacy_source,'legacy_area_source',v_legacy_area));
      v_before_snapshot:=jsonb_strip_nulls(jsonb_build_object('width_in',v_old_w,'height_in',v_old_h,'measurement_source',v_old_src,'area_source',v_old_area,
        'raw_observation',case when v_cur_fact_prior.id is not null then v_cur_fact_prior.raw_observation else null end));
    end if;
  elsif p_action in ('start','stop') then
    at_time:=coalesce((p_data->>'at')::timestamptz,now());
    if at_time>now()+interval '2 minutes' or at_time<now()-interval '7 days' then raise exception 'This work time needs a foreman review. Check the device clock.'; end if;
    expected:=nullif(p_data->>'expected_session_id','')::uuid;
    select * into s from public.custom_work_sessions where profile_id=uid and ended_at is null for update;
    if s.id is null and expected is not null then
      select * into s from public.custom_work_sessions where id=expected and profile_id=uid and ended_at is not null and end_reason in ('clock_out','stop') for update;
      if s.id is not null and (at_time<s.started_at or at_time>s.ended_at) then s.id:=null; end if;
    end if;
    if s.id is distinct from expected then raise exception 'Your current work changed. Sync and review before retrying.'; end if;
    if s.id is not null and at_time<s.started_at then raise exception 'The finish cannot be before the start.'; end if;
    if p_action='start' then
      select * into sh from public.time_shifts where id=(p_data->>'shift_id')::uuid and profile_id=uid for update;
      if sh.id is null or sh.status not in ('open','submitted','approved') or sh.clock_in_at>at_time or (sh.clock_out_at is not null and sh.clock_out_at<=at_time) or (sh.break_started_at is not null and sh.break_started_at<=at_time) then raise exception 'Clock in or resume your job clock before starting work.'; end if;
      -- The job clock already enforces its safety step; do not ask a second time.
      if now()-sh.clock_in_at>interval '16 hours' and sh.clock_out_at is null then raise exception 'Finish the older job clock before starting new work.'; end if;
      target:=nullif(p_data->>'unit_id','')::uuid;
      jid:=sh.project_id;
      -- Both kinds of start wait for today's toolbox signature, right after the
      -- open-shift check above (20261031000000): a UNIT start (a unit_id) meets
      -- the same gate every other unit-start RPC passes; PREP TIME (no unit_id;
      -- kind 'idle') meets its own, in its own sentence — the owner's answer of
      -- 2026-09-24. The two lines are the only change to this branch.
      if target is not null then
        perform public._unit_work_gate(uid);
        select * into u from public.custom_work_units where id=target for update;
        if u.id is null or (u.project_id is null and u.created_by<>uid and not public._is_lead(uid)) then raise exception 'That custom unit is unavailable.'; end if;
        if u.project_id is not null and u.project_id is distinct from sh.project_id then raise exception 'Switch your job clock to this unit''s job first.'; end if;
        jid:=u.project_id;
      else
        perform public._prep_time_gate(uid);
        if length(btrim(coalesce(p_data->>'description','')))=0 then raise exception 'Describe your idle time.'; end if;
      end if;
      if jid is not null and not exists(select 1 from projects where id=jid and deleted_at is null) then raise exception 'That job is unavailable.'; end if;
      -- Never rewrite a newer activity based on a stale/offline start.
      if exists(select 1 from public.custom_work_sessions where profile_id=uid and id is distinct from s.id and coalesce(ended_at,'infinity')>at_time) or exists(select 1 from public.unit_sessions where profile_id=uid and (started_at>at_time or (ended_at is not null and ended_at>at_time))) or exists(select 1 from public.task_sessions where profile_id=uid and (started_at>at_time or (ended_at is not null and ended_at>at_time))) then raise exception 'This overlaps recorded work. Ask a foreman to review the timeline.'; end if;
      if at_time<now()-interval '2 minutes' and exists(select 1 from opening_phases where started_by=uid and status='active' and paused_at is null) then raise exception 'A flashing timer is now running. Ask a foreman to reconcile the older work.'; end if;
      update public.task_sessions set ended_at=at_time where profile_id=uid and ended_at is null;
      update public.unit_sessions set ended_at=at_time,end_reason='handoff' where profile_id=uid and ended_at is null;
      update public.opening_phases set paused_at=at_time where started_by=uid and status='active' and paused_at is null;
    end if;
    if s.id is not null then
      oldj:=to_jsonb(s);
      update public.custom_work_sessions set ended_at=at_time,end_reason=case when p_action='start' then 'switch' else 'stop' end,
        outcome=nullif(p_data->>'outcome',''),description=coalesce(p_data->>'finish_note',description),delay_reason=coalesce(p_data->>'delay_reason',delay_reason),revision=revision+1 where id=s.id;
      insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value) select project_id,uid,id,'stop',oldj,to_jsonb(x) from public.custom_work_sessions x where id=s.id;
    end if;
    if p_action='start' then
      -- A later visit reopens completion; the worker can mark the whole install done again.
      update public.custom_work_units set facts=jsonb_set(facts,'{installation_complete}','"No"'),revision=revision+1,updated_at=now() where id=target and facts->>'installation_complete'='Yes';
      if found then
        insert into custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason) select jid,uid,id,'reopen',to_jsonb(u),to_jsonb(x),'New work visit' from custom_work_units x where id=target;
      end if;
      outid:=(p_data->>'id')::uuid;
      insert into public.custom_work_sessions(id,profile_id,shift_id,project_id,unit_id,kind,participation,stage,description,started_at,ended_at,end_reason,shift_status,review_required)
      values(outid,uid,sh.id,jid,target,case when target is null then 'idle' else 'unit' end,coalesce(p_data->>'participation','install'),case when target is null then 'Idle time' else coalesce(p_data->>'stage','Installing') end,coalesce(p_data->>'description',''),at_time,sh.clock_out_at,case when sh.clock_out_at is not null then 'clock_out' end,sh.status,jid is distinct from sh.project_id or (sh.clock_out_at is not null and coalesce(sh.break_seconds,0)>0));
      oldj:=null;
    else outid:=s.id; jid:=s.project_id;
    end if;
  elsif p_action='session' then
    select * into s from public.custom_work_sessions where id=(p_data->>'id')::uuid for update;
    if s.id is null or (s.profile_id<>uid and not public._is_lead(uid)) then raise exception 'Only the worker or a foreman can correct this record.'; end if;
    if s.project_id is not null and not exists(select 1 from projects where id=s.project_id and deleted_at is null) then raise exception 'That job is unavailable.'; end if;
    if s.revision<>coalesce((p_data->>'revision')::int,-1) then raise exception 'This record changed. Refresh before saving.'; end if;
    if length(btrim(coalesce(p_data->>'reason','')))<3 then raise exception 'Add a correction reason.'; end if;
    if s.kind='idle' and length(btrim(coalesce(p_data->>'description',s.description)))=0 then raise exception 'Describe your idle time.'; end if;
    oldj:=to_jsonb(s); jid:=s.project_id; outid:=s.id;
    if coalesce((p_data->>'review_time')::boolean,false) or p_data ? 'started_at' or p_data ? 'ended_at' then
      if not public._is_lead(uid) then raise exception 'Only foremen and above can correct captured times.'; end if;
      if s.ended_at is null then raise exception 'Stop the activity before correcting its time.'; end if;
      select * into sh from time_shifts where id=s.shift_id for update;
      at_time:=coalesce((p_data->>'started_at')::timestamptz,s.started_at);
      finish_time:=coalesce((p_data->>'ended_at')::timestamptz,s.ended_at);
      if sh.status not in ('submitted','approved') or sh.clock_out_at is null or s.project_id is distinct from sh.project_id or s.project_id is null
        or at_time<sh.clock_in_at or finish_time>sh.clock_out_at or finish_time<at_time or finish_time-at_time>interval '16 hours' then
        raise exception 'First resolve the job, timecard, or shift bounds. Captured time must fit its closed job clock.';
      end if;
      if exists(select 1 from custom_work_sessions x where x.profile_id=s.profile_id and x.id<>s.id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time)
        or exists(select 1 from unit_sessions x where x.profile_id=s.profile_id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time)
        or exists(select 1 from task_sessions x where x.profile_id=s.profile_id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time) then
        raise exception 'The corrected interval overlaps other recorded work.';
      end if;
      if extract(epoch from finish_time-at_time)+(select coalesce(sum(extract(epoch from ended_at-started_at)),0) from custom_work_sessions where shift_id=s.shift_id and id<>s.id)
        >extract(epoch from sh.clock_out_at-sh.clock_in_at)-coalesce(sh.break_seconds,0)+1 then
        raise exception 'Captured activity exceeds the worked shift time after breaks. Review the other intervals too.';
      end if;
      update public.custom_work_sessions set started_at=at_time,ended_at=finish_time,review_required=false,end_reason='reviewed' where id=s.id;
    end if;
    update public.custom_work_sessions set description=coalesce(p_data->>'description',description),outcome=nullif(p_data->>'outcome',''),delay_reason=coalesce(p_data->>'delay_reason',delay_reason),revision=revision+1 where id=s.id;
  else raise exception 'Unknown work action.';
  end if;
  -- Audit values live behind the same job/author boundary as the records.
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason)
  values(jid,uid,coalesce(outid,p_id),p_action,oldj,
    case when p_action in ('unit','link') then (select to_jsonb(x) from public.custom_work_units x where id=outid)
      when p_action='type' then (select to_jsonb(x) from public.custom_work_types x where id=outid)
      else (select to_jsonb(x) from public.custom_work_sessions x where id=outid) end,coalesce(p_data->>'reason',''));
  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,jsonb_build_object('action',p_action,'data',p_data),outid);
  if p_action in ('unit','link') and v_event_kind is not null then
    perform public._work_record_unit_fact(p_id,v_applied_intent,v_before_snapshot,outid);
  end if;
  return outid;
end; $$;;
;
create function public.custom_work_follow_legacy() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  update public.custom_work_units set legacy_time_present=true where opening_id=new.opening_id and not legacy_time_present;
  if new.ended_at is null then
    perform pg_advisory_xact_lock(hashtextextended(new.profile_id::text,7281));
    update public.custom_work_sessions set ended_at=greatest(started_at,new.started_at),end_reason='legacy_unit',revision=revision+1 where profile_id=new.profile_id and ended_at is null;
  end if;
  return new;
end; $$;;
;
create function public.custom_work_follow_phase() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if new.started_by is not null and new.status='active' and new.paused_at is null then
    if TG_OP='UPDATE' and old.status='active' and old.paused_at is null then return new; end if;
    perform pg_advisory_xact_lock(hashtextextended(new.started_by::text,7281));
    update public.custom_work_sessions set ended_at=greatest(started_at,now()),end_reason='legacy_phase',revision=revision+1 where profile_id=new.started_by and ended_at is null;
  end if;
  return new;
end; $$;;
;
create function public.custom_work_follow_shift() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare finish_at timestamptz;
begin
  update public.custom_work_sessions set shift_status=new.status,
    review_required=review_required or new.status in ('needs_finish','rejected','voided') or project_id is distinct from new.project_id
      or started_at<new.clock_in_at or (ended_at is not null and new.clock_out_at is not null and ended_at>new.clock_out_at)
    where shift_id=new.id;
  finish_at:=coalesce(new.clock_out_at,new.break_started_at);
  if finish_at is null and new.status<>'open' then finish_at:=now(); end if;
  if finish_at is not null then
    update public.custom_work_sessions set review_required=review_required or started_at>finish_at,ended_at=greatest(started_at,finish_at),end_reason=case when new.break_started_at is not null and new.clock_out_at is null then 'break' when new.status in ('needs_finish','rejected','voided') then 'needs_review' else 'clock_out' end,revision=revision+1 where shift_id=new.id and ended_at is null;
  end if;
  return new;
end; $$;;
;
create or replace function public.can_edit_timecard(p_profile_id uuid)
returns boolean language sql stable security definer
set search_path = public, pg_temp as $$
  select auth.uid() is not null and not public.is_partner_user() and exists (
    select 1 from profiles target where target.id=p_profile_id
    and target.role in ('installer','foreman','lead','supervisor','owner','admin','big_boss')
    and (_is_supervisor(auth.uid()) or (_is_lead(auth.uid())
      and (p_profile_id=auth.uid() or target.role='installer')))
  );
$$;;
;
create or replace function public.can_approve_timecard(p_profile_id uuid)
returns boolean language sql stable security definer
set search_path = public, pg_temp as $$
  select auth.uid() is not null and not public.is_partner_user() and exists (
    select 1 from profiles target where target.id=p_profile_id
    and target.role in ('installer','foreman','lead','supervisor','owner','admin','big_boss')
    and (_is_supervisor(auth.uid()) or (_is_lead(auth.uid())
      and target.role in ('installer','foreman','lead')))
  );
$$;;
;
create or replace function public.edit_shift_with_description(
  p_shift_id uuid, p_project_id uuid default null, p_cost_code_id uuid default null,
  p_clock_in_at timestamptz default null, p_clock_out_at timestamptz default null,
  p_break_seconds int default null, p_note text default null,
  p_description text default null
) returns time_shifts language plpgsql security definer
set search_path = public, pg_temp as $$
declare v_shift time_shifts; v_old_note text; v_description text := nullif(btrim(p_description),'');
begin
  if length(v_description)>4000 then raise exception 'Keep the description under 4,000 characters.'; end if;
  v_shift := public.edit_shift(p_shift_id,p_project_id,p_cost_code_id,p_clock_in_at,p_clock_out_at,p_break_seconds,p_note);
  v_old_note := v_shift.note;
  if v_old_note is distinct from v_description then
    update time_shifts set note=v_description where id=p_shift_id returning * into v_shift;
    insert into time_shift_edits(shift_id,edited_by,field,old_value,new_value,reason)
      values(p_shift_id,auth.uid(),'note',v_old_note,v_description,btrim(p_note));
  end if;
  return v_shift;
end;
$$;;
;
create or replace function public.approve_timecard_week(
  p_profile_id uuid, p_start timestamptz, p_end timestamptz, p_expected jsonb
) returns int language plpgsql security definer
set search_path = public, pg_temp as $$
declare v_count int; v_rows jsonb;
begin
  if not public.can_approve_timecard(p_profile_id) then
    raise exception 'Foremen may approve installer and foreman time; supervisor time requires a supervisor.';
  end if;
  if p_start is null or p_end is null or p_end-p_start not between interval '167 hours' and interval '169 hours' then
    raise exception 'Select one full week to approve.';
  end if;
  if p_expected is null or jsonb_typeof(p_expected)<>'array' then
    raise exception 'Refresh this timecard before approving.';
  end if;
  -- Serialize concurrent approvals, then snapshot locked rows. New punches
  -- arriving later remain submitted and show that another review is needed.
  perform 1 from profiles where id=p_profile_id for no key update;
  perform 1 from time_shifts where profile_id=p_profile_id and clock_in_at>=p_start
    and clock_in_at<p_end order by id for update;
  select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) into v_rows from time_shifts s
    where profile_id=p_profile_id and clock_in_at>=p_start and clock_in_at<p_end and status<>'voided';
  if jsonb_array_length(v_rows)=0 then raise exception 'There are no entries in this week.'; end if;
  if exists (select 1 from jsonb_to_recordset(v_rows) as s(status text,clock_out_at timestamptz)
    where status not in ('submitted','approved') or clock_out_at is null) then
    raise exception 'Finish or correct the open, unfinished, or rejected entries before approving this week.';
  end if;
  if jsonb_array_length(p_expected)<>jsonb_array_length(v_rows)
    or (select count(distinct id) from jsonb_to_recordset(p_expected) as e(id uuid))<>jsonb_array_length(v_rows)
    or exists (
      select 1
      from jsonb_to_recordset(v_rows) as s(id uuid,project_id uuid,cost_code_id uuid,clock_in_at timestamptz,clock_out_at timestamptz,break_seconds int,note text,edited_at timestamptz)
      full join jsonb_to_recordset(p_expected) as e(id uuid,project_id uuid,cost_code_id uuid,clock_in_at timestamptz,clock_out_at timestamptz,break_seconds int,note text,edited_at timestamptz) on e.id=s.id
      where s.id is null or e.id is null or row(s.project_id,s.cost_code_id,s.clock_in_at,s.clock_out_at,s.break_seconds,s.note,s.edited_at)
        is distinct from row(e.project_id,e.cost_code_id,e.clock_in_at,e.clock_out_at,e.break_seconds,e.note,e.edited_at)
    ) then raise exception 'This timecard changed. Refresh it and review the week again.';
  end if;
  update time_shifts set status='approved',approved_by=auth.uid(),approved_at=now()
    where profile_id=p_profile_id and status='submitted'
      and id in (select (entry->>'id')::uuid from jsonb_array_elements(v_rows) as entry);
  get diagnostics v_count=row_count;
  return v_count;
end;
$$;;
;
create or replace function public.guard_timecard_role_boundary()
returns trigger language plpgsql
set search_path = public, pg_temp as $$
declare v_target uuid; v_approval_only boolean;
begin
  if auth.uid() is null then
    if current_user in ('authenticated','anon') then raise exception 'Sign in to change time.'; end if;
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if public.is_partner_user() then raise exception 'A crew login is required.'; end if;
  if tg_op='DELETE' then
    if not _is_supervisor(auth.uid()) then raise exception 'Only supervisors may remove time.'; end if;
    return old;
  end if;
  v_target := new.profile_id;
  if tg_op='UPDATE' then
    if new.profile_id is distinct from old.profile_id then raise exception 'A punch cannot be moved to another person.'; end if;
    if (new.status='voided' or old.status='voided') and not _is_supervisor(auth.uid()) then
      raise exception 'Only supervisors may remove or restore time.';
    end if;
    v_approval_only := (to_jsonb(new)-array['status','approved_by','approved_at','rejected_by','rejected_at','reject_reason'])
      is not distinct from (to_jsonb(old)-array['status','approved_by','approved_at','rejected_by','rejected_at','reject_reason']);
    if v_approval_only and new.status in ('approved','rejected') then
      if current_user in ('authenticated','anon') or not public.can_approve_timecard(v_target) then
        raise exception 'Use weekly review to approve time.';
      end if;
      return new;
    end if;
    -- A direct REST edit cannot keep an old approval on changed hours or
    -- forge an approver. The reviewed RPCs own approval transitions.
    if current_user in ('authenticated','anon') and
      (new.approved_by is distinct from old.approved_by or new.approved_at is distinct from old.approved_at
        or new.status='approved') then raise exception 'Use the timecard editor to change approved time.'; end if;
  elsif new.status='approved' and current_user in ('authenticated','anon') then
    raise exception 'Use weekly review to approve time.';
  end if;
  if v_target<>auth.uid() and not public.can_edit_timecard(v_target) then
    raise exception 'Foremen may edit their own time and installers; supervisor time requires a supervisor.';
  end if;
  return new;
end;
$$;;
;
create or replace function public.guard_time_entry_import_source()
returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
  if tg_op='UPDATE' and new.source_import_key is not distinct from old.source_import_key
    and new.source_import is not distinct from old.source_import then return new; end if;
  if tg_op='INSERT' and new.source_import_key is null and new.source_import is null then return new; end if;
  if auth.uid() is not null or current_user in ('authenticated','anon') then
    raise exception 'Original import evidence can only be written by the import service.';
  end if;
  if new.source_import_key is null or new.source_import_key !~ '^[a-f0-9]{64}$'
    or new.source_import is null or jsonb_typeof(new.source_import)<>'object'
    or new.source_import->>'source' is distinct from 'busybusy'
    or jsonb_typeof(new.source_import->'original') is distinct from 'object' then
    raise exception 'Import evidence is incomplete.';
  end if;
  return new;
end; $$;;
;
create or replace function public.can_file_daily_log()
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select auth.uid() is not null and not public.is_partner_user() and exists (
    select 1 from public.profiles where id = auth.uid() and access_revoked_at is null
      and role in ('installer','foreman','lead','supervisor','admin','owner','big_boss')
  )
$$;;
;
create or replace function public.claim_description_dictation(p_user_id uuid)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
declare v_count integer;
begin
  if not exists (select 1 from profiles where id = p_user_id and retired_at is null and access_revoked_at is null) then return false; end if;
  delete from description_dictation_usage where day < (now() at time zone 'UTC')::date - 7;
  insert into description_dictation_usage(profile_id, day, requests)
    values(p_user_id, (now() at time zone 'UTC')::date, 1)
    on conflict (profile_id, day) do update
      set requests = description_dictation_usage.requests + 1
      where description_dictation_usage.requests < 120
    returning requests into v_count;
  return v_count is not null;
end;
$$;;
;
create or replace function public.set_compensation(
  p_profile_id uuid, p_pay_basis text, p_amount_cents integer,
  p_effective_from date default null
) returns public.pay_rates language plpgsql security definer
set search_path = public, pg_temp as $$
declare v_row pay_rates; v_from date;
begin
  if coalesce(public.my_role_rank(), -1) < 3 or public.is_partner_user()
     or not exists (select 1 from profiles where id = auth.uid()
       and access_revoked_at is null and retired_at is null) then
    raise exception 'Only a current owner can set pay.' using errcode = '42501';
  end if;
  if p_pay_basis is null or p_pay_basis not in ('hourly', 'salary_monthly')
     or p_amount_cents is null or p_amount_cents < 0 then
    raise exception 'Choose hourly or monthly salary and enter a valid amount.';
  end if;
  -- Lock the person so simultaneous changes cannot miss one another's dates.
  perform 1 from profiles where id = p_profile_id and retired_at is null
    and not coalesce(is_partner, false) for update;
  if not found then raise exception 'Choose a current crew member.'; end if;
  v_from := coalesce(p_effective_from, case when p_pay_basis = 'salary_monthly'
    then date_trunc('month', current_date)::date else current_date end);
  if p_pay_basis = 'salary_monthly' and extract(day from v_from) <> 1 then
    raise exception 'Salary changes start on the first day of a month.';
  end if;
  insert into pay_rates(profile_id, hourly_cents, pay_basis, monthly_cents, effective_from, set_by)
    values(p_profile_id, case when p_pay_basis = 'hourly' then p_amount_cents else 0 end,
      p_pay_basis, case when p_pay_basis = 'salary_monthly' then p_amount_cents else null end,
      v_from, auth.uid())
    on conflict(profile_id, effective_from) do update set
      hourly_cents = excluded.hourly_cents, pay_basis = excluded.pay_basis,
      monthly_cents = excluded.monthly_cents, set_by = excluded.set_by, created_at = now()
    returning * into v_row;
  -- Check both neighbors, including future rates and backdated edits. The
  -- initial version deliberately has no hidden mid-month proration rule.
  if exists (select 1 from (
      select effective_from, pay_basis,
        lag(pay_basis) over(order by effective_from) as previous_basis
      from pay_rates where profile_id = p_profile_id
    ) history where (pay_basis = 'salary_monthly' or previous_basis = 'salary_monthly')
      and extract(day from effective_from) <> 1) then
    raise exception 'Switching to or from salary must start on the first day of a month. Check later rates too.';
  end if;
  return v_row;
end;
$$;;
;
create function public.service_internal() returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select auth.uid() is not null and not public.is_partner_user() and exists(
    select 1 from profiles where id=auth.uid() and retired_at is null and access_revoked_at is null
      and role in ('installer','foreman','supervisor','owner'))
$$;;
;
create function public.service_job_access(j uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select public.service_internal() and exists(select 1 from projects where id=j and deleted_at is null
    and (not is_test or exists(select 1 from profiles where id=auth.uid() and role in ('supervisor','owner'))))
$$;;
;
create function public.service_supervisor() returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select public.service_internal() and exists(select 1 from profiles where id=auth.uid() and role in ('supervisor','owner'))
$$;;
