create function public.service_shift_bounds(p_visit uuid) returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
  select coalesce(jsonb_object_agg(q.id::text,jsonb_build_object('clock_in_at',q.clock_in_at,'clock_out_at',q.clock_out_at,'break_seconds',q.break_seconds,'status',q.status,'project_id',q.project_id)),'{}'::jsonb)
  from (select distinct sh.id,sh.clock_in_at,sh.clock_out_at,sh.break_seconds,sh.status,sh.project_id
    from service_time_sessions ss join service_visits v on v.id=ss.visit_id join time_shifts sh on sh.id=ss.shift_id
    where v.id=p_visit and public.service_job_access(v.project_id)) q
$$;;
;
create function public.service_validate_details(d jsonb) returns void language plpgsql set search_path=public,pg_temp as $$
declare k text; v jsonb; begin
  if jsonb_typeof(d) is distinct from 'object' or octet_length(d::text)>30000 then raise exception 'Service details are too large.'; end if;
  for k,v in select * from jsonb_each(d) loop
    if k not in ('crew_names','truck','truck_id','estimated_miles','actual_miles','lodging','travel_notes','scheduled_date','lodging_cost','parts_cost','other_cost') then raise exception 'Unknown service detail.'; end if;
    if k in ('estimated_miles','actual_miles','lodging_cost','parts_cost','other_cost') then
      if jsonb_typeof(v)<>'number' or (v::text)::numeric<0 or (v::text)::numeric>100000 then raise exception 'Enter a valid nonnegative amount.'; end if;
    elsif k='lodging' then
      if jsonb_typeof(v)<>'boolean' then raise exception 'Choose whether lodging is needed.'; end if;
    elsif jsonb_typeof(v)<>'string' or length(v #>> '{}')>4000 then raise exception 'Enter a short service detail.'; end if;
  end loop;
end $$;;
;
create function public.service_notify_lodging(target uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v service_visits; recipients uuid[]; message_id uuid; job text;
begin
  select * into v from service_visits where id=target for update;
  if not coalesce((v.details->>'lodging')::boolean,false) or v.lodging_message_id is not null then return; end if;
  select array_agg(p.id) into recipients from service_job_supervisors s join profiles p on p.id=s.profile_id
    where s.project_id=v.project_id and not p.is_partner and p.retired_at is null and p.access_revoked_at is null and p.role in ('supervisor','owner');
  if coalesce(cardinality(recipients),0)=0 then
    select array_agg(id) into recipients from profiles where not is_partner and retired_at is null and access_revoked_at is null and role='supervisor';
  end if;
  if coalesce(cardinality(recipients),0)=0 then return; end if;
  select job_code||' · '||name into job from projects where id=v.project_id;
  message_id:=gen_random_uuid();
  insert into project_messages(id,project_id,author_id,body,mentions) values(message_id,v.project_id,auth.uid(),
    'Lodging needed for service: '||job||E'\nCrew: '||coalesce(nullif(v.details->>'crew_names',''),'See service visit')||E'\nDate: '||coalesce(nullif(v.details->>'scheduled_date',''),'Confirm with requester')||E'\nhttps://app.forgewd.com/service?visit='||v.id,recipients);
  update service_visits set lodging_message_id=message_id where id=v.id;
end $$;;
;
create function public.service_command(p_id uuid,p_action text,p_data jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare uid uuid:=auth.uid(); c service_commands; v service_visits; u service_visit_units;
  s service_time_sessions; sh time_shifts; m service_media; oldj jsonb; afterj jsonb;
  target uuid; jid uuid; result uuid; at_time timestamptz; boundary timestamptz; expected uuid; v_details jsonb; recipient uuid; total numeric;
begin
  if not public.service_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
  if p_id is null or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>100000 then raise exception 'Invalid service request.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7482));
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  select * into c from service_commands where id=p_id;
  if found then
    if c.profile_id<>uid or c.payload<>jsonb_build_object('action',p_action,'data',p_data) then raise exception 'This retry belongs to another request.'; end if;
    return c.result_id;
  end if;
  target:=nullif(p_data->>'visit_id','')::uuid;
  if target is not null then
    select * into v from service_visits where id=target for update;
    if not found or not public.service_job_access(v.project_id) then raise exception 'That service visit is unavailable.' using errcode='42501'; end if;
    jid:=v.project_id;
  else jid:=(p_data->>'project_id')::uuid;
  end if;
  if not public.service_job_access(jid) then raise exception 'That job is unavailable.' using errcode='42501'; end if;
  if p_action not in ('visit','supervisor') and v.id is null then raise exception 'Choose a service visit.'; end if;
  if p_action='supervisor' then
    if not public.service_supervisor() then raise exception 'Only a supervisor can assign the job supervisor.' using errcode='42501'; end if;
    recipient:=nullif(p_data->>'profile_id','')::uuid;
    if recipient is not null and not exists(select 1 from profiles where id=recipient and not is_partner and retired_at is null and access_revoked_at is null and role in ('supervisor','owner')) then raise exception 'Choose an active supervisor or owner.'; end if;
    select to_jsonb(x) into oldj from service_job_supervisors x where project_id=jid;
    insert into service_job_supervisors(project_id,profile_id) values(jid,recipient) on conflict(project_id) do update set profile_id=excluded.profile_id;
    result:=jid; afterj:=jsonb_build_object('profile_id',recipient);
  elsif p_action='visit' then
    v_details:=coalesce(p_data->'details','{}'); perform service_validate_details(v_details);
    if v.id is null then
      result:=(p_data->>'id')::uuid;
      if nullif(p_data->>'previous_visit_id','') is not null and not exists(select 1 from service_visits where id=(p_data->>'previous_visit_id')::uuid and project_id=jid) then raise exception 'The earlier visit belongs to another job.'; end if;
      insert into service_visits(id,project_id,created_by,previous_visit_id,details) values(result,jid,uid,nullif(p_data->>'previous_visit_id','')::uuid,v_details);
      target:=result;
    else
      if v.created_by is distinct from uid and not public._is_lead(uid) then raise exception 'The visit creator or a foreman can edit trip details.' using errcode='42501'; end if;
      if v.revision is distinct from (p_data->>'revision')::int then raise exception 'This visit changed. Refresh before saving.'; end if;
      oldj:=to_jsonb(v); result:=v.id;
      update service_visits x set details=p_data->'details',revision=x.revision+1,reviewed_at=null,reviewed_by=null,updated_at=now() where x.id=v.id;
    end if;
    perform service_notify_lodging(result);
    select to_jsonb(x) into afterj from service_visits x where id=result;
  elsif p_action='unit' then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    select * into u from service_visit_units where id=(p_data->>'id')::uuid for update;
    if found then
      if u.visit_id<>v.id or (u.created_by is distinct from uid and v.created_by is distinct from uid and not public._is_lead(uid)) then raise exception 'This unit is not editable from this visit.' using errcode='42501'; end if;
      if u.revision is distinct from (p_data->>'revision')::int then raise exception 'This unit changed. Refresh before saving.'; end if;
      oldj:=to_jsonb(u);
    end if;
    if nullif(p_data->>'work_unit_id','') is not null and not exists(select 1 from custom_work_units where id=(p_data->>'work_unit_id')::uuid and project_id=jid) then raise exception 'That saved unit belongs to another job.'; end if;
    if nullif(p_data->>'opening_id','') is not null and not exists(select 1 from project_openings where id=(p_data->>'opening_id')::uuid and project_id=jid and removed_at is null) then raise exception 'That mapped unit is unavailable.'; end if;
    if nullif(p_data->>'window_id','') is not null and not exists(select 1 from windows where id=(p_data->>'window_id')::uuid and project_id=jid) then raise exception 'That warehouse unit belongs to another job.'; end if;
    if nullif(p_data->>'legacy_case_id','') is not null and not exists(select 1 from service_cases where id=(p_data->>'legacy_case_id')::uuid and project_id=jid) then raise exception 'That earlier case belongs to another job.'; end if;
    perform validate_custom_work_facts(coalesce(p_data->'facts','{}'));
    result:=(p_data->>'id')::uuid;
    insert into service_visit_units(id,visit_id,project_id,created_by,work_unit_id,opening_id,window_id,legacy_case_id,label,type_label,facts,issue,fail_point,cause,repair,verification,prevention,next_steps,memo_text,evidence_exception,outcome)
    values(result,v.id,jid,uid,nullif(p_data->>'work_unit_id','')::uuid,nullif(p_data->>'opening_id','')::uuid,nullif(p_data->>'window_id','')::uuid,nullif(p_data->>'legacy_case_id','')::uuid,
      p_data->>'label',coalesce(p_data->>'type_label','Unknown'),coalesce(p_data->'facts','{}'),p_data->>'issue',coalesce(p_data->>'fail_point',''),coalesce(p_data->>'cause','pending'),coalesce(p_data->>'repair',''),coalesce(p_data->>'verification',''),coalesce(p_data->>'prevention',''),coalesce(p_data->>'next_steps',''),coalesce(p_data->>'memo_text',''),coalesce(p_data->>'evidence_exception',''),coalesce(p_data->>'outcome','open'))
    on conflict(id) do update set work_unit_id=excluded.work_unit_id,opening_id=excluded.opening_id,window_id=excluded.window_id,legacy_case_id=excluded.legacy_case_id,
      label=excluded.label,type_label=excluded.type_label,facts=excluded.facts,issue=excluded.issue,fail_point=excluded.fail_point,cause=excluded.cause,repair=excluded.repair,verification=excluded.verification,prevention=excluded.prevention,next_steps=excluded.next_steps,memo_text=excluded.memo_text,evidence_exception=excluded.evidence_exception,outcome=excluded.outcome,revision=service_visit_units.revision+1,updated_at=now();
    select to_jsonb(x) into afterj from service_visit_units x where id=result;
  elsif p_action in ('start','stop') then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    at_time:=coalesce((p_data->>'at')::timestamptz,now());
    if at_time>now()+interval '2 minutes' or at_time<now()-interval '7 days' then raise exception 'Check the device time; a foreman must review older work.'; end if;
    expected:=nullif(p_data->>'expected_session_id','')::uuid;
    select * into s from service_time_sessions where profile_id=uid and ended_at is null for update;
    -- An offline stop can arrive after the payroll clock already closed it. It may shorten,
    -- never extend, that automatic boundary. Other edits still require reconciliation.
    if s.id is null and expected is not null then
      select * into s from service_time_sessions where id=expected and profile_id=uid and visit_id=v.id
        and end_reason in ('clock_out','break','offline_boundary') for update;
      if s.id is not null then at_time:=least(at_time,s.ended_at); end if;
    end if;
    if s.id is distinct from expected then raise exception 'Your timer changed. Refresh before continuing.'; end if;
    if s.id is not null and (s.visit_id<>v.id or at_time<s.started_at) then raise exception 'Stop your other service visit first.'; end if;
    if p_action='start' then
      if v.status<>'active' then raise exception 'Start a new visit for a return trip.'; end if;
      select * into sh from time_shifts where id=(p_data->>'shift_id')::uuid and profile_id=uid for update;
      boundary:=coalesce(sh.clock_out_at,sh.break_started_at);
      if sh.id is null or sh.project_id is distinct from jid or sh.status not in ('open','submitted','approved') or at_time<sh.clock_in_at
        or (boundary is not null and at_time>=boundary) or (boundary is null and now()-sh.clock_in_at>interval '16 hours') then raise exception 'Clock into this job and finish any break before starting service.'; end if;
      if nullif(p_data->>'unit_id','') is not null and not exists(select 1 from service_visit_units where id=(p_data->>'unit_id')::uuid and visit_id=v.id) then raise exception 'Choose a unit on this service visit.'; end if;
      if p_data->>'kind' in ('idle','travel') and length(btrim(coalesce(p_data->>'description','')))=0 then raise exception 'Describe the travel or idle time.'; end if;
      if exists(select 1 from service_time_sessions where profile_id=uid and id is distinct from s.id and coalesce(ended_at,'infinity')>at_time)
        or exists(select 1 from custom_work_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time))
        or exists(select 1 from unit_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time))
        or exists(select 1 from task_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time)) then raise exception 'This overlaps newer work. Refresh and review the timeline.'; end if;
      if at_time<now()-interval '2 minutes' and exists(select 1 from opening_phases where started_by=uid and status='active' and paused_at is null) then raise exception 'Review the existing flashing timer first.'; end if;
      update custom_work_sessions set ended_at=at_time,end_reason='service',revision=revision+1 where profile_id=uid and ended_at is null;
      update unit_sessions set ended_at=at_time,end_reason='handoff' where profile_id=uid and ended_at is null;
      update task_sessions set ended_at=at_time where profile_id=uid and ended_at is null;
      update opening_phases set paused_at=at_time where started_by=uid and status='active' and paused_at is null;
    end if;
    if s.id is not null then
      oldj:=to_jsonb(s);
      update service_time_sessions set ended_at=at_time,end_reason=case when p_action='start' then 'switch' else 'stop' end,description=coalesce(p_data->>'finish_note',description) where id=s.id;
    end if;
    if p_action='start' then
      result:=(p_data->>'id')::uuid;
      insert into service_time_sessions(id,visit_id,project_id,unit_id,shift_id,profile_id,kind,stage,description,started_at,ended_at,end_reason,review_required)
      values(result,v.id,jid,nullif(p_data->>'unit_id','')::uuid,sh.id,uid,p_data->>'kind',coalesce(p_data->>'stage','Diagnosis'),coalesce(p_data->>'description',''),at_time,boundary,case when boundary is not null then 'offline_boundary' end,boundary is not null);
    else result:=s.id; end if;
    select to_jsonb(x) into afterj from service_time_sessions x where id=result;
  elsif p_action='review_time' then
    if not public.service_supervisor() then raise exception 'Only a supervisor or owner can reconcile service time.' using errcode='42501'; end if;
    select * into s from service_time_sessions where id=(p_data->>'id')::uuid and visit_id=v.id for update;
    if s.id is null or s.ended_at is null then raise exception 'Stop this timer before reviewing it.'; end if;
    if s.started_at is distinct from (p_data->>'expected_start')::timestamptz or s.ended_at is distinct from (p_data->>'expected_end')::timestamptz then raise exception 'This time record changed. Refresh before saving.'; end if;
    if p_data->>'reason' is null or length(btrim(p_data->>'reason'))=0 then raise exception 'Explain the time correction.'; end if;
    select * into sh from time_shifts where id=s.shift_id for update;
    if sh.status not in ('open','submitted','approved') or sh.project_id is distinct from s.project_id then raise exception 'Correct the payroll shift and job before reconciling service time.'; end if;
    if (p_data->>'started_at')::timestamptz<sh.clock_in_at or (p_data->>'ended_at')::timestamptz>coalesce(sh.clock_out_at,now())
      or (p_data->>'started_at')::timestamptz>=(p_data->>'ended_at')::timestamptz or p_data->>'started_at' is null or p_data->>'ended_at' is null then raise exception 'Service time must fit inside the paid shift.'; end if;
    if exists(select 1 from service_time_sessions x where x.id<>s.id and x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from custom_work_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from unit_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from task_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz) then raise exception 'This overlaps another recorded activity.'; end if;
    oldj:=to_jsonb(s); result:=s.id;
    update service_time_sessions set started_at=(p_data->>'started_at')::timestamptz,ended_at=(p_data->>'ended_at')::timestamptz,review_required=false where id=s.id;
    if (select coalesce(sum(extract(epoch from coalesce(ended_at,now())-started_at)),0) from service_time_sessions where shift_id=sh.id)
       +(select coalesce(sum(extract(epoch from coalesce(ended_at,now())-started_at)),0) from custom_work_sessions where shift_id=sh.id)
       >extract(epoch from coalesce(sh.clock_out_at,now())-sh.clock_in_at)-sh.break_seconds then raise exception 'Tracked work exceeds paid time after breaks. Reconcile the intervals first.'; end if;
    select to_jsonb(x)||jsonb_build_object('review_reason',p_data->>'reason') into afterj from service_time_sessions x where id=result;
  elsif p_action in ('finish','review','notify') then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    if p_action='notify' then perform service_notify_lodging(v.id);
    else
      if v.created_by is distinct from uid and not public._is_lead(uid) then raise exception 'The visit creator or a foreman can finish the visit.' using errcode='42501'; end if;
      if v.revision is distinct from (p_data->>'revision')::int then raise exception 'This visit changed. Refresh before continuing.'; end if;
      if exists(select 1 from service_time_sessions where visit_id=v.id and ended_at is null) then raise exception 'Each worker must stop their service timer before finishing the visit.'; end if;
      if not exists(select 1 from service_visit_units where visit_id=v.id) then raise exception 'Add the serviced unit first.'; end if;
      if p_action='finish' then
        oldj:=to_jsonb(v);
        update service_visits set status='completed',completed_at=now(),revision=revision+1,updated_at=now(),reviewed_at=null,reviewed_by=null where id=v.id;
      else
        if not public.service_supervisor() then raise exception 'Only a supervisor or owner can approve billing.' using errcode='42501'; end if;
        if v.status<>'completed' then raise exception 'Finish the visit before billing review.'; end if;
        if exists(select 1 from service_visit_units where visit_id=v.id and (cause='pending' or btrim(fail_point)='' or btrim(repair)='' or btrim(verification)='' or outcome='open' or btrim(memo_text)='')) then raise exception 'Complete the unit explanation, responsibility and result first.'; end if;
        if exists(select 1 from service_time_sessions row_time join time_shifts t on t.id=row_time.shift_id where row_time.visit_id=v.id and (row_time.review_required or t.status in ('voided','rejected','needs_finish') or t.project_id is distinct from row_time.project_id)) then raise exception 'Reconcile flagged labor before billing review.'; end if;
        if exists(select 1 from service_visit_units row_unit where row_unit.visit_id=v.id and btrim(row_unit.evidence_exception)='' and (select count(distinct kind) from service_media row_media where row_media.unit_id=row_unit.id and kind in ('before','after','voice','video'))<4) then raise exception 'Attach the unit evidence or explain what is missing.'; end if;
        v_details:=p_data->'allocation';
        if jsonb_typeof(v_details) is distinct from 'object' or jsonb_typeof(v_details->'manufacturer') is distinct from 'number' or jsonb_typeof(v_details->'customer') is distinct from 'number' or jsonb_typeof(v_details->'installer') is distinct from 'number'
          or (v_details->>'manufacturer')::numeric<0 or (v_details->>'customer')::numeric<0 or (v_details->>'installer')::numeric<0
          or coalesce(v_details->>'reason','')='' or length(v_details->>'reason')>2000 then raise exception 'Explain how shared costs are split and enter all three percentages.'; end if;
        total:=(v_details->>'manufacturer')::numeric+(v_details->>'customer')::numeric+(v_details->>'installer')::numeric;
        if total<>100 then raise exception 'Shared cost percentages must total 100.'; end if;
        oldj:=to_jsonb(v);
        update service_visits set allocation=v_details,reviewed_at=now(),reviewed_by=uid,revision=revision+1,updated_at=now() where id=v.id;
      end if;
    end if;
    result:=v.id; select to_jsonb(x) into afterj from service_visits x where id=result;
  elsif p_action='media' then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    if nullif(p_data->>'unit_id','') is not null and not exists(select 1 from service_visit_units where id=(p_data->>'unit_id')::uuid and visit_id=v.id) then raise exception 'Choose a unit on this visit.'; end if;
    result:=(p_data->>'id')::uuid;
    if split_part(p_data->>'storage_path','/',1)<>uid::text or split_part(p_data->>'storage_path','/',2)<>v.id::text or split_part(split_part(p_data->>'storage_path','/',3),'.',1)<>result::text
      or not exists(select 1 from storage.objects where bucket_id='service-media' and name=p_data->>'storage_path') then raise exception 'Upload the original file before attaching it.'; end if;
    insert into service_media(id,visit_id,project_id,unit_id,created_by,kind,storage_path,filename,content_type,bytes,caption)
    values(result,v.id,jid,nullif(p_data->>'unit_id','')::uuid,uid,p_data->>'kind',p_data->>'storage_path',p_data->>'filename',p_data->>'content_type',(p_data->>'bytes')::bigint,coalesce(p_data->>'caption',''));
    select to_jsonb(x) into afterj from service_media x where id=result;
  elsif p_action='transcript' then
    select * into m from service_media where id=(p_data->>'id')::uuid for update;
    if m.id is null or m.visit_id<>v.id or (m.created_by is distinct from uid and not public._is_lead(uid)) then raise exception 'This memo is not editable.' using errcode='42501'; end if;
    if m.revision is distinct from (p_data->>'revision')::int then raise exception 'This transcript changed. Refresh first.'; end if;
    oldj:=to_jsonb(m); result:=m.id;
    update service_media set transcript=p_data->>'transcript',revision=revision+1 where id=m.id;
    select to_jsonb(x) into afterj from service_media x where id=result;
  else raise exception 'Unknown service action.';
  end if;
  if p_action in ('unit','start','stop','media','transcript','review_time') then
    update service_visits set reviewed_at=null,reviewed_by=null,revision=revision+1,updated_at=now() where id=target;
  end if;
  insert into service_commands(id,profile_id,payload,result_id) values(p_id,uid,jsonb_build_object('action',p_action,'data',p_data),result);
  insert into service_audit(project_id,visit_id,actor_id,action,entity_id,before_value,after_value) values(jid,target,uid,p_action,result,oldj,afterj);
  return result;
end $$;;
;
create function public.service_follow_work() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare who uuid; at_time timestamptz;
begin
  if TG_TABLE_NAME='opening_phases' then
    if new.started_by is null or new.status<>'active' or new.paused_at is not null then return new; end if;
    if TG_OP='UPDATE' and old.status='active' and old.paused_at is null then return new; end if;
    who:=new.started_by; at_time:=now();
  else
    if new.ended_at is not null then return new; end if;
    if TG_OP='UPDATE' and old.ended_at is null then return new; end if;
    who:=new.profile_id; at_time:=new.started_at;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(who::text,7281));
  if exists(select 1 from service_time_sessions where profile_id=who and (started_at>at_time or ended_at>at_time)) then raise exception 'Newer service time exists. Review the timeline first.'; end if;
  update service_visits set revision=revision+1,reviewed_at=null,reviewed_by=null,updated_at=now()
    where id in(select visit_id from service_time_sessions where profile_id=who and ended_at is null);
  update service_time_sessions set ended_at=greatest(started_at,at_time),end_reason='other_work' where profile_id=who and ended_at is null;
  return new;
end $$;;
;
create function public.service_follow_shift() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare finish_at timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.profile_id::text,7281));
  finish_at:=coalesce(new.clock_out_at,new.break_started_at);
  if finish_at is null and new.status<>'open' then finish_at:=now(); end if;
  update service_time_sessions set review_required=review_required or new.status in ('needs_finish','rejected','voided') or project_id is distinct from new.project_id
    or started_at<new.clock_in_at or (ended_at is not null and new.clock_out_at is not null and ended_at>new.clock_out_at)
    or (new.break_seconds is distinct from old.break_seconds and old.break_started_at is null)
    where shift_id=new.id;
  if finish_at is not null then
    update service_time_sessions set ended_at=greatest(started_at,finish_at),end_reason=case when new.clock_out_at is null and new.break_started_at is not null then 'break' else 'clock_out' end
      where shift_id=new.id and ended_at is null;
  end if;
  update service_visits set reviewed_at=null,reviewed_by=null,revision=revision+1 where id in(select visit_id from service_time_sessions where shift_id=new.id);
  return new;
end $$;;
;
create function public.time_off_internal() returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select exists(select 1 from profiles where id=auth.uid() and not is_partner and active and retired_at is null and access_revoked_at is null)
$$;;
;
create function public.time_off_manager() returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select public.time_off_internal() and exists(select 1 from profiles where id=auth.uid() and role in ('supervisor','owner','admin','big_boss'))
$$;;
;
create function public.time_off_notify(p_request uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare r time_off_requests; recipient uuid; recipients uuid[]; person text; title_text text;
begin
 select * into r from time_off_requests where id=p_request;
 select display_name into person from profiles where id=r.profile_id;
 -- Use supervisors assigned to the affected jobs where available; otherwise
 -- every active supervisor, with owners as fallback when no supervisor exists.
 select array_agg(distinct p.id) into recipients from schedule_assignments a
 join schedule_assignment_members m on m.assignment_id=a.id and m.profile_id=r.profile_id
 join service_job_supervisors s on s.project_id=a.project_id
 join profiles p on p.id=s.profile_id
 where a.status in ('published','in_progress') and a.start_date<=r.end_date and a.end_date>=r.start_date
 and not p.is_partner and p.active and p.retired_at is null and p.access_revoked_at is null and p.role in ('supervisor','owner','admin','big_boss');
 if coalesce(cardinality(recipients),0)=0 then
  select array_agg(id) into recipients from profiles where not is_partner and active and retired_at is null and access_revoked_at is null and role='supervisor';
 end if;
 if coalesce(cardinality(recipients),0)=0 then
  select array_agg(id) into recipients from profiles where not is_partner and active and retired_at is null and access_revoked_at is null and role in ('owner','admin','big_boss');
 end if;
 title_text:=case when r.kind='sick' and r.status='approved' then 'Sick day reported' when r.status='pending' then 'Time off needs approval' else 'Time off '||r.status end;
 foreach recipient in array coalesce(recipients,'{}'::uuid[]) loop
  insert into crew_reminders(profile_id,request_id,request_status,dedupe_key,title,body,url,expires_at)
  values(recipient,r.id,r.status,'time-off:'||r.id||':'||r.status||':'||recipient,title_text,
   coalesce(person,'Crew member')||' · '||r.start_date||' – '||r.end_date,'/scheduling',now()+interval '7 days') on conflict(dedupe_key) do nothing;
 end loop;
 if r.status<>'pending' then
  insert into crew_reminders(profile_id,request_id,request_status,dedupe_key,title,body,url,expires_at)
  values(r.profile_id,r.id,r.status,'time-off-self:'||r.id||':'||r.status,title_text,r.start_date||' – '||r.end_date,'/my-schedule',now()+interval '7 days') on conflict(dedupe_key) do nothing;
 end if;
end $$;;
;
create function public.request_time_off(p_id uuid,p_kind text,p_start date,p_end date) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare old time_off_requests;
begin
 if not public.time_off_internal() then raise exception 'An active crew login is required.' using errcode='42501'; end if;
 if p_id is null or p_kind is null or p_kind not in ('sick','vacation','other') or p_start is null or p_end is null or p_end<p_start or p_end-p_start>365 then raise exception 'Choose a valid date range of up to one year.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,919));
 select * into old from time_off_requests where id=p_id;
 if found then
  if old.profile_id<>auth.uid() or old.kind<>p_kind or old.start_date<>p_start or old.end_date<>p_end then raise exception 'That request belongs to another entry.'; end if;
  return old.id;
 end if;
 if exists(select 1 from time_off_requests where profile_id=auth.uid() and status in ('pending','approved') and start_date<=p_end and end_date>=p_start) then raise exception 'Those dates overlap an existing time-off entry. Cancel that entry first if it needs changing.'; end if;
 insert into time_off_requests(id,profile_id,kind,start_date,end_date,status)
 values(p_id,auth.uid(),p_kind,p_start,p_end,case when p_kind='sick' then 'approved' else 'pending' end);
 perform public.time_off_notify(p_id);
 return p_id;
end $$;;
;
create function public.review_time_off(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare r time_off_requests;
begin
 if not public.time_off_internal() then raise exception 'An active crew login is required.' using errcode='42501'; end if;
 select * into r from time_off_requests where id=p_id for update;
 if not found then raise exception 'Time-off entry not found.'; end if;
 if p_status is null or p_status not in ('approved','declined','canceled') then raise exception 'Choose a valid decision.'; end if;
 if not public.time_off_manager() and not (p_status='canceled' and r.profile_id=auth.uid()) then raise exception 'Only a supervisor can approve time off.' using errcode='42501'; end if;
 if r.status=p_status then return; end if;
 if p_status in ('approved','declined') and r.status<>'pending' then raise exception 'This request has already been reviewed.'; end if;
 if p_status='canceled' and r.status not in ('pending','approved') then raise exception 'This entry is already closed.'; end if;
 update time_off_requests set status=p_status,reviewed_by=auth.uid(),reviewed_at=now() where id=p_id;
 perform public.time_off_notify(p_id);
end $$;;
;
create function public.claim_crew_reminders(p_lease uuid) returns setof public.crew_reminders
language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if p_lease is null then raise exception 'A delivery lease is required.'; end if;
 insert into crew_reminders(profile_id,shift_id,break_started_at,dedupe_key,title,body,url,expires_at)
 select s.profile_id,s.id,s.break_started_at,'lunch:'||s.id||':'||floor(extract(epoch from s.break_started_at)*1000)::bigint,
  'Your 30-minute lunch is up','Ready to return? Open Forge and end your break.','/clock',s.break_started_at+interval '2 hours'
 from time_shifts s join profiles p on p.id=s.profile_id
 where s.status='open' and s.clock_out_at is null and s.break_type='lunch'
 and s.break_started_at<=now()-interval '30 minutes' and s.break_started_at>now()-interval '2 hours'
 and p.active and not p.is_partner and p.retired_at is null and p.access_revoked_at is null
 on conflict(dedupe_key) do nothing;
 return query update crew_reminders n set lease=p_lease,lease_until=now()+interval '2 minutes',attempts=n.attempts+1
 where n.id in(select q.id from crew_reminders q join profiles p on p.id=q.profile_id
  where q.sent_at is null and q.expires_at>now() and (q.lease_until is null or q.lease_until<now()) and q.attempts<30
  and p.active and not p.is_partner and p.retired_at is null and p.access_revoked_at is null
  and (q.request_id is null or exists(select 1 from time_off_requests r where r.id=q.request_id and r.status=q.request_status))
  and (q.shift_id is null or exists(select 1 from time_shifts s where s.id=q.shift_id and s.status='open' and s.clock_out_at is null and s.break_type='lunch' and s.break_started_at=q.break_started_at))
  order by q.created_at limit 50 for update of q skip locked)
 returning n.*;
end $$;;
;
create function public.finish_crew_reminder(p_id uuid,p_lease uuid,p_sent boolean) returns void language sql security definer set search_path=public,pg_temp as $$
 update crew_reminders set sent_at=case when p_sent then now() else sent_at end,lease=null,lease_until=now()+interval '2 minutes'
 where id=p_id and lease=p_lease;
$$;;
;
create function public.can_read_app_update(p_audience integer[]) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
 select auth.uid() is not null
 and coalesce(public.my_role_rank()=any(p_audience),false)
 and exists(select 1 from profiles where id=auth.uid() and role in ('installer','foreman','lead','supervisor','admin','owner','big_boss') and not is_partner and retired_at is null and access_revoked_at is null);
$$;;
;
create function public.hex_portal_crew() returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from profiles where id=auth.uid()
 and role in ('installer','foreman','lead','supervisor','admin','owner','big_boss')
 and not is_partner and retired_at is null and access_revoked_at is null)
$$;;
;
create function public.hex_portal_save_case(p_id uuid,p_project_id uuid,p_unit_label text,p_question text,p_answer text,p_sources jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare old public.hex_portal_cases; s jsonb;
begin
 if not public.hex_portal_crew() then raise exception 'Current crew access required' using errcode='42501'; end if;
 if not exists(select 1 from projects where id=p_project_id and deleted_at is null and (not is_test or _is_supervisor(auth.uid()))) then raise exception 'Choose an existing job'; end if;
 if p_sources is null or jsonb_typeof(p_sources)<>'array' or jsonb_array_length(p_sources)>12 or octet_length(p_sources::text)>8000 then raise exception 'Invalid sources'; end if;
 -- Typed source references, never executable URLs or arbitrary model instructions.
 for s in select value from jsonb_array_elements(p_sources) loop
  if jsonb_typeof(s)<>'object' or length(coalesce(s->>'title',''))>300 or length(coalesce(s->>'id',''))>160 then raise exception 'Invalid source'; end if;
  if s->>'kind'='hex-portal' and (coalesce(s->>'id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or coalesce(s->>'revision','') !~ '^[1-9][0-9]{0,8}$') then raise exception 'Invalid guidance revision'; end if;
  if s->>'kind'='hex-portal' and not exists(select 1 from hex_portal_guidance_receipts r where r.actor_id=auth.uid() and r.project_id=p_project_id and r.guidance_id=(s->>'id')::uuid and r.revision=(s->>'revision')::integer) then raise exception 'Guidance was not shown to this person on this job' using errcode='42501'; end if;
 end loop;
 insert into hex_portal_cases(id,asker_id,project_id,unit_label,question,answer,sources)
 values(p_id,auth.uid(),p_project_id,coalesce(p_unit_label,''),btrim(p_question),p_answer,p_sources) on conflict(id) do nothing;
 select * into old from hex_portal_cases where id=p_id;
 if old.asker_id<>auth.uid() or old.project_id<>p_project_id or old.unit_label<>coalesce(p_unit_label,'') or old.question<>btrim(p_question) or old.answer<>p_answer or old.sources<>p_sources then raise exception 'This save ID belongs to different evidence' using errcode='23505'; end if;
 return p_id;
end $$;;
;
create function public.hex_portal_save_outcome(p_id uuid,p_case_id uuid,p_outcome text,p_explanation text) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare c public.hex_portal_cases; prior public.hex_portal_outcomes; s jsonb;
begin
 if not public.hex_portal_crew() then raise exception 'Current crew access required' using errcode='42501'; end if;
 select * into c from hex_portal_cases where id=p_case_id and asker_id=auth.uid();
 if not found then raise exception 'Only the original asker can report this outcome' using errcode='42501'; end if;
 insert into hex_portal_outcomes(id,case_id,actor_id,outcome,explanation) values(p_id,c.id,auth.uid(),p_outcome,coalesce(p_explanation,'')) on conflict(id) do nothing;
 select * into prior from hex_portal_outcomes where id=p_id;
 if prior.case_id<>c.id or prior.actor_id<>auth.uid() or prior.outcome<>p_outcome or prior.explanation<>coalesce(p_explanation,'') then raise exception 'This outcome ID was already used' using errcode='23505'; end if;
 if p_outcome='needs-help' then
  for s in select value from jsonb_array_elements(c.sources) where value->>'kind'='hex-portal' loop
   insert into hex_portal_guidance_flags(guidance_id,revision) values((s->>'id')::uuid,(s->>'revision')::integer) on conflict do nothing;
  end loop;
 end if;
 return p_id;
end $$;;
;
create function public.hex_portal_identity(p_project_id uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare p record;
begin
 if not public.hex_portal_crew() then raise exception 'Current crew access required' using errcode='42501'; end if;
 select id,job_code,name into p from projects where id=p_project_id and deleted_at is null and (not is_test or _is_supervisor(auth.uid()));
 if not found then raise exception 'Job not available' using errcode='42501'; end if;
 return jsonb_build_object('userId',auth.uid(),'rank',public.my_role_rank(),'projectId',p.id,'jobCode',p.job_code,'jobName',p.name);
end $$;;
;
create or replace function public.record_crew_work(p_id uuid,p_data jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands;
  unit_data jsonb; unit_id uuid; job_id uuid; people uuid[]; work_day date;
  result_id uuid; existing public.custom_work_units; person uuid;
  record_payload jsonb:=jsonb_build_object('action','crew_record','data',p_data);
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can record work for the crew.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid crew record.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>record_payload then raise exception 'This retry belongs to a different request.'; end if;
    return receipt.result_id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  unit_data:=p_data->'unit';
  if jsonb_typeof(unit_data) is distinct from 'object' then raise exception 'Choose or build a unit.'; end if;
  unit_id:=(unit_data->>'id')::uuid;
  job_id:=(unit_data->>'project_id')::uuid;
  if unit_id is null or job_id is null then raise exception 'Choose a job and a unit.'; end if;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  select * into existing from public.custom_work_units where id=unit_id for update;
  if existing.id is not null and (existing.project_id is distinct from job_id or existing.opening_id is distinct from nullif(unit_data->>'opening_id','')::uuid) then
    raise exception 'Use Unit details to move or link an existing unit before recording crew work.';
  end if;
  if length(btrim(coalesce(unit_data->>'label','')))=0 then raise exception 'Enter a unit number or name.'; end if;
  if existing.id is null and exists(select 1 from public.custom_work_units where project_id=job_id and lower(btrim(label))=lower(btrim(unit_data->>'label'))) then
    raise exception 'A unit with this name already exists. Select it, or include the building/floor for a different unit.';
  end if;
  if existing.id is null and nullif(unit_data->>'opening_id','') is null and exists(select 1 from public.project_openings where project_id=job_id and removed_at is null and lower(btrim(opening_code))=lower(btrim(unit_data->>'label'))) then
    raise exception 'This unit is already on the map. Select the map unit instead of creating a duplicate.';
  end if;
  if jsonb_typeof(p_data->'people') is distinct from 'array' or jsonb_array_length(p_data->'people') not between 1 and 100 then raise exception 'Select the people who did or will do this work.'; end if;
  select array_agg(distinct value::uuid) into people from jsonb_array_elements_text(p_data->'people');
  foreach person in array people loop
    if person is null or not exists(
      select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
        and is_test=public.is_test_profile(uid)
    ) or not public._ai_job_visible(job_id,person) then
      raise exception 'Choose Forge crew members with current access to this job.';
    end if;
  end loop;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null or work_day<date '2000-01-01' or work_day>date '2100-12-31' then raise exception 'Choose a valid work date.'; end if;
  if p_data->>'outcome' is null or p_data->>'outcome' not in ('assigned','partial','finished') then raise exception 'Choose assigned, partial or stage complete.'; end if;
  if p_data->>'outcome'<>'assigned' and work_day>(now() at time zone 'America/Denver')::date then raise exception 'Completed work cannot have a future date.'; end if;
  if p_data->>'stage' is null or p_data->>'stage' not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then raise exception 'Choose the work stage.'; end if;
  if length(coalesce(p_data->>'description',''))>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if coalesce((p_data->>'whole_complete')::boolean,false) then
    if p_data->>'stage'<>'Installing' or p_data->>'outcome'<>'finished' then raise exception 'Whole installation completion requires the Installing stage to be finished.'; end if;
    unit_data:=jsonb_set(unit_data,'{facts}',coalesce(unit_data->'facts','{}') || '{"installation_complete":"Yes"}'::jsonb);
  end if;
  result_id:=public.custom_work_command(p_id,'unit',unit_data);
  if p_data->>'outcome'<>'assigned' then
    update public.custom_work_units set untimed_work_present=true where id=result_id;
  end if;
  insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
  values(p_id,job_id,result_id,uid,work_day,p_data->>'stage',p_data->>'outcome',coalesce((p_data->>'whole_complete')::boolean,false),coalesce(p_data->>'description',''));
  insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(people);
  update public.custom_work_commands set payload=record_payload where id=p_id;
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,after_value,reason)
  values(job_id,uid,result_id,'crew_record',jsonb_build_object('record_id',p_id,'people',people,'work_date',work_day,'stage',p_data->>'stage','outcome',p_data->>'outcome','description',coalesce(p_data->>'description','')),'Foreman crew record; no payroll changes');
  return result_id;
end; $$;;
;
create function public._ai_one_unit_owner() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare o project_openings;
begin
  if new.opening_id is null or new.assigned_to is null then return new; end if;
  select * into o from project_openings where id = new.opening_id for update;
  if o.assigned_to is null then
    perform set_config('app.assignment_via', 'map', true);
    update project_openings set assigned_to = new.assigned_to, assigned_by = coalesce(auth.uid(), new.assigned_to), assigned_at = now() where id = o.id;
  elsif o.assigned_to <> new.assigned_to then
    raise exception 'This unit and its map unit are assigned to different people. Ask a foreman to reassign one of them first.';
  end if;
  new.assigned_to := null; new.assigned_at := null;
  return new;
end $$;;
;
create function public._ai_bump_clock_epoch() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare who uuid;
begin
  for who in select distinct x from unnest(array[
      case when tg_op <> 'DELETE' then (to_jsonb(new) ->> tg_argv[0])::uuid end,
      case when tg_op <> 'INSERT' then (to_jsonb(old) ->> tg_argv[0])::uuid end]) x
      where x is not null and exists (select 1 from public.profiles p where p.id = x) loop
    insert into public.ai_clock_epochs(profile_id, epoch, changed_at) values (who, 1, now())
    on conflict (profile_id) do update set epoch = ai_clock_epochs.epoch + 1, changed_at = now();
  end loop;
  return null;
end $$;;
;
create function public._ai_field_actor() returns uuid
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid();
begin
  if uid is null or not public.custom_work_internal() then
    raise exception 'Forge AI field actions need a Forge crew login with current access.' using errcode = '42501';
  end if;
  return uid;
end $$;;
;
create function public._ai_job_visible(p_job uuid, p_uid uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from projects p where p.id = p_job and p.deleted_at is null and (
    case when public.is_test_profile(p_uid) then public.is_sandbox_project(p.id)
         else not coalesce(p.is_test, false) or public._is_supervisor(p_uid) end))
$$;;
;
create function public._ai_norm(t text) returns text language sql immutable set search_path = public, pg_temp as $$
  select regexp_replace(lower(coalesce(t, '')), '[^a-z0-9]', '', 'g')
$$;;
;
create function public._ai_plan_facts(p_opening uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'type_label', wt.name,
    'width_in', wt.width_in, 'height_in', wt.height_in,
    'area_source', case when wt.width_in is not null and wt.height_in is not null then 'From plans' end,
    'location', nullif(btrim(o.label), ''),
    'plan_style', ms.style, 'plan_operation', ms.operation, 'plan_call_width_in', ms.width_in, 'plan_call_height_in', ms.height_in))
  from project_openings o
  left join window_types wt on wt.id = o.window_type_id
  left join lateral (select s.style, s.operation, s.width_in, s.height_in from project_mark_specs s
    where s.project_id = o.project_id and upper(btrim(s.mark_code)) = upper(btrim(o.opening_code)) limit 1) ms on true
  where o.id = p_opening
$$;;
;
create function public._ai_plan_seed(p_plan jsonb) returns jsonb language sql immutable set search_path = public, pg_temp as $$
  select coalesce(jsonb_object_agg(key, value), '{}') from jsonb_each(coalesce(p_plan, '{}')) where key in ('width_in','height_in','area_source','location')
$$;;
;
create function public._ai_clock_state(p_uid uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'epoch', coalesce((select epoch from ai_clock_epochs where profile_id = p_uid), 0),
    'changed_at', (select changed_at from ai_clock_epochs where profile_id = p_uid),
    'shift', (select jsonb_build_object('id', s.id, 'project_id', s.project_id, 'status', s.status, 'clock_in_at', s.clock_in_at,
                'break_started_at', s.break_started_at, 'break_seconds', coalesce(s.break_seconds, 0))
              from time_shifts s where s.profile_id = p_uid and s.status in ('open','needs_finish') and s.clock_out_at is null
              order by s.clock_in_at desc limit 1),
    'session', (select jsonb_build_object('id', w.id, 'unit_id', w.unit_id, 'stage', w.stage, 'participation', w.participation, 'started_at', w.started_at)
                from custom_work_sessions w where w.profile_id = p_uid and w.ended_at is null limit 1),
    -- Every other route that times a person; a start ends or pauses these.
    'work', jsonb_build_object(
      'map', (select coalesce(jsonb_agg(id order by id), '[]') from unit_sessions where profile_id = p_uid and ended_at is null),
      'task', (select coalesce(jsonb_agg(id order by id), '[]') from task_sessions where profile_id = p_uid and ended_at is null),
      'flashing', (select coalesce(jsonb_agg(id order by id), '[]') from opening_phases where started_by = p_uid and status = 'active' and paused_at is null)))
$$;;
;
create function public.ai_field_context(p_job uuid default null, p_search text default '') returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor(); q text := left(btrim(coalesce(p_search, '')), 100); st jsonb; units jsonb; lead boolean := public._is_lead(uid);
begin
  if p_job is not null and not public._ai_job_visible(p_job, uid) then raise exception 'That job is unavailable.'; end if;
  st := public._ai_clock_state(uid);
  if p_job is not null then
    with custom as (
      select u.id, u.label, u.type_label, u.opening_id, o.opening_code, u.revision, u.facts,
        case when u.opening_id is not null then public._ai_plan_facts(u.opening_id) else '{}'::jsonb end as plan,
        case when u.opening_id is not null then o.assigned_to else u.assigned_to end as assignee,
        coalesce(u.facts->>'installation_complete' = 'Yes', false) or coalesce(o.status = 'installed', false) as finished
      from custom_work_units u left join project_openings o on o.id = u.opening_id
      where u.project_id = p_job
    ), map_only as (
      select null::uuid as id, o.opening_code as label, null::text as type_label, o.id as opening_id, o.opening_code, null::int as revision,
        '{}'::jsonb as facts, public._ai_plan_facts(o.id) as plan, o.assigned_to as assignee, coalesce(o.status = 'installed', false) as finished
      from project_openings o where o.project_id = p_job and o.removed_at is null
        and not exists (select 1 from custom_work_units u where u.opening_id = o.id)
    ), unit_rows as (
      select r.*, (
        select coalesce(jsonb_agg(jsonb_build_object('name', pr.display_name, 'participation', x.participation, 'stage', x.stage, 'started_at', x.started_at, 'is_me', x.profile_id = uid) order by x.started_at), '[]')
        from (select w.profile_id, w.participation, w.stage, w.started_at from custom_work_sessions w where w.ended_at is null and r.id is not null and w.unit_id = r.id
              union all
              select us.profile_id, coalesce(us.role, 'install'), 'Map timer', us.started_at from unit_sessions us where us.ended_at is null and r.opening_id is not null and us.opening_id = r.opening_id) x
        join profiles pr on pr.id = x.profile_id) as working
      from (select * from custom union all select * from map_only) r
    )
    select jsonb_build_object(
      'units', coalesce(jsonb_agg(jsonb_build_object(
        'unit_id', id, 'opening_id', opening_id, 'label', label, 'map_code', opening_code,
        'type', coalesce(nullif(type_label, 'Unknown'), plan->>'type_label', type_label), 'revision', revision,
        'facts', facts - 'note' - 'named_helpers', 'from_plans', plan,
        'assigned_to', (select display_name from profiles where id = assignee), 'assigned_to_me', assignee = uid,
        'working_now', working,
        'status', case when finished then 'finished' when jsonb_array_length(working) > 0 then 'working'
                       when assignee is not null then 'assigned' else 'available' end) order by rn) filter (where hit and rn <= 300), '[]'),
      -- Counts always describe the whole job; the list is bounded.
      'counts', jsonb_build_object('total', count(*), 'custom_records', count(*) filter (where id is not null), 'map_only', count(*) filter (where id is null),
        'available', count(*) filter (where not finished and assignee is null and jsonb_array_length(working) = 0),
        'assigned', count(*) filter (where not finished and assignee is not null), 'working', count(*) filter (where jsonb_array_length(working) > 0),
        'finished', count(*) filter (where finished), 'matching_search', count(*) filter (where hit)),
      'truncated', count(*) filter (where hit) > 300)
    -- On a large job, p_search narrows to unit labels / map codes containing it,
    -- the exact match first, so "unit 412" is found beyond the first 300.
    into units from (select *, row_number() over (order by hit desc, exact desc, lower(label)) as rn from (
      select u.*, q <> '' and (lower(btrim(u.label)) = lower(q) or lower(btrim(coalesce(u.opening_code, ''))) = lower(q)) as exact,
        q = '' or position(lower(q) in lower(u.label)) > 0 or position(lower(q) in lower(coalesce(u.opening_code, ''))) > 0 as hit
      from unit_rows u) s) z;
  end if;
  return jsonb_build_object(
    'as_of', now(), 'me', jsonb_build_object('id', uid, 'is_lead', lead),
    'clock', jsonb_build_object(
      'shift', case when st->'shift' = 'null' then null else (st->'shift') || jsonb_build_object('job', (select name from projects where id = (st->'shift'->>'project_id')::uuid)) end,
      'unit_timer', case when st->'session' = 'null' then null else (st->'session') || jsonb_build_object('unit', (select label from custom_work_units where id = (st->'session'->>'unit_id')::uuid)) end),
    'jobs', case when p_job is null then (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'job_code', p.job_code, 'location', p.address) order by p.name), '[]')
      from (select * from projects p where public._ai_job_visible(p.id, uid) and (q = '' or p.name ilike '%' || q || '%' or p.job_code ilike '%' || q || '%' or coalesce(p.address, '') ilike '%' || q || '%')
            order by (p.id = (st->'shift'->>'project_id')::uuid) desc nulls last, p.name limit 40) p) end,
    'job', case when p_job is not null then (select jsonb_build_object('id', id, 'name', name, 'job_code', job_code, 'location', address, 'field_created', exists (select 1 from ai_field_jobs j where j.project_id = p.id)) from projects p where id = p_job) end,
    'units', units->'units', 'unit_counts', units->'counts', 'units_truncated', units->'truncated',
    -- A retrospective record names who WORKED, so it lists everyone with login
    -- access, including people marked Off today (availability is not access).
    'crew', case when lead then (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', display_name, 'on_site_today', active) order by display_name), '[]') from (
      select id, display_name, active from profiles where not coalesce(is_partner, false) and retired_at is null and access_revoked_at is null
        and role in ('installer','foreman','supervisor','owner') and public.is_test_profile(id) = public.is_test_profile(uid) order by display_name limit 200) c) end);
end $$;;
;
create function public.ai_field_clock_version() returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object('epoch', coalesce((select epoch from ai_clock_epochs where profile_id = public._ai_field_actor()), 0), 'as_of', now())
$$;;
;
create function public.ai_field_begin(p_id uuid, p_input_kind text, p_transcript text, p_sent_at timestamptz, p_expected_epoch bigint,
  p_audio_path text default null, p_client jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor(); r ai_field_requests; st jsonb; sh jsonb; pending boolean;
begin
  if p_id is null or p_sent_at is null or p_input_kind is null or p_input_kind not in ('text','voice') then raise exception 'Invalid request.'; end if;
  if not isfinite(p_sent_at) or p_sent_at > now() + interval '2 minutes' then raise exception 'Check this phone''s date and time; the request time is in the future.'; end if;
  if p_sent_at < now() - interval '7 days' then raise exception 'This saved request is more than a week old. Ask a foreman to record it.'; end if;
  if p_audio_path is not null then
    -- The same lock the orphan cleanup claims under: attach and claim cannot
    -- interleave, so an attached recording's bytes are never deleted.
    perform pg_advisory_xact_lock(hashtextextended(p_audio_path, 7594));
    if p_audio_path !~ ('^' || uid::text || '/' || p_id::text || '/memo\.(webm|m4a|mp4|ogg|mp3|wav)$')
       or not exists (select 1 from storage.objects o where o.bucket_id = 'ai-field-memos' and o.name = p_audio_path) then
      raise exception 'The recording for this request was not saved. Record it again.';
    end if;
    if exists (select 1 from ai_field_memo_cleanup c where c.name = p_audio_path)
       and not exists (select 1 from ai_field_requests rq where rq.audio_path = p_audio_path) then
      raise exception 'This recording was never sent and is being removed. Record it again.';
    end if;
  end if;
  if p_input_kind = 'voice' and p_audio_path is null then raise exception 'Save the recording before sending a voice request.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text, 7590));
  select * into r from ai_field_requests where id = p_id;
  if found then
    if r.profile_id <> uid or r.transcript <> p_transcript or r.sent_at <> p_sent_at or r.audio_path is distinct from p_audio_path or r.input_kind <> p_input_kind
       or r.conversation_id is distinct from (p_client->>'conversation_id')::uuid then
      raise exception 'This retry does not match the original request. Send it as a new message.';
    end if;
  else
    st := public._ai_clock_state(uid);
    sh := st->'shift';
    pending := coalesce((p_client->>'clock_pending_sync')::boolean, false);
    insert into ai_field_requests(id, profile_id, input_kind, transcript, sent_at, conversation_id, audio_path, clock_snapshot)
    values (p_id, uid, p_input_kind, p_transcript, p_sent_at, (p_client->>'conversation_id')::uuid, p_audio_path,
      st || jsonb_build_object(
        'expected_epoch', p_expected_epoch,
        -- The phone's view was already out of date when the person spoke (or it
        -- did not say what it had seen): timing actions refuse.
        'changed_after_send', p_expected_epoch is null or p_expected_epoch <> (st->>'epoch')::bigint,
        -- D16: the send time only on the open, unpaused shift it was sent on, and
        -- only when the two clocks agree that Send came after that shift and after
        -- the last change the phone had seen. Otherwise the person taps Start now.
        'send_time_eligible', coalesce(sh <> 'null' and sh->>'status' = 'open' and sh->>'break_started_at' is null
          and p_sent_at <= now() and (sh->>'clock_in_at')::timestamptz <= p_sent_at and coalesce((st->>'changed_at')::timestamptz, '-infinity') <= p_sent_at, false),
        'client_pending_sync', pending))
    returning * into r;
  end if;
  return jsonb_build_object('id', r.id, 'sent_at', r.sent_at, 'received_at', r.received_at, 'reply', r.reply, 'captured', r.captured,
    'finished', r.finished_at is not null,
    'actions', (select coalesce(jsonb_agg(a.result || jsonb_build_object('action_id', a.id, 'action', a.action, 'status', a.status) order by a.created_at), '[]') from ai_field_actions a where a.request_id = r.id));
end $$;;
;
create function public.ai_field_finish(p_id uuid, p_reply jsonb, p_captured jsonb default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor();
begin
  if octet_length(coalesce(p_reply, '{}')::text) > 200000 or octet_length(coalesce(p_captured, '{}')::text) > 40000 then raise exception 'This reply is too large to save.'; end if;
  -- First answer wins: a retry returns the saved reply rather than a new one.
  update ai_field_requests set reply = p_reply, captured = coalesce(p_captured, captured), finished_at = now()
  where id = p_id and profile_id = uid and finished_at is null;
end $$;;
;
create function public.ai_field_save_draft(p_id uuid, p_captured jsonb) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor();
begin
  if p_captured is null or jsonb_typeof(p_captured) <> 'object' or octet_length(p_captured::text) > 40000 then raise exception 'These answers are too large to save.'; end if;
  update ai_field_requests set captured = p_captured where id = p_id and profile_id = uid and finished_at is null;
  if not found then raise exception 'This request belongs to another account or is finished.' using errcode = '42501'; end if;
end $$;;
;
create function public.ai_field_draft(p_conversation uuid, p_exclude uuid default null) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select captured from ai_field_requests
    where profile_id = public._ai_field_actor() and conversation_id = p_conversation and id is distinct from p_exclude and captured is not null
    order by received_at desc limit 1), '{}'::jsonb)
$$;;
;
create function public._ai_waiting(p_result jsonb) returns jsonb
language sql stable set search_path = public, pg_temp as $$
  select p_result || jsonb_build_object('status', 'needs_choice', 'expires_at', now() + interval '30 minutes',
    'preview_hash', md5((p_result || jsonb_build_object('status', 'needs_choice', 'expires_at', now() + interval '30 minutes'))::text))
$$;;
;
create function public._ai_unit_json(u custom_work_units) returns jsonb language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object('unit_id', u.id, 'label', u.label, 'type', u.type_label, 'facts', u.facts, 'revision', u.revision, 'opening_id', u.opening_id,
    'assigned_to', (select display_name from profiles where id = case when u.opening_id is not null then (select assigned_to from project_openings where id = u.opening_id) else u.assigned_to end))
$$;;
;
create function public._ai_stale(p_message text) returns jsonb language sql immutable set search_path = public, pg_temp as $$
  select jsonb_build_object('status', 'stale', 'message', p_message)
$$;;
;
create function public._ai_field_apply(p_action uuid, p_choice text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  uid uuid := auth.uid(); a ai_field_actions; r ai_field_requests; d jsonb; jid uuid; res jsonb; st jsonb; snap jsonb;
  u custom_work_units; o project_openings; sh time_shifts; s custom_work_sessions; matches jsonb; people uuid[]; msg uuid;
  at_time timestamptz; can_edit boolean; proposed jsonb; additions jsonb := '{}'; conflicts jsonb := '{}'; plan jsonb;
  k text; v jsonb; newfacts jsonb; unknowns jsonb; stage text; part text; assignee uuid; others jsonb; from_confirm boolean := p_choice is not null;
  outid uuid; label_norm text; prev jsonb;
begin
  select * into a from ai_field_actions where id = p_action and profile_id = uid for update;
  if not found then raise exception 'This action is unavailable.' using errcode = '42501'; end if;
  if a.status <> 'waiting' then return a.result; end if;
  prev := a.result;
  select * into r from ai_field_requests where id = a.request_id;
  d := a.data; snap := r.clock_snapshot;
  jid := nullif(d->>'project_id', '')::uuid;
  if jid is not null and not public._ai_job_visible(jid, uid) then raise exception 'That job is unavailable.'; end if;
  if from_confirm and (prev->>'expires_at')::timestamptz < now() then
    res := public._ai_stale('This choice expired. Ask Forge AI again.');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text, 7281));
  if jid is not null then perform pg_advisory_xact_lock(hashtextextended(jid::text, 7285)); end if;

  if res is not null then
    null;
  elsif a.action = 'create_job' then
    if public.is_test_profile(uid) then raise exception 'This is a test login. It can only use the automation sandbox job, not create a real one.' using errcode = '42501'; end if;
    if length(btrim(coalesce(d->>'name', ''))) not between 2 and 80 or length(btrim(coalesce(d->>'location', ''))) not between 3 and 300 then
      raise exception 'A new job needs its name and site address or location.';
    end if;
    -- One creator at a time, so two phones naming the same site see each other.
    perform pg_advisory_xact_lock(7592);
    select coalesce(jsonb_agg(x order by x->>'name', x->>'id'), '[]') into matches from (
      select jsonb_build_object('id', p.id, 'name', p.name, 'job_code', p.job_code, 'location', p.address) x from projects p
      where public._ai_job_visible(p.id, uid) and (
        (length(public._ai_norm(p.name)) >= 3 and length(public._ai_norm(d->>'name')) >= 3 and
          (public._ai_norm(p.name) like '%' || public._ai_norm(d->>'name') || '%' or public._ai_norm(d->>'name') like '%' || public._ai_norm(p.name) || '%'))
        or (length(public._ai_norm(p.address)) >= 6 and public._ai_norm(p.address) = public._ai_norm(d->>'location'))
        or exists (select 1 from regexp_split_to_table(lower(p.name), '[^a-z0-9]+') w1 join regexp_split_to_table(lower(d->>'name'), '[^a-z0-9]+') w2 on w1 = w2
                   where length(w1) >= 4 and w1 not in ('residence','house','home','project','remodel','street','road','avenue','drive','lane','windows','doors','window','door','building','court')))
      order by p.name, p.id limit 5) m;
    if p_choice like 'use_existing:%' then
      if not exists (select 1 from jsonb_array_elements(prev->'matches') m where m->>'id' = substr(p_choice, 14)) or not public._ai_job_visible(substr(p_choice, 14)::uuid, uid) then
        res := public._ai_stale('That job is no longer available. Ask again.');
      else
        jid := substr(p_choice, 14)::uuid;
        res := jsonb_build_object('status', 'done', 'outcome', 'used_existing', 'project_id', jid, 'name', (select name from projects where id = jid), 'created', false);
      end if;
    elsif jsonb_array_length(matches) > 0 and (p_choice is distinct from 'create_new' or matches <> prev->'matches') then
      -- First sight, or the similar jobs changed since the person chose: show the
      -- current list and ask again rather than create beside one they never saw.
      res := public._ai_waiting(jsonb_build_object('reason', 'similar_job', 'message', 'A similar job already exists. Do you still want to create this project?',
        'proposed', jsonb_build_object('name', btrim(d->>'name'), 'location', btrim(d->>'location')), 'matches', matches,
        'options', (select jsonb_agg(jsonb_build_object('id', 'use_existing:' || (m->>'id'), 'label', 'Use ' || (m->>'name'))) from jsonb_array_elements(matches) m)
          || jsonb_build_array(jsonb_build_object('id', 'create_new', 'label', 'Create a separate new job'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
    else
      jid := gen_random_uuid();
      insert into projects(id, job_code, name, address)
      values (jid, 'FIELD-' || upper(substr(md5(jid::text), 1, 6)), btrim(d->>'name'), btrim(d->>'location'));
      -- Born Not ready, like every job nobody in the office has set up yet.
      insert into project_pipeline(project_id, ready_state, updated_at, updated_by) values (jid, 'not_ready', now(), uid)
      on conflict (project_id) do update set ready_state = 'not_ready', updated_at = now(), updated_by = uid;
      -- D26: the job's supervisors, else every supervisor, else the owners. Login
      -- access decides, not whether they are on site today.
      select array_agg(p.id) into people from service_job_supervisors js join profiles p on p.id = js.profile_id
        where js.project_id = jid and not coalesce(p.is_partner, false) and p.retired_at is null and p.access_revoked_at is null and p.role in ('supervisor','owner');
      if coalesce(cardinality(people), 0) = 0 then
        select array_agg(id) into people from profiles where role = 'supervisor' and not coalesce(is_partner, false) and retired_at is null and access_revoked_at is null and not public.is_test_profile(id);
      end if;
      if coalesce(cardinality(people), 0) = 0 then
        select array_agg(id) into people from profiles where role = 'owner' and not coalesce(is_partner, false) and retired_at is null and access_revoked_at is null and not public.is_test_profile(id);
      end if;
      msg := gen_random_uuid();
      insert into project_messages(id, project_id, author_id, body, mentions) values (msg, jid, uid,
        'New field job created in Forge AI by ' || coalesce((select display_name from profiles where id = uid), 'a crew member') || ': ' || btrim(d->>'name')
        || E'\nLocation: ' || btrim(d->>'location')
        || E'\nNeeds office setup: customer, schedule, readiness and a supervisor. Crew can record work on it now.'
        || E'\nhttps://app.forgewd.com/projects/' || jid, coalesce(people, '{}'));
      insert into ai_field_jobs(project_id, created_by, action_id, notice_message_id, notified) values (jid, uid, a.id, msg, coalesce(people, '{}'));
      res := jsonb_build_object('status', 'done', 'outcome', 'created', 'project_id', jid, 'name', btrim(d->>'name'), 'location', btrim(d->>'location'),
        'job_code', 'FIELD-' || upper(substr(md5(jid::text), 1, 6)), 'created', true, 'ready_state', 'not_ready',
        'supervisor_notice', jsonb_build_object('message_id', msg, 'recipients', coalesce(cardinality(people), 0), 'channel', 'job chat mention'));
    end if;

  elsif a.action = 'save_unit' then
    if jid is null then raise exception 'Choose the job first.'; end if;
    proposed := coalesce(d->'facts', '{}');
    perform public.validate_custom_work_facts(proposed);
    if length(btrim(coalesce(d->>'label', ''))) not between 1 and 120 then raise exception 'Give the unit its number or name.'; end if;
    label_norm := lower(btrim(d->>'label'));
    -- Resolve identity first: a stated id, then a map unit, then a same-named
    -- record. "Start unit four" never makes a second unit four.
    if nullif(d->>'unit_id', '') is not null then
      select * into u from custom_work_units where id = (d->>'unit_id')::uuid for update;
      if u.id is null or u.project_id is distinct from jid then raise exception 'That unit is not on this job.'; end if;
      select * into o from project_openings where id = u.opening_id;
    elsif nullif(d->>'opening_id', '') is not null then
      select * into o from project_openings where id = (d->>'opening_id')::uuid and project_id = jid and removed_at is null;
      if o.id is null then raise exception 'That map unit is not on this job.'; end if;
      select * into u from custom_work_units where opening_id = o.id for update;
    else
      select * into u from custom_work_units where project_id = jid and lower(btrim(label)) = label_norm for update;
      select * into o from project_openings where project_id = jid and removed_at is null and lower(btrim(opening_code)) = label_norm limit 1;
      if u.id is null and o.id is not null then
        select * into u from custom_work_units where opening_id = o.id for update;
      elsif u.id is not null and o.id is not null and u.opening_id is distinct from o.id then
        raise exception 'Two different records use this unit name. Open the job''s unit list and choose the right one.';
      end if;
    end if;
    if u.id is null then
      -- New record. A map unit starts from what the plans say; a spoken value that
      -- disagrees with the plans is shown, never silently chosen.
      plan := case when o.id is not null then public._ai_plan_facts(o.id) else '{}'::jsonb end;
      for k, v in select * from jsonb_each(proposed) loop
        if plan ? k and k in ('width_in','height_in','location') and v is distinct from plan->k
           and (jsonb_typeof(v) <> 'string' or lower(btrim(v #>> '{}')) <> lower(btrim(plan->>k))) then
          conflicts := conflicts || jsonb_build_object(k, jsonb_build_object('plans', plan->k, 'said', v));
        end if;
      end loop;
      if plan ? 'type_label' and nullif(btrim(d->>'type_label'), '') is not null and lower(btrim(d->>'type_label')) <> lower(plan->>'type_label') then
        conflicts := conflicts || jsonb_build_object('type_label', jsonb_build_object('plans', plan->'type_label', 'said', btrim(d->>'type_label')));
      end if;
      if from_confirm and prev->'plan' is distinct from plan then
        res := public._ai_stale('The plans for this unit changed since you chose. Ask again.');
      elsif conflicts <> '{}' and p_choice is null then
        res := public._ai_waiting(jsonb_build_object('reason', 'plan_conflict', 'message', 'The plans say something different for unit ' || o.opening_code || '. Which should the field record use?',
          'plan', plan, 'differences', conflicts, 'map_code', o.opening_code,
          'options', jsonb_build_array(jsonb_build_object('id', 'use_plans', 'label', 'Use the plans'), jsonb_build_object('id', 'use_said', 'label', 'Use what I said (plans stay unchanged)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
      else
        newfacts := public._ai_plan_seed(plan) || case when p_choice = 'use_plans' then proposed - (select coalesce(array_agg(key), '{}') from jsonb_object_keys(conflicts) key) else proposed end;
        outid := public.custom_work_command(md5(a.id::text || ':unit')::uuid, 'unit', jsonb_build_object('id', a.id, 'revision', 0, 'project_id', jid,
          'opening_id', o.id, 'label', coalesce(o.opening_code, btrim(d->>'label')),
          'type_label', coalesce(case when p_choice = 'use_plans' then plan->>'type_label' end, nullif(btrim(d->>'type_label'), ''), plan->>'type_label', 'Unknown'),
          'facts', newfacts, 'reason', 'Field capture through Forge AI'));
        select * into u from custom_work_units where id = outid;
        res := jsonb_build_object('status', 'done', 'outcome', case when o.id is not null then 'created_from_map' else 'created' end, 'unit', public._ai_unit_json(u), 'project_id', jid,
          'from_plans', nullif(plan, '{}'::jsonb));
      end if;
    else
      can_edit := u.created_by = uid or public._is_lead(uid);
      -- A confirmation answers the record as it was shown. If anyone changed the
      -- unit since, the person has not seen what they would be overwriting.
      if from_confirm and (prev->'unit'->>'revision')::int is distinct from u.revision then
        res := public._ai_stale('Unit ' || u.label || ' changed since you saw this. Nothing was changed; ask again to see the latest details.');
      elsif nullif(d->>'unit_id', '') is not null and lower(btrim(d->>'label')) <> lower(btrim(u.label)) and p_choice is null then
        res := public._ai_waiting(jsonb_build_object('reason', 'identity', 'message', 'You named unit ' || btrim(d->>'label') || ', but the selected record is unit ' || u.label || '. Which is it?',
          'unit', public._ai_unit_json(u), 'options', jsonb_build_array(jsonb_build_object('id', 'keep_original', 'label', 'It is unit ' || u.label), jsonb_build_object('id', 'cancel', 'label', 'Neither — cancel'))));
      else
        for k, v in select * from jsonb_each(proposed) loop
          if k = 'unknown_fields' then continue; end if;
          if not (u.facts ? k) then additions := additions || jsonb_build_object(k, v);
          elsif (jsonb_typeof(v) = 'string' and lower(btrim(v #>> '{}')) is distinct from lower(btrim(u.facts ->> k))) or (jsonb_typeof(v) <> 'string' and v is distinct from u.facts -> k) then
            conflicts := conflicts || jsonb_build_object(k, jsonb_build_object('stored', u.facts -> k, 'said', v));
          end if;
        end loop;
        if nullif(btrim(d->>'type_label'), '') is not null and lower(btrim(d->>'type_label')) <> lower(u.type_label) then
          if u.type_label = 'Unknown' then additions := additions || jsonb_build_object('type_label', btrim(d->>'type_label'));
          else conflicts := conflicts || jsonb_build_object('type_label', jsonb_build_object('stored', u.type_label, 'said', btrim(d->>'type_label'))); end if;
        end if;
        if conflicts <> '{}' and p_choice is null then
          -- D18: say what the record says and what was said; nothing is overwritten.
          res := public._ai_waiting(jsonb_build_object('reason', 'fact_conflict', 'message', 'Unit ' || u.label || ' already has different details. Keep what is saved, or correct the record?',
            'unit', public._ai_unit_json(u), 'differences', conflicts, 'additions', additions, 'can_edit', can_edit,
            'options', jsonb_build_array(jsonb_build_object('id', 'keep_original', 'label', 'Keep the saved details (I misspoke)'))
              || case when can_edit then jsonb_build_array(jsonb_build_object('id', 'correct_record', 'label', 'Correct the unit record')) else '[]'::jsonb end
              || jsonb_build_array(jsonb_build_object('id', 'send_for_review', 'label', 'Keep saved details and send my observation for review'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif p_choice = 'correct_record' and not can_edit then
          raise exception 'Only the unit''s author or a foreman can correct this record. Send it for review instead.';
        elsif p_choice = 'send_for_review' or (not can_edit and (additions <> '{}' or conflicts <> '{}')) then
          -- The saved record stays as it is; the observation waits in the unit's
          -- history for a foreman. Checked before "unchanged" so a review of
          -- differences alone is never dropped.
          insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
          values (jid, uid, u.id, 'ai_observation', jsonb_build_object('type', u.type_label, 'facts', u.facts, 'revision', u.revision),
            jsonb_build_object('additions', additions, 'differences', conflicts, 'request_id', r.id),
            'Crew observation through Forge AI; not applied to the record');
          res := jsonb_build_object('status', 'done', 'outcome', 'sent_for_review', 'unit', public._ai_unit_json(u), 'project_id', jid,
            'observation', jsonb_build_object('additions', additions, 'differences', conflicts),
            'message', 'Saved as an observation for a foreman to review. The unit record is unchanged.');
        else
          newfacts := u.facts || (additions - 'type_label') || case when p_choice = 'correct_record' then (select coalesce(jsonb_object_agg(key, value->'said'), '{}') from jsonb_each(conflicts) where key <> 'type_label') else '{}' end;
          select coalesce(jsonb_agg(distinct x), '[]') into unknowns from (
            select jsonb_array_elements_text(coalesce(u.facts->'unknown_fields', '[]')) x union select jsonb_array_elements_text(coalesce(proposed->'unknown_fields', '[]'))) z
            where not (newfacts ? x) and not (x = 'type_label' and coalesce(additions->>'type_label', u.type_label) <> 'Unknown');
          newfacts := (newfacts - 'unknown_fields') || case when jsonb_array_length(unknowns) > 0 then jsonb_build_object('unknown_fields', unknowns) else '{}' end;
          -- Same facts and the same set of unanswered questions (order aside) is no change.
          if additions = '{}' and (p_choice is distinct from 'correct_record' or conflicts = '{}') and (newfacts - 'unknown_fields') = (u.facts - 'unknown_fields')
             and unknowns = (select coalesce(jsonb_agg(distinct x), '[]') from jsonb_array_elements_text(coalesce(u.facts->'unknown_fields', '[]')) x) then
            res := jsonb_build_object('status', 'done', 'outcome', 'unchanged', 'unit', public._ai_unit_json(u), 'project_id', jid,
              'kept_original', case when p_choice = 'keep_original' then conflicts end);
          else
            outid := public.custom_work_command(md5(a.id::text || ':unit')::uuid, 'unit', jsonb_build_object('id', u.id, 'revision', u.revision, 'project_id', u.project_id,
              'opening_id', u.opening_id, 'label', u.label,
              'type_label', case when p_choice = 'correct_record' and conflicts ? 'type_label' then conflicts->'type_label'->>'said' else coalesce(additions->>'type_label', u.type_label) end,
              'facts', newfacts, 'reason', case when p_choice = 'correct_record' then 'Crew correction through Forge AI' else 'Details added through Forge AI' end));
            select * into u from custom_work_units where id = outid;
            res := jsonb_build_object('status', 'done', 'outcome', case when p_choice = 'correct_record' then 'corrected' else 'details_added' end,
              'unit', public._ai_unit_json(u), 'project_id', jid, 'kept_original', case when p_choice = 'keep_original' then conflicts end);
          end if;
        end if;
      end if;
    end if;

  elsif a.action in ('start_unit','start_idle','stop_work') then
    st := public._ai_clock_state(uid);
    if not from_confirm then
      -- Never act on an old or delayed request, on a phone still sending a clock
      -- change, or on timing that moved at ANY point after the phone last read
      -- it before Send — in transit, on arrival or while the model worked, and
      -- even if it moved back.
      if r.sent_at < now() - interval '5 minutes' or r.received_at < now() - interval '5 minutes' then
        res := public._ai_stale('This request was sent more than five minutes ago, so no timer was changed. Ask again if you still want this.');
      elsif coalesce((snap->>'client_pending_sync')::boolean, false) then
        res := public._ai_stale('Your phone is still sending a job-clock change. Wait until it syncs, then ask again.');
      elsif coalesce((snap->>'changed_after_send')::boolean, true) or (st->>'epoch')::bigint <> (snap->>'epoch')::bigint then
        res := public._ai_stale('Your job clock or a timer changed after you sent this, so I did not change anything. Check the clock and ask again.');
      end if;
    elsif p_choice in ('end_break_and_start','join_helper') and (st->>'epoch')::bigint is distinct from (prev->>'epoch')::bigint then
      res := public._ai_stale('Your clock or timers changed since this question. Nothing was started; ask again.');
    elsif p_choice = 'start_now' and (st->'session' is distinct from prev->'work_session' or st->'work' is distinct from prev->'work') then
      -- Clocking in is the expected change; any other timer that started since is
      -- not ours to stop.
      res := public._ai_stale('Another timer started since this question. It was left running; ask again if you want to switch.');
    end if;
    if res is null then
      select * into sh from time_shifts where id = nullif(st->'shift'->>'id', '')::uuid for update;
      select * into s from custom_work_sessions where profile_id = uid and ended_at is null for update;
      if a.action = 'stop_work' then
        if s.id is null then res := jsonb_build_object('status', 'done', 'outcome', 'already_stopped');
        else
          if d->>'outcome' not in ('finished','partial','blocked','rework') then raise exception 'Was this stage finished, partial, blocked or rework?'; end if;
          outid := public.custom_work_command(md5(a.id::text || ':stop')::uuid, 'stop', jsonb_build_object('expected_session_id', s.id, 'at', now(),
            'outcome', d->>'outcome', 'finish_note', coalesce(nullif(btrim(d->>'note'), ''), s.description)));
          jid := s.project_id;
          res := jsonb_build_object('status', 'done', 'outcome', 'stopped', 'session_id', outid, 'stage', s.stage, 'stage_outcome', d->>'outcome',
            'unit', (select label from custom_work_units where id = s.unit_id), 'stopped_at', now(), 'job_clock_still_running', sh.id is not null,
            'helpers_still_working', (select count(*) from custom_work_sessions where unit_id = s.unit_id and ended_at is null and profile_id <> uid),
            'qc', 'not_approved');
        end if;
      else
        stage := coalesce(nullif(d->>'stage', ''), 'Installing');
        part := case when p_choice = 'join_helper' then 'helper' else coalesce(nullif(d->>'participation', ''), 'install') end;
        if a.action = 'start_idle' then
          if length(btrim(coalesce(d->>'description', ''))) not between 1 and 4000 then raise exception 'Describe the idle time.'; end if;
          jid := coalesce(jid, (sh.project_id));
        else
          if stage not in ('Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') or part not in ('install','helper') then raise exception 'Choose a work stage.'; end if;
          select * into u from custom_work_units where id = nullif(d->>'unit_id', '')::uuid for update;
          if u.id is null or u.project_id is distinct from jid then raise exception 'Choose a unit on this job first.'; end if;
          if lower(btrim(u.type_label)) = 'unknown' then raise exception 'Say what type of unit this is before starting its timer.'; end if;
          -- The map owner is the owner; lock it so dispatch cannot hand it out mid-claim.
          if u.opening_id is not null then select * into o from project_openings where id = u.opening_id for update; end if;
          if (u.facts->>'installation_complete' = 'Yes' or o.status = 'installed') and stage <> 'Rework' then
            raise exception 'Unit % is already finished. Rework starts only as the Rework stage.', u.label;
          end if;
          assignee := case when u.opening_id is not null then o.assigned_to else u.assigned_to end;
          select coalesce(jsonb_agg(pr.display_name order by pr.display_name), '[]') into others from (
            select w.profile_id from custom_work_sessions w where w.unit_id = u.id and w.ended_at is null and w.profile_id <> uid
            union select us.profile_id from unit_sessions us where u.opening_id is not null and us.opening_id = u.opening_id and us.ended_at is null and us.profile_id <> uid) x
            join profiles pr on pr.id = x.profile_id;
        end if;
        if a.action = 'start_unit' and s.id is not null and s.unit_id is not distinct from u.id and s.stage = stage and s.participation = part then
          -- Repeating a start never restarts the timer.
          res := jsonb_build_object('status', 'running', 'outcome', 'already_running', 'session_id', s.id, 'unit', public._ai_unit_json(u), 'started_at', s.started_at, 'stage', s.stage);
        elsif a.action = 'start_unit' and part = 'install' and ((assignee is not null and assignee <> uid) or (assignee is null and jsonb_array_length(others) > 0)) then
          -- D25: occupied work is never silently taken; the person may help instead.
          res := public._ai_waiting(jsonb_build_object('reason', 'claimed', 'message', 'Unit ' || u.label || ' is ' ||
              case when assignee is not null then 'assigned to ' || coalesce((select display_name from profiles where id = assignee), 'someone else') else 'being worked by ' || (select string_agg(x, ', ') from jsonb_array_elements_text(others) x) end
              || '. Join as a helper with your own time?', 'unit', public._ai_unit_json(u), 'working_now', others, 'epoch', (st->>'epoch')::bigint,
            'options', jsonb_build_array(jsonb_build_object('id', 'join_helper', 'label', 'Join as a helper'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif sh.id is null or sh.status <> 'open' then
          res := public._ai_waiting(jsonb_build_object('reason', 'needs_clock', 'message', 'You are not clocked in. Use the job clock to clock in' ||
              coalesce(' to ' || (select name from projects where id = jid), '') || ', then tap Start now.',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'stage', stage, 'work_session', st->'session', 'work', st->'work',
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now (after clocking in)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif jid is not null and sh.project_id is distinct from jid then
          res := public._ai_waiting(jsonb_build_object('reason', 'wrong_job', 'message', 'Use the job clock to switch from ' || coalesce((select name from projects where id = sh.project_id), 'your current job') || ' to ' || (select name from projects where id = jid) || ', then tap Start now. Your time so far stays on ' || coalesce((select name from projects where id = sh.project_id), 'that job') || '.',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'current_job', (select name from projects where id = sh.project_id), 'stage', stage,
            'work_session', st->'session', 'work', st->'work',
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now (after switching jobs)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif sh.break_started_at is not null and p_choice is distinct from 'end_break_and_start' then
          res := public._ai_waiting(jsonb_build_object('reason', 'on_break', 'message', 'End your break and start ' || coalesce('unit ' || u.label, 'idle time') || '?',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'stage', stage, 'epoch', (st->>'epoch')::bigint,
            'options', jsonb_build_array(jsonb_build_object('id', 'end_break_and_start', 'label', 'End break and start ' || coalesce('unit ' || u.label, 'idle time')), jsonb_build_object('id', 'cancel', 'label', 'Stay on break'))));
        elsif not from_confirm and not coalesce((snap->>'send_time_eligible')::boolean, false) then
          -- Nothing changed, but the phone's clock puts Send before this shift or
          -- before the last change it had seen: the send time cannot be trusted,
          -- so the person decides to start now rather than we guess a time.
          res := public._ai_waiting(jsonb_build_object('reason', 'confirm_time', 'message', 'This phone''s clock does not match the server, so the time you sent this cannot be used. Start ' || coalesce('unit ' || u.label, 'idle time') || ' now?',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'stage', stage, 'work_session', st->'session', 'work', st->'work', 'device_sent_at', r.sent_at,
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        else
          if p_choice = 'end_break_and_start' then
            perform public.end_break(sh.id);
            select * into sh from time_shifts where id = sh.id;
          end if;
          -- D16: the send time, only for an unchanged request sent on this open
          -- shift. A resume, a switch or a later tap starts now, never backdated.
          at_time := case when not from_confirm then r.sent_at else now() end;
          if s.id is not null and at_time < s.started_at then
            -- The running timer began after the words were said; the epoch should
            -- already have refused this, and it is never restamped to "now".
            raise exception 'Your current timer started after this request was sent. Ask again.';
          end if;
          outid := public.custom_work_command(md5(a.id::text || ':start')::uuid, 'start', jsonb_build_object('id', md5(a.id::text || ':session')::uuid,
            'unit_id', u.id, 'shift_id', sh.id, 'project_id', jid, 'expected_session_id', s.id, 'stage', stage, 'participation', part,
            'description', case when a.action = 'start_idle' then btrim(d->>'description') else '' end, 'at', at_time));
          if a.action = 'start_unit' and part = 'install' and assignee is null then
            if u.opening_id is not null then
              perform set_config('app.assignment_via', 'map', true);
              update project_openings set assigned_to = uid, assigned_by = uid, assigned_at = now() where id = u.opening_id and assigned_to is null;
            else
              update custom_work_units set assigned_to = uid, assigned_at = now(), revision = revision + 1, updated_at = now() where id = u.id and assigned_to is null;
            end if;
            insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
            values (jid, uid, u.id, 'claim', jsonb_build_object('assigned_to', null), jsonb_build_object('assigned_to', uid, 'map_opening', u.opening_id), 'Claimed through Forge AI');
          end if;
          if u.id is not null then select * into u from custom_work_units where id = u.id; end if;
          res := jsonb_build_object('status', 'running', 'outcome', 'started', 'session_id', outid, 'unit', case when u.id is not null then public._ai_unit_json(u) end,
            'project_id', jid, 'stage', case when a.action = 'start_idle' then 'Idle time' else stage end, 'participation', part, 'started_at', at_time,
            'start_time_basis', case when not from_confirm then 'request_sent' else 'tapped_start' end, 'device_sent_at', r.sent_at,
            'previous_timer_ended', s.id is not null, 'break_ended', p_choice = 'end_break_and_start',
            'claimed', a.action = 'start_unit' and part = 'install' and assignee is null);
        end if;
      end if;
    end if;

  elsif a.action = 'release_unit' then
    select * into u from custom_work_units where id = nullif(d->>'unit_id', '')::uuid for update;
    if u.id is null or u.project_id is distinct from jid then raise exception 'Choose a unit on this job first.'; end if;
    if u.opening_id is not null then select * into o from project_openings where id = u.opening_id for update; assignee := o.assigned_to; else assignee := u.assigned_to; end if;
    if assignee is null then res := jsonb_build_object('status', 'done', 'outcome', 'not_assigned', 'unit', public._ai_unit_json(u));
    elsif assignee <> uid and not public._is_lead(uid) then raise exception 'Only the assigned installer or a foreman can release this unit.';
    elsif exists (select 1 from custom_work_sessions where unit_id = u.id and profile_id = uid and ended_at is null) then raise exception 'Stop your timer on this unit before releasing it.';
    else
      if u.opening_id is not null then
        update project_openings set assigned_to = null, assigned_by = null, assigned_at = null where id = u.opening_id;
      else
        update custom_work_units set assigned_to = null, assigned_at = null, revision = revision + 1, updated_at = now() where id = u.id;
      end if;
      insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
      values (jid, uid, u.id, 'release', jsonb_build_object('assigned_to', assignee), jsonb_build_object('assigned_to', null), 'Released through Forge AI');
      select * into u from custom_work_units where id = u.id;
      res := jsonb_build_object('status', 'done', 'outcome', 'released', 'unit', public._ai_unit_json(u),
        'helpers_still_working', (select count(*) from custom_work_sessions where unit_id = u.id and ended_at is null));
    end if;

  elsif a.action = 'crew_record' then
    if not public._is_lead(uid) then raise exception 'Only an active foreman, supervisor or owner can record work for the crew.' using errcode = '42501'; end if;
    if jid is null then raise exception 'Choose the job first.'; end if;
    if nullif(d->>'unit_id', '') is not null then
      select * into u from custom_work_units where id = (d->>'unit_id')::uuid;
      if u.id is null or u.project_id is distinct from jid then raise exception 'That unit is not on this job.'; end if;
    else
      select * into u from custom_work_units where project_id = jid and lower(btrim(label)) = lower(btrim(d->>'label'));
      if u.id is null then
        select * into o from project_openings where project_id = jid and removed_at is null and lower(btrim(opening_code)) = lower(btrim(d->>'label')) limit 1;
        if o.id is not null then select * into u from custom_work_units where opening_id = o.id; end if;
      end if;
    end if;
    plan := case when u.id is null and o.id is not null then public._ai_plan_facts(o.id) else '{}'::jsonb end;
    -- Existing facts go through unchanged: a crew record never corrects a unit.
    outid := public.record_crew_work(md5(a.id::text || ':crew')::uuid, jsonb_build_object(
      'unit', case when u.id is not null then jsonb_build_object('id', u.id, 'revision', u.revision, 'project_id', u.project_id, 'opening_id', u.opening_id, 'label', u.label, 'type_label', u.type_label, 'facts', u.facts)
               else jsonb_build_object('id', a.id, 'revision', 0, 'project_id', jid, 'opening_id', o.id, 'label', coalesce(o.opening_code, btrim(d->>'label')),
                 'type_label', coalesce(plan->>'type_label', nullif(btrim(d->>'type_label'), ''), 'Unknown'), 'facts', public._ai_plan_seed(plan), 'reason', 'Crew record through Forge AI') end,
      'people', d->'people', 'work_date', d->>'work_date', 'stage', d->>'stage', 'outcome', d->>'outcome', 'description', coalesce(d->>'description', ''), 'whole_complete', false));
    res := jsonb_build_object('status', 'done', 'outcome', 'crew_recorded', 'record_id', md5(a.id::text || ':crew')::uuid, 'unit', (select public._ai_unit_json(x) from custom_work_units x where id = outid),
      'people', (select jsonb_agg(display_name order by display_name) from profiles where id::text in (select jsonb_array_elements_text(d->'people'))),
      'work_date', d->>'work_date', 'stage', d->>'stage', 'stage_outcome', d->>'outcome', 'payroll_changed', false);
  else
    raise exception 'Unsupported field action.';
  end if;

  res := res || jsonb_build_object('action_id', a.id, 'action', a.action, 'request_id', a.request_id);
  update ai_field_actions set project_id = coalesce(jid, project_id), result = res, choice = coalesce(p_choice, choice),
    status = case res->>'status' when 'needs_choice' then 'waiting' when 'stale' then 'stale' else 'done' end,
    resolved_at = case when res->>'status' = 'needs_choice' then null else now() end
  where id = a.id;
  return res;
end $$;;
;
create function public.ai_field_command(p_request uuid, p_key text, p_action text, p_data jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor(); r ai_field_requests; aid uuid; a ai_field_actions;
begin
  select * into r from ai_field_requests where id = p_request;
  if r.id is null or r.profile_id <> uid then raise exception 'This request belongs to another account.' using errcode = '42501'; end if;
  if r.finished_at is not null then raise exception 'This request is finished. Send a new message.'; end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' or octet_length(p_data::text) > 40000 then raise exception 'Invalid action details.'; end if;
  if p_key is null or length(p_key) not between 1 and 300 then raise exception 'Invalid action key.'; end if;
  aid := md5(p_request::text || ':' || p_key)::uuid;
  perform pg_advisory_xact_lock(hashtextextended(aid::text, 7593));
  select * into a from ai_field_actions where id = aid;
  if found then
    -- Same action retried: the saved receipt. Different details under the same
    -- key: refuse, and show what was already done.
    if a.action <> p_action or a.data <> p_data then
      return a.result || jsonb_build_object('replay', 'changed', 'message', 'This request already did something different. Send a new message to change it.');
    end if;
    return a.result || jsonb_build_object('replay', 'same');
  end if;
  -- A stop or idle start names no job; file it under the running shift/timer so
  -- the receipt sits behind the same job boundary (and sandbox fence).
  insert into ai_field_actions(id, request_id, profile_id, project_id, action, action_key, data)
  values (aid, p_request, uid, coalesce(nullif(p_data->>'project_id', '')::uuid,
    case when p_action = 'stop_work' then (select project_id from custom_work_sessions where profile_id = uid and ended_at is null)
         when p_action = 'start_idle' then (select project_id from time_shifts where profile_id = uid and status = 'open' and clock_out_at is null order by clock_in_at desc limit 1) end),
    p_action, p_key, p_data);
  return public._ai_field_apply(aid, null);
end $$;;
;
create function public.ai_field_resolve(p_action uuid, p_choice text, p_preview_hash text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := public._ai_field_actor(); a ai_field_actions;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_action::text, 7593));
  select * into a from ai_field_actions where id = p_action;
  if a.id is null or a.profile_id <> uid then raise exception 'This choice belongs to another account.' using errcode = '42501'; end if;
  if a.status <> 'waiting' then return a.result; end if;
  if p_preview_hash is distinct from a.result->>'preview_hash' then raise exception 'This choice changed. Review the latest card before choosing.'; end if;
  if not exists (select 1 from jsonb_array_elements(a.result->'options') x where x->>'id' = p_choice) then raise exception 'Choose one of the options shown.'; end if;
  if p_choice = 'cancel' then
    update ai_field_actions set status = 'cancelled', choice = 'cancel', resolved_at = now(),
      result = result - 'options' - 'preview_hash' || jsonb_build_object('status', 'cancelled') where id = a.id;
    return (select result from ai_field_actions where id = a.id);
  end if;
  return public._ai_field_apply(a.id, p_choice);
end $$;;
;
create function public.ai_field_guard_memo_upload() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.bucket_id = 'ai-field-memos' then
    perform pg_advisory_xact_lock(hashtextextended(new.name, 7594));
    if exists (select 1 from ai_field_memo_cleanup where name = new.name) then
      raise exception 'This recording is being removed. Retry after cleanup finishes.';
    end if;
  end if;
  return new;
end $$;;
;
create function public.ai_field_claim_orphan_memos(p_lease uuid, p_limit int default 50) returns setof text
language plpgsql security definer set search_path = public, pg_temp as $$
declare n text;
begin
  if p_lease is null then raise exception 'A lease is required.'; end if;
  for n in
    select o.name from storage.objects o
    where o.bucket_id = 'ai-field-memos' and o.created_at < now() - interval '90 days'
      and not exists (select 1 from ai_field_requests r where r.audio_path = o.name)
      and not exists (select 1 from ai_field_memo_cleanup c where c.name = o.name and c.lease is not null and c.claimed_at > now() - interval '1 hour')
    order by o.created_at limit greatest(1, least(coalesce(p_limit, 50), 200))
  loop
    perform pg_advisory_xact_lock(hashtextextended(n, 7594));
    -- Re-check under the lock: a request may have attached it a moment ago.
    if exists (select 1 from ai_field_requests r where r.audio_path = n) then continue; end if;
    -- The cursor's lease check may predate waiting for another sweeper's lock.
    if exists (select 1 from ai_field_memo_cleanup c where c.name = n
      and c.lease is not null and c.claimed_at > now() - interval '1 hour') then continue; end if;
    if not exists (select 1 from storage.objects o where o.bucket_id = 'ai-field-memos'
      and o.name = n and o.created_at < now() - interval '90 days') then continue; end if;
    insert into ai_field_memo_cleanup(name, lease, claimed_at, attempts) values (n, p_lease, now(), 1)
    on conflict (name) do update set lease = p_lease, claimed_at = now(), attempts = ai_field_memo_cleanup.attempts + 1;
    return next n;
  end loop;
end $$;;
;
create function public.ai_field_finish_memo_cleanup(p_lease uuid, p_failed jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare removed int; retried int;
begin
  -- Gone from storage: the marker has done its job.
  delete from ai_field_memo_cleanup c where c.lease = p_lease
    and not exists (select 1 from storage.objects o where o.bucket_id = 'ai-field-memos' and o.name = c.name);
  get diagnostics removed = row_count;
  -- Still there (deletion failed or was skipped): keep the marker, free the lease.
  update ai_field_memo_cleanup c set lease = null, last_error = left(coalesce(p_failed ->> c.name, 'not removed'), 500)
  where c.lease = p_lease;
  get diagnostics retried = row_count;
  return jsonb_build_object('removed', removed, 'retry', retried);
end $$;;
;
create or replace function public.app_training_chapters_valid(p_chapters jsonb, p_duration integer)
returns boolean
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  v_item jsonb;
  v_prev numeric := -1;
  v_sec numeric;
  v_title text;
  v_i integer := 0;
begin
  if p_chapters is null or jsonb_typeof(p_chapters) <> 'array' then return false; end if;
  if jsonb_array_length(p_chapters) not between 1 and 60 then return false; end if;
  if p_duration is null or p_duration < 1 then return false; end if;
  for v_item in select value from jsonb_array_elements(p_chapters) loop
    if jsonb_typeof(v_item) <> 'object' then return false; end if;
    if jsonb_typeof(v_item->'seconds') is distinct from 'number' then return false; end if;
    if jsonb_typeof(v_item->'title') is distinct from 'string' then return false; end if;
    v_sec := (v_item->>'seconds')::numeric;
    v_title := btrim(v_item->>'title');
    if v_sec <> trunc(v_sec) then return false; end if;
    if v_i = 0 and v_sec <> 0 then return false; end if;
    if v_sec <= v_prev or v_sec >= p_duration then return false; end if;
    if length(v_title) not between 1 and 120 then return false; end if;
    if coalesce(v_item->>'status', '') not in ('proposal', 'live', 'mixed') then return false; end if;
    v_prev := v_sec;
    v_i := v_i + 1;
  end loop;
  return true;
end;
$$;;
;
create or replace function public.app_training_videos_guard()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    if old.published_at is not null then
      raise exception 'A published walkthrough is never deleted. Switch it off (active = false) instead.';
    end if;
    return old;
  end if;
  if (new.id, new.slug, new.title, new.min_role, new.language, new.content_status,
      new.version, new.duration_seconds, new.video_path, new.captions_path,
      new.poster_path, new.transcript_text, new.chapters, new.created_at)
     is distinct from
     (old.id, old.slug, old.title, old.min_role, old.language, old.content_status,
      old.version, old.duration_seconds, old.video_path, old.captions_path,
      old.poster_path, old.transcript_text, old.chapters, old.created_at) then
    raise exception 'Walkthrough rows are immutable. Publish a new version instead.';
  end if;
  if old.published_at is not null and new.published_at is distinct from old.published_at then
    raise exception 'published_at is stamped once.';
  end if;
  return new;
end;
$$;;
;
create or replace function public.can_watch_app_training(p_min_role text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select auth.uid() is not null
    and exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and not coalesce(p.is_partner, false)
        and p.retired_at is null
        and p.access_revoked_at is null
        and p.role in ('installer', 'foreman', 'lead', 'supervisor', 'admin', 'owner', 'big_boss')
        and public.role_rank(p.role) >= case p_min_role
          when 'installer' then 0
          when 'foreman' then 1
          when 'supervisor' then 2
          else 99
        end
    );
$$;;
;
create or replace function public.can_read_app_training_object(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p_name is not null
    and exists (
      select 1 from public.app_training_videos v
      where v.active
        and v.published_at is not null
        and v.published_at <= now()
        and p_name in (v.video_path, v.captions_path, v.poster_path)
        and public.can_watch_app_training(v.min_role)
    );
$$;;
;
create or replace function public.app_training_importer_ok()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select auth.uid() is not null
    and exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and not coalesce(p.is_partner, false)
        and p.retired_at is null
        and p.access_revoked_at is null
        and p.role in ('supervisor', 'admin', 'owner', 'big_boss')
    );
$$;;
;
create or replace function public.app_training_import_lock(p_slug text, p_language text)
returns void
language sql
volatile
set search_path = public, pg_temp
as $$
  select pg_advisory_xact_lock(hashtextextended('app_training_import:' || p_slug || ':' || p_language, 0));
$$;;
;
create or replace function public.can_upload_app_training_object(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p_name is not null
    and public.app_training_importer_ok()
    and exists (
      select 1 from public.app_training_imports i
      where i.actor_id = auth.uid()
        and i.state = 'reserved'
        and i.expires_at > now()
        and p_name in (i.video_path, i.captions_path, i.poster_path)
    )
    and not exists (
      select 1 from public.app_training_videos v
      where p_name in (v.video_path, v.captions_path, v.poster_path)
    );
$$;;
;
create or replace function public.can_see_staged_app_training_object(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p_name is not null
    and public.app_training_importer_ok()
    and exists (
      select 1 from public.app_training_imports i
      where i.actor_id = auth.uid()
        and p_name in (i.video_path, i.captions_path, i.poster_path)
    );
$$;;
;
create or replace function public.app_training_import_int(p_obj jsonb, p_key text, p_min numeric, p_max numeric)
returns integer
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  v numeric;
begin
  if jsonb_typeof(p_obj -> p_key) is distinct from 'number' then
    raise exception 'The walkthrough''s % is missing or not a number.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  v := (p_obj ->> p_key)::numeric;
  if v <> trunc(v) or v < p_min or v > p_max then
    raise exception 'The walkthrough''s % is out of range.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  return v::integer;
end;
$$;;
;
create or replace function public.app_training_import_text(p_obj jsonb, p_key text, p_max integer)
returns text
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  if jsonb_typeof(p_obj -> p_key) is distinct from 'string'
     or length(btrim(p_obj ->> p_key)) not between 1 and p_max then
    raise exception 'The walkthrough''s % is missing or too long.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  return p_obj ->> p_key;
end;
$$;;
;
create or replace function public.app_training_import_asset(p_obj jsonb, p_key text, p_max_bytes bigint, p_mimes text[])
returns jsonb
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  v jsonb := p_obj -> p_key;
  v_bytes numeric;
begin
  if jsonb_typeof(v) is distinct from 'object' then
    raise exception 'The % file description is incomplete.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  if exists (select 1 from jsonb_object_keys(v) k where k not in ('bytes', 'sha256', 'mime'))
     or jsonb_typeof(v -> 'bytes') is distinct from 'number'
     or jsonb_typeof(v -> 'sha256') is distinct from 'string'
     or jsonb_typeof(v -> 'mime') is distinct from 'string' then
    raise exception 'The % file description is incomplete.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  v_bytes := (v ->> 'bytes')::numeric;
  if v_bytes <> trunc(v_bytes) or v_bytes < 1 or v_bytes > p_max_bytes then
    raise exception 'The % file is empty or too large.', p_key using errcode = '22023', hint = 'too_large_' || p_key;
  end if;
  if (v ->> 'sha256') !~ '^[0-9a-f]{64}$' then
    raise exception 'The % file fingerprint is malformed.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  if not ((v ->> 'mime') = any (p_mimes)) then
    raise exception 'The % file type is not allowed.', p_key using errcode = '22023', hint = 'invalid_' || p_key;
  end if;
  return jsonb_build_object('bytes', v_bytes::bigint, 'sha256', v ->> 'sha256', 'mime', v ->> 'mime');
end;
$$;;
;
create or replace function public.app_training_import_chapters_ok(p_chapters jsonb, p_duration integer)
returns boolean
language sql
immutable
set search_path = public, pg_temp
as $$
  select jsonb_typeof(p_chapters) is not distinct from 'array'
    and not exists (
      select 1 from jsonb_array_elements(p_chapters) c
      where case
        when jsonb_typeof(c) is distinct from 'object' then true
        else jsonb_typeof(c -> 'seconds') is distinct from 'number'
          or jsonb_typeof(c -> 'title') is distinct from 'string'
          or jsonb_typeof(c -> 'status') is distinct from 'string'
          or exists (select 1 from jsonb_object_keys(c) k where k not in ('seconds', 'title', 'status'))
      end
    )
    and coalesce(public.app_training_chapters_valid(p_chapters, p_duration), false);
$$;;
;
create or replace function public.app_training_import_json(i public.app_training_imports)
returns jsonb
language sql
stable
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'id', i.id, 'requestId', i.request_id, 'slug', i.slug, 'language', i.language,
    'version', i.version, 'state', i.state, 'expiresAt', i.expires_at,
    'publishedAt', i.published_at,
    'assets', jsonb_build_array(
      jsonb_build_object('kind', 'video', 'path', i.video_path, 'bytes', i.video_bytes, 'mime', 'video/mp4'),
      jsonb_build_object('kind', 'captions', 'path', i.captions_path, 'bytes', i.captions_bytes, 'mime', 'text/vtt')
    ) || case when i.poster_path is null then '[]'::jsonb else jsonb_build_array(
      jsonb_build_object('kind', 'poster', 'path', i.poster_path, 'bytes', i.poster_bytes, 'mime', i.poster_mime)
    ) end
  );
$$;;
;
create or replace function public.app_training_import_reserve(p_request_id uuid, p_entry jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_slug text;
  v_min_role text;
  v_language text;
  v_title text;
  v_duration integer;
  v_version integer;
  v_requested integer;
  v_transcript text;
  v_video jsonb;
  v_captions jsonb;
  v_poster jsonb;
  v_prefix text;
  v_row public.app_training_imports;
begin
  if not public.app_training_importer_ok() then
    raise exception 'Only a supervisor or owner can publish walkthroughs.' using errcode = '42501', hint = 'not_allowed';
  end if;
  if p_request_id is null or jsonb_typeof(p_entry) is distinct from 'object' then
    raise exception 'The walkthrough description is missing.' using errcode = '22023', hint = 'invalid_entry';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_entry) k
    where k not in ('slug', 'minRole', 'language', 'contentStatus', 'title', 'durationSeconds',
                    'chapters', 'transcriptText', 'version', 'video', 'captions', 'poster')
  ) then
    raise exception 'The walkthrough description has fields this importer does not accept.' using errcode = '22023', hint = 'invalid_entry';
  end if;

  v_slug := public.app_training_import_text(p_entry, 'slug', 20);
  v_min_role := public.app_training_import_text(p_entry, 'minRole', 20);
  if (v_slug, v_min_role) not in (('installer', 'installer'), ('foreman', 'foreman'), ('leadership', 'supervisor')) then
    raise exception 'That walkthrough and role floor do not belong together.' using errcode = '22023', hint = 'invalid_slug';
  end if;
  v_language := public.app_training_import_text(p_entry, 'language', 5);
  if v_language not in ('en', 'es') then
    raise exception 'Unknown narration language.' using errcode = '22023', hint = 'invalid_language';
  end if;
  if (p_entry ->> 'contentStatus') is distinct from 'proposal'
     or jsonb_typeof(p_entry -> 'contentStatus') is distinct from 'string' then
    raise exception 'The importer only publishes design previews (contentStatus "proposal").' using errcode = '22023', hint = 'invalid_contentStatus';
  end if;
  v_title := btrim(public.app_training_import_text(p_entry, 'title', 160));
  v_duration := public.app_training_import_int(p_entry, 'durationSeconds', 1, 7200);
  v_transcript := public.app_training_import_text(p_entry, 'transcriptText', 200000);
  if not public.app_training_import_chapters_ok(p_entry -> 'chapters', v_duration) then
    raise exception 'The chapter list is not valid for this video.' using errcode = '22023', hint = 'invalid_chapters';
  end if;
  if jsonb_typeof(p_entry -> 'version') is distinct from 'null' then
    v_requested := public.app_training_import_int(p_entry, 'version', 1, 999);
  end if;
  v_video := public.app_training_import_asset(p_entry, 'video', 47185920, array['video/mp4']);
  v_captions := public.app_training_import_asset(p_entry, 'captions', 1048576, array['text/vtt']);
  if jsonb_typeof(p_entry -> 'poster') is distinct from 'null' then
    v_poster := public.app_training_import_asset(p_entry, 'poster', 5242880, array['image/jpeg', 'image/png', 'image/webp']);
  end if;

  perform public.app_training_import_lock(v_slug, v_language);

  -- The same request again (a lost answer, a retry): hand back the same
  -- reservation if, and only if, it describes exactly the same thing.
  select * into v_row from public.app_training_imports i
   where i.actor_id = v_actor and i.request_id = p_request_id
     and i.slug = v_slug and i.language = v_language;
  if found then
    if (v_row.title, v_row.duration_seconds, v_row.chapters, v_row.transcript_text,
        v_row.video_bytes, v_row.video_sha256, v_row.captions_bytes, v_row.captions_sha256,
        v_row.poster_bytes, v_row.poster_sha256, v_row.poster_mime)
       is distinct from
       (v_title, v_duration, p_entry -> 'chapters', v_transcript,
        (v_video ->> 'bytes')::bigint, v_video ->> 'sha256',
        (v_captions ->> 'bytes')::bigint, v_captions ->> 'sha256',
        (v_poster ->> 'bytes')::bigint, v_poster ->> 'sha256', v_poster ->> 'mime')
       or (v_requested is not null and v_requested <> v_row.version) then
      raise exception 'These files differ from the ones this import started with. Start a new import.' using errcode = '22023', hint = 'request_changed';
    end if;
    return public.app_training_import_json(v_row);
  end if;

  -- Next version: past every catalog version AND every reservation, cancelled
  -- ones included, so no path is ever used twice.
  select greatest(
           coalesce((select max(v.version) from public.app_training_videos v where v.slug = v_slug and v.language = v_language), 0),
           coalesce((select max(i.version) from public.app_training_imports i where i.slug = v_slug and i.language = v_language), 0)
         ) + 1
    into v_version;
  if v_requested is not null then
    if v_requested < v_version then
      raise exception 'Version % of this walkthrough already exists. Leave the version out, or use a higher one.', v_requested
        using errcode = '23505', hint = 'version_taken';
    end if;
    v_version := v_requested;
  end if;
  if v_version > 999 then
    raise exception 'This walkthrough has run out of version numbers.' using errcode = '22023', hint = 'invalid_version';
  end if;

  v_prefix := v_slug || '/' || v_language || '/v' || v_version::text || '/';
  insert into public.app_training_imports (
    request_id, actor_id, slug, min_role, language, version, title, duration_seconds,
    chapters, transcript_text,
    video_path, video_bytes, video_sha256,
    captions_path, captions_bytes, captions_sha256,
    poster_path, poster_bytes, poster_mime, poster_sha256,
    expires_at
  ) values (
    p_request_id, v_actor, v_slug, v_min_role, v_language, v_version, v_title, v_duration,
    p_entry -> 'chapters', v_transcript,
    v_prefix || 'walkthrough.mp4', (v_video ->> 'bytes')::bigint, v_video ->> 'sha256',
    v_prefix || 'captions.vtt', (v_captions ->> 'bytes')::bigint, v_captions ->> 'sha256',
    case when v_poster is null then null else v_prefix || 'poster.' ||
      case v_poster ->> 'mime' when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end end,
    (v_poster ->> 'bytes')::bigint, v_poster ->> 'mime', v_poster ->> 'sha256',
    now() + interval '6 hours'
  )
  returning * into v_row;
  return public.app_training_import_json(v_row);
end;
$$;;
;
create or replace function public.app_training_import_status(p_ids uuid[])
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_out jsonb := '[]'::jsonb;
  v_row public.app_training_imports;
  v_json jsonb;
  v_assets jsonb;
begin
  if not public.app_training_importer_ok() then
    raise exception 'Only a supervisor or owner can publish walkthroughs.' using errcode = '42501', hint = 'not_allowed';
  end if;
  if p_ids is null or cardinality(p_ids) not between 1 and 3 then
    raise exception 'Ask about one to three imports at a time.' using errcode = '22023', hint = 'invalid_entry';
  end if;
  for v_row in
    select * from public.app_training_imports i
     where i.id = any (p_ids) and i.actor_id = auth.uid()
     order by i.slug
  loop
    v_json := public.app_training_import_json(v_row);
    select coalesce(jsonb_agg(
             a || jsonb_build_object(
               'present', o.name is not null,
               'ownedByYou', o.name is not null and coalesce(o.owner_id, o.owner::text) = auth.uid()::text,
               'storedBytes', case when (o.metadata ->> 'size') ~ '^[0-9]{1,15}$' then (o.metadata ->> 'size')::bigint end,
               'storedMime', o.metadata ->> 'mimetype'
             ) order by ord), '[]'::jsonb)
      into v_assets
      from jsonb_array_elements(v_json -> 'assets') with ordinality as e(a, ord)
      left join storage.objects o on o.bucket_id = 'app-training' and o.name = a ->> 'path';
    v_out := v_out || jsonb_build_array(jsonb_set(v_json, '{assets}', v_assets)
      || jsonb_build_object('expired', v_row.state = 'reserved' and v_row.expires_at <= now()));
  end loop;
  return v_out;
end;
$$;;
;
create or replace function public.app_training_import_cancel(p_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_row public.app_training_imports;
begin
  if not public.app_training_importer_ok() then
    raise exception 'Only a supervisor or owner can publish walkthroughs.' using errcode = '42501', hint = 'not_allowed';
  end if;
  update public.app_training_imports i
     set state = 'cancelled', cancelled_at = now()
   where i.id = p_id and i.actor_id = auth.uid() and i.state = 'reserved'
  returning * into v_row;
  if not found then
    select * into v_row from public.app_training_imports i where i.id = p_id and i.actor_id = auth.uid();
    if not found then
      raise exception 'That import was not found.' using errcode = 'P0002', hint = 'not_found';
    end if;
  end if;
  return public.app_training_import_json(v_row);
end;
$$;;
;
create or replace function public.app_training_import_publish(p_ids uuid[])
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_row public.app_training_imports;
  v_asset jsonb;
  v_obj record;
  v_active record;
  v_out jsonb := '[]'::jsonb;
  v_count integer;
begin
  if not public.app_training_importer_ok() then
    raise exception 'Only a supervisor or owner can publish walkthroughs.' using errcode = '42501', hint = 'not_allowed';
  end if;
  if p_ids is null or cardinality(p_ids) not between 1 and 3
     or (select count(distinct x) from unnest(p_ids) x) <> cardinality(p_ids)
     or array_position(p_ids, null) is not null then
    raise exception 'Publish one to three different imports at a time.' using errcode = '22023', hint = 'invalid_entry';
  end if;
  select count(*) into v_count from public.app_training_imports i
   where i.id = any (p_ids) and i.actor_id = v_actor;
  if v_count <> cardinality(p_ids) then
    raise exception 'That import was not found.' using errcode = 'P0002', hint = 'not_found';
  end if;
  if (select count(distinct (i.slug, i.language)) from public.app_training_imports i where i.id = any (p_ids)) <> cardinality(p_ids) then
    raise exception 'Two imports of the same walkthrough cannot be published together.' using errcode = '22023', hint = 'invalid_entry';
  end if;

  -- Locks in a fixed order, so two batches can never deadlock each other.
  perform public.app_training_import_lock(i.slug, i.language)
     from public.app_training_imports i
    where i.id = any (p_ids)
    order by i.slug, i.language;

  for v_row in
    select * from public.app_training_imports i
     where i.id = any (p_ids)
     order by i.slug, i.language
     for update
  loop
    if v_row.state = 'published' then
      -- Already done by this caller: report the row, change nothing.
      select v.id, v.slug, v.language, v.version, v.active into v_active
        from public.app_training_videos v where v.id = v_row.id;
      if not found then
        raise exception 'This import is marked published but its catalog row is missing.' using errcode = 'P0002', hint = 'not_found';
      end if;
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'id', v_row.id, 'slug', v_row.slug, 'language', v_row.language, 'version', v_row.version,
        'active', v_active.active, 'alreadyPublished', true));
      continue;
    end if;
    if v_row.state = 'cancelled' then
      raise exception 'This import was cancelled. Start a new one.' using errcode = '22023', hint = 'cancelled';
    end if;
    if v_row.expires_at <= now() then
      raise exception 'This import expired before it was published. Start a new one.' using errcode = '22023', hint = 'expired';
    end if;

    -- Every expected object, exactly as storage recorded it.
    for v_asset in select value from jsonb_array_elements(public.app_training_import_json(v_row) -> 'assets') loop
      select o.owner_id, o.owner, o.metadata into v_obj
        from storage.objects o
       where o.bucket_id = 'app-training' and o.name = v_asset ->> 'path';
      if not found then
        raise exception 'A file for the % walkthrough has not finished uploading.', v_row.slug
          using errcode = '22023', hint = 'missing_' || (v_asset ->> 'kind');
      end if;
      if coalesce(v_obj.owner_id, v_obj.owner::text) is distinct from v_actor::text
         or (v_obj.metadata ->> 'size') is distinct from (v_asset ->> 'bytes')
         or (v_obj.metadata ->> 'mimetype') is distinct from (v_asset ->> 'mime') then
        raise exception 'A file for the % walkthrough does not match what was reserved.', v_row.slug
          using errcode = '22023', hint = 'mismatch_' || (v_asset ->> 'kind');
      end if;
    end loop;

    -- Never publish over a newer version (a stale tab, a second importer).
    select v.id, v.version into v_active
      from public.app_training_videos v
     where v.slug = v_row.slug and v.language = v_row.language and v.active
     for update;
    if found and v_active.version > v_row.version then
      raise exception 'A newer version of the % walkthrough is already published.', v_row.slug
        using errcode = '22023', hint = 'newer_published';
    end if;

    update public.app_training_videos v
       set active = false
     where v.slug = v_row.slug and v.language = v_row.language and v.active;

    insert into public.app_training_videos (
      id, slug, title, min_role, language, content_status, version, duration_seconds,
      video_path, captions_path, poster_path, transcript_text, chapters, published_at, active
    ) values (
      v_row.id, v_row.slug, v_row.title, v_row.min_role, v_row.language, 'proposal', v_row.version,
      v_row.duration_seconds, v_row.video_path, v_row.captions_path, v_row.poster_path,
      v_row.transcript_text, v_row.chapters, now(), true
    );

    update public.app_training_imports i
       set state = 'published', published_at = now()
     where i.id = v_row.id;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'id', v_row.id, 'slug', v_row.slug, 'language', v_row.language, 'version', v_row.version,
      'active', true, 'alreadyPublished', false));
  end loop;
  return v_out;
end;
$$;;
;
create function public._hex_learning_rank(p_uid uuid) returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select public.role_rank(p.role) from profiles p
  where p.id = p_uid and p.role in ('installer','foreman','lead','supervisor','admin','owner','big_boss')
    and not coalesce(p.is_partner, false) and p.retired_at is null and p.access_revoked_at is null
$$;;
;
create function public._hex_learning_caller() returns integer
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare r integer;
begin
  if auth.uid() is null or public.is_partner_user() then raise exception 'Current crew access required' using errcode = '42501'; end if;
  r := public._hex_learning_rank(auth.uid());
  if r is null then raise exception 'Current crew access required' using errcode = '42501'; end if;
  return r;
end $$;;
;
create function public._hex_learning_actor(p_actor uuid) returns integer
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if p_actor is null or auth.uid() is null or p_actor <> auth.uid() then
    raise exception 'This was started under another sign-in. Nothing was changed.' using errcode = '42501';
  end if;
  return public._hex_learning_caller();
end $$;;
;
create function public._hex_learning_reviewer_ok(p_reviewer uuid, p_author uuid, p_project uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_reviewer is not null and p_author is not null
    and coalesce(public._hex_learning_rank(p_reviewer) between 1 and 3, false)
    and (p_reviewer <> p_author or public._hex_learning_rank(p_reviewer) >= 2)
    and public.is_test_profile(p_reviewer) = public.is_test_profile(p_author)
    and public._ai_job_visible(p_project, p_reviewer)
$$;;
;
create function public._hex_learning_approver_ok(p_uid uuid, p_author uuid, p_project uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public._hex_learning_reviewer_ok(p_uid, p_author, p_project) and public._hex_learning_rank(p_uid) >= 2
$$;;
;
create function public._hex_learning_content(p jsonb) returns jsonb
language plpgsql immutable set search_path = public, pg_temp as $$
declare k text; v jsonb; out jsonb := '{}'; unknown jsonb; heading text;
begin
  if p is null or jsonb_typeof(p) <> 'object' or octet_length(p::text) > 30000 then raise exception 'This write-up is too large or invalid.'; end if;
  for k, v in select * from jsonb_each(p) loop
    if k not in ('issue','what_happened','impact','lesson_learned','preventive_action','impact_minutes','impact_cost_cents','unknown') then
      raise exception 'Unknown write-up field.';
    end if;
  end loop;
  foreach heading in array array['issue','what_happened','impact','lesson_learned','preventive_action'] loop
    v := p -> heading;
    if v is not null and jsonb_typeof(v) not in ('string','null') then raise exception 'Each heading is text.'; end if;
    if length(v #>> '{}') > 4000 then raise exception 'Keep each heading under 4000 characters.'; end if;
    out := out || jsonb_build_object(heading, nullif(btrim(coalesce(v #>> '{}', '')), ''));
  end loop;
  foreach k in array array['impact_minutes','impact_cost_cents'] loop
    v := p -> k;
    if v is not null and jsonb_typeof(v) <> 'null' and (jsonb_typeof(v) <> 'number' or (v::text)::numeric <> trunc((v::text)::numeric)
       or (v::text)::numeric < 0 or (v::text)::numeric > case when k = 'impact_minutes' then 100000 else 100000000 end) then
      raise exception 'Enter impact minutes and cost as whole numbers, or leave them blank.';
    end if;
    out := out || jsonb_build_object(k, case when jsonb_typeof(v) = 'number' then v end);
  end loop;
  unknown := coalesce(p -> 'unknown', '[]');
  if jsonb_typeof(unknown) <> 'array' or exists (select 1 from jsonb_array_elements(unknown) x
     where jsonb_typeof(x) <> 'string' or x #>> '{}' not in ('issue','what_happened','impact','lesson_learned','preventive_action')) then
    raise exception 'Unknown must name write-up headings.';
  end if;
  if exists (select 1 from jsonb_array_elements_text(unknown) x where out ->> x is not null
             or (x = 'impact' and (out ->> 'impact_minutes' is not null or out ->> 'impact_cost_cents' is not null))) then
    raise exception 'A heading cannot be both answered and Unknown.';
  end if;
  return out || jsonb_build_object('unknown', (select coalesce(jsonb_agg(distinct x order by x), '[]') from jsonb_array_elements_text(unknown) x));
end $$;;
;
create function public._hex_learning_missing(c jsonb) returns text[]
language sql immutable set search_path = public, pg_temp as $$
  select coalesce(array_agg(k order by o), '{}') from unnest(array['issue','what_happened','impact','lesson_learned','preventive_action']) with ordinality h(k, o)
  where c ->> k is null and not (c -> 'unknown' ? k)
    and not (k = 'impact' and (c ->> 'impact_minutes' is not null or c ->> 'impact_cost_cents' is not null))
$$;;
;
create function public._hex_learning_content_of(r public.hex_learning_reviews) returns jsonb
language sql stable set search_path = public, pg_temp as $$
  select jsonb_build_object('issue', r.issue, 'what_happened', r.what_happened, 'impact', r.impact, 'impact_minutes', r.impact_minutes,
    'impact_cost_cents', r.impact_cost_cents, 'lesson_learned', r.lesson_learned, 'preventive_action', r.preventive_action,
    'unknown', to_jsonb(r.unknown_fields))
$$;;
;
create function public._hex_learning_person(p_id uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select case when p_id is null then null else jsonb_build_object('id', p_id, 'name', (select display_name from profiles where id = p_id)) end
$$;;
;
create function public._hex_learning_sections(c jsonb) returns jsonb
language sql immutable set search_path = public, pg_temp as $$
  select jsonb_build_object('issue', c->'issue', 'whatHappened', c->'what_happened', 'impact', c->'impact',
    'lessonLearned', c->'lesson_learned', 'preventiveAction', c->'preventive_action')
$$;;
;
create function public._hex_learning_fingerprint(p_review uuid, p_revision integer) returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select encode(sha256(convert_to(jsonb_build_object(
    'version', 1, 'caseId', r.case_id, 'projectId', r.project_id, 'unitLabel', c.unit_label, 'unitId', r.unit_id,
    'sourceRequestIds', to_jsonb(e.source_request_ids), 'sources', c.sources, 'authorId', r.author_id, 'reviewerId', e.actor_id,
    'approvalEventId', e.id, 'revision', e.revision, 'sections', public._hex_learning_sections(e.content),
    'impactMinutes', e.content->'impact_minutes', 'impactCostCents', e.content->'impact_cost_cents', 'unknown', e.content->'unknown')::text, 'UTF8')), 'hex')
  from hex_learning_reviews r join hex_portal_cases c on c.id = r.case_id
  join hex_learning_review_events e on e.review_id = r.id and e.revision = p_revision and e.action = 'approved'
  where r.id = p_review
$$;;
;
create function public._hex_learning_json(r public.hex_learning_reviews, p_detail boolean) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'id', r.id, 'case_id', r.case_id, 'project_id', r.project_id, 'state', r.state, 'revision', r.revision,
    'job', (select jsonb_build_object('name', p.name, 'job_code', p.job_code) from projects p where p.id = r.project_id),
    'unit_id', r.unit_id, 'unit_label', c.unit_label, 'question', c.question, 'request_id', r.request_id,
    'author', public._hex_learning_person(r.author_id),
    'reviewer', case when r.reviewer_id is not null then public._hex_learning_person(r.reviewer_id)
      || jsonb_build_object('available', public._hex_learning_reviewer_ok(r.reviewer_id, r.author_id, r.project_id),
                            'can_approve', public._hex_learning_approver_ok(r.reviewer_id, r.author_id, r.project_id)) end,
    'content', public._hex_learning_content_of(r),
    'missing', to_jsonb(public._hex_learning_missing(public._hex_learning_content_of(r))),
    'submitted_at', r.submitted_at, 'decided_at', r.decided_at, 'decided_by', public._hex_learning_person(r.decided_by),
    'decided_as_oversight', r.decided_as_oversight, 'created_via', r.created_via, 'created_at', r.created_at, 'updated_at', r.updated_at,
    'approved_revision', r.approved_revision, 'approval_event_id', r.approval_event_id,
    'last_note', (select e.note from hex_learning_review_events e where e.review_id = r.id and e.action in ('changes_requested','forwarded','reassigned') and e.note <> '' order by e.revision desc limit 1),
    'delivery', (select jsonb_build_object('revision', d.revision, 'status', d.status, 'attempts', d.attempts, 'last_attempt_at', d.last_attempt_at,
                   'last_error', d.last_error, 'receipt_id', d.receipt_id, 'received_at', d.received_at)
                 from hex_learning_deliveries d where d.review_id = r.id order by d.revision desc limit 1),
    'withdrawal', case when r.state = 'withdrawn' then (select jsonb_build_object('status', w.status, 'reason', r.withdrawal_reason, 'withdrawn_at', r.withdrawn_at,
                   'withdrawn_by', public._hex_learning_person(r.withdrawn_by), 'attempts', w.attempts, 'last_error', w.last_error,
                   'receipt_id', w.receipt_id, 'received_at', w.received_at, 'withdrawal_event_id', r.withdrawal_event_id)
                 from hex_learning_withdrawals w where w.review_id = r.id) end)
  || case when p_detail then jsonb_build_object(
    'case', jsonb_build_object('question', c.question, 'answer', c.answer, 'sources', c.sources, 'unit_label', c.unit_label, 'created_at', c.created_at),
    'outcomes', (select coalesce(jsonb_agg(jsonb_build_object('outcome', o.outcome, 'explanation', o.explanation, 'created_at', o.created_at) order by o.created_at), '[]')
                 from hex_portal_outcomes o where o.case_id = c.id),
    -- The recording path comes from the author's own request row, never from a
    -- client; storage decides separately whether this reader may play it.
    'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'input_kind', q.input_kind, 'transcript', q.transcript, 'sent_at', q.sent_at,
                  'audio_path', q.audio_path) order by s.n), '[]')
                from unnest(r.source_request_ids) with ordinality s(id, n) join ai_field_requests q on q.id = s.id and q.profile_id = r.author_id),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('revision', e.revision, 'action', e.action, 'state', e.state_after,
                  'actor', public._hex_learning_person(e.actor_id), 'reviewer', public._hex_learning_person(e.reviewer_id),
                  'oversight', e.oversight, 'note', e.note, 'content', e.content, 'at', e.created_at) order by e.revision), '[]')
                from hex_learning_review_events e where e.review_id = r.id))
  else '{}'::jsonb end
  from hex_portal_cases c where c.id = r.case_id
$$;;
;
create function public._hex_learning_forwarded_by(r public.hex_learning_reviews, p_uid uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from hex_learning_review_events e where e.review_id = r.id and e.action = 'forwarded' and e.actor_id = p_uid)
    and public._hex_learning_reviewer_ok(p_uid, r.author_id, r.project_id)
$$;;
;
create function public._hex_learning_can_read(r public.hex_learning_reviews, p_uid uuid, p_rank integer) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select (r.author_id = p_uid and public._ai_job_visible(r.project_id, p_uid))
    or (r.state <> 'draft' and r.reviewer_id = p_uid and public._hex_learning_reviewer_ok(p_uid, r.author_id, r.project_id))
    or (r.state <> 'draft' and public._hex_learning_forwarded_by(r, p_uid))
    or (r.state <> 'draft' and p_rank >= 2 and public._ai_job_visible(r.project_id, p_uid))
$$;;
;
create function public._hex_learning_replay(p_action uuid, p_review uuid, p_hash text) returns boolean
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare e hex_learning_review_events;
begin
  select * into e from hex_learning_review_events where action_id = p_action;
  if not found then return false; end if;
  if e.review_id <> p_review or e.actor_id is distinct from auth.uid() or e.request_hash <> p_hash then
    raise exception 'This action was already used for something different. Reload and try again.' using errcode = '23505';
  end if;
  return true;
end $$;;
;
create function public._hex_learning_stale() returns void language plpgsql set search_path = public, pg_temp as $$
begin
  -- P0001, not 40001: a queued save must dead-letter visibly, never retry forever.
  raise exception 'This write-up changed on another screen. Reload it to see the latest before changing it.' using hint = 'stale_revision';
end $$;;
;
create function public._hex_learning_event(r public.hex_learning_reviews, p_action uuid, p_hash text, p_kind text, p_oversight boolean, p_note text) returns uuid
language sql security definer set search_path = public, pg_temp as $$
  insert into hex_learning_review_events(review_id, revision, action_id, request_hash, actor_id, action, state_after, reviewer_id, oversight, note, content, source_request_ids)
  values (r.id, r.revision, p_action, p_hash, auth.uid(), p_kind, r.state, r.reviewer_id, coalesce(p_oversight, false), coalesce(p_note, ''), public._hex_learning_content_of(r), r.source_request_ids)
  returning id
$$;;
;
create function public._hex_learning_sources(p_author uuid, p_existing uuid[], p_new uuid[]) returns uuid[]
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare out uuid[] := coalesce(p_existing, '{}'); x uuid; conv uuid; first_conv uuid; has_first boolean;
begin
  if p_new is null then return out; end if;
  if array_position(p_new, null) is not null then raise exception 'Invalid message reference.'; end if;
  if cardinality(out) > 0 then select conversation_id into first_conv from ai_field_requests where id = out[1]; end if;
  foreach x in array p_new loop
    if x = any(out) then continue; end if;
    select conversation_id into conv from ai_field_requests where id = x and profile_id = p_author;
    if not found then raise exception 'Only your own messages can be attached as evidence.' using errcode = '42501'; end if;
    has_first := cardinality(out) > 0;
    if has_first and (first_conv is null or conv is distinct from first_conv) then
      raise exception 'Only messages from the same Ask conversation can be attached.' using errcode = '42501';
    end if;
    if not has_first then first_conv := conv; end if;
    out := out || x;
  end loop;
  if cardinality(out) > 20 then raise exception 'A write-up can keep up to 20 messages.'; end if;
  return out;
end $$;;
;
create function public.hex_learning_save_draft(p_review uuid, p_action uuid, p_case uuid, p_expected_revision integer, p_content jsonb,
  p_request uuid default null, p_unit uuid default null, p_via text default 'form', p_actor uuid default null, p_sources uuid[] default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_actor(p_actor); c hex_portal_cases; r hex_learning_reviews; content jsonb; h text;
  sources uuid[] := coalesce(p_sources, case when p_request is not null then array[p_request] end);
begin
  if p_review is null or p_action is null or p_case is null or p_expected_revision is null or p_content is null then raise exception 'Invalid write-up.'; end if;
  content := public._hex_learning_content(p_content);
  h := md5(jsonb_build_object('op', 'draft', 'case', p_case, 'expected', p_expected_revision, 'content', content, 'sources', sources, 'unit', p_unit)::text);
  perform pg_advisory_xact_lock(hashtextextended(p_case::text, 7610));
  select * into c from hex_portal_cases where id = p_case;
  if not found or c.asker_id <> uid then raise exception 'Only the person who saved this case can write it up.' using errcode = '42501'; end if;
  if not public._ai_job_visible(c.project_id, uid) then raise exception 'That job is unavailable.' using errcode = '42501'; end if;
  if public._hex_learning_replay(p_action, p_review, h) then
    select * into r from hex_learning_reviews where id = p_review;
    return public._hex_learning_json(r, false);
  end if;
  select * into r from hex_learning_reviews where id = p_review for update;
  if not found then
    if p_expected_revision <> 0 then perform public._hex_learning_stale(); end if;
    if exists (select 1 from hex_learning_reviews where case_id = p_case) then
      raise exception 'This case already has a write-up. Open it from your list.' using errcode = '23505';
    end if;
    sources := public._hex_learning_sources(uid, '{}', sources);
    if p_unit is not null and not exists (select 1 from custom_work_units where id = p_unit and project_id = c.project_id) then
      raise exception 'That unit is not on this job.';
    end if;
    insert into hex_learning_reviews(id, case_id, author_id, project_id, request_id, source_request_ids, unit_id, issue, what_happened, impact, impact_minutes,
      impact_cost_cents, lesson_learned, preventive_action, unknown_fields, created_via)
    values (p_review, p_case, uid, c.project_id, sources[1], sources, p_unit, content->>'issue', content->>'what_happened', content->>'impact',
      (content->>'impact_minutes')::integer, (content->>'impact_cost_cents')::bigint, content->>'lesson_learned', content->>'preventive_action',
      array(select jsonb_array_elements_text(content->'unknown')), case when p_via = 'ask' then 'ask' else 'form' end)
    returning * into r;
  else
    if r.case_id <> p_case or r.author_id <> uid then raise exception 'This write-up belongs to someone else.' using errcode = '42501'; end if;
    if r.state not in ('draft','changes_requested') then
      raise exception 'This write-up was sent for review. It can change only if the reviewer asks for changes.';
    end if;
    if r.revision <> p_expected_revision then perform public._hex_learning_stale(); end if;
    if (p_request is not null and r.request_id is not null and p_request is distinct from r.request_id) or (p_unit is not null and p_unit is distinct from r.unit_id) then
      raise exception 'The original message and unit of a write-up cannot be changed.';
    end if;
    -- Later answers from the same conversation add their messages; none is dropped.
    sources := public._hex_learning_sources(uid, r.source_request_ids, sources);
    update hex_learning_reviews set source_request_ids = sources, request_id = coalesce(request_id, sources[1]), issue = content->>'issue', what_happened = content->>'what_happened', impact = content->>'impact',
      impact_minutes = (content->>'impact_minutes')::integer, impact_cost_cents = (content->>'impact_cost_cents')::bigint,
      lesson_learned = content->>'lesson_learned', preventive_action = content->>'preventive_action',
      unknown_fields = array(select jsonb_array_elements_text(content->'unknown')), revision = revision + 1, updated_at = now()
    where id = r.id returning * into r;
  end if;
  perform public._hex_learning_event(r, p_action, h, 'draft_saved', false, null);
  return public._hex_learning_json(r, false);
end $$;;
;
create function public.hex_learning_submit(p_review uuid, p_action uuid, p_expected_revision integer, p_reviewer uuid, p_actor uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_actor(p_actor); r hex_learning_reviews; h text; missing text[]; act text;
begin
  if p_review is null or p_action is null or p_expected_revision is null then raise exception 'Invalid write-up.'; end if;
  if p_reviewer is null then raise exception 'Choose who reviews it.'; end if;
  h := md5(jsonb_build_object('op', 'submit', 'expected', p_expected_revision, 'reviewer', p_reviewer)::text);
  select * into r from hex_learning_reviews where id = p_review for update;
  if not found or r.author_id <> uid then raise exception 'Only the author can send this write-up.' using errcode = '42501'; end if;
  if public._hex_learning_replay(p_action, p_review, h) then return public._hex_learning_json(r, false); end if;
  if not public._ai_job_visible(r.project_id, uid) then raise exception 'That job is unavailable.' using errcode = '42501'; end if;
  if r.state in ('approved','withdrawn') then raise exception 'This write-up is already decided.'; end if;
  if r.revision <> p_expected_revision then perform public._hex_learning_stale(); end if;
  if r.state = 'submitted' and r.reviewer_id = p_reviewer then raise exception 'It is already waiting with that reviewer.'; end if;
  missing := public._hex_learning_missing(public._hex_learning_content_of(r));
  if cardinality(missing) > 0 then raise exception 'Answer or mark Unknown: %.', array_to_string(missing, ', '); end if;
  if r.issue is null or r.what_happened is null then raise exception 'Say what the issue was and what happened before sending.'; end if;
  if p_reviewer = uid and rnk < 2 then raise exception 'You cannot review your own write-up. Choose another foreman or supervisor.' using errcode = '42501'; end if;
  if not public._hex_learning_reviewer_ok(p_reviewer, uid, r.project_id) then
    raise exception 'That person cannot review this job. Choose a current foreman or supervisor.' using errcode = '42501';
  end if;
  act := case when r.state = 'submitted' then 'reassigned' else 'submitted' end;
  update hex_learning_reviews set state = 'submitted', reviewer_id = p_reviewer, submitted_at = now(), revision = revision + 1, updated_at = now()
  where id = r.id returning * into r;
  perform public._hex_learning_event(r, p_action, h, act, false, null);
  return public._hex_learning_json(r, false);
end $$;;
;
create function public.hex_learning_decide(p_review uuid, p_action uuid, p_expected_revision integer, p_decision text, p_note text,
  p_oversight boolean default false, p_forward_to uuid default null, p_actor uuid default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_actor(p_actor); r hex_learning_reviews; h text; note text := btrim(coalesce(p_note, ''));
  oversight boolean := coalesce(p_oversight, false); named boolean; ev uuid; fp text;
begin
  if p_review is null or p_action is null or p_expected_revision is null or p_decision is null
     or p_decision not in ('approve','request_changes','forward') then raise exception 'Invalid decision.'; end if;
  if length(note) > 4000 then raise exception 'Keep the note under 4000 characters.'; end if;
  h := md5(jsonb_build_object('op', 'decide', 'expected', p_expected_revision, 'decision', p_decision, 'note', note, 'oversight', oversight, 'to', p_forward_to)::text);
  select * into r from hex_learning_reviews where id = p_review for update;
  if not found then raise exception 'This write-up is unavailable.' using errcode = '42501'; end if;
  -- Only a current supervisor/owner may act on their own write-up, and only by
  -- this explicit decision on the revision they are looking at.
  if r.author_id = uid and rnk < 2 then raise exception 'You cannot review your own write-up. Send it to another foreman or supervisor.' using errcode = '42501'; end if;
  -- A retry of this person's own tap returns what it did, even once the write-up
  -- has moved on (a forward leaves the forwarder no longer named).
  if public._hex_learning_replay(p_action, p_review, h) then return public._hex_learning_json(r, false); end if;
  named := r.reviewer_id = uid and public._hex_learning_reviewer_ok(uid, r.author_id, r.project_id);
  if p_decision = 'approve' then
    -- Supervisor authority, checked now: a demoted or revoked approver cannot approve.
    if rnk < 2 or not public._hex_learning_approver_ok(uid, r.author_id, r.project_id) then
      raise exception 'Only a supervisor or owner can approve for the Hex-Portal archive. Forward it to one.' using errcode = '42501';
    end if;
    if not named and not oversight then raise exception 'This write-up is not assigned to you. Decide as oversight to approve it.' using errcode = '42501'; end if;
  elsif p_decision = 'forward' then
    if not named then raise exception 'Only the named reviewer can forward this write-up.' using errcode = '42501'; end if;
    if p_forward_to is null or p_forward_to = uid or not public._hex_learning_approver_ok(p_forward_to, r.author_id, r.project_id) then
      raise exception 'Choose a current supervisor or owner (not the author or yourself) to approve it.' using errcode = '42501';
    end if;
  else
    if not named and not (oversight and rnk >= 2 and public._ai_job_visible(r.project_id, uid)) then
      raise exception 'This write-up is not assigned to you, or your reviewer access changed.' using errcode = '42501';
    end if;
  end if;
  if oversight and (rnk < 2 or not public._ai_job_visible(r.project_id, uid)) then raise exception 'Only a supervisor or owner can decide as oversight.' using errcode = '42501'; end if;
  if r.state <> 'submitted' then raise exception 'Only a write-up waiting for review can be decided.'; end if;
  if r.revision <> p_expected_revision then perform public._hex_learning_stale(); end if;
  if p_decision = 'request_changes' and note = '' then raise exception 'Say what needs to change.'; end if;
  if p_decision = 'forward' then
    update hex_learning_reviews set reviewer_id = p_forward_to, revision = revision + 1, updated_at = now() where id = r.id returning * into r;
    perform public._hex_learning_event(r, p_action, h, 'forwarded', false, note);
  elsif p_decision = 'request_changes' then
    update hex_learning_reviews set state = 'changes_requested', decided_at = now(), decided_by = uid, decided_as_oversight = oversight and not named,
      revision = revision + 1, updated_at = now() where id = r.id returning * into r;
    perform public._hex_learning_event(r, p_action, h, 'changes_requested', oversight and not named, note);
  else
    update hex_learning_reviews set state = 'approved', decided_at = now(), decided_by = uid, decided_as_oversight = oversight and not named,
      revision = revision + 1, updated_at = now() where id = r.id returning * into r;
    ev := public._hex_learning_event(r, p_action, h, 'approved', oversight and not named, note);
    fp := public._hex_learning_fingerprint(r.id, r.revision);
    update hex_learning_reviews set approved_revision = r.revision, approval_event_id = ev, approved_fingerprint = fp where id = r.id returning * into r;
    -- Approved is not delivered: it waits here for the receiver's receipt.
    insert into hex_learning_deliveries(review_id, revision, approval_event_id, revision_fingerprint) values (r.id, r.revision, ev, fp);
  end if;
  return public._hex_learning_json(r, false);
end $$;;
;
create function public.hex_learning_reassign(p_review uuid, p_action uuid, p_expected_revision integer, p_reviewer uuid, p_reason text, p_actor uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_actor(p_actor); r hex_learning_reviews; h text; reason text := btrim(coalesce(p_reason, ''));
begin
  if p_review is null or p_action is null or p_expected_revision is null or p_reviewer is null then raise exception 'Invalid reassignment.'; end if;
  if reason = '' or length(reason) > 4000 then raise exception 'Say why it is being reassigned.'; end if;
  h := md5(jsonb_build_object('op', 'reassign', 'expected', p_expected_revision, 'reviewer', p_reviewer, 'reason', reason)::text);
  select * into r from hex_learning_reviews where id = p_review for update;
  if not found or rnk < 2 or r.author_id = uid or not public._ai_job_visible(r.project_id, uid) then
    raise exception 'Only a supervisor or owner (not the author) can reassign this write-up.' using errcode = '42501';
  end if;
  if public._hex_learning_replay(p_action, p_review, h) then return public._hex_learning_json(r, false); end if;
  if r.state <> 'submitted' then raise exception 'Only a write-up waiting for review can be reassigned.'; end if;
  if r.revision <> p_expected_revision then perform public._hex_learning_stale(); end if;
  if p_reviewer = r.reviewer_id then raise exception 'It is already waiting with that reviewer.'; end if;
  if not public._hex_learning_reviewer_ok(p_reviewer, r.author_id, r.project_id) then
    raise exception 'That person cannot review this job. Choose a current foreman or supervisor.' using errcode = '42501';
  end if;
  update hex_learning_reviews set reviewer_id = p_reviewer, revision = revision + 1, updated_at = now() where id = r.id returning * into r;
  perform public._hex_learning_event(r, p_action, h, 'reassigned', true, reason);
  return public._hex_learning_json(r, false);
end $$;;
;
create function public.hex_learning_withdraw(p_review uuid, p_action uuid, p_expected_revision integer, p_reason text, p_actor uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_actor(p_actor); r hex_learning_reviews; h text; reason text := btrim(coalesce(p_reason, '')); ev uuid;
begin
  if p_review is null or p_action is null or p_expected_revision is null then raise exception 'Invalid withdrawal.'; end if;
  if reason = '' or length(reason) > 4000 then raise exception 'Say why it is being withdrawn.'; end if;
  h := md5(jsonb_build_object('op', 'withdraw', 'expected', p_expected_revision, 'reason', reason)::text);
  select * into r from hex_learning_reviews where id = p_review for update;
  if not found or rnk < 2 or not public._ai_job_visible(r.project_id, uid) then
    raise exception 'Only a supervisor or owner can withdraw a lesson from Hex-Portal.' using errcode = '42501';
  end if;
  if public._hex_learning_replay(p_action, p_review, h) then return public._hex_learning_json(r, false); end if;
  if r.state <> 'approved' then raise exception 'Only an approved lesson can be withdrawn.'; end if;
  if r.revision <> p_expected_revision then perform public._hex_learning_stale(); end if;
  update hex_learning_reviews set state = 'withdrawn', revision = revision + 1, withdrawn_at = now(), withdrawn_by = uid, withdrawn_actor_id = uid,
    withdrawn_by_role = public._hex_learning_role_name(uid), withdrawal_reason = reason,
    withdrawal_event_id = gen_random_uuid(), updated_at = now() where id = r.id returning * into r;
  -- The event carries the same id the withdrawal is known by.
  ev := public._hex_learning_event(r, p_action, h, 'withdrawn', false, reason);
  update hex_learning_review_events set id = r.withdrawal_event_id where id = ev;
  insert into hex_learning_withdrawals(review_id, withdrawal_event_id) values (r.id, r.withdrawal_event_id);
  return public._hex_learning_json(r, false);
end $$;;
;
create function public.hex_learning_list(p_scope text, p_project uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); out jsonb;
begin
  -- NULL is not a scope: it would slip past NOT IN and land in the oversight branch.
  if p_scope is null or p_scope not in ('mine','assigned','oversight') then raise exception 'Invalid list.'; end if;
  if p_scope = 'oversight' and rnk < 2 then raise exception 'Only supervisors and owners have oversight.' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(public._hex_learning_json(r, false) order by (r.state = 'submitted') desc, r.updated_at desc), '[]') into out
  from (select x.id from hex_learning_reviews x
        where (p_project is null or x.project_id = p_project)
          and case p_scope when 'mine' then x.author_id = uid
                           when 'assigned' then x.state <> 'draft' and ((x.reviewer_id = uid and public._hex_learning_reviewer_ok(uid, x.author_id, x.project_id))
                                                                        or public._hex_learning_forwarded_by(x, uid))
                           when 'oversight' then x.state <> 'draft' and public._ai_job_visible(x.project_id, uid)
                           else false end
        order by (x.state = 'submitted') desc, x.updated_at desc limit 100) s
  join hex_learning_reviews r on r.id = s.id;
  return out;
end $$;;
;
create function public.hex_learning_get(p_review uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); r hex_learning_reviews; named boolean;
begin
  if p_review is null then raise exception 'This write-up is unavailable.' using errcode = '42501'; end if;
  select * into r from hex_learning_reviews where id = p_review;
  if not found or not public._hex_learning_can_read(r, uid, rnk) then raise exception 'This write-up is unavailable.' using errcode = '42501'; end if;
  named := r.reviewer_id = uid and public._hex_learning_reviewer_ok(uid, r.author_id, r.project_id);
  return public._hex_learning_json(r, true) || jsonb_build_object('viewer', jsonb_build_object(
    'is_author', r.author_id = uid,
    'is_reviewer', named,
    'can_approve', public._hex_learning_approver_ok(uid, r.author_id, r.project_id),
    'can_oversee', rnk >= 2,
    'can_retry', r.state = 'approved' and not exists (select 1 from hex_learning_deliveries d where d.review_id = r.id and d.status = 'removed_remote'),
    'can_withdraw', rnk >= 2 and r.state = 'approved',
    'can_send_withdrawal', rnk >= 2 and r.state = 'withdrawn'));
end $$;;
;
create function public.hex_learning_reviewers(p_project uuid, p_name text default '', p_review uuid default null, p_purpose text default 'submit') returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); q text := lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'));
  choices jsonb; exact jsonb; author uuid := uid; r hex_learning_reviews; final boolean := false;
begin
  if length(q) > 100 then raise exception 'Search for a shorter name.'; end if;
  if p_project is null or p_purpose is null or p_purpose not in ('submit','forward','reassign') then raise exception 'Invalid reviewer search.'; end if;
  if not public._ai_job_visible(p_project, uid) then raise exception 'That job is unavailable.' using errcode = '42501'; end if;
  if p_purpose <> 'submit' then
    select * into r from hex_learning_reviews where id = p_review and project_id = p_project;
    if not found or (p_purpose = 'forward' and not (r.reviewer_id = uid and public._hex_learning_reviewer_ok(uid, r.author_id, r.project_id)))
       or (p_purpose = 'reassign' and (rnk < 2 or r.author_id = uid)) then
      raise exception 'This write-up is unavailable.' using errcode = '42501';
    end if;
    author := r.author_id; final := p_purpose = 'forward';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name,
      'role', case public.role_rank(p.role) when 3 then 'owner' when 2 then 'supervisor' else 'foreman' end,
      'exact', lower(regexp_replace(btrim(p.display_name), '\s+', ' ', 'g')) = q)
      order by lower(regexp_replace(btrim(p.display_name), '\s+', ' ', 'g')) = q desc, p.display_name, p.id), '[]')
  -- A supervisor/owner author may pick themselves (reviewer_ok decides); nobody forwards or reassigns to themselves.
  into choices from (select * from profiles p where (p.id <> uid or p_purpose = 'submit') and public._hex_learning_reviewer_ok(p.id, author, p_project)
    and (not final or public._hex_learning_rank(p.id) >= 2)
    and (q = '' or lower(p.display_name) like '%' || replace(replace(q, '%', ''), '_', '') || '%'
         or exists (select 1 from regexp_split_to_table(q, ' ') w where length(w) >= 2 and lower(p.display_name) like '%' || replace(replace(w, '%', ''), '_', '') || '%'))
    order by p.display_name limit 30) p;
  select coalesce(jsonb_agg(x), '[]') into exact from jsonb_array_elements(choices) x where (x->>'exact')::boolean;
  return jsonb_build_object('status', case when q = '' then 'not_named' when jsonb_array_length(exact) = 1 then 'exact'
      when jsonb_array_length(exact) > 1 or jsonb_array_length(choices) > 0 then 'choose' else 'none' end,
    'match', case when q <> '' and jsonb_array_length(exact) = 1 then exact->0 end, 'choices', choices);
end $$;;
;
create function public.hex_learning_waiting() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller();
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'revision', r.revision, 'job_code', p.job_code, 'unit_label', c.unit_label,
      'author', (select display_name from profiles where id = r.author_id)) order by r.updated_at desc), '[]')
    from hex_learning_reviews r join hex_portal_cases c on c.id = r.case_id join projects p on p.id = r.project_id
    where r.state = 'submitted' and r.reviewer_id = uid and public._hex_learning_reviewer_ok(uid, r.author_id, r.project_id));
end $$;;
;
create function public._hex_learning_packet(r public.hex_learning_reviews) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object('version', 1, 'caseId', r.case_id, 'projectId', r.project_id, 'revision', r.approved_revision,
    'reviewerId', e.actor_id, 'approvalEventId', e.id, 'approvedAt', e.created_at, 'revisionFingerprint', r.approved_fingerprint,
    'reviewerRole', case public._hex_learning_rank(e.actor_id) when 3 then 'owner' when 2 then 'supervisor' end,
    'status', 'approved', 'authorId', r.author_id, 'unitLabel', nullif(c.unit_label, ''), 'sections', public._hex_learning_sections(e.content),
    'unknownFields', (select coalesce(jsonb_agg(case k when 'what_happened' then 'whatHappened' when 'lesson_learned' then 'lessonLearned'
                        when 'preventive_action' then 'preventiveAction' else k end order by o), '[]')
                      from unnest(array['issue','what_happened','impact','lesson_learned','preventive_action']) with ordinality h(k, o) where e.content->'unknown' ? k),
    'selfReportedImpact', jsonb_build_object('minutes', e.content->'impact_minutes', 'costCents', e.content->'impact_cost_cents'))
  from hex_learning_review_events e join hex_portal_cases c on c.id = r.case_id
  where e.review_id = r.id and e.revision = r.approved_revision and e.id = r.approval_event_id and e.action = 'approved'
$$;;
;
create function public._hex_learning_approval_current(r public.hex_learning_reviews) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select r.state = 'approved' and exists (select 1 from hex_learning_review_events e
    where e.review_id = r.id and e.revision = r.approved_revision and e.id = r.approval_event_id and e.action = 'approved'
      and e.actor_id is not null and public._hex_learning_approver_ok(e.actor_id, r.author_id, r.project_id))
    and public._hex_learning_fingerprint(r.id, r.approved_revision) = r.approved_fingerprint
    -- Removed in Hexcore is terminal: not offered for export or retry again.
    and not exists (select 1 from hex_learning_deliveries d where d.review_id = r.id and d.status = 'removed_remote')
$$;;
;
create function public._hex_learning_may_deliver(r public.hex_learning_reviews, p_uid uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public._hex_learning_rank(p_uid) is not null and (
    (r.author_id = p_uid and public._ai_job_visible(r.project_id, p_uid))
    or (r.reviewer_id = p_uid and public._hex_learning_reviewer_ok(p_uid, r.author_id, r.project_id))
    or public._hex_learning_forwarded_by(r, p_uid)
    or (public._hex_learning_rank(p_uid) >= 2 and public._ai_job_visible(r.project_id, p_uid)))
$$;;
;
create function public._hex_learning_role_name(p_uid uuid) returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select case public._hex_learning_rank(p_uid) when 3 then 'owner' when 2 then 'supervisor' end
$$;;
;
create function public.hex_portal_review_packet(p_case_id uuid, p_revision integer, p_approval_event_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); r hex_learning_reviews;
begin
  if p_case_id is null or p_revision is null or p_approval_event_id is null then raise exception 'Invalid packet request.' using errcode = '22023'; end if;
  select * into r from hex_learning_reviews where case_id = p_case_id;
  if not found or r.approved_revision is distinct from p_revision or r.approval_event_id is distinct from p_approval_event_id
     or not public._hex_learning_approval_current(r) then
    raise exception 'This approval is not current.' using errcode = '42501';
  end if;
  if not public._hex_learning_may_deliver(r, uid) then
    raise exception 'This approval is unavailable to you.' using errcode = '42501';
  end if;
  return public._hex_learning_packet(r) || jsonb_build_object('callerId', uid, 'deliveryAuthorized', true);
end $$;;
;
create function public.hex_portal_approved_cases(p_project_id uuid, p_after uuid default null, p_case_id uuid default null, p_limit integer default 31) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); rows jsonb; more boolean; page integer;
begin
  if rnk < 2 then raise exception 'Only a supervisor or owner can read the approved export.' using errcode = '42501'; end if;
  if p_project_id is null or p_limit is null or p_limit not between 1 and 31 or (p_after is not null and p_case_id is not null) then
    raise exception 'Invalid export request.' using errcode = '22023';
  end if;
  if not public._ai_job_visible(p_project_id, uid) then raise exception 'That job is unavailable.' using errcode = '42501'; end if;
  page := least(p_limit, 30);
  select coalesce(jsonb_agg(public._hex_learning_packet(x) || jsonb_build_object('callerId', uid, 'deliveryAuthorized', true) order by x.case_id), '[]'),
         count(*) > page
  into rows, more
  from (select * from hex_learning_reviews y where y.project_id = p_project_id and y.state = 'approved'
          and (p_after is null or y.case_id > p_after) and (p_case_id is null or y.case_id = p_case_id)
          and public._hex_learning_approval_current(y)
        order by y.case_id limit page + 1) x;
  if more then rows := rows - page; end if;
  return jsonb_build_object('items', rows, 'nextCursor', case when more then rows -> (page - 1) ->> 'caseId' end);
end $$;;
;
create function public.hex_portal_withdrawal_packet(p_case_id uuid, p_withdrawal_event_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); rnk integer := public._hex_learning_caller(); r hex_learning_reviews;
begin
  if p_case_id is null or p_withdrawal_event_id is null then raise exception 'Invalid withdrawal request.' using errcode = '22023'; end if;
  if rnk < 2 then raise exception 'Only a supervisor or owner can withdraw a lesson.' using errcode = '42501'; end if;
  select * into r from hex_learning_reviews where case_id = p_case_id;
  if not found or r.state <> 'withdrawn' or r.withdrawal_event_id is distinct from p_withdrawal_event_id or not public._ai_job_visible(r.project_id, uid) then
    raise exception 'This withdrawal is not current.' using errcode = '42501';
  end if;
  -- withdrawnBy/At/Role are history from the withdrawal itself; callerId and
  -- callerRole are the CURRENT supervisor/owner completing removal. No check on
  -- whether the original withdrawer or approver still has access, and none on
  -- the pilot link: removal always stays possible.
  return jsonb_build_object('version', 1, 'caseId', r.case_id, 'projectId', r.project_id, 'withdrawalEventId', r.withdrawal_event_id,
    'withdrawnAt', r.withdrawn_at, 'withdrawnBy', r.withdrawn_actor_id, 'withdrawnByRole', r.withdrawn_by_role,
    'callerId', uid, 'callerRole', public._hex_learning_role_name(uid), 'withdrawalAuthorized', true, 'revisionFingerprint', r.approved_fingerprint);
end $$;;
;
create function public.hex_learning_record_delivery(p_case_id uuid, p_revision integer, p_approval_event_id uuid, p_fingerprint text, p_caller uuid,
  p_outcome text, p_receipt_id text default null, p_received_at timestamptz default null, p_error text default null) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare r hex_learning_reviews; d hex_learning_deliveries;
begin
  if p_case_id is null or p_revision is null or p_approval_event_id is null or p_fingerprint is null or p_caller is null
     or p_outcome is null or p_outcome not in ('delivered','needs_link','pilot_paused','failed','removed_remote') then raise exception 'Invalid delivery record.'; end if;
  select * into r from hex_learning_reviews where case_id = p_case_id for update;
  if not found then raise exception 'Unknown lesson.'; end if;
  -- A withdrawn lesson never becomes delivered again, however late a reply arrives.
  if r.state = 'withdrawn' then raise exception 'This lesson was withdrawn. Nothing was recorded.'; end if;
  if r.state <> 'approved' or r.approved_revision <> p_revision or r.approval_event_id <> p_approval_event_id or r.approved_fingerprint <> p_fingerprint then
    raise exception 'This approval is not current. Nothing was recorded.';
  end if;
  select * into d from hex_learning_deliveries where review_id = r.id and revision = p_revision for update;
  if d.status = 'removed_remote' then return 'removed_remote'; end if;
  -- The exact same receipt again changes nothing and is safe to acknowledge.
  if p_outcome = 'delivered' and d.status = 'delivered' and d.receipt_id = p_receipt_id and d.received_at = p_received_at then return 'delivered'; end if;
  -- The service role carries no authority of its own: re-check, inside this
  -- transaction, that the approval and its final approver are still current and
  -- that the person who tapped may still deliver it.
  if not public._hex_learning_approval_current(r) then raise exception 'This approval is not current. Nothing was recorded.'; end if;
  if not public._hex_learning_may_deliver(r, p_caller) then raise exception 'The person who sent this can no longer deliver it. Nothing was recorded.'; end if;
  if p_outcome in ('delivered','removed_remote') then
    if p_receipt_id is null or length(p_receipt_id) not between 1 and 200 or p_received_at is null or not isfinite(p_received_at) then
      raise exception 'This needs the receiver''s receipt.';
    end if;
    if d.status = p_outcome then
      if d.receipt_id = p_receipt_id and d.received_at = p_received_at then return p_outcome; end if;
      raise exception 'A different receipt is already recorded.';
    end if;
  elsif d.status = 'delivered' then
    return 'delivered';
  end if;
  update hex_learning_deliveries set status = p_outcome, attempts = attempts + 1, last_attempt_at = now(),
    last_caller = case when exists (select 1 from profiles where id = p_caller) then p_caller end,
    last_error = case when p_outcome = 'failed' then case when coalesce(p_error, '') ~ '^[a-z_]{1,60}$' then p_error else 'unconfirmed' end end,
    receipt_id = case when p_outcome in ('delivered','removed_remote') then p_receipt_id end,
    received_at = case when p_outcome in ('delivered','removed_remote') then p_received_at end
  where review_id = r.id and revision = p_revision;
  return p_outcome;
end $$;;
;
create function public.hex_learning_record_withdrawal(p_case_id uuid, p_withdrawal_event_id uuid, p_caller uuid, p_outcome text,
  p_receipt_id text default null, p_received_at timestamptz default null, p_error text default null) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare r hex_learning_reviews; w hex_learning_withdrawals;
begin
  if p_case_id is null or p_withdrawal_event_id is null or p_caller is null or p_outcome is null or p_outcome not in ('removed','failed') then
    raise exception 'Invalid withdrawal record.';
  end if;
  select * into r from hex_learning_reviews where case_id = p_case_id for update;
  if not found or r.state <> 'withdrawn' or r.withdrawal_event_id <> p_withdrawal_event_id then raise exception 'This withdrawal is not current.'; end if;
  select * into w from hex_learning_withdrawals where review_id = r.id for update;
  -- A recorded tombstone stays recorded; the same receipt again is acknowledged.
  if p_outcome = 'removed' and w.status = 'removed' and w.receipt_id = p_receipt_id and w.received_at = p_received_at then return 'removed'; end if;
  -- Only a CURRENT supervisor/owner who can see the job may record removal;
  -- nothing depends on the original withdrawer or approver still being here.
  if coalesce(public._hex_learning_rank(p_caller), 0) < 2 or not public._ai_job_visible(r.project_id, p_caller) then
    raise exception 'Only a current supervisor or owner can complete removal. Nothing was recorded.';
  end if;
  if p_outcome = 'removed' then
    if p_receipt_id is null or length(p_receipt_id) not between 1 and 200 or p_received_at is null or not isfinite(p_received_at) then
      raise exception 'A removal needs the receiver''s receipt.';
    end if;
    if w.status = 'removed' then
      if w.receipt_id = p_receipt_id and w.received_at = p_received_at then return 'removed'; end if;
      raise exception 'A different receipt is already recorded.';
    end if;
  elsif w.status = 'removed' then
    return 'removed';
  end if;
  update hex_learning_withdrawals set status = p_outcome, attempts = attempts + 1, last_attempt_at = now(),
    last_caller = case when exists (select 1 from profiles where id = p_caller) then p_caller end,
    last_error = case when p_outcome = 'failed' then case when coalesce(p_error, '') ~ '^[a-z_]{1,60}$' then p_error else 'unconfirmed' end end,
    receipt_id = case when p_outcome = 'removed' then p_receipt_id end, received_at = case when p_outcome = 'removed' then p_received_at end
  where review_id = r.id;
  return p_outcome;
end $$;;
;
create function public.hex_learning_memo_readable(p_name text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_name is not null and exists (select 1 from hex_learning_reviews r join ai_field_requests q on q.id = any(r.source_request_ids) and q.profile_id = r.author_id
    where q.audio_path = p_name and r.reviewer_id = auth.uid() and r.state in ('submitted','changes_requested','approved','withdrawn')
      and public._hex_learning_reviewer_ok(r.reviewer_id, r.author_id, r.project_id))
$$;;
;
create or replace function public._clock_pick_time(
  p_tapped_at timestamptz,
  p_clock_checked_at timestamptz,
  p_clock_skew_ms integer,
  p_not_before timestamptz
)
returns public.clock_time_pick
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  v_now timestamptz := now();
  v_corrected timestamptz;
begin
  -- No tap sent: an old bundle. Today's behaviour, and no mark.
  if p_tapped_at is null then
    return (v_now, false, null)::public.clock_time_pick;
  end if;
  if p_clock_checked_at is null or v_now - p_clock_checked_at > interval '24 hours'
     or p_clock_checked_at > v_now + interval '2 minutes' then
    return (v_now, false, 'clock_unchecked')::public.clock_time_pick;
  end if;
  if p_clock_skew_ms is null or abs(p_clock_skew_ms) > 120000 then
    return (v_now, false, 'clock_off')::public.clock_time_pick;
  end if;
  -- The tap in the server's own clock: a phone 40 s fast said 7:02:40 when
  -- the server would have said 7:02:00.
  v_corrected := p_tapped_at - make_interval(secs => p_clock_skew_ms / 1000.0);
  if v_corrected > v_now then
    return (v_now, false, 'tap_after_arrival')::public.clock_time_pick;
  end if;
  if v_now - v_corrected > make_interval(hours => public.shift_cap_hours()) then
    return (v_now, false, 'tap_too_old')::public.clock_time_pick;
  end if;
  if p_not_before is not null and v_corrected < p_not_before then
    return (v_now, false, 'tap_out_of_order')::public.clock_time_pick;
  end if;
  return (v_corrected, true, null)::public.clock_time_pick;
end;
$$;;
;
create or replace function public._flag_shift_for_review(
  p_shift_id uuid,
  p_reason text,
  p_sentence text
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.time_shifts
     set review_reason = coalesce(review_reason, p_reason)
   where id = p_shift_id;
  insert into public.time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'review_reason', null, p_reason, p_sentence);
end;
$$;;
;
create or replace function public._clock_review_sentence(p_reason text, p_tapped_at timestamptz, p_arrived_at timestamptz, p_not_before timestamptz)
returns text
language sql
stable
set search_path = public, pg_temp
as $$
  select case p_reason
    when 'clock_unchecked' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s clock had not been checked in the last day. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'HH12:MI AM') || '.'
    when 'clock_off' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s clock was more than 2 minutes off. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'HH12:MI AM') || '.'
    when 'tap_after_arrival' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s tap time was later than that. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'HH12:MI AM') || '.'
    when 'tap_too_old' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s tap time was more than ' || public.shift_cap_hours() || ' hours earlier. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'YYYY-MM-DD HH12:MI AM') || '.'
    when 'tap_out_of_order' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s tap time was before the shift''s last punch' || coalesce(' (' || to_char(p_not_before at time zone 'America/Denver', 'HH12:MI AM') || ')', '') || '. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'HH12:MI AM') || '.'
    when 'overlaps_previous_shift' then 'Pay used the time this punch reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') because the phone''s tap time was before the previous shift ended' || coalesce(' (' || to_char(p_not_before at time zone 'America/Denver', 'HH12:MI AM') || ')', '') || ', and a shift starting inside another would pay that time twice. The phone said ' || to_char(p_tapped_at at time zone 'America/Denver', 'HH12:MI AM') || '.'
    when 'previous_shift_open' then 'The previous shift was still open, so this clock-in starts when it reached Forge (' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ') rather than at the phone''s tap time.'
    when 'break_end_without_break' then 'A break end arrived at ' || to_char(p_arrived_at at time zone 'America/Denver', 'HH12:MI AM') || ' with no break running, so nothing was ended. Check this shift''s breaks.'
    else 'This punch needs a look.'
  end
$$;;
;
create or replace function public.clock_in(
  p_project_id uuid,
  p_cost_code_id uuid,
  p_photo text,
  p_lat double precision,
  p_lng double precision,
  p_note text,
  p_mode text,
  p_client_id uuid,
  p_tapped_at timestamptz default null,
  p_clock_checked_at timestamptz default null,
  p_clock_skew_ms integer default null
)
returns public.time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_had_open boolean;
  v_previous_end timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before clocking in.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This clock-in is missing its id. Update the app and try again.';
  end if;

  -- One person, one clock-in at a time, until this transaction ends. Two
  -- devices sending clock-ins together — or one tap resent neck and neck
  -- with itself — would otherwise both read the timeline below before either
  -- had written to it, and the second would not see the first's shift.
  perform pg_advisory_xact_lock(hashtextextended('clock_in:' || v_uid::text, 0));

  -- The same tap arriving twice: answer with the shift it already made.
  select ts.* into v_shift
    from public.time_clock_actions a
    join public.time_shifts ts on ts.id = a.shift_id
   where a.client_id = p_client_id and a.profile_id = v_uid;
  if v_shift.id is not null then
    return v_shift;
  end if;
  -- A queued punch that went through the older client_id overload before the
  -- app updated, then retried through this one.
  select * into v_shift from public.time_shifts
   where client_id = p_client_id and profile_id = v_uid;
  if v_shift.id is not null then
    return v_shift;
  end if;

  if not public._toolbox_gate_open(v_uid) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  -- A shift still open when this one arrives is closed at ARRIVAL by the
  -- dangling-shift guard. Starting the new one at an earlier tap time would
  -- overlap the two and pay the gap twice, so the new one starts at arrival
  -- too, and says why.
  select exists (
    select 1 from public.time_shifts
     where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) into v_had_open;
  perform public._close_dangling_shift(v_uid);

  if v_had_open then
    v_pick := (now(), false, 'previous_shift_open')::public.clock_time_pick;
  else
    v_pick := public._clock_pick_time(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, null);
    -- The end of this person's timeline: the latest moment any shift that
    -- still counts reached (a voided one has left every total; a completed
    -- or approved one has not). A trusted tap before it would start this
    -- shift inside the previous one and pay the overlap twice — the stale
    -- device whose earlier clock-in arrives after another phone or the
    -- office closed the day. Arrival instead, marked, with the tap kept in
    -- the ledger for the review. An untrusted tap is already arrival time.
    select max(greatest(clock_in_at, clock_out_at)) into v_previous_end
      from public.time_shifts
     where profile_id = v_uid and status <> 'voided';
    if v_pick.used_tap and v_previous_end is not null and v_pick.pay_at < v_previous_end then
      v_pick := (now(), false, 'overlaps_previous_shift')::public.clock_time_pick;
    end if;
  end if;

  insert into public.time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng,
     note, job_mode, client_id, clock_in_at, last_punch_at, review_reason)
  values
    (v_uid, p_project_id, p_cost_code_id, p_photo, p_lat, p_lng,
     nullif(btrim(p_note), ''),
     case when p_mode in ('data', 'tracking') then p_mode else null end,
     p_client_id, v_pick.pay_at, v_pick.pay_at, v_pick.reason)
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'clock_in', 'clocked_in', p_tapped_at, now(),
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, now(), v_previous_end));
  end if;

  return v_shift;
end;
$$;;
;
create or replace function public.clock_out(
  p_shift_id uuid,
  p_photo text,
  p_injured boolean,
  p_time_confirmed boolean,
  p_break_seconds int,
  p_lat double precision,
  p_lng double precision,
  p_injury_note text,
  p_client_id uuid,
  p_tapped_at timestamptz default null,
  p_clock_checked_at timestamptz default null,
  p_clock_skew_ms integer default null
)
returns public.time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before clocking out.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This clock-out is missing its id. Update the app and try again.';
  end if;

  -- Already applied: the original result, and not one column moved.
  if exists (select 1 from public.time_clock_actions where client_id = p_client_id and profile_id = v_uid) then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return v_shift;
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;
  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    raise exception 'This shift was already clocked out. Nothing was changed.';
  end if;

  -- Not before the shift's last punch: the clock-in, the break still running,
  -- or the end of a break already finished (last_punch_at — the break columns
  -- are cleared when a break ends, and were once all this looked at).
  v_not_before := greatest(v_open.clock_in_at, v_open.break_started_at, v_open.last_punch_at);
  v_pick := public._clock_pick_time(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before);

  update public.time_shifts ts
  set clock_out_at = v_pick.pay_at,
      last_punch_at = v_pick.pay_at,
      clock_out_photo = coalesce(p_photo, ts.clock_out_photo),
      injured = p_injured,
      injury_note = case when p_injured then nullif(trim(coalesce(p_injury_note, '')), '') else null end,
      time_confirmed = p_time_confirmed,
      break_seconds = coalesce(p_break_seconds,
        ts.break_seconds + case
          when ts.break_started_at is not null
            then greatest(0, floor(extract(epoch from (v_pick.pay_at - ts.break_started_at)))::int)
          else 0
        end),
      break_started_at = null,
      break_type = null,
      clock_out_lat = coalesce(p_lat, ts.clock_out_lat),
      clock_out_lng = coalesce(p_lng, ts.clock_out_lng),
      signed_at = now(),
      status = 'submitted',
      review_reason = coalesce(ts.review_reason, v_pick.reason)
  where ts.id = v_open.id
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'clock_out', 'clocked_out', p_tapped_at, now(),
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, now(), v_not_before));
  end if;

  return v_shift;
end;
$$;;
;
create or replace function public.start_break(
  p_shift_id uuid,
  p_break_type text,
  p_client_id uuid,
  p_tapped_at timestamptz default null,
  p_clock_checked_at timestamptz default null,
  p_clock_skew_ms integer default null
)
returns public.time_shifts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_outcome text;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before starting a break.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This break is missing its id. Update the app and try again.';
  end if;

  if exists (select 1 from public.time_clock_actions where client_id = p_client_id and profile_id = v_uid) then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return v_shift;
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;
  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    raise exception 'This shift is already clocked out, so a break can''t start on it.';
  end if;

  if v_open.break_started_at is not null then
    -- Already on a break: the earlier start stands, as it always has.
    v_shift := v_open;
    v_outcome := 'already_on_break';
    v_pick := (now(), false, null)::public.clock_time_pick;
  else
    -- Not before the clock-in, nor before a break this shift already finished
    -- (last_punch_at): a second break tapped inside the first would deduct
    -- that time twice.
    v_not_before := greatest(v_open.clock_in_at, v_open.last_punch_at);
    v_pick := public._clock_pick_time(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before);
    update public.time_shifts ts
       set break_started_at = v_pick.pay_at,
           last_punch_at = v_pick.pay_at,
           break_type = coalesce(ts.break_type, case when p_break_type in ('lunch', 'rest', 'other') then p_break_type else 'other' end),
           review_reason = coalesce(ts.review_reason, v_pick.reason)
     where ts.id = v_open.id
    returning * into v_shift;
    v_outcome := 'started';

    -- Going on a break pauses every phase clock you have running (20260811010000).
    update public.opening_phases
       set paused_at = coalesce(paused_at, now())
     where status = 'active' and started_by = v_uid;
  end if;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'break_start', v_outcome, p_tapped_at, now(),
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, now(), v_not_before));
  end if;

  return v_shift;
end;
$$;;
;
create or replace function public.end_break(
  p_shift_id uuid,
  p_client_id uuid,
  p_tapped_at timestamptz default null,
  p_clock_checked_at timestamptz default null,
  p_clock_skew_ms integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_prior text;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before ending a break.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This break end is missing its id. Update the app and try again.';
  end if;

  select a.outcome into v_prior from public.time_clock_actions a
   where a.client_id = p_client_id and a.profile_id = v_uid;
  if v_prior is not null then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return jsonb_build_object('outcome', v_prior, 'shift', to_jsonb(v_shift));
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;

  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    insert into public.time_clock_actions
      (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at, clock_checked_at, clock_skew_ms)
    values
      (p_client_id, v_open.id, v_uid, 'break_end', 'shift_closed', p_tapped_at, now(), p_clock_checked_at, p_clock_skew_ms);
    return jsonb_build_object('outcome', 'shift_closed', 'shift', to_jsonb(v_open));
  end if;

  if v_open.break_started_at is null then
    -- K0.4: nothing to end. Refuse, keep the refusal, mark the shift.
    insert into public.time_clock_actions
      (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at, clock_checked_at, clock_skew_ms, review_reason)
    values
      (p_client_id, v_open.id, v_uid, 'break_end', 'no_break_running', p_tapped_at, now(), p_clock_checked_at, p_clock_skew_ms, 'break_end_without_break');
    perform public._flag_shift_for_review(v_open.id, 'break_end_without_break',
      public._clock_review_sentence('break_end_without_break', p_tapped_at, now(), null));
    select * into v_shift from public.time_shifts where id = v_open.id;
    return jsonb_build_object('outcome', 'no_break_running', 'shift', to_jsonb(v_shift));
  end if;

  -- Not before the break it is ending (which is also the shift's last punch).
  v_not_before := greatest(v_open.break_started_at, v_open.last_punch_at);
  v_pick := public._clock_pick_time(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before);

  update public.time_shifts ts
     set break_seconds = ts.break_seconds
           + greatest(0, extract(epoch from (v_pick.pay_at - ts.break_started_at))::int),
         break_started_at = null,
         break_type = null,
         last_punch_at = v_pick.pay_at,
         review_reason = coalesce(ts.review_reason, v_pick.reason)
   where ts.id = v_open.id
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'break_end', 'ended', p_tapped_at, now(),
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, now(), v_not_before));
  end if;

  return jsonb_build_object('outcome', 'ended', 'shift', to_jsonb(v_shift));
end;
$$;;
;
create or replace function public._daily_log_revision() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  if (old.headline, old.notes, old.day_flow, old.reflection, old.weather)
     is distinct from (new.headline, new.notes, new.day_flow, new.reflection, new.weather) then
    new.revision := old.revision + 1;
  else
    -- Nobody sets a revision by hand; an unchanged text keeps its number.
    new.revision := old.revision;
  end if;
  return new;
end $$;;
;
create or replace function public._daily_log_contributor() returns uuid
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid();
begin
  if uid is null or public.is_partner_user() or not public.can_file_daily_log()
     or exists (select 1 from profiles where id = uid and retired_at is not null) then
    raise exception 'Daily log entries need a Forge crew login with current access.' using errcode = '42501';
  end if;
  return uid;
end $$;;
;
create or replace function public._daily_log_snapshot(p_log public.daily_logs) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select case when p_log.id is null then null else jsonb_build_object(
    'id', p_log.id, 'project_id', p_log.project_id, 'log_date', p_log.log_date,
    'revision', p_log.revision, 'headline', p_log.headline, 'notes', p_log.notes,
    'day_flow', p_log.day_flow, 'weather', p_log.weather, 'reflection', p_log.reflection,
    'filed_by', p_log.filed_by, 'filed_by_name', (select display_name from profiles where id = p_log.filed_by),
    'updated_by', p_log.updated_by, 'updated_at', p_log.updated_at, 'created_at', p_log.created_at) end
$$;;
;
create or replace function public._daily_log_receipt(p_c public.daily_log_contributions, p_status text) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'status', p_status,
    'contribution_id', p_c.id, 'log_id', p_c.log_id, 'project_id', p_c.project_id,
    'log_date', p_c.log_date, 'actor_id', p_c.actor_id,
    'actor_name', (select display_name from profiles where id = p_c.actor_id),
    'base_revision', p_c.base_revision, 'saved_revision', p_c.saved_revision,
    'created_log', p_c.created_log, 'saved_at', p_c.created_at,
    'source_request_ids', to_jsonb(p_c.source_request_ids),
    'photo_ids', coalesce((select jsonb_agg(ph.photo_id order by ph.created_at, ph.photo_id)
      from daily_log_contribution_photos ph where ph.contribution_id = p_c.id), '[]'::jsonb),
    'log', (select public._daily_log_snapshot(l) from daily_logs l where l.id = p_c.log_id))
$$;;
;
create or replace function public._daily_log_actor(p_actor uuid) returns uuid
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if p_actor is null or auth.uid() is null or p_actor <> auth.uid() then
    raise exception 'This was started under another sign-in. Nothing was saved.' using errcode = '42501';
  end if;
  return public._daily_log_contributor();
end $$;;
;
create or replace function public._daily_log_sources(p_actor uuid, p_ids uuid[]) returns uuid[]
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare x uuid; conv uuid; first_conv uuid; n int := 0; seen uuid[] := '{}';
begin
  if p_ids is null then return '{}'; end if;
  if cardinality(p_ids) > 50 then raise exception 'An entry can list up to 50 messages.' using errcode = '22023'; end if;
  foreach x in array p_ids loop
    if x is null then raise exception 'A message this entry came from is missing its id.' using errcode = '22023'; end if;
    if x = any(seen) then raise exception 'The same message is listed twice.' using errcode = '22023'; end if;
    select r.conversation_id into conv from ai_field_requests r where r.id = x and r.profile_id = p_actor;
    if not found or conv is null then
      raise exception 'A message this entry came from is not one of yours. Nothing was saved.' using errcode = '22023';
    end if;
    n := n + 1;
    if n = 1 then first_conv := conv;
    elsif conv <> first_conv then
      raise exception 'The messages in one entry must come from the same Ask conversation.' using errcode = '22023';
    end if;
    seen := seen || x;
  end loop;
  return seen;
end $$;;
;
create or replace function public.append_daily_log_contribution(
  p_id uuid,
  p_actor uuid,
  p_project_id uuid,
  p_log_date date,
  p_expected_revision bigint,
  p_answers jsonb,
  p_body text,
  p_photo_ids uuid[] default '{}',
  p_source_request_ids uuid[] default '{}'
) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  uid uuid;
  v_name text;
  v_email text;
  v_body text := btrim(coalesce(p_body, ''));
  v_photos uuid[];
  v_sources uuid[];
  v_hash text;
  v_key text;
  v_entry jsonb;
  v_status text;
  v_flow text;
  v_weather text;
  v_reflection jsonb := '{}'::jsonb;
  v_header text;
  v_log daily_logs;
  v_c daily_log_contributions;
  v_base bigint;
begin
  -- Before anything is read: the account that pressed Save is the caller.
  uid := public._daily_log_actor(p_actor);
  if p_id is null then raise exception 'This draft is missing its id. Start the daily log again.' using errcode = '22023'; end if;
  if p_project_id is null or not public._ai_job_visible(p_project_id, uid) then
    raise exception 'Choose an existing job for the daily log.' using errcode = '22023';
  end if;
  if p_log_date is null then raise exception 'A log date is required.' using errcode = '22023'; end if;
  -- The same coarse backstop file_daily_log uses; the phone's local day decides.
  if p_log_date > current_date then raise exception 'The log date cannot be in the future.' using errcode = '22023'; end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'Reload the daily log before saving.' using errcode = '22023';
  end if;
  if length(v_body) = 0 then raise exception 'Say what work was completed before saving.' using errcode = '22023'; end if;
  if length(v_body) > 8000 then raise exception 'This entry is too long. Shorten it and save again.' using errcode = '22023'; end if;

  -- Answers: known fields only, each an object with an explicit status, and a
  -- captured one with nonblank words. Every test is written so an ABSENT key
  -- fails it: in plpgsql a NULL condition is simply "not true", so
  -- `x->>'status' not in (...)` alone would wave a missing status through.
  if p_answers is null or jsonb_typeof(p_answers) is distinct from 'object' or length(p_answers::text) > 40000 then
    raise exception 'This draft could not be read. Start the daily log again.' using errcode = '22023';
  end if;
  for v_key, v_entry in select key, value from jsonb_each(p_answers) loop
    if v_key not in ('work_completed','units_stages','people','problems','notes','day_flow','weather',
                     'went_well','went_poorly','would_have_helped','what_worked') then
      raise exception 'This draft has an answer the daily log does not use.' using errcode = '22023';
    end if;
    v_status := case when jsonb_typeof(v_entry) = 'object' and jsonb_typeof(v_entry->'status') = 'string' then v_entry->>'status' end;
    if v_status is null or v_status not in ('captured','unknown') then
      raise exception 'This draft could not be read. Start the daily log again.' using errcode = '22023';
    end if;
    if v_status = 'captured' and (jsonb_typeof(v_entry->'value') is distinct from 'string'
        or coalesce(btrim(v_entry->>'value'), '') = '') then
      raise exception 'This draft could not be read. Start the daily log again.' using errcode = '22023';
    end if;
  end loop;
  if (p_answers->'work_completed'->>'status') is distinct from 'captured' then
    raise exception 'Say what work was completed before saving.' using errcode = '22023';
  end if;
  if (p_answers->'day_flow'->>'status') = 'captured' then
    v_flow := p_answers->'day_flow'->>'value';
    if v_flow is null or v_flow not in ('smooth','fine','stuck') then
      raise exception 'Day flow must be smooth, fine, or stuck.' using errcode = '22023';
    end if;
  end if;
  if (p_answers->'weather'->>'status') = 'captured' then v_weather := btrim(p_answers->'weather'->>'value'); end if;
  foreach v_key in array array['went_well','went_poorly','would_have_helped','what_worked'] loop
    if (p_answers->v_key->>'status') = 'captured' then
      v_reflection := v_reflection || jsonb_build_object(v_key, btrim(p_answers->v_key->>'value'));
    end if;
  end loop;

  v_sources := public._daily_log_sources(uid, p_source_request_ids);

  select coalesce(array_agg(distinct x order by x), '{}') into v_photos from unnest(coalesce(p_photo_ids, '{}')) x;
  if array_position(v_photos, null) is not null then raise exception 'A photo is missing its id.' using errcode = '22023'; end if;
  if cardinality(v_photos) <> cardinality(coalesce(p_photo_ids, '{}')) then
    raise exception 'The same photo is listed twice.' using errcode = '22023';
  end if;
  if cardinality(v_photos) > 12 then raise exception 'Attach at most 12 photos to one entry.' using errcode = '22023'; end if;

  -- The words, not the revision: a retry after a lost response must match
  -- even though the log has since moved on because of that very save.
  v_hash := md5(jsonb_build_object('project', p_project_id, 'date', p_log_date, 'answers', p_answers,
    'body', v_body, 'photos', to_jsonb(v_photos), 'sources', to_jsonb(v_sources))::text);

  -- Same id first, then the job-day: a double tap serialises on the id, two
  -- people on one job-day serialise on the day, and the order never inverts.
  perform pg_advisory_xact_lock(hashtextextended('daily_log_contribution:' || p_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('daily_log:' || p_project_id::text || ':' || p_log_date::text, 0));

  select * into v_c from daily_log_contributions where id = p_id;
  if found then
    if v_c.actor_id <> uid or v_c.content_hash <> v_hash then
      raise exception 'This entry was already saved with different words. Start a new daily log entry.' using errcode = '22023';
    end if;
    return public._daily_log_receipt(v_c, 'already_saved');
  end if;

  select * into v_log from daily_logs where project_id = p_project_id and log_date = p_log_date for update;
  v_base := coalesce(v_log.revision, 0);
  if v_base <> p_expected_revision then
    -- Nothing is written. The phone shows what the log says now.
    return jsonb_build_object('status', 'stale', 'expected_revision', p_expected_revision,
      'current_revision', v_base, 'log', public._daily_log_snapshot(v_log));
  end if;

  -- Photos: never linked twice; an uploaded row must be this job's and this
  -- account's. A row that has not arrived yet is checked when it is read.
  if exists (select 1 from daily_log_contribution_photos where photo_id = any(v_photos)) then
    raise exception 'A photo in this entry is already part of another daily log entry.' using errcode = '22023';
  end if;
  select email into v_email from auth.users where id = uid;
  if exists (select 1 from attachments a where a.client_id = any(v_photos)
             and (a.project_id is distinct from p_project_id or lower(coalesce(a.created_by, '')) <> lower(coalesce(v_email, '')))) then
    raise exception 'A photo in this entry belongs to a different job or person. Remove it and save again.' using errcode = '22023';
  end if;

  select display_name into v_name from profiles where id = uid;
  v_header := 'Added by ' || coalesce(nullif(btrim(v_name), ''), 'a crew member') || ' with Forge AI:';

  if v_log.id is null then
    insert into daily_logs (project_id, log_date, headline, notes, day_flow, reflection, weather, filed_by)
    values (p_project_id, p_log_date, null, v_header || E'\n' || v_body, v_flow,
            nullif(v_reflection, '{}'::jsonb), nullif(v_weather, ''), uid)
    returning * into v_log;
  else
    -- Added, never replaced: optional details fill only what is still empty.
    update daily_logs set
      notes = rtrim(notes) || E'\n\n' || v_header || E'\n' || v_body,
      day_flow = coalesce(day_flow, v_flow),
      weather = coalesce(weather, nullif(v_weather, '')),
      reflection = case when v_reflection = '{}'::jsonb then reflection
                        else nullif(v_reflection || coalesce(reflection, '{}'::jsonb), '{}'::jsonb) end,
      updated_by = uid,
      updated_at = now()
    where id = v_log.id
    returning * into v_log;
  end if;

  insert into daily_log_contributions (id, log_id, project_id, log_date, actor_id, answers, body, content_hash,
    source_request_ids, base_revision, saved_revision, created_log)
  values (p_id, v_log.id, p_project_id, p_log_date, uid, p_answers, v_body, v_hash,
    v_sources, v_base, v_log.revision, v_base = 0)
  returning * into v_c;
  insert into daily_log_contribution_photos (photo_id, contribution_id, project_id)
  select x, p_id, p_project_id from unnest(v_photos) x;

  return public._daily_log_receipt(v_c, 'saved');
end $$;;
;
create or replace function public.daily_log_contribution_photo_status(p_contribution uuid)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  uid uuid := public._daily_log_contributor();
  v_c daily_log_contributions;
  v_email text;
begin
  select * into v_c from daily_log_contributions where id = p_contribution;
  if not found or not public._ai_job_visible(v_c.project_id, uid) then return '[]'::jsonb; end if;
  select email into v_email from auth.users where id = v_c.actor_id;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'photo_id', ph.photo_id,
      'arrived', a.id is not null,
      'attachment_id', a.id,
      'storage_path', a.storage_path) order by ph.created_at, ph.photo_id)
    from daily_log_contribution_photos ph
    left join lateral (select at.id, at.storage_path from attachments at
      where at.client_id = ph.photo_id and at.project_id = v_c.project_id
        and lower(coalesce(at.created_by, '')) = lower(coalesce(v_email, '')) limit 1) a on true
    where ph.contribution_id = v_c.id), '[]'::jsonb);
end $$;;
;
create or replace function public.partner_has_job_grant(p_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p_project_id is not null and exists (
    select 1 from public.partner_job_grants g
     where g.project_id = p_project_id
       and g.partner_profile_id = auth.uid()
  );
$$;;
;
create or replace function public.set_my_ui_design(p_design text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v text := lower(coalesce(trim(p_design), ''));
begin
  if auth.uid() is null then
    raise exception 'sign in before choosing a design' using errcode = '42501';
  end if;

  if v not in ('classic', 'new') then
    raise exception 'design must be classic or new' using errcode = '22023';
  end if;

  update public.profiles
     set ui_design = v, updated_at = now()
   where id = auth.uid();
end;
$$;;
;
create or replace function public.set_new_design_switch(p_release text, p_enabled boolean)
returns company_settings
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row company_settings;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can turn a new design on or off for everyone.'
      using errcode = '42501';
  end if;
  if p_enabled is null then
    raise exception 'Say whether the new design is on or off.' using errcode = '22023';
  end if;

  if p_release = 'r1' then
    update company_settings
       set new_design_r1_enabled = p_enabled,
           updated_at = now(),
           updated_by = auth.uid()
     where id = 1
    returning * into v_row;
  else
    raise exception 'Unknown release "%". The only new design so far is r1.', p_release
      using errcode = '22023';
  end if;

  return v_row;
end;
$$;;
;
create or replace function public.set_paid_time_rule_date(p_on date)
returns company_settings
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row company_settings;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can set when paid time starts at Start day.'
      using errcode = '42501';
  end if;
  -- A past date would switch the rule on retroactively for today's shifts
  -- already punched under the old timing — nothing is recalculated, but the
  -- day would then run under two rules. Today or later only; null turns it off.
  if p_on is not null and p_on < (now() at time zone 'America/Denver')::date then
    raise exception 'Pick today or a later day — the rule cannot start in the past.'
      using errcode = '22023';
  end if;

  update company_settings
     set paid_time_from_start_day_on = p_on,
         updated_at = now(),
         updated_by = auth.uid()
   where id = 1
  returning * into v_row;

  return v_row;
end;
$$;;
;
create or replace function public._toolbox_signed_today(p_uid uuid)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from toolbox_completions
    where profile_id = p_uid
      and (signed_at at time zone 'America/Denver')::date
        = (now() at time zone 'America/Denver')::date
  );
$$;;
;
create or replace function public._toolbox_gate_open(p_uid uuid)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select public._toolbox_signed_today(p_uid)
    or exists (
      select 1 from company_settings
      where id = 1
        and paid_time_from_start_day_on is not null
        and paid_time_from_start_day_on <= (now() at time zone 'America/Denver')::date
    );
$$;;
;
create or replace function public._unit_work_gate(p_uid uuid)
returns void
language plpgsql
stable
set search_path = public, pg_temp
as $$
begin
  if not public._toolbox_signed_today(p_uid) then
    raise exception 'Sign today''s toolbox talk before starting work on a unit.';
  end if;
end;
$$;;
;
create or replace function public._prep_time_gate(p_uid uuid)
returns void
language plpgsql
stable
set search_path = public, pg_temp
as $$
begin
  if not public._toolbox_signed_today(p_uid) then
    raise exception 'Sign today''s toolbox talk before starting work.';
  end if;
end;
$$;;
;
create or replace function public.sign_toolbox_talk(
  p_client_id uuid,
  p_profile_id uuid,
  p_talk_id uuid,
  p_typed_name text,
  p_signature_path text,
  p_pdf_path text,
  p_talk_snapshot text,
  p_signed_at timestamptz
)
returns public.toolbox_completions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_name text := nullif(btrim(coalesce(p_typed_name, '')), '');
  v_folder text;
  v_row public.toolbox_completions;
  v_talk uuid;
  v_talk_day date;
  v_day date;
  v_at timestamptz;
  v_note text;
begin
  if v_uid is null then
    raise exception 'Sign in to send your toolbox talk signature.' using errcode = '42501';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  -- Nobody files a signature for somebody else, whoever is signed in on the
  -- phone that happens to send it.
  if p_profile_id is distinct from v_uid then
    raise exception 'This toolbox talk signature belongs to someone else on this phone. Sign in as the person who signed it to send it.'
      using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This toolbox talk signature is missing its id. Sign today''s talk again.' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'Type your name to sign the toolbox talk.' using errcode = '22023';
  end if;
  -- The files live under the signer's own folder in toolbox-records, the
  -- folder a test login may write (20261027020000). A record pointing
  -- anywhere else would be pointing at somebody else's signature.
  v_folder := v_uid::text || '/';
  if (p_signature_path is not null and left(p_signature_path, length(v_folder)) <> v_folder)
     or (p_pdf_path is not null and left(p_pdf_path, length(v_folder)) <> v_folder) then
    raise exception 'A toolbox talk signature can only point at files in the signer''s own folder.'
      using errcode = '22023';
  end if;

  -- One signature at a time per person, until this transaction ends: the same
  -- signature sent twice at once must find the first, not race it.
  perform pg_advisory_xact_lock(hashtextextended('toolbox_sign:' || v_uid::text, 0));

  select * into v_row from public.toolbox_completions
   where profile_id = v_uid and client_id = p_client_id;
  if v_row.id is not null then
    return v_row;
  end if;

  -- A lead can re-point a day's talk after the phone kept it (assignTalk
  -- deletes an unsigned instance). The person signed what the phone showed
  -- them; the snapshot says what that was.
  select st.id, st.talk_date into v_talk, v_talk_day from public.safety_talks st where st.id = p_talk_id;

  if p_signed_at is null then
    v_at := v_now;
  elsif p_signed_at > v_now + interval '2 minutes' then
    v_at := v_now;
    v_note := 'phone_clock_ahead';
  elsif p_signed_at < v_now - interval '24 hours' then
    v_at := p_signed_at;
    v_note := 'arrived_late';
  else
    v_at := least(p_signed_at, v_now);
  end if;

  -- The day this signature will count for — the day clock_in's gate reads —
  -- must be its talk's own day (see A TALK IS SIGNED FOR ITS OWN DAY above).
  v_day := (v_at at time zone 'America/Denver')::date;
  if v_talk is not null and v_talk_day is distinct from v_day
     and exists (select 1 from public.safety_talks st where st.talk_date = v_day) then
    raise exception 'This signature is for the toolbox talk of %, but it would count for %. Sign that day''s own talk.',
      to_char(v_talk_day, 'FMMonth FMDD'), to_char(v_day, 'FMMonth FMDD')
      using errcode = '22023';
  end if;

  insert into public.toolbox_completions
    (talk_id, profile_id, signed_at, typed_name, signature_path, talk_snapshot, pdf_path,
     signed_via, signed_by, client_id, phone_signed_at, signed_at_note)
  values
    (v_talk, v_uid, v_at, v_name, p_signature_path, p_talk_snapshot, p_pdf_path,
     'self', null, p_client_id, p_signed_at, v_note)
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function public.can_see_bill_to(p_uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select (public.role_rank(p.role) >= 2 or p.can_see_costs)
            and not coalesce(p.is_partner, false)
            and p.retired_at is null
            and p.access_revoked_at is null
       from public.profiles p
      where p.id = p_uid),
    false);
$$;;
;
create or replace function public.can_manage_bill_to(p_uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select public.role_rank(p.role) >= 2
            and not coalesce(p.is_partner, false)
            and p.retired_at is null
            and p.access_revoked_at is null
       from public.profiles p
      where p.id = p_uid),
    false);
$$;;
;
create or replace function public.project_bill_to_default()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.project_bill_to (project_id, bill_to_customer_id)
  select new.id, c.id
    from public.bill_to_customers c
   where c.is_default
  on conflict (project_id) do nothing;
  return null;
end;
$$;;
;
create or replace function public.save_bill_to_customer(
  p_id uuid,
  p_name text,
  p_billing_email text,
  p_quickbooks_customer_id text
)
returns public.bill_to_customers
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row public.bill_to_customers;
  v_name text := btrim(coalesce(p_name, ''));
  v_email text := nullif(btrim(coalesce(p_billing_email, '')), '');
  v_qb text := nullif(btrim(coalesce(p_quickbooks_customer_id, '')), '');
begin
  if not public.can_manage_bill_to(auth.uid()) then
    raise exception 'Only a supervisor or the owner can change the bill-to list.'
      using errcode = '42501';
  end if;
  if length(v_name) = 0 or length(v_name) > 120 then
    raise exception 'Give the customer a name, up to 120 letters.'
      using errcode = '22023';
  end if;
  if v_email is not null
     and (length(v_email) > 254 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+$') then
    raise exception 'That billing email does not look right. Check it or leave it blank.'
      using errcode = '22023';
  end if;
  if v_qb is not null and v_qb !~ '^[0-9]{1,20}$' then
    raise exception 'The QuickBooks customer ID is digits only. Leave it blank if you do not know it.'
      using errcode = '22023';
  end if;
  if exists (select 1 from public.bill_to_customers c
              where lower(c.name) = lower(v_name) and c.id is distinct from p_id) then
    raise exception 'A customer with that name is already on the list. If it was retired, bring it back instead.'
      using errcode = '23505';
  end if;
  if v_qb is not null and exists (
       select 1 from public.bill_to_customers c
        where c.quickbooks_customer_id = v_qb and c.id is distinct from p_id) then
    raise exception 'Another customer on the list already has that QuickBooks ID.'
      using errcode = '23505';
  end if;

  if p_id is null then
    insert into public.bill_to_customers
      (name, billing_email, quickbooks_customer_id, created_by, updated_by)
    values (v_name, v_email, v_qb, auth.uid(), auth.uid())
    returning * into v_row;
  else
    update public.bill_to_customers c
       set name = v_name,
           billing_email = v_email,
           quickbooks_customer_id = v_qb,
           updated_at = now(),
           updated_by = auth.uid()
     where c.id = p_id
    returning * into v_row;
    if not found then
      raise exception 'That customer is not on the bill-to list.'
        using errcode = 'P0002';
    end if;
  end if;

  return v_row;
end;
$$;;
;
create or replace function public.set_bill_to_customer_retired(
  p_id uuid,
  p_retired boolean
)
returns public.bill_to_customers
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row public.bill_to_customers;
begin
  if not public.can_manage_bill_to(auth.uid()) then
    raise exception 'Only a supervisor or the owner can change the bill-to list.'
      using errcode = '42501';
  end if;
  if p_retired is null then
    raise exception 'Say whether to retire the customer or bring it back.'
      using errcode = '22023';
  end if;

  select * into v_row from public.bill_to_customers c where c.id = p_id for update;
  if not found then
    raise exception 'That customer is not on the bill-to list.'
      using errcode = 'P0002';
  end if;
  if p_retired and v_row.is_default then
    raise exception '% is what every new job bills to, so it cannot be retired.', v_row.name
      using errcode = '22023';
  end if;

  update public.bill_to_customers c
     set retired_at = case when p_retired then coalesce(c.retired_at, now()) end,
         retired_by = case when p_retired then coalesce(c.retired_by, auth.uid()) end,
         updated_at = now(),
         updated_by = auth.uid()
   where c.id = p_id
  returning * into v_row;

  return v_row;
end;
$$;;
;
create or replace function public.set_project_bill_to(
  p_project_id uuid,
  p_bill_to_customer_id uuid
)
returns public.project_bill_to
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row public.project_bill_to;
  v_old uuid;
  v_retired timestamptz;
begin
  if not public.can_manage_bill_to(auth.uid()) then
    raise exception 'Only a supervisor or the owner can change who a job bills to.'
      using errcode = '42501';
  end if;

  select c.retired_at into v_retired
    from public.bill_to_customers c where c.id = p_bill_to_customer_id;
  if not found then
    raise exception 'That customer is not on the bill-to list.'
      using errcode = 'P0002';
  end if;
  if v_retired is not null then
    raise exception 'That customer is retired. Pick one that is still on the list.'
      using errcode = '22023';
  end if;

  perform 1 from public.projects p
    where p.id = p_project_id and p.deleted_at is null;
  if not found then
    raise exception 'That job does not exist or is in the trash.'
      using errcode = 'P0002';
  end if;

  select b.bill_to_customer_id into v_old
    from public.project_bill_to b where b.project_id = p_project_id
    for update;

  if v_old is not distinct from p_bill_to_customer_id then
    select * into v_row from public.project_bill_to b where b.project_id = p_project_id;
    return v_row;
  end if;

  insert into public.project_bill_to
    (project_id, bill_to_customer_id, updated_at, updated_by)
  values (p_project_id, p_bill_to_customer_id, now(), auth.uid())
  on conflict (project_id) do update
    set bill_to_customer_id = excluded.bill_to_customer_id,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by
  returning * into v_row;

  insert into public.project_bill_to_history
    (project_id, from_customer_id, to_customer_id, changed_by)
  values (p_project_id, v_old, p_bill_to_customer_id, auth.uid());

  return v_row;
end;
$$;;
;
create or replace function public.schedule_ai_reasons_active_supervisor()
returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select not public.is_partner_user() and public.travel_is_supervisor() and exists (
    select 1 from public.profiles where id = auth.uid()
      and retired_at is null and access_revoked_at is null)
$$;;
;
create function public.qc_actor_can_review() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.profiles p where p.id = auth.uid()
      and p.role in ('foreman', 'lead', 'supervisor', 'admin', 'owner', 'big_boss')
      and p.retired_at is null and p.access_revoked_at is null
      and not public.is_partner_user()
  );
$$;;
;
create function public.qc_stamp_legacy_reviewer() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is not null then
    if not public.qc_actor_can_review() then
      raise exception 'Only an active foreman, supervisor or owner can review QC.' using errcode = '42501';
    end if;
    if not exists (select 1 from public.project_openings o
                   where o.id = new.project_opening_id and o.status = 'installed' and o.removed_at is null) then
      raise exception 'This installed unit is unavailable for QC.' using errcode = '22023';
    end if;
    if tg_op = 'UPDATE' and (new.id is distinct from old.id
       or new.project_opening_id is distinct from old.project_opening_id) then
      raise exception 'A QC review cannot be moved to another unit.' using errcode = '42501';
    end if;
    if length(coalesce(new.note, '')) > 4000 then
      raise exception 'Keep the QC note under 4,000 characters.' using errcode = '22023';
    end if;
    if coalesce(current_setting('app.qc_rpc', true), '') <> '1' then
      -- The old app supplied checked_at from the phone and no checked_by.
      -- Trust neither field. A repeat of the same write is not a new review.
      if tg_op = 'UPDATE' and old.status is not distinct from new.status
         and old.note is not distinct from new.note
         and old.checked_by is not distinct from auth.uid() then
        return old;
      end if;
      new.checked_by := auth.uid();
      new.checked_at := clock_timestamp();
    end if;
  end if;
  return new;
end;
$$;;
;
create function public.qc_archive_legacy_decision() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if coalesce(current_setting('app.qc_rpc', true), '') = '1'
     or new.status not in ('passed', 'callback') then return new; end if;
  if tg_op = 'UPDATE' and old.status is not distinct from new.status
     and old.note is not distinct from new.note
     and old.checked_by is not distinct from new.checked_by then return new; end if;
  insert into public.qc_decision_events
    (id, project_opening_id, status, note, reviewer_id, decided_at, source)
  values (gen_random_uuid(), new.project_opening_id, new.status, new.note,
          new.checked_by, coalesce(new.checked_at, clock_timestamp()),
          case when auth.uid() is null then 'system' else 'legacy_client' end);
  return new;
end;
$$;;
;
create function public.record_qc_decision(
  p_decision_id uuid,
  p_opening_id uuid,
  p_status text,
  p_note text default null
) returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_existing public.qc_decision_events;
  v_inserted uuid;
  v_at timestamptz := clock_timestamp();
  v_note text := nullif(btrim(p_note), '');
begin
  if p_decision_id is null or p_opening_id is null then
    raise exception 'A QC decision and opening are required.' using errcode = '22023';
  end if;
  if p_status not in ('passed', 'callback') or p_status is null then
    raise exception 'Choose Pass or Callback.' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 4000 then
    raise exception 'Keep the QC note under 4,000 characters.' using errcode = '22023';
  end if;
  if v_actor is null or not public.qc_actor_can_review() then
    raise exception 'Only an active foreman, supervisor or owner can review QC.' using errcode = '42501';
  end if;

  -- A repeated request is a no-op, even if the opening was reviewed again
  -- afterward. A reused ID with different contents is never accepted.
  select * into v_existing from public.qc_decision_events where id = p_decision_id;
  if found then
    if v_existing.project_opening_id is distinct from p_opening_id
       or v_existing.status is distinct from p_status
       or v_existing.note is distinct from v_note
       or v_existing.reviewer_id is distinct from v_actor
       or v_existing.source <> 'review' then
      raise exception 'This QC request ID was already used for another decision.' using errcode = '23505';
    end if;
    return v_existing.id;
  end if;

  perform 1 from public.project_openings o
  where o.id = p_opening_id and o.status = 'installed' and o.removed_at is null
  for update;
  if not found then
    raise exception 'This installed unit is unavailable for QC.' using errcode = '22023';
  end if;

  -- Claim the request ID before touching the current QC row. Concurrent
  -- retries wait on the opening lock or unique key and then become no-ops.
  insert into public.qc_decision_events
    (id, project_opening_id, status, note, reviewer_id, decided_at, source)
  values (p_decision_id, p_opening_id, p_status, v_note, v_actor, v_at, 'review')
  on conflict (id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    select * into v_existing from public.qc_decision_events where id = p_decision_id;
    if v_existing.project_opening_id is distinct from p_opening_id
       or v_existing.status is distinct from p_status
       or v_existing.note is distinct from v_note
       or v_existing.reviewer_id is distinct from v_actor
       or v_existing.source <> 'review' then
      raise exception 'This QC request ID was already used for another decision.' using errcode = '23505';
    end if;
    return v_existing.id;
  end if;

  -- Keep the direct-write compatibility trigger from also archiving this RPC
  -- decision; the explicit event above carries its stable request UUID.
  perform set_config('app.qc_rpc', '1', true);
  insert into public.qc_checks(project_opening_id, status, note, checked_by, checked_at)
  values (p_opening_id, p_status, v_note, v_actor, v_at)
  on conflict (project_opening_id) do update
    set status = excluded.status, note = excluded.note,
        checked_by = excluded.checked_by, checked_at = excluded.checked_at;

  -- The QC projection, history, and pending-point resolution commit together.
  -- Existing points rules intentionally do not reopen already-settled rows.
  perform public.resolve_install_points(
    p_opening_id::text,
    case when p_status = 'passed' then 'confirmed' else 'void' end
  );

  return p_decision_id;
end;
$$;;
;
create function public.crew_work_project_visible(p_project uuid) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select public.custom_work_internal()
    and public._ai_job_visible(p_project,auth.uid())
$$;;
;
create function public._stage_contributor_digest(p_unit uuid,p_stage text,p_work_date date) returns text
language sql stable security definer set search_path=public,pg_temp as $$
  select md5(coalesce(string_agg(x.evidence,',' order by x.evidence),''))
  from (
    select distinct p.record_id::text||':'||p.profile_id::text as evidence
    from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
    where r.unit_id=p_unit and r.stage=p_stage and r.work_date=p_work_date
      and p.voided_at is null and r.outcome in ('partial','finished')
  ) x
$$;;
;
create function public._stage_contributor_sources_visible(p_unit uuid,p_stage text,p_work_date date) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select not exists (
    select 1
    from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
    where r.unit_id=p_unit and r.stage=p_stage and r.work_date=p_work_date
      and p.voided_at is null and r.outcome in ('partial','finished')
      and not coalesce(public._ai_job_visible(r.project_id,auth.uid()),false)
  )
$$;;
;
create function public.stage_contributor_summary(p_unit uuid) returns table(stage text,work_date date,profile_id uuid,digest text)
language sql stable security definer set search_path=public,pg_temp as $$
  select distinct r.stage,r.work_date,p.profile_id,public._stage_contributor_digest(r.unit_id,r.stage,r.work_date)
  from public.crew_work_record_people p
    join public.crew_work_records r on r.id=p.record_id
    join public.custom_work_units u on u.id=r.unit_id
  where r.unit_id=p_unit and p.voided_at is null and r.outcome in ('partial','finished')
    and public.custom_work_internal() and not public.is_partner_user()
    and exists(select 1 from public.projects pu where pu.id=u.project_id and pu.deleted_at is null)
    and public._ai_job_visible(u.project_id,auth.uid())
    and exists(select 1 from public.projects pr where pr.id=r.project_id and pr.deleted_at is null)
    and public._ai_job_visible(r.project_id,auth.uid())
    and public._stage_contributor_sources_visible(r.unit_id,r.stage,r.work_date)
$$;;
;
create function public.record_stage_contributors(p_id uuid,p_data jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands;
  v_unit_id uuid; v_opening_id uuid; opening public.project_openings; unit_row public.custom_work_units;
  job_id uuid; v_stage text; work_day date; outcome text; description text;
  people uuid[]; person uuid; existing_people uuid[]; new_people uuid[];
  plan jsonb; norm_payload jsonb;
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can record crew contributors.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid contributor record.'; end if;

  v_unit_id:=nullif(p_data->>'unit_id','')::uuid;
  v_opening_id:=nullif(p_data->>'opening_id','')::uuid;
  if (v_unit_id is not null)=(v_opening_id is not null) then raise exception 'Choose exactly one saved unit or mapped opening.'; end if;

  v_stage:=p_data->>'stage';
  if v_stage is null or v_stage not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then
    raise exception 'Choose the work stage.';
  end if;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null or work_day<date '2000-01-01' or work_day>(now() at time zone 'America/Denver')::date then
    raise exception 'Choose a valid work date, not in the future.';
  end if;
  outcome:=p_data->>'outcome';
  if outcome is null or outcome not in ('partial','finished') then raise exception 'Choose partial or stage complete.'; end if;
  description:=coalesce(p_data->>'description','');
  if length(description)>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if jsonb_typeof(p_data->'people') is distinct from 'array' or jsonb_array_length(p_data->'people') not between 1 and 100 then
    raise exception 'Select the people who worked.';
  end if;
  select array_agg(distinct value::uuid order by value::uuid) into people from jsonb_array_elements_text(p_data->'people');

  -- Normalized fingerprint: sorted/deduped people, so a resend of this exact
  -- request id with the same people in a different order still matches.
  norm_payload:=jsonb_build_object('action','stage_contributors','data',p_data||jsonb_build_object('people',to_jsonb(people)));

  -- Same namespace as custom_work_command/record_crew_work's own receipt
  -- lock (7282): every route keyed by a custom_work_commands id must
  -- serialize against every other, or two different actions sharing one
  -- request id could both pass the "not found yet" check at once.
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>norm_payload then raise exception 'This retry belongs to a different request.'; end if;
    return receipt.result_id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));

  -- Resolve the job server-side from the reference; the caller never names it.
  if v_unit_id is not null then
    select project_id into job_id from public.custom_work_units where id=v_unit_id;
    if job_id is null then raise exception 'Choose a saved unit on a job.'; end if;
  else
    select * into opening from public.project_openings where id=v_opening_id and removed_at is null;
    if opening.id is null then raise exception 'This opening is not available.'; end if;
    job_id:=opening.project_id;
  end if;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  perform pg_advisory_xact_lock(hashtextextended(coalesce(v_unit_id,v_opening_id)::text,7296));

  if v_unit_id is not null then
    select * into unit_row from public.custom_work_units where id=v_unit_id for update;
    if unit_row.id is null then raise exception 'Choose a saved unit on a job.'; end if;
  else
    select * into unit_row from public.custom_work_units where opening_id=opening.id for update;
    if unit_row.id is null then
      plan:=public._ai_plan_facts(opening.id);
      insert into public.custom_work_units(id,project_id,opening_id,created_by,label,type_label,facts)
      values(gen_random_uuid(),job_id,opening.id,uid,opening.opening_code,coalesce(plan->>'type_label','Unknown'),public._ai_plan_seed(plan))
      on conflict (opening_id) where opening_id is not null do nothing;
      select * into unit_row from public.custom_work_units where opening_id=opening.id for update;
      if unit_row.id is null then raise exception 'Could not create a unit for this opening.'; end if;
    end if;
  end if;

  -- Revalidate identity under the lock (Astra review): the job/opening
  -- checked above was read before this transaction held the unit row. A
  -- concurrent move or removal between that read and this lock is refused,
  -- never silently trusted from a moment earlier. Applies to both the
  -- existing-unit and the just-resolved-opening path, and to an existing
  -- unit's linked opening being removed concurrently.
  if unit_row.project_id is distinct from job_id then
    raise exception 'This unit moved to a different job. Refresh and try again.';
  end if;
  if unit_row.opening_id is not null and not exists(
    select 1 from public.project_openings where id=unit_row.opening_id and removed_at is null and project_id=job_id
  ) then
    raise exception 'This opening is not available.';
  end if;

  foreach person in array people loop
    if person is null or not exists(
      select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null
        and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
        and is_test=public.is_test_profile(uid)
    ) or not public._ai_job_visible(job_id,person) then
      raise exception 'Choose Forge crew members with current access to this job.';
    end if;
  end loop;

  -- The unit and project locks are held before checking historical sources;
  -- a saved digest or an accessible current job grants no access to old jobs.
  if not public._stage_contributor_sources_visible(unit_row.id,v_stage,work_day) then
    raise exception 'Some earlier records for this work are unavailable. Ask a supervisor to review them.' using errcode='42501';
  end if;

  -- Semantic dedupe against every EFFECTIVE report for this exact tuple, not
  -- merely this request: same/fresh id, reordered or overlapping submissions
  -- all land on the same "who is actually new" answer.
  select coalesce(array_agg(distinct p.profile_id),'{}') into existing_people
  from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
  where r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day and p.voided_at is null and r.outcome in ('partial','finished');
  select coalesce(array_agg(x),'{}') into new_people from unnest(people) x where not (x=any(existing_people));

  if array_length(new_people,1) is not null then
    update public.custom_work_units set untimed_work_present=true where id=unit_row.id;
    insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
    values(p_id,job_id,unit_row.id,uid,work_day,v_stage,outcome,false,description);
    insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(new_people);
    insert into public.custom_work_history(project_id,actor_id,entity_id,action,after_value,reason)
    values(job_id,uid,unit_row.id,'stage_contributors',
      jsonb_build_object('record_id',p_id,'people',new_people,'requested',people,'work_date',work_day,'stage',v_stage,'outcome',outcome),
      'Foreman contributor record; no payroll changes');
  end if;

  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,norm_payload,unit_row.id);
  return unit_row.id;
end; $$;;
;
create function public.correct_stage_contributors(p_id uuid,p_data jsonb) returns uuid
language plpgsql security definer set search_path=public,pg_temp as $$
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands; unit_row public.custom_work_units;
  job_id uuid; v_stage text; work_day date; reason text; expected text; current_digest text;
  remove_ids uuid[]; add_ids uuid[]; person uuid; voided_ids uuid[]:='{}'; added_ids uuid[]:='{}';
  outcome text; description text; existing_people uuid[]; norm_payload jsonb;
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can correct crew contributors.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid correction.'; end if;

  reason:=btrim(coalesce(p_data->>'reason',''));
  if length(reason) not between 1 and 500 then raise exception 'Enter a short reason for this correction.'; end if;
  v_stage:=p_data->>'stage';
  if v_stage is null or v_stage not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then
    raise exception 'Choose the work stage.';
  end if;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null then raise exception 'Choose the work date being corrected.'; end if;
  expected:=p_data->>'expected_digest';
  if expected is null then raise exception 'This correction needs the summary you reviewed.'; end if;
  if jsonb_typeof(p_data->'remove')<>'array' then remove_ids:='{}'; else
    select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into remove_ids from jsonb_array_elements_text(p_data->'remove');
  end if;
  if jsonb_typeof(p_data->'add')<>'array' then add_ids:='{}'; else
    select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into add_ids from jsonb_array_elements_text(p_data->'add');
  end if;
  if coalesce(array_length(remove_ids,1),0)>100 or coalesce(array_length(add_ids,1),0)>100 then
    raise exception 'Correct up to 100 people at a time.';
  end if;
  if coalesce(array_length(remove_ids,1),0)=0 and coalesce(array_length(add_ids,1),0)=0 then
    raise exception 'Choose who to remove or add.';
  end if;
  outcome:=p_data->>'outcome';
  description:=coalesce(p_data->>'description','');
  if length(description)>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if array_length(add_ids,1) is not null then
    if outcome is null or outcome not in ('partial','finished') then
      raise exception 'Choose partial or stage complete for the people being added.';
    end if;
    -- Same finite range as record_stage_contributors; a removal-only
    -- correction skips this so it can still clean up old invalid evidence.
    if work_day<date '2000-01-01' or work_day>(now() at time zone 'America/Denver')::date then
      raise exception 'Choose a valid work date, not in the future.';
    end if;
  end if;

  -- Normalized fingerprint: the (already sorted/deduped) remove/add arrays,
  -- so a resend of this exact request id matches regardless of input order.
  norm_payload:=jsonb_build_object('action','correct_stage_contributors','data',
    p_data||jsonb_build_object('remove',to_jsonb(remove_ids),'add',to_jsonb(add_ids)));
  -- Same shared receipt namespace as every other custom_work_commands route
  -- (crew_record/stage_contributors/custom_work_command): every route keyed
  -- by a request id must serialize against every other.
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>norm_payload then raise exception 'This retry belongs to a different request.'; end if;
    return receipt.result_id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));

  select u.* into unit_row from public.custom_work_units u where u.id=(p_data->>'unit_id')::uuid;
  if unit_row.id is null or unit_row.project_id is null then raise exception 'Choose a saved unit on a job.'; end if;
  job_id:=unit_row.project_id;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  perform pg_advisory_xact_lock(hashtextextended(unit_row.id::text,7296));
  select * into unit_row from public.custom_work_units where id=unit_row.id for update;

  -- Revalidate identity under the lock (Astra review): job_id above was read
  -- before this transaction held the unit row. Re-derive authority from what
  -- is actually locked, and refuse rather than trust a moment-old read.
  if unit_row.project_id is distinct from job_id then
    raise exception 'This unit moved to a different job. Refresh and try again.';
  end if;
  if unit_row.opening_id is not null and not exists(
    select 1 from public.project_openings where id=unit_row.opening_id and removed_at is null and project_id=job_id
  ) then
    raise exception 'This opening is not available.';
  end if;

  if not public._stage_contributor_sources_visible(unit_row.id,v_stage,work_day) then
    raise exception 'Some earlier records for this work are unavailable. Ask a supervisor to review them.' using errcode='42501';
  end if;

  -- Recomputed under the mutation locks: a tuple that moved between
  -- loading the summary and submitting the correction is refused, not guessed.
  current_digest:=public._stage_contributor_digest(unit_row.id,v_stage,work_day);
  if current_digest is distinct from expected then
    raise exception 'This contributor summary changed since you loaded it. Review it again before correcting.' using errcode='40001';
  end if;

  if array_length(remove_ids,1) is not null then
    foreach person in array remove_ids loop
      with voided as (
        update public.crew_work_record_people p set voided_at=now(),voided_by=uid,void_reason=reason
        from public.crew_work_records r
        where r.id=p.record_id and r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day
          and r.outcome in ('partial','finished') and p.profile_id=person and p.voided_at is null
        returning p.record_id
      )
      select voided_ids||coalesce(array_agg(record_id),'{}') into voided_ids from voided;
    end loop;
  end if;

  if array_length(add_ids,1) is not null then
    select coalesce(array_agg(distinct p.profile_id),'{}') into existing_people
    from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
    where r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day and p.voided_at is null and r.outcome in ('partial','finished');
    foreach person in array add_ids loop
      if person=any(existing_people) then continue; end if;
      if not exists(
        select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null
          and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
          and is_test=public.is_test_profile(uid)
      ) or not public._ai_job_visible(job_id,person) then
        raise exception 'Choose Forge crew members with current access to this job.';
      end if;
      added_ids:=added_ids||person;
    end loop;
    if array_length(added_ids,1) is not null then
      update public.custom_work_units set untimed_work_present=true where id=unit_row.id;
      insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
      values(p_id,job_id,unit_row.id,uid,work_day,v_stage,outcome,false,description);
      insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(added_ids);
    end if;
  end if;

  -- request_id is recorded even remove-only, so every correction — whether
  -- or not it also added a replacement report — traces to the exact request.
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason)
  values(job_id,uid,unit_row.id,'stage_contributor_correction',
    jsonb_build_object('request_id',p_id,'stage',v_stage,'work_date',work_day,'voided_source_records',voided_ids,'digest_before',current_digest),
    jsonb_build_object('request_id',p_id,'removed',remove_ids,'added',added_ids,'new_record_id',case when array_length(added_ids,1) is not null then p_id end,
      'digest_after',public._stage_contributor_digest(unit_row.id,v_stage,work_day)),
    reason);

  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,norm_payload,unit_row.id);
  return unit_row.id;
end; $$;;
;
create or replace function sign_my_semimonthly_timecard(p_period_start timestamptz, p_timezone text)
returns semimonthly_timecard_periods
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_local timestamp;
  v_day int;
  v_period_end timestamptz;
  v_row semimonthly_timecard_periods;
begin
  if v_uid is null or public.is_partner_user() or not exists (
    select 1 from profiles where id = v_uid and retired_at is null and access_revoked_at is null
  ) then
    raise exception 'an active crew login is required';
  end if;
  if p_period_start is null then
    raise exception 'a period start is required';
  end if;
  if p_timezone is null or btrim(p_timezone) = '' then
    raise exception 'a timezone is required';
  end if;

  -- Raises on its own ("time zone ... not recognized") for a malformed zone.
  v_local := p_period_start at time zone p_timezone;
  v_day := extract(day from v_local)::int;

  if v_day not in (1, 16) or v_local::time <> time '00:00:00' then
    raise exception 'the period start must be local midnight on the 1st or the 16th';
  end if;

  v_period_end := case
    when v_day = 1
      then make_timestamp(extract(year from v_local)::int, extract(month from v_local)::int, 16, 0, 0, 0)
    else (date_trunc('month', v_local) + interval '1 month')::timestamp
  end at time zone p_timezone;

  -- Never sign a running period, from any client — including a first-half
  -- card checked on the 15th or a long second half checked on the 30th.
  if v_period_end > now() then
    raise exception 'this pay period has not ended yet';
  end if;

  insert into semimonthly_timecard_periods
    (profile_id, period_start, period_end, timezone, employee_signed_at)
  values (v_uid, p_period_start, v_period_end, p_timezone, now())
  on conflict (profile_id, period_start)
    do update set employee_signed_at = now()
  returning * into v_row;

  return v_row;
end;
$$;;
;
create or replace function countersign_semimonthly_timecard(p_profile_id uuid, p_period_start timestamptz)
returns semimonthly_timecard_periods
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row semimonthly_timecard_periods;
begin
  if auth.uid() is null or public.is_partner_user() or not exists (
    select 1 from profiles where id = auth.uid() and retired_at is null and access_revoked_at is null
  ) or not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can countersign a timecard';
  end if;

  select * into v_row from semimonthly_timecard_periods
    where profile_id = p_profile_id and period_start = p_period_start
    for update;
  if v_row is null or v_row.employee_signed_at is null then
    raise exception 'the crew member has not signed this period yet';
  end if;

  update semimonthly_timecard_periods
     set supervisor_signed_at = now(),
         supervisor_signed_by = auth.uid()
   where id = v_row.id
   returning * into v_row;

  if v_row.id is null then
    raise exception 'countersign did not apply — no row was updated';
  end if;

  return v_row;
end;
$$;;
;
create function public.file_daily_log(
  p_project_id uuid,
  p_log_date date,
  p_headline text default null,
  p_notes text default null,
  p_day_flow text default null,
  p_reflection jsonb default null,
  p_weather text default null,
  p_expected_revision bigint default null,
  p_progress_provided boolean default false,
  p_work_stages text[] default null,
  p_stage_progress jsonb default null,
  p_covers text default null,
  p_delays jsonb default null,
  p_safety_status text default null,
  p_weather_impact text default null,
  p_missing_tomorrow jsonb default null,
  p_tomorrow_stages text[] default null,
  p_tomorrow_crew_expected integer default null,
  p_tomorrow_plan text default null,
  p_units_today integer default null,
  p_units_to_date integer default null,
  p_units_remaining integer default null,
  p_units_remaining_detail text default null
)
returns public.daily_logs
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_row public.daily_logs;
  v_work_stages text[] := coalesce(p_work_stages, '{}');
  v_tomorrow_stages text[] := coalesce(p_tomorrow_stages, '{}');
  v_stage_progress jsonb := coalesce(p_stage_progress, '{}'::jsonb);
  v_missing_tomorrow jsonb := coalesce(p_missing_tomorrow, '[]'::jsonb);
  v_delays jsonb := coalesce(p_delays, '[]'::jsonb);
  v_item text;
  v_kv record;
  v_elem jsonb;
begin
  if not public.can_file_daily_log() or not exists (
    select 1 from public.profiles where id = v_uid and retired_at is null
  ) then
    raise exception 'only internal crew can file a daily log';
  end if;
  if not exists (select 1 from public.projects where id = p_project_id and deleted_at is null) then
    raise exception 'choose an existing job for the daily log';
  end if;
  if p_notes is null or btrim(p_notes) = '' then
    raise exception 'notes are required — what did the crew get done today?';
  end if;
  if p_day_flow is not null and p_day_flow not in ('smooth', 'fine', 'stuck') then
    raise exception 'day flow must be smooth, fine, or stuck';
  end if;
  if p_log_date is null then
    raise exception 'a log date is required';
  end if;
  if p_log_date > current_date then
    raise exception 'the log date cannot be in the future';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'refresh the daily log before saving' using errcode = '40001';
  end if;

  -- Omission has the same meaning on insert and update. Do not apply
  -- unvalidated trailing arguments from a caller that did not provide a
  -- structured snapshot (including a NULL presence flag).
  if p_progress_provided is not true then
    v_work_stages := '{}';
    v_stage_progress := '{}'::jsonb;
    v_delays := '[]'::jsonb;
    v_missing_tomorrow := '[]'::jsonb;
    v_tomorrow_stages := '{}';
    p_covers := null;
    p_safety_status := null;
    p_weather_impact := null;
    p_tomorrow_crew_expected := null;
    p_tomorrow_plan := null;
    p_units_today := null;
    p_units_to_date := null;
    p_units_remaining := null;
    p_units_remaining_detail := null;
  end if;

  -- Structured-field validation only applies when this caller is actually
  -- answering for them (p_progress_provided) — a caller that left it false
  -- may have sent garbage in the trailing params (an old build sends
  -- nothing at all, so these are irrelevant) and none of it is ever read.
  if p_progress_provided then
    -- Stage vocabulary, validated against the same list the client carries
    -- (lib/dailyLogStages.ts). A key neither list knows is refused, not
    -- silently dropped — the client never sends one it didn't offer, so
    -- this only ever fires on a stale build or a hand-crafted call. A NULL
    -- array element (a malformed call bypassing the client entirely) is
    -- refused explicitly — `x not in (...)` on NULL is NULL, not true, and
    -- would otherwise slip through the loop unnoticed.
    foreach v_item in array v_work_stages loop
      if v_item is null or v_item not in ('prep','flashing','frames','glass','doors','hardware','sealing','qc','site_clean','corrections','material_run') then
        raise exception 'unknown work stage: %', coalesce(v_item, '<null>');
      end if;
    end loop;
    foreach v_item in array v_tomorrow_stages loop
      if v_item is null or v_item not in ('prep','flashing','frames','glass','doors','hardware','sealing','qc','site_clean') then
        raise exception 'unknown tomorrow stage: %', coalesce(v_item, '<null>');
      end if;
    end loop;
    if jsonb_typeof(v_stage_progress) <> 'object' then
      raise exception 'stage progress must be an object keyed by stage';
    end if;
    for v_kv in select * from jsonb_each(v_stage_progress) loop
      if v_kv.key not in ('prep','flashing','frames','glass','doors','hardware','sealing','qc','site_clean') then
        raise exception 'unknown stage in progress: %', v_kv.key;
      end if;
      -- Preserve a numeric JSON contract; text extraction alone would
      -- accept "50" and leave a string where readers expect a number.
      if jsonb_typeof(v_kv.value) is distinct from 'number'
        or v_kv.value::text !~ '^\d+$'
        or v_kv.value::text::numeric < 0 or v_kv.value::text::numeric > 100 then
        raise exception 'stage progress for % must be a whole number 0-100', v_kv.key;
      end if;
    end loop;

    if p_covers is not null and p_covers not in ('windows', 'doors', 'both') then
      raise exception 'covers must be windows, doors, or both';
    end if;

    -- Horizon's delay cards: ANY number of causes, each its own shape — not
    -- one cause object. description required; minutes optional >=0; status
    -- and attribution from fixed, closed lists.
    if jsonb_typeof(v_delays) <> 'array' then
      raise exception 'delays must be a list';
    end if;
    for v_elem in select * from jsonb_array_elements(v_delays) loop
      if jsonb_typeof(v_elem) <> 'object' then
        raise exception 'each delay entry must be an object';
      end if;
      if jsonb_typeof(v_elem->'description') is distinct from 'string'
        or coalesce(btrim(v_elem->>'description'), '') = '' then
        raise exception 'each delay entry needs a description';
      end if;
      if v_elem ? 'minutes' and jsonb_typeof(v_elem->'minutes') <> 'null' then
        if jsonb_typeof(v_elem->'minutes') <> 'number' or (v_elem->>'minutes')::numeric < 0 then
          raise exception 'a delay''s minutes must be a non-negative number';
        end if;
      end if;
      if coalesce(v_elem->>'status', '') not in ('happened', 'still_going') then
        raise exception 'unknown delay status: %', v_elem->>'status';
      end if;
      if coalesce(v_elem->>'attribution', '') not in ('builder', 'forge', 'weather', 'other') then
        raise exception 'unknown delay attribution: %', v_elem->>'attribution';
      end if;
    end loop;

    if p_safety_status is not null and p_safety_status not in ('none_reported', 'reported') then
      raise exception 'unknown safety status';
    end if;
    if p_weather_impact is not null and p_weather_impact not in ('slowed', 'stopped', 'none') then
      raise exception 'unknown weather impact';
    end if;
    if jsonb_typeof(v_missing_tomorrow) <> 'array' then
      raise exception 'missing-tomorrow must be a list';
    end if;
    for v_elem in select * from jsonb_array_elements(v_missing_tomorrow) loop
      if jsonb_typeof(v_elem) <> 'object'
        or jsonb_typeof(v_elem->'description') is distinct from 'string'
        or coalesce(btrim(v_elem->>'description'), '') = '' then
        raise exception 'each missing-tomorrow item needs a description';
      end if;
      if coalesce(v_elem->>'kind', 'material') not in ('material','equipment') then
        raise exception 'unknown missing-tomorrow kind: %', v_elem->>'kind';
      end if;
    end loop;
    if p_tomorrow_crew_expected is not null and (p_tomorrow_crew_expected < 0 or p_tomorrow_crew_expected > 500) then
      raise exception 'crew expected must be between 0 and 500';
    end if;
    if p_units_today is not null and p_units_today < 0 then raise exception 'units today cannot be negative'; end if;
    if p_units_to_date is not null and p_units_to_date < 0 then raise exception 'units to date cannot be negative'; end if;
    if p_units_remaining is not null and p_units_remaining < 0 then raise exception 'units remaining cannot be negative'; end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('daily_log:' || p_project_id::text || ':' || p_log_date::text, 0));
  select * into v_row from public.daily_logs
    where project_id = p_project_id and log_date = p_log_date for update;
  if coalesce(v_row.revision, 0) <> p_expected_revision then
    raise exception 'daily log changed; review the current version before saving' using errcode = '40001';
  end if;

  if v_row.id is null then
    -- Nothing to preserve on a first insert — use the provided snapshot
    -- (empty defaults if the caller never answered for it at all).
    insert into public.daily_logs (
      project_id, log_date, headline, notes, day_flow, reflection, weather, filed_by,
      work_stages, stage_progress, covers, delays, safety_status, weather_impact,
      missing_tomorrow, tomorrow_stages, tomorrow_crew_expected, tomorrow_plan,
      units_today, units_to_date, units_remaining, units_remaining_detail
    )
    values (
      p_project_id, p_log_date, nullif(btrim(p_headline), ''), btrim(p_notes),
      p_day_flow, p_reflection, nullif(btrim(p_weather), ''), v_uid,
      v_work_stages, v_stage_progress, p_covers, v_delays, p_safety_status, p_weather_impact,
      v_missing_tomorrow, v_tomorrow_stages, p_tomorrow_crew_expected, nullif(btrim(p_tomorrow_plan), ''),
      p_units_today, p_units_to_date, p_units_remaining, nullif(btrim(p_units_remaining_detail), '')
    )
    returning * into v_row;
  elsif p_progress_provided then
    -- A full, deliberate structured snapshot — may legitimately clear a
    -- nullable field (an explicit null is as real an answer as a value).
    update public.daily_logs set
      headline = nullif(btrim(p_headline), ''), notes = btrim(p_notes),
      day_flow = p_day_flow, reflection = p_reflection, weather = nullif(btrim(p_weather), ''),
      work_stages = v_work_stages, stage_progress = v_stage_progress, covers = p_covers,
      delays = v_delays, safety_status = p_safety_status, weather_impact = p_weather_impact,
      missing_tomorrow = v_missing_tomorrow, tomorrow_stages = v_tomorrow_stages,
      tomorrow_crew_expected = p_tomorrow_crew_expected, tomorrow_plan = nullif(btrim(p_tomorrow_plan), ''),
      units_today = p_units_today, units_to_date = p_units_to_date, units_remaining = p_units_remaining,
      units_remaining_detail = nullif(btrim(p_units_remaining_detail), ''),
      updated_by = v_uid, updated_at = now()
    where id = v_row.id returning * into v_row;
  else
    -- LEGACY OMISSION: this caller never answered for the structured
    -- fields at all. Every structured column is left exactly as it was —
    -- not in the SET list, not touched, not cleared. Only the text fields
    -- (which every caller, old or new, has always sent) change.
    update public.daily_logs set
      headline = nullif(btrim(p_headline), ''), notes = btrim(p_notes),
      day_flow = p_day_flow, reflection = p_reflection, weather = nullif(btrim(p_weather), ''),
      updated_by = v_uid, updated_at = now()
    where id = v_row.id returning * into v_row;
  end if;
  return v_row;
end $$;;
;
create or replace function public._is_daily_log_photo_name(p_name text)
returns boolean language sql immutable set search_path = public, pg_temp as $$
  select coalesce(split_part(p_name, '/', 2) = 'daily-logs', false);
$$;;
;
create or replace function public._daily_log_photo_actor()
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select public.can_file_daily_log() and exists (
    select 1 from public.profiles where id = auth.uid()
      and retired_at is null and access_revoked_at is null
  );
$$;;
;
create or replace function public._daily_log_photo_upload_allowed(
  p_name text, p_owner_id text, p_metadata jsonb
)
returns boolean language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_project uuid;
  v_deleted timestamptz;
begin
  if not public._daily_log_photo_actor() or p_owner_id is distinct from auth.uid()::text then
    return false;
  end if;
  if p_name is null or p_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/daily-logs/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$'
     or split_part(p_name, '/', 4) <> auth.uid()::text then
    return false;
  end if;
  -- Storage canUpload is a permission preflight: modern releases supply
  -- mimetype/contentLength, older releases may supply no metadata. Final size
  -- does not exist yet. Refuse a known wrong MIME here; the attachment guard
  -- separately requires the completed object's MIME and actual stored size.
  if p_metadata->>'mimetype' is not null and p_metadata->>'mimetype' <> 'image/jpeg' then
    return false;
  end if;

  v_project := split_part(p_name, '/', 1)::uuid;
  select deleted_at into v_deleted from public.projects where id = v_project for share;
  if not found or v_deleted is not null then return false; end if;
  return exists (
    select 1 from public.daily_logs
      where id = split_part(p_name, '/', 3)::uuid and project_id = v_project
  );
end;
$$;;
;
create or replace function public._daily_log_photo_metadata_valid(p_metadata jsonb)
returns boolean language plpgsql immutable set search_path = public, pg_temp as $$
begin
  if p_metadata is null or p_metadata->>'mimetype' is distinct from 'image/jpeg'
     or coalesce(p_metadata->>'size', '') !~ '^[0-9]{1,10}$' then return false; end if;
  return (p_metadata->>'size')::numeric between 1 and 25 * 1024 * 1024;
end;
$$;;
;
create or replace function public._daily_log_photo_storage_guard()
returns trigger language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  v_old_protected boolean := old.bucket_id = 'install-media'
    and public._is_daily_log_photo_name(old.name);
  v_new_protected boolean := false;
  v_attachment public.attachments;
  v_ignored text[] := array['last_accessed_at', 'updated_at'];
  v_trusted boolean := current_user = pg_get_userbyid(
    (select relowner from pg_class where oid = 'public.attachments'::regclass))
    or current_user = 'service_role';
begin
  if tg_op = 'UPDATE' then
    -- PostgreSQL computes generated values AFTER BEFORE triggers. NEW's
    -- transient generated fields cannot establish a writable evidence change.
    -- Exclude only catalog-confirmed generated columns; every ordinary column
    -- (including future fields) remains immutable on a protected object.
    select v_ignored || coalesce(array_agg(attname::text), '{}'::text[])
      into v_ignored from pg_attribute
      where attrelid = tg_relid and attnum > 0 and not attisdropped
        and attgenerated <> '';
    v_new_protected := new.bucket_id = 'install-media' and public._is_daily_log_photo_name(new.name);
    if not v_old_protected and not v_new_protected then return new; end if;
    if (to_jsonb(new) - v_ignored) is distinct from
       (to_jsonb(old) - v_ignored) then
      raise exception 'A completed daily log upload cannot be replaced or moved.' using errcode = '42501';
    end if;
    return new;
  end if;
  if not v_old_protected then return old; end if;
  if v_trusted then
    -- Same path lock as association: an aged orphan cannot disappear between
    -- the uploader's object proof and its new attachment INSERT. Lock an
    -- existing attachment before rechecking expiry, so a concurrent restore
    -- cannot commit between the old sweep's object and attachment DELETEs.
    perform pg_advisory_xact_lock(hashtextextended('daily_log_photo:' || old.bucket_id || '/' || old.name, 0));
    select * into v_attachment from public.attachments
      where daily_log_id is not null and storage_path = old.bucket_id || '/' || old.name
      for update;
    if found then
      if v_attachment.deleted_at < now() - interval '30 days' then return old; end if;
    elsif old.created_at < now() - interval '30 days' and not exists (
        select 1 from public.attachments where storage_path = old.bucket_id || '/' || old.name
      ) then return old;
    end if;
  end if;
  raise exception 'Keep this daily log upload until its recoverable photo trash expires.' using errcode = '42501';
end;
$$;;
;
create or replace function public._attachments_daily_log_guard()
returns trigger language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  -- A DEFINER trigger would erase this distinction. No request GUC is a bypass.
  v_trusted boolean := current_user = pg_get_userbyid((select relowner from pg_class where oid = tg_relid))
                       or current_user = 'service_role';
  v_old_protected boolean := false;
  v_new_protected boolean := false;
  v_path text;
  v_owner text;
  v_metadata jsonb;
  v_log_project uuid;
  v_row_changed boolean;
begin
  if tg_op <> 'INSERT' then
    v_old_protected := old.daily_log_id is not null or
      (split_part(old.storage_path, '/', 1) = 'install-media'
       and public._is_daily_log_photo_name(substr(old.storage_path, strpos(old.storage_path, '/') + 1)));
  end if;
  if tg_op <> 'DELETE' then
    v_new_protected := new.daily_log_id is not null or
      (split_part(new.storage_path, '/', 1) = 'install-media'
       and public._is_daily_log_photo_name(substr(new.storage_path, strpos(new.storage_path, '/') + 1)));
  end if;
  if not v_old_protected and not v_new_protected then return coalesce(new, old); end if;

  if tg_op = 'DELETE' then
    if v_trusted and old.daily_log_id is not null
       and old.deleted_at < now() - interval '30 days' then return old; end if;
    raise exception 'Remove this daily log photo through the recoverable photo trash.' using errcode = '42501';
  end if;
  if new.daily_log_id is null then
    raise exception 'A daily log upload must retain its daily log association.' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' then
    if old.daily_log_id is null then
      raise exception 'Attach a new photo; an existing photo cannot be claimed by a daily log.' using errcode = '42501';
    end if;
    -- All fields, including future columns, are immutable except the one
    -- ordinary editorial field and the exact named lifecycle transitions.
    v_row_changed := (to_jsonb(new) - array['caption','project_id','deleted_at','deleted_by'])
                     is distinct from
                     (to_jsonb(old) - array['caption','project_id','deleted_at','deleted_by']);
    if v_row_changed then
      raise exception 'A saved daily log photo cannot change identity.' using errcode = '42501';
    end if;

    if new.project_id is distinct from old.project_id then
      -- The final projects DELETE fires its existing FK SET NULL after the
      -- log has detached. At that point the project is already invisible to
      -- this transaction; an explicit earlier detach may still see its trash.
      select project_id into v_log_project from public.daily_logs where id = old.daily_log_id;
      if not found or not v_trusted or new.project_id is not null or old.project_id is null
         or v_log_project is not null
         or exists (select 1 from public.projects where id = old.project_id and deleted_at is null)
         or (auth.uid() is not null and (not public._daily_log_photo_actor() or not public._is_supervisor(auth.uid())))
         or (to_jsonb(new) - 'project_id') is distinct from (to_jsonb(old) - 'project_id') then
        raise exception 'This photo can only detach as part of an authorized job purge.' using errcode = '42501';
      end if;
      return new;
    end if;

    -- Preserve deleted_by's existing profile FK ON DELETE SET NULL. This is
    -- only a trusted referential cleanup after that profile actually vanished,
    -- not permission for a client to erase an audit actor.
    if v_trusted and old.deleted_by is not null and new.deleted_by is null
       and not exists (select 1 from public.profiles where id = old.deleted_by)
       and (to_jsonb(new) - 'deleted_by') is not distinct from (to_jsonb(old) - 'deleted_by') then
      return new;
    end if;

    if new.deleted_at is distinct from old.deleted_at or new.deleted_by is distinct from old.deleted_by then
      if not v_trusted or not public._daily_log_photo_actor() or not public._is_lead(auth.uid())
         or (to_jsonb(new) - array['deleted_at','deleted_by']) is distinct from
            (to_jsonb(old) - array['deleted_at','deleted_by']) then
        raise exception 'Use the authorized photo trash or restore action.' using errcode = '42501';
      end if;
      if old.deleted_at is null and new.deleted_at = now() and new.deleted_by = auth.uid() then return new; end if;
      if old.deleted_at is not null and now() < old.deleted_at + interval '30 days'
         and new.deleted_at is null and new.deleted_by is null then return new; end if;
      raise exception 'That photo trash or restore transition is not allowed.' using errcode = '42501';
    end if;

    -- An exact retry may not resurrect a removed photo. Its original row is
    -- still the confirmed result. Only an active original uploader may retry
    -- or edit a caption; the immutable UUID path remains valid after email changes.
    if not public._daily_log_photo_actor()
       or split_part(old.storage_path, '/', 5) is distinct from auth.uid()::text
       or (old.deleted_at is not null and new.caption is distinct from old.caption) then
      raise exception 'Only the active uploader may update this photo.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- New association. No secondary anchor may broaden gallery access later.
  if not public._daily_log_photo_actor() or not public.is_my_upload_name(new.created_by)
     or new.kind is distinct from 'photo' or new.client_id is null
     or new.project_id is null or new.deleted_at is not null or new.deleted_by is not null
     or new.window_id is not null or new.install_event_id is not null
     or new.package_id is not null or new.project_opening_id is not null or new.service_case_id is not null then
    raise exception 'A daily log photo needs its active uploader, job, and original upload identity.' using errcode = '42501';
  end if;
  v_path := new.project_id::text || '/daily-logs/' || new.daily_log_id::text || '/'
            || auth.uid()::text || '/' || new.client_id::text || '.jpg';
  if new.storage_path is distinct from 'install-media/' || v_path then
    raise exception 'The upload path does not match this daily log and operation.' using errcode = '42501';
  end if;
  -- Validate and lock project before object/attachment work, matching purge's
  -- project-first order. A missing or foreign-owned object fails closed.
  if not public._daily_log_photo_upload_allowed(v_path, auth.uid()::text,
       '{"mimetype":"image/jpeg","size":1}'::jsonb) then
    raise exception 'Choose a live job and its matching daily log.' using errcode = '42501';
  end if;
  -- Serialize new association with aged-orphan deletion as well as retries.
  perform pg_advisory_xact_lock(hashtextextended('daily_log_photo:' || new.storage_path, 0));
  -- Serialize retries with the sweep BEFORE reading its immutable object.
  -- FOR KEY SHARE on storage.objects under this invoker would require its
  -- intentionally denied UPDATE policy. Objects cannot otherwise be changed
  -- by a client; protected deletion takes the same path and attachment locks.
  perform 1 from public.attachments where client_id = new.client_id for update;
  if exists (select 1 from public.attachments where client_id = new.client_id and deleted_at is not null) then
    raise exception 'This upload is already in photo trash; reconcile its existing row.' using errcode = '42501';
  end if;
  select owner_id, metadata into v_owner, v_metadata from storage.objects
    where bucket_id = 'install-media' and name = v_path;
  if not found or not public._daily_log_photo_upload_allowed(v_path, v_owner, v_metadata)
     or not public._daily_log_photo_metadata_valid(v_metadata) then
    raise exception 'Upload your original JPEG before attaching it to the daily log.' using errcode = '42501';
  end if;
  return new;
end;
$$;;
;
create or replace function public.crew_goal_summary(p_project_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_target public.project_labor_targets;
  v_recorded numeric;
  v_running numeric;
  v_open integer;
  v_unresolved integer;
  v_at timestamptz := statement_timestamp();
begin
  if not public.custom_work_internal() or public.is_partner_user() or p_project_id is null
    or not exists (
      select 1 from public.projects p where p.id = p_project_id and p.deleted_at is null
      and (not p.is_test or public._is_supervisor(auth.uid()) or
        (public.is_test_profile(auth.uid()) and public.is_sandbox_project(p.id)))
    ) then
    raise exception 'This job is unavailable.' using errcode = '42501';
  end if;

  select * into v_target from public.project_labor_targets where project_id = p_project_id;
  -- A single statement snapshot makes the all-time sum complete regardless of row count.
  -- Closed time follows shiftHours: max(0, wall time minus stored break seconds).
  select coalesce(sum(case when status in ('submitted','approved') and clock_out_at is not null
      then greatest(0, extract(epoch from (clock_out_at - clock_in_at)) - break_seconds) / 3600
      else 0 end), 0),
    coalesce(sum(case when status = 'open' and clock_out_at is null
      then greatest(0, floor(extract(epoch from (v_at - clock_in_at))) - break_seconds
        - case when break_started_at is not null then greatest(0, floor(extract(epoch from (v_at - break_started_at)))) else 0 end) / 3600
      else 0 end), 0),
    count(*) filter (where status = 'open' and clock_out_at is null),
    -- A reviewed-looking status can still carry clock uncertainty. Keep its
    -- payable-shaped hours in recorded total, but count the row once here.
    count(*) filter (where status in ('needs_finish','rejected')
      or (status not in ('voided','open') and clock_out_at is null)
      or (status = 'open' and clock_out_at is not null)
      or (status in ('submitted','approved') and clock_out_at is not null and (
        review_reason is not null or time_confirmed is false
        or clock_out_at < clock_in_at or break_seconds < 0
        or break_seconds > extract(epoch from (clock_out_at - clock_in_at)))))
  into v_recorded, v_running, v_open, v_unresolved
  from public.time_shifts where project_id = p_project_id and status <> 'voided';

  return jsonb_build_object(
    'goal_hours', v_target.goal_hours, 'goal_revision', v_target.revision,
    'goal_updated_at', v_target.updated_at, 'recorded_hours', v_recorded,
    'running_provisional_hours', v_running, 'open_shifts', v_open,
    'unresolved_shifts', v_unresolved, 'as_of', v_at,
    'allowance_hours', case when v_target.goal_hours is null then null
      else v_target.goal_hours - v_recorded - v_running end);
end; $$;;
;
create or replace function public._values_slugs() returns text[]
language sql immutable
as $$
  select array['fullsend','ownership','integrity','sincerity','tribe','growth','strategic','safety']
$$;;
;
create or replace function public._values_eligible(p_uid uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp
as $$
  select p_uid is not null and exists (
    select 1 from public.profiles
     where id = p_uid
       and retired_at is null
       and access_revoked_at is null
       and not coalesce(is_partner, false)
  )
$$;;
;
create or replace function public._values_is_owner(p_uid uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp
as $$
  select public._values_eligible(p_uid) and exists (
    select 1 from public.profiles where id = p_uid and role = 'owner'
  )
$$;;
;
create or replace function public._values_caller_eligible() returns boolean
language sql stable security definer set search_path = public, pg_temp
as $$ select public._values_eligible(auth.uid()) $$;;
;
create or replace function public._values_caller_is_owner() returns boolean
language sql stable security definer set search_path = public, pg_temp
as $$ select public._values_is_owner(auth.uid()) $$;;
;
create or replace function public.set_values_scheduler_enabled(p_enabled boolean)
returns public.company_settings
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row public.company_settings;
begin
  if not public._values_is_owner(auth.uid()) then
    raise exception 'Only an owner can turn the monthly values-review scheduler on or off.'
      using errcode = '42501';
  end if;
  if p_enabled is null then
    raise exception 'Say whether the scheduler is on or off.' using errcode = '22023';
  end if;
  update public.company_settings
     set values_scheduler_enabled = p_enabled, updated_at = now(), updated_by = auth.uid()
   where id = 1
  returning * into v_row;
  return v_row;
end;
$$;;
;
create or replace function public._values_tz() returns text
language sql immutable
as $$ select 'America/Denver' $$;;
;
create or replace function public._values_launch() returns date
language sql immutable
as $$ select '2026-10-01'::date $$;;
;
create or replace function public._values_day(p_at timestamptz) returns date
language sql stable
as $$ select (p_at at time zone public._values_tz())::date $$;;
;
create or replace function public._values_period_of(p_day date) returns date
language sql immutable
as $$ select date_trunc('month', p_day)::date $$;;
;
create or replace function public._values_days_in_period(p_period date) returns int
language sql immutable
as $$ select extract(day from ((p_period + interval '1 month') - interval '1 day'))::int $$;;
;
create or replace function public._values_window_opens_on(p_period date) returns date
language sql immutable
as $$ select p_period + (public._values_days_in_period(p_period) - 7) $$;;
;
create or replace function public._values_window_open(p_at timestamptz) returns boolean
language sql stable
as $$
  select public._values_day(p_at) >= public._values_window_opens_on(public._values_period_of(public._values_day(p_at)))
$$;;
;
create or replace function public._values_active_period(p_at timestamptz) returns date
language sql stable
as $$
  select case
    when public._values_window_open(p_at) then public._values_period_of(public._values_day(p_at))
    else (public._values_period_of(public._values_day(p_at)) - interval '1 month')::date
  end
$$;;
;
create or replace function public._values_period_scorable(p_period date) returns boolean
language sql immutable
as $$ select p_period >= public._values_launch() $$;;
;
create or replace function public._values_quarter_of(p_period date) returns date
language sql immutable
as $$ select date_trunc('quarter', p_period)::date $$;;
;
create or replace function public._values_quarter_end_exclusive(p_quarter date) returns date
language sql immutable
as $$ select (p_quarter + interval '3 months')::date $$;;
;
create or replace function public._values_quarter_closed(p_quarter date, p_at timestamptz) returns boolean
language sql stable
as $$
  select public._values_day(p_at) >= ((public._values_quarter_end_exclusive(p_quarter) + interval '9 days')::date)
$$;;
;
create or replace function public._values_quarter_cutoff_at(p_quarter date) returns timestamptz
language sql immutable
as $$
  select ((public._values_quarter_end_exclusive(p_quarter) + interval '9 days')::date)::timestamp
    at time zone 'America/Denver'
$$;;
;
create or replace function public._values_role_class(p_role text) returns text
language sql immutable
as $$
  select case p_role
    when 'owner' then 'owner'
    when 'supervisor' then 'crew_leader'
    when 'foreman' then 'crew_leader'
    else 'worker'
  end
$$;;
;
create or replace function public._values_ensure_period(p_period date) returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rubric int;
begin
  select id into v_rubric from public.values_rubric_versions order by id desc limit 1;
  insert into public.values_periods (
    period_start, timezone, rubric_version, algorithm_version,
    weight_owner, weight_lead, weight_worker, weight_self, solo_factor, min_raters
  ) values (
    p_period, public._values_tz(), v_rubric, 1,
    1.0, 0.9, 0.65, 0.15, 0.5, 3
  )
  on conflict (period_start) do nothing;
end;
$$;;
;
create or replace function public._values_mirror(
  p_subject uuid, p_since date, p_until date, p_min_raters int, p_cutoff timestamptz default null
)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with complete_submissions as (
    select s.id, s.rater_id, s.rater_class, s.solo, s.period_start
    from public.values_submissions s
    where s.subject_id = p_subject
      and (p_since is null or s.period_start >= p_since)
      and (p_until is null or s.period_start < p_until)
      and (p_cutoff is null or s.submitted_at < p_cutoff)
      and (select count(*) from public.values_scores sc2 where sc2.submission_id = s.id) = 8
      -- CALLER/TEST PARTITION (independent review: test/live separation is a
      -- partition rule, not only an attendance-time exclusion). The deal
      -- engine already never pairs a test rater with a real subject or vice
      -- versa, but this aggregate must not trust that invariant blindly any
      -- more than it trusts the eight-scores one above it — a hand-written
      -- or legacy row that somehow crossed the wall must still never feed a
      -- subject's combined number.
      and public.is_test_profile(s.rater_id) = public.is_test_profile(p_subject)
  ),
  rows as (
    select
      sc.value_slug,
      cs.rater_id,
      cs.rater_class,
      cs.solo,
      sc.score,
      (case cs.rater_class
         when 'owner' then vp.weight_owner
         when 'crew_leader' then vp.weight_lead
         when 'worker' then vp.weight_worker
         when 'self' then vp.weight_self
         else 0
       end) * (case when cs.solo then vp.solo_factor else 1 end) as w
    from complete_submissions cs
    join public.values_scores sc on sc.submission_id = cs.id
    join public.values_periods vp on vp.period_start = cs.period_start
  ),
  per_slug as (
    select
      value_slug,
      count(distinct rater_id) filter (where rater_class <> 'self') as raters,
      sum(score) filter (where rater_class = 'self') as self_sum,
      count(*) filter (where rater_class = 'self') as self_n,
      sum(w * score) as weighted_sum,
      sum(w) as weight_total
    from rows
    group by value_slug
  )
  select coalesce(
    jsonb_object_agg(
      value_slug,
      jsonb_build_object(
        'average',
          case when coalesce(raters, 0) >= p_min_raters and coalesce(weight_total, 0) > 0
            then round((weighted_sum / weight_total)::numeric, 2)
            else null end,
        'self',
          case when coalesce(self_n, 0) > 0 then round((self_sum::numeric / self_n), 2) else null end,
        'raters', coalesce(raters, 0)
      )
    ),
    '{}'::jsonb
  )
  from per_slug;
$$;;
;
create or replace function public.values_my_tasks()
returns table (
  assignment_id uuid,
  period_start date,
  subject_id uuid,
  subject_name text,
  reason text,
  solo boolean,
  status text,
  submitted_at timestamptz,
  -- The rubric version THIS assignment's period is using — the client must
  -- send this back on submit so a mismatch (the questions changed since the
  -- form opened) is caught server-side rather than silently answering stale
  -- wording (independent review finding #5).
  rubric_version int
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  -- Explicit, recognizable denial for an ineligible caller (consistent with
  -- values_my_summary/values_submit), not a silently empty result set that
  -- an offline/degrading client could mistake for "nothing owed" when the
  -- real reason is a revoked/retired account.
  if not public._values_eligible(auth.uid()) then
    raise exception 'Sign in to see your values reviews.' using errcode = '42501';
  end if;

  return query
  select
    a.id,
    a.period_start,
    a.subject_id,
    coalesce(p.display_name, '?'),
    a.reason,
    a.solo,
    case when s.id is not null then 'submitted' else 'pending' end,
    s.submitted_at,
    coalesce(vp.rubric_version, (select id from public.values_rubric_versions order by id desc limit 1))
  from public.values_assignments a
  join public.profiles p on p.id = a.subject_id
  left join public.values_submissions s on s.assignment_id = a.id
    and (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8
  left join public.values_periods vp on vp.period_start = a.period_start
  where a.rater_id = auth.uid()
    -- A subject who has since been retired/revoked withholds the
    -- outstanding task (retirement cancels; revocation suspends): a still-eligible rater is never asked to complete a
    -- review of someone no longer with the company (independent review
    -- finding #7). The assignment ROW is preserved (nothing is deleted); it
    -- does not show as owed while the subject is ineligible. A SUBMITTED one still shows, since
    -- that history must be preserved regardless of the subject's status.
    and (s.id is not null or public._values_eligible(a.subject_id))
    -- CALLER/TEST PARTITION: a row that somehow crossed the test/live wall
    -- (never written by the deal engine itself, which is two-sided-filtered)
    -- is always withheld, including submitted history. Retention does not
    -- override the caller partition boundary.
    and public.is_test_profile(a.subject_id) = public.is_test_profile(auth.uid())
  order by (s.id is not null), a.period_start desc, p.display_name;
end;
$$;;
;
create or replace function public.values_my_owed_count()
returns int
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select count(*)::int
  from public.values_assignments a
  where a.rater_id = auth.uid()
    and public._values_eligible(auth.uid())
    and public._values_eligible(a.subject_id)
    and public.is_test_profile(a.subject_id) = public.is_test_profile(auth.uid())
    and not exists (select 1 from public.values_submissions s where s.assignment_id = a.id
      and (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8);
$$;;
;
create or replace function public.values_my_summary()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_window_start date;
  v_today date;
begin
  if not public._values_eligible(v_uid) then
    raise exception 'Sign in to see your values review.' using errcode = '42501';
  end if;
  v_today := public._values_day(now());
  v_window_start := (public._values_period_of(v_today) - interval '3 months')::date;
  return jsonb_build_object(
    'subjectId', v_uid,
    'windowStart', v_window_start,
    'windowEnd', v_today,
    'mirror', public._values_mirror(v_uid, v_window_start, null, 3),
    'allTime', public._values_mirror(v_uid, null, null, 3),
    'quarters', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'quarterStart', r.quarter_start,
        'overall', r.overall,
        'raterCount', r.rater_count,
        'values', (
          select coalesce(jsonb_object_agg(qv.value_slug, qv.score), '{}'::jsonb)
          from public.values_quarterly_values qv where qv.rating_id = r.id
        )
      ) order by r.quarter_start desc), '[]'::jsonb)
      from public.values_quarterly_ratings r
      where r.subject_id = v_uid
    )
  );
end;
$$;;
;
create or replace function public.values_submit(
  p_assignment_id uuid,
  p_request_id uuid,
  p_rubric_version int,
  p_scores jsonb,
  p_comment text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_assignment public.values_assignments;
  v_period public.values_periods;
  v_existing_by_request public.values_submissions;
  v_existing_by_slot public.values_submissions;
  -- ASCII-space-only trim (VALUES-RECEIPT-CONTRACT.md §1) — btrim's second
  -- argument pins the trim character set explicitly rather than relying on
  -- its space-only default; null propagates through btrim/nullif untouched,
  -- so a null p_comment needs no separate coalesce.
  v_comment text := nullif(btrim(p_comment, ' '), '');
  v_digest text;
  v_canonical text;
  v_score_lines text;
  -- Accumulates the eight validated {slug: score} pairs for the canonical
  -- digest, built only from entries already proven unique/known/in-range —
  -- never from raw client JSON.
  v_validated jsonb := '{}'::jsonb;
  v_rater_class text;
  v_submission_id uuid;
  v_slugs text[] := public._values_slugs();
  v_elem jsonb;
  v_slug text;
  v_raw text;
  v_score int;
  v_seen_slugs text[] := '{}';
  v_quarter date;
  v_cutoff timestamptz;
  v_accepted_at timestamptz;
  v_eligibility text;
  v_receipt jsonb;
begin
  if v_uid is null then
    raise exception 'Sign in before submitting a values review.' using errcode = '42501';
  end if;
  if not public._values_eligible(v_uid) then
    raise exception 'This account no longer has access to submit reviews.' using errcode = '42501';
  end if;
  if p_assignment_id is null or p_request_id is null then
    raise exception 'This review is missing its id and cannot be sent. Open it again.' using errcode = '22023';
  end if;
  if p_rubric_version is null then
    raise exception 'This review is missing which version of the questions it showed. Open it again.' using errcode = '22023';
  end if;
  if p_scores is null or jsonb_typeof(p_scores) <> 'array' or jsonb_array_length(p_scores) <> 8 then
    raise exception 'All eight values need a score before you can submit.' using errcode = '22023';
  end if;
  if v_comment is not null and char_length(v_comment) > 2000 then
    raise exception 'That comment is too long — 2000 characters at most.' using errcode = '22023';
  end if;

  -- One submit at a time per rater, so two near-simultaneous sends (a tap and
  -- a queued retry) cannot both pass the lookups below and double-insert.
  perform pg_advisory_xact_lock(hashtextextended('values_submit:' || v_uid::text, 0));

  -- Validate structure and type STRICTLY before building anything from it:
  -- a score must be a genuine JSON number (not the string "7"), a slug a
  -- genuine JSON string, each slug known and seen at most once. Build the
  -- canonical "slug:score" pairs as we go for a deterministic digest input.
  for v_elem in select * from jsonb_array_elements(p_scores) loop
    if jsonb_typeof(v_elem) is distinct from 'object' then
      raise exception 'Each value needs exactly slug and score.' using errcode = '22023';
    end if;
    if (select count(*) from jsonb_object_keys(v_elem)) <> 2
       or jsonb_typeof(v_elem->'slug') is distinct from 'string'
       or jsonb_typeof(v_elem->'score') is distinct from 'number' then
      raise exception 'Each value needs a slug and a whole-number score.' using errcode = '22023';
    end if;
    v_slug := v_elem->>'slug';
    v_raw := v_elem->>'score';
    if not (v_slug = any (v_slugs)) then
      raise exception 'Unknown value "%" in this review.', v_slug using errcode = '22023';
    end if;
    if v_slug = any (v_seen_slugs) then
      raise exception 'Value "%" was scored twice in this review.', v_slug using errcode = '22023';
    end if;
    v_seen_slugs := array_append(v_seen_slugs, v_slug);
    -- A genuine JSON number can still be "5.5" or "-1" or "10.0" — the raw
    -- text form is checked against a bare 1-or-2-digit pattern so a
    -- fractional score is refused outright, never rounded.
    if v_raw !~ '^[0-9]{1,2}$' then
      raise exception 'Every value needs a whole-number score from 1 to 10.' using errcode = '22023';
    end if;
    v_score := v_raw::int;
    if v_score < 1 or v_score > 10 then
      raise exception 'Every value needs a whole-number score from 1 to 10.' using errcode = '22023';
    end if;
    v_validated := v_validated || jsonb_build_object(v_slug, v_score);
  end loop;
  if array_length(v_seen_slugs, 1) is distinct from 8 then
    raise exception 'All eight values need a score before you can submit.' using errcode = '22023';
  end if;

  -- CANONICAL DIGEST — exactly VALUES-RECEIPT-CONTRACT.md §2/§3, not an ad
  -- hoc delimiter format: encoding version tag, assignment, REQUEST id and
  -- rubric version (all three belong to the digest — independent review
  -- finding #5 named the request id specifically), then the eight value
  -- lines sorted by ASCII slug (COLLATE "C", never locale-sensitive default
  -- ordering), then the comment as `null` or `hex:<utf8 hex>` so no
  -- delimiter in a comment can ever be mistaken for a field boundary. Every
  -- line, including the last, ends in a single LF. Postgres's BUILT-IN
  -- pg_catalog.sha256 (no pgcrypto/extension-schema dependency — independent
  -- review finding #10) over the UTF-8 bytes of that exact text.
  select string_agg(key || '=' || value || chr(10), '' order by key collate "C")
    into v_score_lines
    from jsonb_each_text(v_validated);

  v_canonical :=
    'forge-values-submit/v1' || chr(10) ||
    'assignment=' || p_assignment_id::text || chr(10) ||
    'request=' || p_request_id::text || chr(10) ||
    'rubric=' || p_rubric_version::text || chr(10) ||
    v_score_lines ||
    'comment=' || case when v_comment is null then 'null'
      else 'hex:' || encode(convert_to(v_comment, 'UTF8'), 'hex') end || chr(10);

  v_digest := encode(pg_catalog.sha256(convert_to(v_canonical, 'UTF8')), 'hex');

  -- IDEMPOTENT REPLAY: the same rater, the same request id, ever again —
  -- looked up by (rater_id, request_id) ALONE first (that pair is what the
  -- table's own unique constraint protects), not also filtered by
  -- assignment id, so a request id reused against a DIFFERENT assignment is
  -- caught here as an explicit, friendly conflict rather than falling
  -- through to the insert and raising a raw, unhandled constraint violation
  -- (VALUES-RECEIPT-CONTRACT.md §5: "reuse against a different assignment is
  -- conflict, never a new answer"). The SAME assignment + SAME digest is the
  -- only path that returns the ORIGINAL, immutable, PERSISTED receipt
  -- object — stored verbatim, never recomputed, so it is byte-identical
  -- before and after a later freeze.
  select * into v_existing_by_request
    from public.values_submissions
   where rater_id = v_uid and request_id = p_request_id;
  if v_existing_by_request.id is not null then
    -- A stored receipt is still a read: a partition change cannot grant
    -- access to historical opposite-partition identity on replay.
    if public.is_test_profile(v_uid) <> public.is_test_profile(v_existing_by_request.subject_id) then
      raise exception 'This review crosses the test/live account boundary and cannot be submitted.' using errcode = '42501';
    end if;
    if v_existing_by_request.assignment_id <> p_assignment_id then
      raise exception 'This request id was already used for a different review. Reopen the review to get a new one.'
        using errcode = '23505';
    end if;
    if v_existing_by_request.payload_digest = v_digest then
      return jsonb_build_object('receipt', v_existing_by_request.receipt, 'replay', true);
    end if;
    raise exception 'This request was already submitted with different answers. Reopen the review to try again.'
      using errcode = '23505';
  end if;

  select * into v_assignment from public.values_assignments where id = p_assignment_id for update;
  if v_assignment.id is null or v_assignment.rater_id <> v_uid then
    raise exception 'This review is not assigned to your account.' using errcode = '42501';
  end if;
  -- The subject must still be a current, eligible account — lifecycle
  -- denial while inaccessible (independent review finding #7): a retired/revoked subject
  -- can no longer be newly reviewed, even by a still-eligible rater holding
  -- an old assignment row (values_my_tasks already withholds it as "owed",
  -- this is the server-side enforcement of the same rule).
  if not public._values_eligible(v_assignment.subject_id) then
    raise exception 'This review is currently unavailable because the person does not have review access.'
      using errcode = '42501';
  end if;
  -- CALLER/TEST PARTITION: a test (QA/sandbox) rater and a real subject, or
  -- vice versa, never submit against each other — even against a row that
  -- somehow crossed the wall (the deal engine itself never writes one). A
  -- test rater reviewing a test subject, or a real rater reviewing a real
  -- subject, is unaffected (same-partition QA self-probes remain possible).
  if public.is_test_profile(v_uid) <> public.is_test_profile(v_assignment.subject_id) then
    raise exception 'This review crosses the test/live account boundary and cannot be submitted.'
      using errcode = '42501';
  end if;

  -- GOVERNING PERIOD LOCK (independent review finding #3), acquired before
  -- the slot check and before acceptedAt is captured, and the SAME lock key
  -- _values_freeze_quarter takes for every period in a quarter before it
  -- reads anything — a freeze in flight for this period's quarter and a
  -- submit for this period can never interleave.
  perform pg_advisory_xact_lock(hashtextextended('values_period:' || v_assignment.period_start::text, 0));

  if not public._values_eligible(v_uid) or not public._values_eligible(v_assignment.subject_id)
     or public.is_test_profile(v_uid) <> public.is_test_profile(v_assignment.subject_id) then
    raise exception 'Review access changed while waiting. Reopen this review.' using errcode = '42501';
  end if;

  -- COMPETING REQUEST FOR A COMPLETED ASSIGNMENT: a different request id
  -- arriving for an assignment that already has ANY accepted submission —
  -- never merged, never silently accepted as a second answer.
  select * into v_existing_by_slot
    from public.values_submissions
   where period_start = v_assignment.period_start
     and rater_id = v_assignment.rater_id
     and subject_id = v_assignment.subject_id;
  if v_existing_by_slot.id is not null then
    raise exception 'This review was already submitted for this person this month.' using errcode = '23505';
  end if;

  perform public._values_ensure_period(v_assignment.period_start);
  select * into v_period from public.values_periods where period_start = v_assignment.period_start;

  if p_rubric_version <> v_period.rubric_version then
    raise exception 'The values questions were updated since this review opened. Reopen it to see the current wording before submitting.'
      using errcode = '22023';
  end if;

  v_rater_class := case when v_assignment.rater_id = v_assignment.subject_id
    then 'self'
    else public._values_role_class((select role from public.profiles where id = v_uid))
  end;

  -- Captured AFTER the governing lock, so a transaction that waited for the
  -- lock across the cutoff instant is judged by when it actually runs, not a
  -- stale transaction-start time (independent review finding #5). `now()`
  -- is transaction-start time for the whole transaction in PostgreSQL — it
  -- would still read as of before the lock wait even placed AFTER it.
  -- `clock_timestamp()` is the one function that advances during a
  -- transaction and actually reflects wall time once the lock is held.
  v_accepted_at := clock_timestamp();
  v_quarter := public._values_quarter_of(v_assignment.period_start);
  v_cutoff := public._values_quarter_cutoff_at(v_quarter);
  v_eligibility := case when v_accepted_at < v_cutoff then 'eligible_before_cutoff' else 'late_after_cutoff' end;
  -- The id is generated here, not left to the column default, so it can be
  -- embedded in the receipt object stored in THIS SAME row (VALUES-RECEIPT-
  -- CONTRACT.md §5's immutable nested receipt, not a flat ad hoc shape).
  v_submission_id := gen_random_uuid();
  v_receipt := jsonb_build_object(
    'encodingVersion', 'forge-values-submit/v1',
    'submissionId', v_submission_id,
    'assignmentId', v_assignment.id,
    'requestId', p_request_id,
    'rubricVersion', v_period.rubric_version,
    'digest', v_digest,
    'acceptedAt', v_accepted_at,
    'quarterStart', v_quarter,
    'cutoffAt', v_cutoff,
    'quarterEligibility', v_eligibility
  );

  insert into public.values_submissions (
    id, period_start, assignment_id, rater_id, subject_id, rater_class, solo,
    comment, request_id, payload_digest, rubric_version, algorithm_version, submitted_at, receipt
  ) values (
    v_submission_id, v_assignment.period_start, v_assignment.id, v_assignment.rater_id, v_assignment.subject_id,
    v_rater_class, v_assignment.solo, v_comment, p_request_id, v_digest,
    v_period.rubric_version, v_period.algorithm_version, v_accepted_at, v_receipt
  );

  -- Aliased `elem` here, not `v_elem` — `v_elem` is already a declared
  -- plpgsql variable from the validation loop above, and reusing it as a
  -- FROM-clause alias makes every reference to it ambiguous (42702).
  insert into public.values_scores (submission_id, value_slug, score)
  select v_submission_id, elem->>'slug', (elem->>'score')::int from jsonb_array_elements(p_scores) as elem;

  return jsonb_build_object('receipt', v_receipt, 'replay', false);
end;
$$;;
;
create or replace function public.values_owner_report()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_period date;
  v_cutoff_now timestamptz;
begin
  -- Checked on EVERY call, not cached — a revoked owner loses this instantly.
  -- Exact role='owner' + currently eligible, not a generic rank floor
  -- (independent review finding #1).
  if not public._values_is_owner(v_uid) then
    raise exception 'Owner access only.' using errcode = '42501';
  end if;
  v_period := greatest(public._values_active_period(now()), public._values_launch());
  v_cutoff_now := public._values_quarter_cutoff_at(public._values_quarter_of(v_period));

  return jsonb_build_object(
    'periodStart', v_period,
    'schedulerEnabled', (select values_scheduler_enabled from public.company_settings where id = 1),
    'people', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'userId', pr.id,
        'name', pr.display_name,
        'mirror', public._values_mirror(pr.id, (v_period - interval '3 months')::date, null, 1),
        'owedCount', (
          select count(*) from public.values_assignments a
          where a.subject_id = pr.id and a.period_start = v_period
            and public.is_test_profile(a.rater_id) = public.is_test_profile(pr.id)
            and not exists (select 1 from public.values_submissions s where s.assignment_id = a.id
              and (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8)
        ),
        -- ADDITIVE lifecycle coverage (VALUES-OWNER-CONTRACT.md) — every
        -- field below is new; nothing above is renamed or removed.
        -- `asRater.*` describes this person's OWN workload as a rater this
        -- period; `suspended`/`retired` describe this person's OWN account
        -- state right now; `coverage.*` describes them as a SUBJECT this
        -- period, against the brief's two-received-reviews floor.
        'asRater', jsonb_build_object(
          -- Every a2/a3/s2/s4 join below additionally requires the OTHER
          -- side of the pair to share pr's (and therefore the caller's,
          -- since the outer FROM below is already partitioned) test/live
          -- partition — defense in depth against a hand-written/legacy row
          -- that crossed the wall, same rule as the RLS policies and
          -- _values_mirror above.
          'assigned', (
            select count(*) from public.values_assignments a2
            where a2.rater_id = pr.id and a2.period_start = v_period
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
          ),
          'accepted', (
            select count(*) from public.values_assignments a2
            join public.values_submissions s2 on s2.assignment_id = a2.id
              and (select count(*) from public.values_scores sc where sc.submission_id = s2.id) = 8
            where a2.rater_id = pr.id and a2.period_start = v_period
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
          ),
          'late', (
            select count(*) from public.values_assignments a2
            join public.values_submissions s2 on s2.assignment_id = a2.id
              and (select count(*) from public.values_scores sc where sc.submission_id = s2.id) = 8
            where a2.rater_id = pr.id and a2.period_start = v_period and s2.submitted_at >= v_cutoff_now
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
          ),
          -- Retirement cancels unanswered work; temporary lost access
          -- suspends it. Accepted history is independent of either flag.
          -- All three unanswered buckets are disjoint and partitioned.
          'pending', (
            select count(*) from public.values_assignments a2
            where a2.rater_id = pr.id and a2.period_start = v_period
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
              and not exists (select 1 from public.values_submissions s3 where s3.assignment_id = a2.id
                and (select count(*) from public.values_scores sc where sc.submission_id = s3.id) = 8)
              and public._values_eligible(pr.id) and public._values_eligible(a2.subject_id)
          ),
          'canceled', (
            select count(*) from public.values_assignments a2
            join public.profiles subject on subject.id = a2.subject_id
            where a2.rater_id = pr.id and a2.period_start = v_period
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
              and not exists (select 1 from public.values_submissions s3 where s3.assignment_id = a2.id
                and (select count(*) from public.values_scores sc where sc.submission_id = s3.id) = 8)
              and (pr.retired_at is not null or subject.retired_at is not null)
          ),
          'suspended', (
            select count(*) from public.values_assignments a2
            join public.profiles subject on subject.id = a2.subject_id
            where a2.rater_id = pr.id and a2.period_start = v_period
              and public.is_test_profile(a2.subject_id) = public.is_test_profile(pr.id)
              and not exists (select 1 from public.values_submissions s3 where s3.assignment_id = a2.id
                and (select count(*) from public.values_scores sc where sc.submission_id = s3.id) = 8)
              and pr.retired_at is null and subject.retired_at is null
              and not (public._values_eligible(pr.id) and public._values_eligible(a2.subject_id))
          )
        ),
        'suspended', (pr.access_revoked_at is not null),
        'retired', (pr.retired_at is not null),
        'coverage', jsonb_build_object(
          'expectedReceived', 2,
          'actualReceived', (
            select count(*) from public.values_assignments a3
            join public.values_submissions s4 on s4.assignment_id = a3.id
              and (select count(*) from public.values_scores sc where sc.submission_id = s4.id) = 8
            where a3.subject_id = pr.id and a3.period_start = v_period and s4.rater_class <> 'self'
              and public.is_test_profile(s4.rater_id) = public.is_test_profile(pr.id)
          ),
          'missingCoverage', (
            (select count(*) from public.values_assignments a3
             join public.values_submissions s4 on s4.assignment_id = a3.id
              and (select count(*) from public.values_scores sc where sc.submission_id = s4.id) = 8
             where a3.subject_id = pr.id and a3.period_start = v_period and s4.rater_class <> 'self'
               and public.is_test_profile(s4.rater_id) = public.is_test_profile(pr.id)) < 2
          )
        ),
        'received', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'raterName', rp.display_name,
            'raterClass', s.rater_class,
            'solo', s.solo,
            'periodStart', s.period_start,
            'comment', s.comment,
            'scores', (select coalesce(jsonb_object_agg(sc.value_slug, sc.score), '{}'::jsonb)
                       from public.values_scores sc where sc.submission_id = s.id)
          ) order by s.period_start desc), '[]'::jsonb)
          from public.values_submissions s
          join public.profiles rp on rp.id = s.rater_id
          where s.subject_id = pr.id and s.rater_class <> 'self'
            and public.is_test_profile(rp.id) = public.is_test_profile(pr.id)
        )
      ) order by pr.display_name), '[]'::jsonb)
      from public.profiles pr
      where (
        exists (select 1 from public.values_assignments a where a.subject_id = pr.id
          and public.is_test_profile(a.rater_id) = public.is_test_profile(pr.id))
           or exists (select 1 from public.values_submissions s2 where s2.subject_id = pr.id
             and public.is_test_profile(s2.rater_id) = public.is_test_profile(pr.id))
      )
      -- CALLER/TEST PARTITION: a test-flagged owner's report lists only
      -- test-flagged people; a real owner's lists only real people. This is
      -- the report's own "raw owner RLS" boundary, not just a filter on
      -- display — a test owner never learns a real subject even exists
      -- here, and vice versa.
      and public.is_test_profile(pr.id) = public.is_test_profile(v_uid)
    )
  );
end;
$$;;
;
create or replace function public._values_deal_period(p_period date)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_dealt int := 0;
  v_rec record;
  v_running int;
begin
  if not public._values_period_scorable(p_period) then
    return jsonb_build_object('periodStart', p_period, 'dealt', 0, 'skipped', 'not scorable');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('values_deal:' || p_period::text, 0));
  perform public._values_ensure_period(p_period);

  create temp table if not exists tmp_values_days (user_id uuid, project_id uuid, day date);
  create temp table if not exists tmp_values_pairs (a uuid, b uuid);
  -- UNIQUE (rater_id, subject_id) (independent review finding #8): every
  -- insert below uses ON CONFLICT DO NOTHING against it, so the SAME pair
  -- queued twice from two different generation steps (an owner's "every
  -- active lead" pass and their "own coworkers" pass can target the same
  -- person) is one row, not two — a duplicate row would otherwise inflate a
  -- subject's received count and let the floor pass believe they are
  -- covered when only one real rater exists.
  create temp table if not exists tmp_values_new (
    rater_id uuid, subject_id uuid, reason text, solo boolean,
    seq int generated always as identity, unique (rater_id, subject_id)
  );
  create temp table if not exists tmp_values_running (subject_id uuid primary key, n int not null default 0);
  -- A snapshot of who already held a row BEFORE this run, taken once, up
  -- front. The merge loop below must judge "is this rater new?" against this
  -- snapshot, never against the live table as it fills in during the SAME
  -- run — querying live would make a worker's own SECOND base pick look like
  -- "an existing rater's fresh pick" the moment their first pick landed,
  -- which is not what the merge rule means.
  create temp table if not exists tmp_values_prior_raters (rater_id uuid primary key);
  truncate tmp_values_days;
  truncate tmp_values_pairs;
  truncate tmp_values_new;
  truncate tmp_values_running;
  truncate tmp_values_prior_raters;
  insert into tmp_values_prior_raters
    select distinct rater_id from public.values_assignments where period_start = p_period;

  -- Distinct (person, project, Denver day) from real, accessible, non-test
  -- crew accounts, excluding voided/rejected/needs-finish evidence (that gets
  -- flagged for owner coverage review elsewhere, never silently used here).
  -- `status = any(...)` deliberately does NOT include 'rejected'/'needs_finish':
  -- open shifts DO count (the brief says so explicitly).
  -- Partition match is TWO-SIDED (independent review finding #6): the
  -- PERSON must not be a test account, AND the PROJECT must not be a
  -- testing project — a real crew member's shift on a practice job is not
  -- real review evidence either.
  insert into tmp_values_days (user_id, project_id, day)
  select distinct ts.profile_id, ts.project_id, public._values_day(ts.clock_in_at)
  from public.time_shifts ts
  join public.profiles pr on pr.id = ts.profile_id
  join public.projects pj on pj.id = ts.project_id
  where ts.status in ('open', 'submitted', 'approved')
    and ts.project_id is not null
    and pr.retired_at is null
    and pr.access_revoked_at is null
    and not coalesce(pr.is_partner, false)
    and not public.is_test_profile(pr.id)
    and not coalesce(pj.is_test, false)
    and pr.role in ('installer', 'foreman', 'supervisor', 'owner')
    and public._values_period_of(public._values_day(ts.clock_in_at)) = p_period;

  insert into tmp_values_pairs (a, b)
  select distinct d1.user_id, d2.user_id
  from tmp_values_days d1
  join tmp_values_days d2 on d1.project_id = d2.project_id and d1.day = d2.day and d1.user_id <> d2.user_id;

  -- Owner → every active lead (owner_lead) + owner's own coworkers (crew),
  -- if the owner clocked too.
  for v_rec in
    select pr.id as owner_id from public.profiles pr
    where pr.role = 'owner' and pr.retired_at is null and pr.access_revoked_at is null
      and not coalesce(pr.is_partner, false) and not public.is_test_profile(pr.id)
  loop
    insert into tmp_values_new (rater_id, subject_id, reason, solo)
    select v_rec.owner_id, lead.id, 'owner_lead', false
    from public.profiles lead
    where lead.role in ('foreman', 'supervisor') and lead.retired_at is null and lead.access_revoked_at is null
      and not coalesce(lead.is_partner, false) and not public.is_test_profile(lead.id)
      and exists (select 1 from tmp_values_days d where d.user_id = lead.id)
    on conflict (rater_id, subject_id) do nothing;

    insert into tmp_values_new (rater_id, subject_id, reason, solo)
    select v_rec.owner_id, p.b, 'crew', false
    from tmp_values_pairs p
    where p.a = v_rec.owner_id
    on conflict (rater_id, subject_id) do nothing;
  end loop;

  -- Lead → coworkers (crew) + self, for every lead who clocked.
  for v_rec in
    select lead_id from (
      select distinct pr.id as lead_id from public.profiles pr
      join tmp_values_days d on d.user_id = pr.id
      where pr.role in ('foreman', 'supervisor') and pr.retired_at is null and pr.access_revoked_at is null
        and not coalesce(pr.is_partner, false) and not public.is_test_profile(pr.id)
    ) s
    order by lead_id
  loop
    insert into tmp_values_new (rater_id, subject_id, reason, solo)
    select v_rec.lead_id, p.b, 'crew', false from tmp_values_pairs p where p.a = v_rec.lead_id
    on conflict (rater_id, subject_id) do nothing;
    insert into tmp_values_new (rater_id, subject_id, reason, solo) values (v_rec.lead_id, v_rec.lead_id, 'self', false)
    on conflict (rater_id, subject_id) do nothing;
  end loop;

  -- Worker base deal: up to two coworkers (least-dealt-to-this-subject
  -- first, period-seeded tiebreak), or up to two of last month's coworkers
  -- at solo weight when nobody shared a site this period, plus self.
  --
  -- The outer worker order is wrapped in a derived table (independent
  -- review finding #2): `SELECT DISTINCT pr.id ... ORDER BY md5(...)` is
  -- refused outright by PostgreSQL with 42P10, because the ORDER BY
  -- expression is not the exact expression in the DISTINCT select list — a
  -- real planner error this function used to hit on every call with any
  -- worker rows at all. Deduplicating in the inner query and sorting the
  -- OUTER, non-DISTINCT result is unrestricted.
  for v_rec in
    select worker_id from (
      select distinct pr.id as worker_id from public.profiles pr
      join tmp_values_days d on d.user_id = pr.id
      where pr.role = 'installer' and pr.retired_at is null and pr.access_revoked_at is null
        and not coalesce(pr.is_partner, false) and not public.is_test_profile(pr.id)
    ) s
    order by md5(p_period::text || worker_id::text)
  loop
    if exists (select 1 from tmp_values_pairs where a = v_rec.worker_id) then
      -- "received" counts what is already stored for real AND what this
      -- very run has already queued for that subject so far (including
      -- earlier workers' picks in this same loop) — a live count, not the
      -- snapshot-only one this function used to read here, which could
      -- never see this run's own in-progress picks (independent review
      -- finding #8).
      insert into tmp_values_new (rater_id, subject_id, reason, solo)
      select v_rec.worker_id, cand.b, 'dealt', false
      from (
        select p.b,
          coalesce(r.n, 0) + (select count(*) from tmp_values_new n where n.subject_id = p.b and n.reason <> 'self') as received
        from tmp_values_pairs p
        left join tmp_values_running r on r.subject_id = p.b
        where p.a = v_rec.worker_id
        order by received, md5(p_period::text || v_rec.worker_id::text || p.b::text)
        limit 2
      ) cand(b, received)
      on conflict (rater_id, subject_id) do nothing;
    else
      -- Solo: up to two of last month's coworkers, at solo weight
      -- (_values_recent_coworkers computes that pool from time_shifts
      -- directly — see its own definition below).
      insert into tmp_values_new (rater_id, subject_id, reason, solo)
      select v_rec.worker_id, mate, 'solo', true
      from unnest(public._values_recent_coworkers(v_rec.worker_id, p_period)) with ordinality as t(mate, ord)
      order by ord
      limit 2
      on conflict (rater_id, subject_id) do nothing;
    end if;
    insert into tmp_values_new (rater_id, subject_id, reason, solo) values (v_rec.worker_id, v_rec.worker_id, 'self', false)
    on conflict (rater_id, subject_id) do nothing;
  end loop;

  -- Running received-count, seeded from what is ALREADY stored this period
  -- (so the floor pass below is correct on a re-run, not just a first run).
  insert into tmp_values_running (subject_id, n)
  select subject_id, count(*) from public.values_assignments
  where period_start = p_period and rater_id <> subject_id
  group by subject_id
  on conflict (subject_id) do update set n = excluded.n;

  -- Floor top-up: anyone active, not an owner, still short of 2 received
  -- (counting both what is stored AND what this pass already queued),
  -- picked up by the least-burdened coworker who actually worked beside them.
  -- Same DISTINCT/ORDER BY fix as the worker loop above (finding #2).
  for v_rec in
    select subject_id from (
      select distinct d.user_id as subject_id
      from tmp_values_days d
      where not exists (
        select 1 from public.profiles pr where pr.id = d.user_id and pr.role = 'owner'
      )
    ) s
    order by md5(p_period::text || 'floor' || subject_id::text)
  loop
    select coalesce(n, 0) into v_running from tmp_values_running where subject_id = v_rec.subject_id;
    v_running := coalesce(v_running, 0)
      + (select count(*) from tmp_values_new where subject_id = v_rec.subject_id and reason <> 'self');
    if v_running >= 2 then continue; end if;

    insert into tmp_values_new (rater_id, subject_id, reason, solo)
    select cand.rater_id, v_rec.subject_id, 'dealt', false
    from (
      select p.a as rater_id
      from tmp_values_pairs p
      where p.b = v_rec.subject_id
        and not exists (
          select 1 from public.values_assignments va
          where va.period_start = p_period and va.rater_id = p.a and va.subject_id = v_rec.subject_id
        )
        and not exists (
          select 1 from tmp_values_new n
          where n.rater_id = p.a and n.subject_id = v_rec.subject_id
        )
      order by (
        select count(*) from tmp_values_new n2 where n2.rater_id = p.a and n2.reason <> 'self'
      ), md5(p_period::text || p.a::text || v_rec.subject_id::text)
      limit (2 - v_running)
    ) cand;
    -- A one-person site cannot reach the floor; nothing is invented.
  end loop;

  -- MERGE RULE (assignmentsToStore semantics): a rater who already holds ANY
  -- row this period is never dealt a fresh base pick again; a subject still
  -- short of the floor may still collect one, from any rater. Processed in a
  -- single deterministic pass so "short" reflects earlier inserts in THIS
  -- pass too.
  for v_rec in select * from tmp_values_new order by seq loop
    continue when exists (
      select 1 from public.values_assignments
      where period_start = p_period and rater_id = v_rec.rater_id and subject_id = v_rec.subject_id
    );
    if v_rec.rater_id <> v_rec.subject_id then
      select coalesce(n, 0) into v_running from tmp_values_running where subject_id = v_rec.subject_id;
      v_running := coalesce(v_running, 0);
      -- Skip exactly when the subject is NOT short of the floor AND the
      -- rater is NOT new (judged against the pre-run snapshot) — i.e. insert
      -- when either is true, per the merge rule.
      if v_running >= 2 and exists (select 1 from tmp_values_prior_raters where rater_id = v_rec.rater_id) then
        continue;
      end if;
    end if;
    insert into public.values_assignments (period_start, rater_id, subject_id, reason, solo)
    values (p_period, v_rec.rater_id, v_rec.subject_id, v_rec.reason, v_rec.solo)
    on conflict (period_start, rater_id, subject_id) do nothing;
    if found then
      v_dealt := v_dealt + 1;
      if v_rec.rater_id <> v_rec.subject_id then
        insert into tmp_values_running (subject_id, n) values (v_rec.subject_id, 1)
          on conflict (subject_id) do update set n = tmp_values_running.n + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object('periodStart', p_period, 'dealt', v_dealt);
end;
$$;;
;
create or replace function public._values_recent_coworkers(p_user uuid, p_period date)
returns uuid[]
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(array_agg(distinct d2.profile_id order by d2.profile_id), '{}'::uuid[])
  from public.time_shifts d1
  join public.time_shifts d2
    on d2.project_id = d1.project_id
   and public._values_day(d2.clock_in_at) = public._values_day(d1.clock_in_at)
   and d2.profile_id <> d1.profile_id
  join public.profiles cand on cand.id = d2.profile_id
  join public.projects pj1 on pj1.id = d1.project_id
  join public.projects pj2 on pj2.id = d2.project_id
  where d1.profile_id = p_user
    and d1.status in ('open', 'submitted', 'approved')
    and d2.status in ('open', 'submitted', 'approved')
    and public._values_period_of(public._values_day(d1.clock_in_at)) = (p_period - interval '1 month')::date
    and cand.retired_at is null
    and cand.access_revoked_at is null
    and not coalesce(cand.is_partner, false)
    and not public.is_test_profile(cand.id)
    and cand.role in ('installer', 'foreman', 'supervisor', 'owner')
    and not coalesce(pj1.is_test, false)
    and not coalesce(pj2.is_test, false)
$$;;
;
create or replace function public._values_freeze_quarter(p_quarter date)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_subject uuid;
  v_period date;
  v_frozen int := 0;
  v_skipped int := 0;
  v_rating jsonb;
  v_rating_id uuid;
  v_sub_count int;
  v_rater_count int;
  v_quarter_end date := public._values_quarter_end_exclusive(p_quarter);
  v_cutoff timestamptz := public._values_quarter_cutoff_at(p_quarter);
  v_rubric int;
  v_algorithm int;
  v_policy_versions jsonb;
  v_policy_snapshots jsonb;
  v_distinct_rubrics int;
  v_distinct_algorithms int;
begin
  -- GOVERNING LOCK (independent review finding #3): the SAME per-period lock
  -- values_submit() takes, acquired here for EVERY period in the quarter, in
  -- deterministic ascending order, BEFORE reading anything. A submit in
  -- flight for any of these periods blocks this freeze until it commits or
  -- rolls back, and a freeze in flight blocks a new submit for any of these
  -- periods the same way — the two can never interleave on the same period.
  v_period := p_quarter;
  while v_period < v_quarter_end loop
    perform pg_advisory_xact_lock(hashtextextended('values_period:' || v_period::text, 0));
    v_period := (v_period + interval '1 month')::date;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('values_freeze:' || p_quarter::text, 0));

  -- QUARTER-WIDE POLICY PROVENANCE (independent review: a single "latest
  -- rubric ever inserted" scalar is a fake answer for a mixed-version
  -- quarter — it can disagree with what any period in THIS quarter actually
  -- snapshotted at deal/submit time). Built once from every values_periods
  -- row this quarter's own assignments touched, SAFE fields only (no weight
  -- ladder — that stays owner-only, in private accounting below). The convenience
  -- scalars are set ONLY when every period agreed; a genuinely mixed
  -- quarter leaves them null rather than picking one arbitrarily.
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'periodStart', vp.period_start,
      'timezone', vp.timezone,
      'rubricVersion', vp.rubric_version,
      'algorithmVersion', vp.algorithm_version,
      'weightVersion', vp.weight_version,
      'minRaters', vp.min_raters
    ) order by vp.period_start), '[]'::jsonb),
    count(distinct vp.rubric_version),
    count(distinct vp.algorithm_version)
    into v_policy_versions, v_distinct_rubrics, v_distinct_algorithms
  from public.values_periods vp
  where vp.period_start >= p_quarter and vp.period_start < v_quarter_end;

  select coalesce(jsonb_agg(jsonb_build_object(
    'periodStart', vp.period_start, 'timezone', vp.timezone,
    'rubricVersion', vp.rubric_version, 'algorithmVersion', vp.algorithm_version,
    'weightVersion', vp.weight_version, 'minRaters', vp.min_raters,
    'weightOwner', vp.weight_owner, 'weightLead', vp.weight_lead,
    'weightWorker', vp.weight_worker, 'weightSelf', vp.weight_self,
    'soloFactor', vp.solo_factor, 'cutoff', v_cutoff
  ) order by vp.period_start), '[]'::jsonb) into v_policy_snapshots
  from public.values_periods vp
  where vp.period_start >= p_quarter and vp.period_start < v_quarter_end;

  v_rubric := case when v_distinct_rubrics = 1
    then (select vp.rubric_version from public.values_periods vp
          where vp.period_start >= p_quarter and vp.period_start < v_quarter_end limit 1)
    else null end;
  v_algorithm := case when v_distinct_algorithms = 1
    then (select vp.algorithm_version from public.values_periods vp
          where vp.period_start >= p_quarter and vp.period_start < v_quarter_end limit 1)
    else null end;

  -- ENUMERATE FROM ASSIGNMENTS, not submissions (independent review finding
  -- #4): someone assigned reviews who received zero still gets a frozen
  -- null result, atomically with everyone else, rather than being silently
  -- left out and then picked up by a later run on whatever late answer
  -- happens to arrive first.
  for v_subject in
    select distinct subject_id from public.values_assignments
    where period_start >= p_quarter and period_start < v_quarter_end
  loop
    if exists (
      select 1 from public.values_quarterly_ratings
      where quarter_start = p_quarter and subject_id = v_subject
    ) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    -- COMPLETE submissions, accepted BEFORE the exact cutoff instant, in the
    -- subject's own test/live partition only (independent review finding
    -- #3, and the caller-partition rule above) — _values_mirror's own
    -- complete-submission and partition filters apply here too, for free.
    v_rating := public._values_mirror(v_subject, p_quarter, v_quarter_end, 3, v_cutoff);
    select count(*) into v_sub_count from public.values_submissions s
      where s.subject_id = v_subject and s.period_start >= p_quarter and s.period_start < v_quarter_end
        and s.submitted_at < v_cutoff
        and public.is_test_profile(s.rater_id) = public.is_test_profile(v_subject)
        and (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8;
    select count(distinct s.rater_id) into v_rater_count from public.values_submissions s
      where s.subject_id = v_subject and s.period_start >= p_quarter and s.period_start < v_quarter_end
        and s.submitted_at < v_cutoff
        and s.rater_class <> 'self'
        and public.is_test_profile(s.rater_id) = public.is_test_profile(v_subject)
        and (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8;

    insert into public.values_quarterly_ratings (
      quarter_start, subject_id, overall, rater_count, submission_count, algorithm_version, cutoff, rubric_version,
      policy_versions
    )
    values (
      p_quarter, v_subject,
      (select avg((val->>'average')::numeric) from jsonb_each(v_rating) as t(slug, val) where val->>'average' is not null),
      v_rater_count, v_sub_count, v_algorithm, v_cutoff, v_rubric,
      v_policy_versions
    )
    on conflict (quarter_start, subject_id) do nothing
    returning id into v_rating_id;

    if v_rating_id is null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    insert into public.values_quarterly_values (rating_id, value_slug, score)
    select v_rating_id, slug, (val->>'average')::numeric
    from jsonb_each(v_rating) as t(slug, val)
    where val->>'average' is not null;

    -- Aggregate-only explanatory math, including zero and suppressed values.
    -- Exactly the same complete/cutoff/partition inputs as the visible mirror.
    insert into public.values_quarterly_accounting (rating_id, cutoff, policy_snapshots, value_totals)
    with contribution_rows as (
      select sc.value_slug, sc.score, s.rater_id, s.rater_class,
        (case s.rater_class when 'owner' then vp.weight_owner
          when 'crew_leader' then vp.weight_lead when 'worker' then vp.weight_worker
          when 'self' then vp.weight_self else 0 end)
          * (case when s.solo then vp.solo_factor else 1 end) as w
      from public.values_submissions s
      join public.values_scores sc on sc.submission_id = s.id
      join public.values_periods vp on vp.period_start = s.period_start
      where s.subject_id = v_subject and s.period_start >= p_quarter and s.period_start < v_quarter_end
        and s.submitted_at < v_cutoff
        and public.is_test_profile(s.rater_id) = public.is_test_profile(v_subject)
        and (select count(*) from public.values_scores c where c.submission_id = s.id) = 8
    ), totals as (
      select sl.slug,
        coalesce(sum(c.w * c.score), 0) as numerator, coalesce(sum(c.w), 0) as denominator,
        count(distinct c.rater_id) filter (where c.rater_class <> 'self') as raters,
        count(c.score) as submissions,
        coalesce(sum(c.score) filter (where c.rater_class = 'self'), 0) as self_sum,
        count(c.score) filter (where c.rater_class = 'self') as self_count
      from unnest(public._values_slugs()) sl(slug)
      left join contribution_rows c on c.value_slug = sl.slug
      group by sl.slug
    )
    select v_rating_id, v_cutoff, v_policy_snapshots,
      jsonb_object_agg(slug, jsonb_build_object(
        'weightedNumerator', numerator, 'weightedDenominator', denominator,
        'nonSelfRaters', raters, 'submissions', submissions,
        'selfSum', self_sum, 'selfCount', self_count
      )) from totals;

    -- Cross-partition source identities are omitted altogether. Same-
    -- partition late/incomplete evidence remains owner-only until its purge.
    insert into public.values_quarterly_manifest (
      rating_id, submission_id, rater_id, included, exclusion_reason
    )
    select v_rating_id, s.id, s.rater_id,
      calc.is_complete and s.submitted_at < v_cutoff,
      case when not calc.is_complete then 'incomplete'
           when s.submitted_at >= v_cutoff then 'late' else null end
    from public.values_submissions s
    cross join lateral (
      select (select count(*) from public.values_scores sc where sc.submission_id = s.id) = 8 as is_complete
    ) calc
    where s.subject_id = v_subject and s.period_start >= p_quarter and s.period_start < v_quarter_end
      and public.is_test_profile(s.rater_id) = public.is_test_profile(v_subject);

    v_frozen := v_frozen + 1;
  end loop;

  return jsonb_build_object('quarterStart', p_quarter, 'cutoff', v_cutoff, 'frozen', v_frozen, 'skipped', v_skipped);
end;
$$;;
;
create or replace function public.values_run_due()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_enabled boolean;
  v_now timestamptz := now();
  v_period date;
  v_deals jsonb := '[]'::jsonb;
  v_d jsonb;
  v_q date;
  v_last_q date;
  v_freezes jsonb := '[]'::jsonb;
  v_f jsonb;
begin
  select values_scheduler_enabled into v_enabled from public.company_settings where id = 1;
  if not coalesce(v_enabled, false) then
    return jsonb_build_object('skipped', 'scheduler disabled');
  end if;

  -- CATCH-UP DEALING (independent review finding #7): every month from
  -- launch through the current one gets a deal/top-up pass, not only
  -- "today's" period — a worker whose first shift of the month falls in the
  -- window's last days, or a scheduler outage spanning the whole open week,
  -- is caught up here instead of being missed outright. _values_deal_period
  -- is a cheap no-op on a month nothing changed, and assignmentsToStore's
  -- merge rule (see its own comment) makes repeated calls additive-safe. A
  -- month whose quarter has already closed is skipped — dealing into an
  -- already-frozen quarter cannot change its result and would only queue
  -- pointless late assignments.
  v_period := public._values_launch();
  while v_period <= public._values_active_period(v_now) loop
    if public._values_period_scorable(v_period)
       and not public._values_quarter_closed(public._values_quarter_of(v_period), v_now)
    then
      v_d := public._values_deal_period(v_period);
      v_deals := v_deals || jsonb_build_array(v_d);
    end if;
    v_period := (v_period + interval '1 month')::date;
  end loop;

  v_q := public._values_quarter_of(public._values_launch());
  v_last_q := public._values_quarter_of(public._values_day(v_now));
  while v_q <= v_last_q loop
    if public._values_quarter_closed(v_q, v_now) then
      v_f := public._values_freeze_quarter(v_q);
      v_freezes := v_freezes || jsonb_build_array(v_f);
    end if;
    v_q := (v_q + interval '3 months')::date;
  end loop;

  return jsonb_build_object('deals', v_deals, 'freezes', v_freezes);
end;
$$;;
;
create or replace function public.work_data_snapshot(
  p_project_id uuid,
  p_from timestamptz,
  p_until timestamptz
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_project jsonb;
  v_shifts jsonb;
  v_shift_count int;
  v_claims jsonb;
  v_claim_count int;
  v_untimed jsonb;
  v_untimed_count int;
  v_units jsonb;
  v_as_of timestamptz := statement_timestamp();
begin
  -- 1. Who is asking — before any source read, per the brief's correction
  -- that broad table-level RLS is not sufficient privacy for this payload.
  if v_uid is null or not public.custom_work_internal() or not public._is_supervisor(v_uid) then
    raise exception 'A signed-in supervisor or owner is required to read work data.' using errcode = '42501';
  end if;

  if p_project_id is null or p_from is null or p_until is null then
    raise exception 'A project and a complete from/until window are required.';
  end if;
  if not isfinite(p_from) or not isfinite(p_until) then
    raise exception 'The requested window is not a valid pair of timestamps.';
  end if;
  if p_until <= p_from or p_until - p_from > interval '93 days' then
    raise exception 'The window must be more than zero and at most 93 days.';
  end if;

  -- Gates the project itself: live, not deleted, and — the test-login fence
  -- restated for a real (non-test) supervisor/owner caller — visible under
  -- the same rule projects_select_visible already enforces for everyone
  -- else. A test-flagged job off the sandbox list, or a trashed job, is
  -- refused here exactly as it would be refused by the ordinary read.
  if not public._ai_job_visible(p_project_id, v_uid) then
    raise exception 'That job is unavailable.' using errcode = '42501';
  end if;

  select jsonb_build_object('id', p.id, 'jobCode', p.job_code, 'name', p.name)
    into v_project
  from public.projects p
  where p.id = p_project_id;
  -- _ai_job_visible already proved this row exists and is visible; this
  -- re-read only guards a delete racing between the check and here.
  if v_project is null then
    raise exception 'That job is unavailable.' using errcode = '42501';
  end if;

  -- ---------------------------------------------------------------------
  -- 2. Shifts — time_shifts whose clock_in falls in [from, until). Payroll
  -- stays time_shifts' own arithmetic (shiftHours); this is a read of it,
  -- never a second total. No profile override: the shift's own project_id
  -- is what is read, never a caller-supplied person list.
  -- ---------------------------------------------------------------------
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id,
      'profileId', s.profile_id,
      'profileName', coalesce(nullif(btrim(pr.display_name), ''), 'Crew'),
      'projectId', s.project_id,
      'startedAt', s.clock_in_at,
      'endedAt', s.clock_out_at,
      'breakSeconds', s.break_seconds,
      'breakStartedAt', s.break_started_at,
      'status', s.status,
      'reviewReason', s.review_reason
    ) order by s.clock_in_at, s.id), '[]'::jsonb), count(*)
    into v_shifts, v_shift_count
  from public.time_shifts s
  join public.profiles pr on pr.id = s.profile_id
  where s.project_id = p_project_id
    and s.clock_in_at >= p_from and s.clock_in_at < p_until;

  if v_shift_count > 10000 then
    raise exception 'Too many shifts in this window (%). Narrow the date range.', v_shift_count;
  end if;

  -- ---------------------------------------------------------------------
  -- 3. Claims — every existing table that times a person against a unit or
  -- a named activity, matched to this job's own shifts above. Coexisting
  -- claims keep separate raw source IDs; the overlap engine in
  -- app/src/lib/workData/reconcile.ts counts an overlap once as conflict,
  -- never as added time. Historical stage/description text is passed
  -- through unchanged, never relabelled into a new taxonomy.
  -- ---------------------------------------------------------------------
  with w_shifts as (
    select id, profile_id, clock_in_at, clock_out_at from public.time_shifts
    where project_id = p_project_id and clock_in_at >= p_from and clock_in_at < p_until
  ),
  openings as (
    -- The authorized, nonremoved opening graph for this job: every claim
    -- below that keys off an opening joins through this, so a removed
    -- opening or one belonging to another job never leaks a raw ID or a
    -- total.
    select o.id, o.project_id from public.project_openings o
    where o.project_id = p_project_id and o.removed_at is null
  ),
  custom as (
    select
      'custom_work_sessions:' || cs.id::text as source_id,
      'custom_work_sessions'::text as source_table,
      cs.revision as revision,
      cs.profile_id as profile_id,
      cs.project_id as project_id,
      cs.shift_id as shift_id,
      case when cs.unit_id is null then null
           else coalesce('opening:' || cu.opening_id::text, 'custom:' || cs.unit_id::text) end as unit_id,
      case when cs.kind = 'idle'
             then 'idle:' || coalesce(nullif(btrim(cs.description), ''), cs.stage)
           else 'unit:' || cs.stage end as activity_id,
      case when cs.kind = 'idle'
             then coalesce(nullif(btrim(cs.description), ''), cs.stage)
           else cs.stage end as label,
      case when cs.kind = 'idle' then 'general' else 'specific' end as scope,
      cs.started_at as started_at,
      cs.ended_at as ended_at,
      false as pending,
      (coalesce(cs.review_required, false)
        or cs.project_id <> p_project_id or (cu.id is not null and cu.project_id <> cs.project_id)
        or (cs.shift_status is not null and cs.shift_status not in ('open', 'submitted', 'approved'))) as unresolved,
      coalesce(cs.outcome = 'rework', false) as rework
    from public.custom_work_sessions cs
    join w_shifts ws on ws.id = cs.shift_id and ws.profile_id = cs.profile_id
    left join public.custom_work_units cu on cu.id = cs.unit_id
    where public._ai_job_visible(cs.project_id, v_uid)
      and (cs.unit_id is null or (cu.id is not null
        and public._ai_job_visible(cu.project_id, v_uid)
        and (cu.opening_id is null or exists (select 1 from public.project_openings mapped
          where mapped.id = cu.opening_id and mapped.removed_at is null
            and public._ai_job_visible(mapped.project_id, v_uid)))))
  ),
  unit_sess as (
    select
      'unit_sessions:' || us.id::text as source_id,
      'unit_sessions'::text as source_table,
      null::int as revision,
      us.profile_id as profile_id,
      op.project_id as project_id,
      null::uuid as shift_id,
      'opening:' || us.opening_id::text as unit_id,
      'unit_session:' || us.role as activity_id,
      case when us.role = 'helper' then 'Helper' else 'Install' end as label,
      'specific'::text as scope,
      us.started_at as started_at,
      us.ended_at as ended_at,
      false as pending,
      coalesce(us.end_reason = 'auto_closed', false) as unresolved,
      coalesce(us.is_rework, false) as rework
    from public.unit_sessions us
    join openings op on op.id = us.opening_id
    where (us.started_at >= p_from and us.started_at < p_until)
      or exists (select 1 from w_shifts ws where ws.profile_id = us.profile_id
        and us.started_at < coalesce(ws.clock_out_at, v_as_of)
        and coalesce(us.ended_at, v_as_of) > ws.clock_in_at)
  ),
  task as (
    select
      'task_sessions:' || ts.id::text as source_id,
      'task_sessions'::text as source_table,
      null::int as revision,
      ts.profile_id as profile_id,
      ts.project_id as project_id,
      null::uuid as shift_id,
      case when ts.opening_id is null then null else 'opening:' || ts.opening_id::text end as unit_id,
      'on_task'::text as activity_id,
      'On task'::text as label,
      'specific'::text as scope,
      ts.started_at as started_at,
      ts.ended_at as ended_at,
      false as pending,
      false as unresolved,
      false as rework
    from public.task_sessions ts
    left join openings op on op.id = ts.opening_id
    where ts.project_id = p_project_id
      and ts.state = 'on_task'
      and (ts.opening_id is null or op.id is not null)
      and ((ts.started_at >= p_from and ts.started_at < p_until)
        or exists (select 1 from w_shifts ws where ws.profile_id = ts.profile_id
          and ts.started_at < coalesce(ws.clock_out_at, v_as_of)
          and coalesce(ts.ended_at, v_as_of) > ws.clock_in_at))
  ),
  service as (
    select
      'service_time_sessions:' || sts.id::text as source_id,
      'service_time_sessions'::text as source_table,
      null::int as revision,
      sts.profile_id as profile_id,
      sts.project_id as project_id,
      sts.shift_id as shift_id,
      case
        when sts.unit_id is null then null
        when svu.opening_id is not null and svo.id is not null then 'opening:' || svu.opening_id::text
        when svu.work_unit_id is not null then coalesce('opening:' || cu.opening_id::text, 'custom:' || svu.work_unit_id::text)
        else 'service:' || svu.id::text
      end as unit_id,
      case sts.kind
        when 'unit' then 'service:' || sts.stage
        when 'idle' then 'idle:' || coalesce(nullif(btrim(sts.description), ''), sts.stage)
        else 'travel:' || coalesce(nullif(btrim(sts.description), ''), sts.stage)
      end as activity_id,
      case sts.kind
        when 'unit' then sts.stage
        else coalesce(nullif(btrim(sts.description), ''), sts.stage)
      end as label,
      case sts.kind when 'unit' then 'specific' when 'idle' then 'general' else 'other' end as scope,
      sts.started_at as started_at,
      sts.ended_at as ended_at,
      false as pending,
      (coalesce(sts.review_required, false) or sts.project_id <> p_project_id
        or sv.project_id <> sts.project_id or (svu.id is not null and svu.project_id <> sts.project_id)
        or (cu.id is not null and cu.project_id <> sts.project_id)) as unresolved,
      (sts.kind = 'unit') as rework
    from public.service_time_sessions sts
    join w_shifts ws on ws.id = sts.shift_id and ws.profile_id = sts.profile_id
    join public.service_visits sv on sv.id = sts.visit_id
    left join public.service_visit_units svu on svu.id = sts.unit_id
    left join openings svo on svo.id = svu.opening_id
    left join public.custom_work_units cu on cu.id = svu.work_unit_id
    where public._ai_job_visible(sts.project_id, v_uid) and public.service_job_access(sts.project_id)
      and public._ai_job_visible(sv.project_id, v_uid) and public.service_job_access(sv.project_id)
      and (sts.unit_id is null or (svu.id is not null and svu.visit_id = sv.id
        and public._ai_job_visible(svu.project_id, v_uid) and public.service_job_access(svu.project_id)
        and (svu.opening_id is null or exists (select 1 from public.project_openings mapped
          where mapped.id = svu.opening_id and mapped.removed_at is null
            and public._ai_job_visible(mapped.project_id, v_uid)))
        and (svu.work_unit_id is null or (cu.id is not null
          and public._ai_job_visible(cu.project_id, v_uid)
          and (cu.opening_id is null or exists (select 1 from public.project_openings mapped
            where mapped.id = cu.opening_id and mapped.removed_at is null
              and public._ai_job_visible(mapped.project_id, v_uid)))))))
  ),
  all_claims as (
    select * from custom union all
    select * from unit_sess union all
    select * from task union all
    select * from service
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'sourceId', c.source_id, 'sourceTable', c.source_table, 'revision', c.revision,
      'profileId', c.profile_id, 'projectId', c.project_id, 'shiftId', c.shift_id,
      'unitId', c.unit_id, 'activityId', c.activity_id, 'label', c.label, 'scope', c.scope,
      'startedAt', c.started_at, 'endedAt', c.ended_at,
      'pending', c.pending, 'unresolved', c.unresolved, 'rework', c.rework
    ) order by c.started_at, c.source_id), '[]'::jsonb), count(*)
    into v_claims, v_claim_count
  from all_claims c;

  if v_claim_count > 10000 then
    raise exception 'Too much claim evidence in this window (%). Narrow the date range.', v_claim_count;
  end if;

  -- ---------------------------------------------------------------------
  -- 4. Untimed evidence — a reported duration (or none) with no provable
  -- start/end interval. opening_phases' minutes are an aggregate over a
  -- possibly-paused clock and are never turned into a guessed range;
  -- install_events' legacy minutes and crew_work_records' named
  -- attribution are claims about who worked, not measured intervals.
  -- ---------------------------------------------------------------------
  with openings as (
    select o.id, o.project_id from public.project_openings o
    where o.project_id = p_project_id and o.removed_at is null
  ),
  phases as (
    select
      'opening_phases:' || ph.id::text as source_id, 'opening_phases'::text as source_table,
      ph.started_by as profile_id, op.project_id as project_id,
      'opening:' || ph.opening_id::text as unit_id,
      'flashing'::text as activity_id, 'Flashing'::text as label,
      to_char(ph.started_at at time zone 'America/Denver', 'YYYY-MM-DD') as work_date,
      case when ph.minutes is not null then ph.minutes * 60 else null end as reported_seconds
    from public.opening_phases ph
    join openings op on op.id = ph.opening_id
    where ph.kind = 'flashing' and ph.started_at >= p_from and ph.started_at < p_until
  ),
  legacy as (
    select
      'install_events:' || ie.id::text as source_id, 'install_events'::text as source_table,
      ie.installer_id as profile_id, op.project_id as project_id,
      'opening:' || ie.project_opening_id::text as unit_id,
      'legacy_install'::text as activity_id, 'Install (legacy time entry)'::text as label,
      to_char(coalesce(ie.started_at, ie.created_at) at time zone 'America/Denver', 'YYYY-MM-DD') as work_date,
      case when ie.minutes is not null then ie.minutes * 60 else null end as reported_seconds
    from public.install_events ie
    join openings op on op.id = ie.project_opening_id
    where ie.installer_id is not null
      and coalesce(ie.started_at, ie.created_at) >= p_from and coalesce(ie.started_at, ie.created_at) < p_until
  ),
  crew as (
    select
      'crew_work_record_people:' || r.id::text || ':' || p.profile_id::text as source_id,
      'crew_work_record_people'::text as source_table,
      p.profile_id as profile_id, r.project_id as project_id,
      coalesce('opening:' || cu.opening_id::text, 'custom:' || r.unit_id::text) as unit_id,
      'crew_record:' || r.stage as activity_id, r.stage as label,
      to_char(r.work_date, 'YYYY-MM-DD') as work_date,
      null::int as reported_seconds
    from public.crew_work_records r
    join public.crew_work_record_people p on p.record_id = r.id and p.voided_at is null
    join public.custom_work_units cu on cu.id = r.unit_id
    where r.project_id = p_project_id and r.work_date >= (p_from at time zone 'America/Denver')::date and r.work_date <= ((p_until - interval '1 microsecond') at time zone 'America/Denver')::date
      and r.outcome in ('partial', 'finished')
      and public._ai_job_visible(cu.project_id, v_uid)
      and (cu.opening_id is null or exists (select 1 from public.project_openings mapped
        where mapped.id = cu.opening_id and mapped.removed_at is null
          and public._ai_job_visible(mapped.project_id, v_uid)))
  ),
  all_untimed as (
    select * from phases union all
    select * from legacy union all
    select * from crew
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'sourceId', u.source_id, 'sourceTable', u.source_table, 'profileId', u.profile_id,
      'projectId', u.project_id, 'unitId', u.unit_id, 'activityId', u.activity_id,
      'label', u.label, 'workDate', u.work_date, 'reportedSeconds', u.reported_seconds
    ) order by u.work_date, u.source_id), '[]'::jsonb), count(*)
    into v_untimed, v_untimed_count
  from all_untimed u;

  if v_untimed_count > 10000 then
    raise exception 'Too much untimed evidence in this window (%). Narrow the date range.', v_untimed_count;
  end if;

  -- ---------------------------------------------------------------------
  -- 5. Units — every canonical unit identity (opening: or custom:) named by
  -- a claim or an untimed row above, each with only what this first slice
  -- independently establishes. Category, subtype, verified dimension and
  -- final QC are left null/false rather than guessed from free text — see
  -- docs/work-data.md.
  -- ---------------------------------------------------------------------
  with ids as (
    select distinct (j->>'unitId') as unit_id from jsonb_array_elements(v_claims) j where j->>'unitId' is not null
    union
    select distinct (j->>'unitId') as unit_id from jsonb_array_elements(v_untimed) j where j->>'unitId' is not null
  ),
  opening_units as (
    select i.unit_id, o.opening_code as label, (o.status = 'installed') as complete,
      (exists (select 1 from jsonb_array_elements(v_untimed) j where j->>'unitId' = i.unit_id) or coalesce(cu.untimed_work_present, false)) as has_untimed, coalesce(cu.facts, '{}'::jsonb) as facts
    from ids i
    join public.project_openings o on 'opening:' || o.id::text = i.unit_id
    left join public.custom_work_units cu on cu.opening_id = o.id and cu.project_id = p_project_id
    where o.project_id = p_project_id and o.removed_at is null
  ),
  custom_units as (
    select i.unit_id, cu.label as label,
      coalesce(cu.facts->>'installation_complete' = 'Yes', false) as complete,
      (coalesce(cu.untimed_work_present, false) or exists (select 1 from jsonb_array_elements(v_untimed) j where j->>'unitId' = i.unit_id)) as has_untimed,
      cu.facts as facts
    from ids i
    join public.custom_work_units cu on 'custom:' || cu.id::text = i.unit_id
    where cu.project_id = p_project_id
      and (cu.opening_id is null or exists (select 1 from public.project_openings mapped
        where mapped.id = cu.opening_id and mapped.removed_at is null
          and public._ai_job_visible(mapped.project_id, v_uid)))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', x.unit_id, 'label', x.label, 'category', null, 'subtype', null,
      'material', x.material, 'floor', x.floor,
      'widthIn', x.width_in, 'heightIn', x.height_in, 'dimensionSource', x.dimension_source,
      'dimensionsVerified', false, 'complete', x.complete, 'qcAccepted', false,
      'hasUntimedEvidence', x.has_untimed
    ) order by x.unit_id), '[]'::jsonb)
    into v_units
  from (
    select unit_id, label, complete, has_untimed,
      nullif(facts->>'material', '') as material, nullif(facts->>'story', '') as floor,
      case when (facts->>'width_in') ~ '^[0-9]+(\.[0-9]+)?$' then (facts->>'width_in')::numeric else null end as width_in,
      case when (facts->>'height_in') ~ '^[0-9]+(\.[0-9]+)?$' then (facts->>'height_in')::numeric else null end as height_in,
      nullif(facts->>'area_source', '') as dimension_source
    from opening_units
    union all
    select unit_id, label, complete, has_untimed,
      nullif(facts->>'material', '') as material,
      nullif(facts->>'story', '') as floor,
      case when (facts->>'width_in') ~ '^[0-9]+(\.[0-9]+)?$' then (facts->>'width_in')::numeric else null end as width_in,
      case when (facts->>'height_in') ~ '^[0-9]+(\.[0-9]+)?$' then (facts->>'height_in')::numeric else null end as height_in,
      nullif(facts->>'area_source', '') as dimension_source
    from custom_units
  ) x;

  if jsonb_array_length(v_units) > 10000 then
    raise exception 'Too many units. Narrow the date range.';
  end if;

  return jsonb_build_object(
    'schemaVersion', 1,
    'asOf', v_as_of,
    'project', v_project,
    'shifts', v_shifts,
    'claims', v_claims,
    'units', v_units,
    'untimed', v_untimed
  );
end;
$$;;
;
create function public.work_capture_validate_menu() returns trigger
language plpgsql set search_path = public,pg_temp as $$
declare item jsonb; definition uuid; version_id uuid; position integer;
  seen_definitions uuid[] := '{}'; seen_positions integer[] := '{}';
begin
  if jsonb_typeof(new.items) <> 'array' or jsonb_array_length(new.items) > 200 then
    raise exception using errcode='23514', message='Invalid menu snapshot.';
  end if;
  for item in select value from jsonb_array_elements(new.items) loop
    if jsonb_typeof(item) <> 'object' or
        not (item ?& array['definitionId','versionId','position','enabled']) or
        exists(select 1 from jsonb_object_keys(item) k
          where k not in ('definitionId','versionId','position','enabled')) or
        jsonb_typeof(item->'definitionId') <> 'string' or
        jsonb_typeof(item->'versionId') <> 'string' or
        jsonb_typeof(item->'position') <> 'number' or
        jsonb_typeof(item->'enabled') <> 'boolean' then
      raise exception using errcode='23514', message='Invalid menu item.';
    end if;
    definition := (item->>'definitionId')::uuid;
    version_id := (item->>'versionId')::uuid;
    if (item->>'position')::numeric <> trunc((item->>'position')::numeric) then
      raise exception using errcode='23514', message='Menu position must be an integer.';
    end if;
    position := (item->>'position')::integer;
    if position not between 0 and 199 or definition=any(seen_definitions)
        or position=any(seen_positions) or not exists (
          select 1 from public.work_activity_definition_versions v
          where v.id=version_id and v.definition_id=definition) then
      raise exception using errcode='23514', message='Menu membership is invalid or duplicated.';
    end if;
    seen_definitions := array_append(seen_definitions,definition);
    seen_positions := array_append(seen_positions,position);
  end loop;
  return new;
end;
$$;;
;
create function public.work_capture_immutable_record() returns trigger
language plpgsql set search_path = public,pg_temp as $$
begin
  raise exception using errcode='23514', message='Recorded capture evidence is immutable; create a new revision.';
end;
$$;;
